/* ============================================================
   TBD Dolo -- motor de datos ejecutivo (Ene-Jul 2025 vs Ene-Jul 2026).
   NO toca STATE ni ninguna funcion de app.js/engine.js -- lee los mismos
   YEARS_DATA/MKTORG_MARCA/DECK_INFO ya construidos y corregidos, y agrega
   su propia capa de agregacion (equivalente a agg()/dagg()/wearout()/
   launch_week() del proyecto de referencia en Python), mas el indice de
   estacionalidad de Ahrefs (reemplaza Google Trends) y el JR Halo.
   Organization es seleccionable (Open English / Open English Junior, ver
   TBD_STATE.org y tbdOrgName()) -- toda la matematica de abajo es identica
   para ambas marcas, solo cambia que slice de YEARS_DATA se lee.
   MarketingOrganization = solo la propia (igual a Organization) porque
   SEM-Brand y "gasto ajeno" no aplican a un reporte ejecutivo de inversion
   propia. ============================================================ */
var TBD_PERIODS = {
  '2025': { from: '2025-01-01', to: '2025-07-31' },
  '2026': { from: '2026-01-01', to: '2026-07-31' },
};
/* Titulo y explicacion del halo, escritos segun la marca seleccionada:
   viendo adulto se mide el halo hacia Junior, viendo Junior se mide el halo
   hacia adulto. Antes el texto estaba fijo hacia Junior. */
function tbdHaloColLeads(){
  var to=tbdHaloTargetName()==='Open English Junior'?'JR':'OE';
  return LANG==='en' ? to+' leads' : 'Leads '+to;
}
function tbdHaloColAdj(){
  var to=tbdHaloTargetName()==='Open English Junior'?'JR':'OE';
  return to+' L/$1k adj \u2605';
}
function tbdHaloColRef(){
  var from=tbdOrgName()==='Open English Junior'?'JR':'OE';
  return from+' L/$1k adj (ref)';
}
function tbdHaloTitle(){
  var L=LANG, from=tbdOrgName(), to=tbdHaloTargetName();
  return L==='en' ? 'Cross-brand halo \u2014 '+to+' leads generated by '+from+'\u2019s own spend'
    : L==='pt' ? 'Halo entre marcas \u2014 leads de '+to+' gerados pelo investimento da '+from
    : 'Halo entre marcas \u2014 leads de '+to+' generados por la inversi\u00f3n de '+from;
}
function tbdHaloSub(){
  var L=LANG, from=tbdOrgName(), to=tbdHaloTargetName();
  return L==='en'
    ? 'Halo L/$1k adj. = real '+to+' leads that the source system tagged as marketing_organization='+from+', prorated by the same creative rotation %, divided by '+from+' spend and demand-adjusted. The last column is the same creative\u2019s own '+from+' performance, as a reference.'
    : L==='pt'
    ? 'Halo L/$1k adj. = leads reais de '+to+' que o sistema de origem marcou como marketing_organization='+from+', prorrateados pelo mesmo % de rota\u00e7\u00e3o do criativo, divididos pelo gasto de '+from+' e ajustados por demanda. A \u00faltima coluna \u00e9 a performance pr\u00f3pria do mesmo criativo em '+from+', como refer\u00eancia.'
    : 'Halo L/$1k adj. = leads reales de '+to+' que el sistema de origen etiquet\u00f3 como marketing_organization='+from+', prorrateados por el mismo % de rotaci\u00f3n del creativo, divididos entre el gasto de '+from+' y ajustados por demanda. La \u00faltima columna es el desempe\u00f1o propio del mismo creativo en '+from+', como referencia.';
}
function tbdOrgName(){ return TBD_STATE.org === 'Open English Junior' ? 'Open English Junior' : 'Open English'; }

/* ---------- estacionalidad: modelo v2026 (ver tbd_seasonality.js) ---------- */
var TBD_SEASONALITY = window.__TBD_SEASONALITY__ || {};
/* Divisor de demanda = factor de estacionalidad FIJO del mes (modelo v2026).
   Antes se leia index_by_month, que es el volumen del mes concreto: eso
   mezclaba DOS cosas distintas en un solo numero -- la epoca del anio (que
   si hay que neutralizar, porque nadie elige nacer en enero) y el nivel del
   mercado de ese anio (que NO hay que neutralizar, porque un mercado que se
   cayo 20% es un hecho del negocio, no un sesgo de medicion). Al dividir por
   los dos a la vez, un creativo de un anio flojo salia premiado por la
   division. Ahora se divide UNICAMENTE por el patron de mes, que es igual en
   2025 y en 2026, y el movimiento del mercado se reporta aparte. */
function tbdDemandIndex(territory, fecha){
  var t = TBD_SEASONALITY[territory];
  if(!t || !t.factorsIndex) return 100;
  var m = Number(fecha.slice(5,7)) - 1;
  var v = t.factorsIndex[m];
  return v==null ? 100 : v;
}
/* meses cuyo factor NO es distinguible de 1.000 al 95% -- se marcan en gris:
   el ajuste se aplica igual (es la mejor estimacion puntual), pero el lector
   tiene que saber que ahi el ajuste es ruido y no debe rankear por decimas. */
function tbdSeasonMonthIsGrey(territory, monthIdx0){
  var t = TBD_SEASONALITY[territory];
  return !!(t && t.grey && t.grey[monthIdx0]);
}
function tbdSeasonGate(territory){
  var t = TBD_SEASONALITY[territory];
  return t ? { label: t.gate, skill: t.skill, seLog: t.seLog, lambda: t.lambda } : null;
}
/* margen de error del ajuste, en %, para el rotulo "no rankees por debajo de esto" */
function tbdSeasonErrPct(territory){
  var t = TBD_SEASONALITY[territory];
  if(!t || t.seLog==null) return null;
  return (Math.exp(1.96*t.seLog)-1)*100;
}

/* ---------- filtro de dias: rango de fecha explicito + pais ---------- */
/* Espejo EXACTO de `has_date_activity` en recomputeCreative() (app.js): un
   creativo entra al set solo si tuvo al menos UN dia con leads>0 de
   cualquier marketing_organization. Un creativo que salio al aire pero
   nunca genero un solo lead en ese pais no entra -- misma regla que el
   dashboard "TV Ads Performance", para que ambos den el mismo universo de
   creativos y el mismo gasto total. */
function tbdHasAnyLeadDay(rawDays){
  return rawDays.some(function(d){
    if((d.leads||0) > 0) return true;
    var bm = d.by_mktorg||{};
    return Object.keys(bm).some(function(mo){ return (bm[mo].leads||0) > 0; });
  });
}
function tbdDayInRange(fecha, from, to){ return fecha>=from && fecha<=to; }
function tbdDayPassesPais(topcountry, pais){
  if(topcountry==null) return true; // Brasil: sin desglose de pais
  return pais==null || topcountry===pais;
}

/* ---------- JR Halo: leads de clientes reales Junior atribuidos a marketing_organization='OE',
   re-derivado directo de dailyRows del deck de Junior (JR-BR.json / JR-LATAM.json) -- no toca
   engine.js. Se prorratea con el MISMO peso de rotacion del dia para el creativo OE (mismo
   mecanismo que ya usa engine.js para todo lo demas). ---------- */
/* HALO CRUZADO ENTRE MARCAS -- EN AMBAS DIRECCIONES.
   El halo son leads REALES de la OTRA marca que el sistema de origen atribuyo
   a la inversion de la marca que estamos viendo. Existe en los dos sentidos y
   ambos se leen del mismo modo, cambiando de que deck se lee y que valor de
   marketing_organization se filtra:

     Viendo Open English (adulto)  -> halo = leads de JUNIOR generados por el
       gasto de adulto. Se leen los decks JR-* filtrando marketing_organization
       === 'OE'.
     Viendo Open English Junior    -> halo = leads de ADULTO generados por el
       gasto de Junior. Se leen los decks OE-* filtrando
       marketing_organization === 'Open English Junior'.

   En ambos casos el total del dia se prorratea por el MISMO peso de rotacion
   del creativo de la marca que se esta viendo (d.peso_propio), igual que el
   resto del dashboard. */
var TBD_HALO_MAPS = { 'Open English': null, 'Open English Junior': null };
var TBD_JR_HALO_RAW = null; // compatibilidad: apunta al mapa de la marca OE adulto
function tbdBuildHaloMap(deckJsons, deckKeys, mktOrgValue){
  var m = new Map();
  deckKeys.forEach(function(deckKey){
    var info = DECK_INFO[deckKey];
    var d = deckJsons[deckKey];
    if(!d || !info) return;
    (d.dailyRows||[]).forEach(function(r){
      if(r.channel_grouping!=='Brand TV Channels') return;
      if(r.marketing_organization!==mktOrgValue) return;
      var country = info.region==='Brazil' ? null : r.country;
      var k = info.region+'|'+r.date+'|'+(country||'');
      m.set(k, (m.get(k)||0) + (r.leadsEligible||0));
    });
  });
  return m;
}
function tbdBuildJrHaloRaw(deckJsons){
  // halo hacia Junior: lo que la inversion de OE adulto le genero a Junior
  TBD_HALO_MAPS['Open English'] = tbdBuildHaloMap(deckJsons, ['JR-LATAM','JR-BR'], 'OE');
  // halo hacia adulto: lo que la inversion de Junior le genero a OE adulto
  TBD_HALO_MAPS['Open English Junior'] = tbdBuildHaloMap(deckJsons, ['OE-LATAM','OE-BR'], 'Open English Junior');
  TBD_JR_HALO_RAW = TBD_HALO_MAPS['Open English'];
  return TBD_JR_HALO_RAW;
}
/* la marca que se esta viendo decide que mapa de halo aplica */
function tbdActiveHaloMap(){
  return TBD_HALO_MAPS[tbdOrgName()] || null;
}
/* nombre de la marca RECEPTORA del halo (la otra) */
function tbdHaloTargetName(){
  return tbdOrgName()==='Open English Junior' ? 'Open English' : 'Open English Junior';
}
function tbdJrHaloLeadsForDay(region, fecha, topcountry, peso){
  var TBD_JR_HALO_RAW = tbdActiveHaloMap();
  if(!TBD_JR_HALO_RAW) return 0;
  var k = region+'|'+fecha+'|'+(topcountry||'');
  return (TBD_JR_HALO_RAW.get(k)||0) * peso;
}

/* ---------- construir los "dias" de un creativo para un periodo+pais, con demand index ---------- */
function tbdDailyItemFromRaw(d, territory, region){
  return {
    date: d.fecha,
    l: d.leads||0,            // home: MarketingOrganization===Organization (mismo criterio que el resto del dashboard)
    s: d.adcost_real||0,      // SIEMPRE neto de SEM-Brand (regla permanente del reporte ejecutivo)
    e: d.core_enrollments||0,
    c: d.new_cash_core||0,
    jr_l: tbdJrHaloLeadsForDay(region, d.fecha, d.topcountry, d.peso_propio),
    dem: tbdDemandIndex(territory, d.fecha),
  };
}

/* ---------- agg(): puerto directo de la funcion Python, misma forma de retorno ---------- */
function tbdAgg(dl){
  if(!dl || !dl.length) return null;
  var tl=0, ts=0, te=0, tc=0, jr=0;
  dl.forEach(function(d){ tl+=d.l; ts+=d.s; te+=d.e; tc+=d.c; jr+=d.jr_l; });
  // Solo se descarta por gasto 0 (sin gasto no hay nada que medir por $).
  // NO se descarta por leads=0: un creativo que gasto y no trajo leads es un
  // dato real -- excluirlo sacaba su gasto del total del portafolio e
  // inflaba el L/$1k de todo el territorio. Validado contra el dashboard
  // "TV Ads Performance", que si los incluye (ver Documentacion/).
  if(ts<=0) return null;
  var n = dl.length;
  var dw=0; dl.forEach(function(d){ dw += d.dem*d.s; });
  var di = ts>0 ? dw/ts : 100; // demand index spend-weighted
  return {
    l: tl, s: ts, e: te, c: tc, jr_l: jr, n: n,
    l1k: tl/ts*1000,
    l1k_adj: tl/ts*1000/(di/100),
    cpl: tl>0 ? ts/tl : null,
    cpl_adj: tl>0 ? ts/tl*(di/100) : null,
    cvr: tl>0 ? te/tl : 0,
    mncc: tc>0 ? (tc-ts)/tc : 0,
    lpd: tl/n,
    jr_lpd: jr/n,
    jr_l1k_adj: ts>0 ? (jr/ts*1000)/(di/100) : 0,
    dem: di,
  };
}

/* ---------- lista de creativos de un territorio/periodo, agrupados por Ad Name ----------
   CORREGIDO 2026-08-21: el Video Name (columna A, `row.nombre`) puede tener
   variantes V2/V3/etc. del MISMO anuncio (cambios minimos, ej. una nota
   legal) -- agruparlos como si fueran creativos distintos infla la lista y
   descuadra los dias/porcentajes de rotacion. Se agrupa por Ad Name (columna
   B, `row.ad_name`) exactamente como ya hace `groupCreativesByAdName()` en
   el dashboard principal (app.js) -- misma regla, portada aqui porque TBD
   Dolo arma su propia lista de dias (`_dailyItems`) en vez de usar
   `recomputeCreative()`. */
function tbdCreativesForPeriod(territory, region, yearKey, pais, adTypeFilter){
  var yd = YEARS_DATA[yearKey];
  if(!yd) return [];
  var slice = yd.slices[tbdOrgName()+'|'+region+'|Total'];
  var rows = slice ? slice.ranking_creativos : [];
  var per = TBD_PERIODS[yearKey];

  var byAdName = {}; // ad_name -> [{row, rawDays, dailyItems}, ...] (uno por Video Name)
  rows.forEach(function(row){
    if(adTypeFilter && adTypeFilter!=='Todos' && row.ad_type!==adTypeFilter) return;
    var rawDays = (row.detalle_diario||[]).filter(function(d){
      return tbdDayInRange(d.fecha, per.from, per.to) && tbdDayPassesPais(d.topcountry, pais);
    });
    if(!rawDays.length) return;
    if(!tbdHasAnyLeadDay(rawDays)) return; // paridad con has_date_activity de app.js
    var dailyItems = rawDays.map(function(d){ return tbdDailyItemFromRaw(d, territory, region); });
    var adName = row.ad_name || row.nombre;
    (byAdName[adName] = byAdName[adName] || []).push({ row: row, rawDays: rawDays, dailyItems: dailyItems });
  });

  var out = [];
  Object.keys(byAdName).forEach(function(adName){
    var videos = byAdName[adName];
    var mergedItems = [], mergedRawDays = [], allDates = new Set();
    videos.forEach(function(v){
      mergedItems = mergedItems.concat(v.dailyItems);
      v.rawDays.forEach(function(d){ mergedRawDays.push(Object.assign({video_name:v.row.nombre}, d)); allDates.add(d.fecha); });
    });
    var a = tbdAgg(mergedItems);
    if(!a) return;
    // dias activos = FECHAS UNICAS (no filas) -- si dos versiones rotaron el
    // mismo dia, cuenta como un solo dia activo, igual que en el dashboard
    // principal (`allDates.size` en groupCreativesByAdName).
    a.n = allDates.size;
    a.lpd = a.n ? a.l/a.n : null;
    a.jr_lpd = a.n ? a.jr_l/a.n : null;
    var primary = videos.slice().sort(function(x,y){ return y.rawDays.length - x.rawDays.length; })[0].row;
    mergedRawDays.sort(function(x,y){ return x.fecha<y.fecha ? -1 : (x.fecha>y.fecha?1:0); });
    out.push(Object.assign({
      nombre: adName, ad_name: adName, ad_type: primary.ad_type, campaign_name: primary.campaign_name,
      theme: primary.theme, theme_mechanism_code: primary.theme_mechanism_code, pain_point: primary.pain_point, pain_point_code: primary.pain_point_code, tone_category: primary.tone_category,
      hook_audio_type_code: primary.hook_audio_type_code, hook_visual_type_code: primary.hook_visual_type_code,
      cta_type_code: primary.cta_type_code, type_of_production: primary.type_of_production, version: primary.version,
      link_video: primary.link_video, launch_dates: primary.launch_dates,
      theme_explanation: primary.theme_explanation, hook_audio: primary.hook_audio, hook_visual: primary.hook_visual,
      /* Ya venian en tvads-creative-taxonomy.json y engine.js ya los pega a la
         fila del deck; simplemente nadie los estaba copiando hasta aca, asi
         que el brief no podia hablar de reparto ni de la frase de CTA real. */
      main_character: primary.main_character, secondary_characters: primary.secondary_characters,
      cta_phrase: primary.cta_phrase, promo_name: primary.promo_name,
      is_grouped: videos.length > 1,
      versions: videos.map(function(v){ return { video_name: v.row.nombre, link_video: v.row.link_video, version: v.row.version, num_dias: new Set(v.rawDays.map(function(d){return d.fecha;})).size }; }),
      _dailyItems: mergedItems, _rawDays: mergedRawDays,
    }, a));
  });
  return out.sort(function(a,b){ return b.l1k_adj - a.l1k_adj; });
}

/* ---------- SOLO para la pestana "Versions": V1 vs V2/V3 necesita cada Video
   Name como fila propia (si se agrupara por Ad Name, V1 y V2 quedarian
   fundidos en la MISMA fila y la comparacion dejaria de existir). El resto
   del dashboard (Portfolio, Promo, Generic, JR Halo, Launch, Wearout, y las
   demas dimensiones) usa `tbdCreativesForPeriod()` (agrupado por Ad Name)
   arriba -- esta funcion es la unica excepcion, a proposito. ---------- */
function tbdVideoRowsForPeriod(territory, region, yearKey, pais, adTypeFilter){
  var yd = YEARS_DATA[yearKey];
  if(!yd) return [];
  var slice = yd.slices[tbdOrgName()+'|'+region+'|Total'];
  var rows = slice ? slice.ranking_creativos : [];
  var per = TBD_PERIODS[yearKey];
  var out = [];
  rows.forEach(function(row){
    if(adTypeFilter && adTypeFilter!=='Todos' && row.ad_type!==adTypeFilter) return;
    var rawDays = (row.detalle_diario||[]).filter(function(d){
      return tbdDayInRange(d.fecha, per.from, per.to) && tbdDayPassesPais(d.topcountry, pais);
    });
    if(!rawDays.length) return;
    if(!tbdHasAnyLeadDay(rawDays)) return; // paridad con has_date_activity de app.js
    var dailyItems = rawDays.map(function(d){ return tbdDailyItemFromRaw(d, territory, region); });
    var a = tbdAgg(dailyItems);
    if(!a) return;
    a.n = new Set(rawDays.map(function(d){return d.fecha;})).size;
    a.lpd = a.n ? a.l/a.n : null;
    var taggedRawDays = rawDays.map(function(d){ return Object.assign({video_name:row.nombre}, d); });
    out.push(Object.assign({
      nombre: row.nombre, ad_name: row.ad_name||row.nombre, version: row.version, ad_type: row.ad_type,
      campaign_name: row.campaign_name, theme: row.theme, theme_mechanism_code: row.theme_mechanism_code,
      pain_point: row.pain_point, pain_point_code: row.pain_point_code, tone_category: row.tone_category,
      hook_audio_type_code: row.hook_audio_type_code, hook_visual_type_code: row.hook_visual_type_code,
      cta_type_code: row.cta_type_code, type_of_production: row.type_of_production,
      link_video: row.link_video, launch_dates: row.launch_dates,
      theme_explanation: row.theme_explanation, hook_audio: row.hook_audio, hook_visual: row.hook_visual,
      main_character: row.main_character, secondary_characters: row.secondary_characters,
      cta_phrase: row.cta_phrase, promo_name: row.promo_name,
      is_grouped: false, versions: [{ video_name: row.nombre, link_video: row.link_video, version: row.version, num_dias: a.n }],
      _dailyItems: dailyItems, _rawDays: taggedRawDays,
    }, a));
  });
  return out;
}

/* ---------- launch week: primeros 7 dias calendario desde la primera fecha de aire ---------- */
function tbdLaunchWeek(item){
  var dl = item._dailyItems;
  if(!dl || !dl.length) return null;
  var asc = dl.slice().sort(function(a,b){ return a.date<b.date?-1:1; });
  var firstT = Date.parse(asc[0].date+'T00:00:00Z');
  var lw = asc.filter(function(d){ return (Date.parse(d.date+'T00:00:00Z')-firstT)/86400000 <= 6; });
  return tbdAgg(lw);
}

/* ---------- wearout: mitad por conteo de dias, no por semana calendario ---------- */
function tbdWearout(item){
  var dl = item._dailyItems;
  if(!dl || dl.length<6) return {h1:null, h2:null, pct:null};
  var asc = dl.slice().sort(function(a,b){ return a.date<b.date?-1:1; });
  var mid = Math.floor(asc.length/2);
  var h1 = tbdAgg(asc.slice(0,mid)), h2 = tbdAgg(asc.slice(mid));
  if(!h1 || !h2 || h1.l1k_adj<=0) return {h1:h1, h2:h2, pct:null};
  return {h1:h1, h2:h2, pct:(h2.l1k_adj-h1.l1k_adj)/h1.l1k_adj*100};
}

/* ---------- desgaste por FECHA unica ----------
   tbdWearout() de arriba parte _dailyItems por numero de FILAS. En un Ad Name
   agrupado (is_grouped) dos versiones que rotaron el mismo dia son dos filas,
   asi que la "primera mitad al aire" y la "segunda" podian compartir fecha y
   el delta salia contaminado. Esta version parte por fecha unica y exige 12
   fechas para dar un porcentaje: con menos, la mitad tiene 5 dias o menos y
   el numero es ruido. Devuelve tambien las fechas de corte, para poder decir
   en el texto contra que periodo se esta comparando. */
function tbdWearout2(r){
  var dl = r && r._dailyItems;
  var out = { h1:null, h2:null, pct:null, d1:0, d2:0, fIniH1:null, fFinH1:null, fIniH2:null, fFinH2:null, leadsH1:0, leadsH2:0 };
  if(!dl || !dl.length) return out;
  var byDate = {};
  dl.forEach(function(d){ (byDate[d.date] = byDate[d.date] || []).push(d); });
  var fechas = Object.keys(byDate).sort();
  out.d1 = Math.floor(fechas.length/2); out.d2 = fechas.length - out.d1;
  if(fechas.length < 12) return out;
  var mid = Math.floor(fechas.length/2);
  var a = [], b = [];
  fechas.forEach(function(f, i){ (i<mid ? a : b).push.apply(i<mid ? a : b, byDate[f]); });
  var h1 = tbdAgg(a), h2 = tbdAgg(b);
  out.h1 = h1; out.h2 = h2;
  out.d1 = mid; out.d2 = fechas.length - mid;
  out.fIniH1 = fechas[0]; out.fFinH1 = fechas[mid-1];
  out.fIniH2 = fechas[mid]; out.fFinH2 = fechas[fechas.length-1];
  out.leadsH1 = h1 ? h1.l : 0; out.leadsH2 = h2 ? h2.l : 0;
  if(!h1 || !h2 || !(h1.l1k_adj>0)) return out;
  out.pct = (h2.l1k_adj - h1.l1k_adj) / h1.l1k_adj * 100;
  return out;
}
function tbdDaysUnique(r){
  var dl = r && r._dailyItems;
  if(!dl || !dl.length) return 0;
  var set = {};
  dl.forEach(function(d){ set[d.date] = 1; });
  return Object.keys(set).length;
}

/* ---------- dimension rollup: puerto de dagg() ---------- */
function tbdDimensionRollup(items, keyFn){
  var buckets = {};
  items.forEach(function(r){
    var k = keyFn(r);
    if(k==null) return;
    if(!buckets[k]) buckets[k] = {tl:0, ts:0, te:0, jr:0, tc:0, n:0, days:0, dw:0, dws:0};
    var b = buckets[k];
    b.tl += r.l; b.ts += r.s; b.te += r.e; b.jr += r.jr_l; b.tc += (r.c||0); b.n++; b.days += r.n; b.dw += r.dem*r.s; b.dws += r.s;
  });
  var out = [];
  Object.keys(buckets).forEach(function(k){
    var b = buckets[k];
    if(b.ts<=0) return;
    var l1k = b.tl/b.ts*1000;
    var di = b.dws>0 ? b.dw/b.dws : 100;
    out.push({ label:k, l1k:l1k, l1k_adj:l1k/(di/100), cpl: b.tl>0?b.ts/b.tl:null, cpl_adj: b.tl>0?(b.ts/b.tl)*(di/100):null,
      cvr: b.tl>0? b.te/b.tl:0, mncc: b.tc>0 ? (b.tc-b.ts)/b.tc : 0, n:b.n, days:b.days, s:b.ts,
      jr_l1k_adj: b.ts>0?(b.jr/b.ts*1000)/(di/100):0, dem:di });
  });
  return out.sort(function(a,b){ return b.l1k_adj-a.l1k_adj; });
}
/* ---------- registro de dimensiones + helpers compartidos por los 15
   detectores del panel de expertos (ver especificacion sintetizada) ---------- */
var TBD_DIM_DEFS = {
  tone_category: { keyFn:function(r){return r.tone_category||null;}, label:{en:'Tone',es:'Tono',pt:'Tom'} },
  theme_mechanism_code: { keyFn:function(r){return r.theme_mechanism_code||null;}, label:{en:'theme mechanism',es:'mecanismo temático',pt:'mecanismo temático'} },
  pain_point: { keyFn:function(r){return r.pain_point||null;}, label:{en:'pain point',es:'pain point',pt:'pain point'} },
  hook_audio_type_code: { keyFn:function(r){return r.hook_audio_type_code||null;}, label:{en:'audio hook',es:'hook de audio',pt:'hook de áudio'} },
  hook_visual_type_code: { keyFn:function(r){return r.hook_visual_type_code||null;}, label:{en:'visual hook',es:'hook visual',pt:'hook visual'} },
  ad_type: { keyFn:function(r){return r.ad_type||null;}, label:{en:'ad type',es:'tipo de anuncio',pt:'tipo de anúncio'} },
  type_of_production: { keyFn:function(r){return r.type_of_production||null;}, label:{en:'production method',es:'método de producción',pt:'método de produção'} },
  cta_type_code: { keyFn:function(r){return r.cta_type_code||null;}, label:{en:'CTA type',es:'tipo de CTA',pt:'tipo de CTA'} },
};
/* Devuelve la clave cruda si la dimension no esta en el catalogo, en vez de
   reventar: hay dimensiones validas del dataset (pain_point_code, version,
   campaign_name) que nunca estuvieron en TBD_DIM_DEFS. */
function tbdDimLabel(dimKey){
  var d = TBD_DIM_DEFS[dimKey];
  return d && d.label ? tbdT(d.label) : String(dimKey||'');
}
function tbdPainPrefix(r){ var c=r.pain_point_code||''; var i=c.indexOf('-'); return i===-1?c:c.slice(0,i); }
function tbdIsFearPain(r){ return (r.pain_point_code||'').indexOf('Fear')!==-1; }
function tbdLaunchDateOf(r){ return (r.launch_dates&&r.launch_dates[0]) || (r._dailyItems&&r._dailyItems.length?r._dailyItems.slice().sort(function(a,b){return a.date<b.date?-1:1;})[0].date:null); }

/* ---------- portfolio: agregado de TODOS los creativos de un periodo (no por creativo) ---------- */
function tbdPortfolio(items){
  var dl = [];
  items.forEach(function(r){ dl = dl.concat(r._dailyItems); });
  var a = tbdAgg(dl);
  var uniqueCreatives = items.length;
  return Object.assign({ num_creatives: uniqueCreatives }, a || {l:0,s:0,l1k_adj:null,cpl_adj:null,cvr:null,mncc:null});
}

