function tbdS(key){ return tbdT(TBD_STR[key] || {en:key,es:key,pt:key}); }

function tbdApplyBrandTheme(){
  var isJr = TBD_STATE.org==='Open English Junior';
  document.getElementById('tbdShell').classList.toggle('brand-jr', isJr);
  // el acento se marca en <html> para que tambien lo hereden el tooltip del
  // tour y el modal, que se renderizan fuera de #tbdShell
  if(isJr) document.documentElement.setAttribute('data-tbd-brand','jr');
  else document.documentElement.removeAttribute('data-tbd-brand');
}
/* ============================================================
   Sesion persistente y refresco por cambio de dia de calendario.

   Dos problemas distintos que se resuelven juntos:

   1. Recargar el navegador devolvia a todo el mundo al estado inicial
      (Open English / Brasil / Portfolio). El hash ya llevaba pestana, pais
      y marca, pero no el layout, ni la agrupacion Ad Name vs Video Name,
      ni si el panel de filtros estaba plegado. Ahora la sesion completa se
      guarda en localStorage y se restaura al abrir; si la URL trae hash,
      el hash manda (es un enlace directo y debe ganarle a la preferencia).

   2. El ETL de KPIs se regenera a diario. Quien dejaba el dashboard abierto
      de un dia para otro -- o cerraba la laptop y la volvia a abrir --
      seguia leyendo la data de ayer sin ningun aviso. Ahora se vigila el
      dia de calendario local y, cuando cambia, se vuelve a pedir la data y
      se re-renderiza dejando al usuario en la misma pestana y con la misma
      posicion de scroll.
   ============================================================ */
var TBD_SESSION_KEY = 'tbd_dolo_session';
var TBD_DATA_DAY = null;        // dia local en que se cargo la data que esta en pantalla
var TBD_REFRESH_BUSY = false;
var TBD_SNAPSHOT_NOTICE_SHOWN = false;

function tbdLocalDay(d){
  d = d || new Date();
  return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);
}
function tbdSaveSession(){
  try{
    var shell = document.getElementById('tbdShell');
    localStorage.setItem(TBD_SESSION_KEY, JSON.stringify({
      org: TBD_STATE.org, territory: TBD_STATE.territory, tab: TBD_STATE.tab,
      viewLayout: TBD_STATE.viewLayout, viewMode: TBD_STATE.viewMode,
      sbCollapsed: !!(shell && shell.classList.contains('sb-collapsed')),
      savedAt: Date.now()
    }));
  }catch(e){ /* modo privado o storage lleno: la sesion es un lujo, no se rompe nada */ }
}
function tbdLoadSession(){
  try{
    var raw = localStorage.getItem(TBD_SESSION_KEY);
    if(!raw) return null;
    var o = JSON.parse(raw);
    return (o && typeof o==='object') ? o : null;
  }catch(e){ return null; }
}
/* Restaura lo que no viaja en el hash. Devuelve el objeto para que tbdBoot()
   decida que hacer con marca/pais/pestana (el hash tiene prioridad). */
function tbdRestoreSession(){
  var o = tbdLoadSession();
  if(!o) return null;
  if(o.viewLayout==='isolated' || o.viewLayout==='continuous') TBD_STATE.viewLayout = o.viewLayout;
  if(o.viewMode && typeof o.viewMode==='object') TBD_STATE.viewMode = o.viewMode;
  return o;
}
function tbdApplySessionSidebar(o){
  if(!o || !o.sbCollapsed) return;
  var shell = document.getElementById('tbdShell');
  if(shell) shell.classList.add('sb-collapsed');
}

/* ---------- overlay ---------- */
function tbdRefreshOverlay(state, opts){
  var L = LANG, ex = document.getElementById('tbd-refresh-overlay');
  if(state==='hide'){ if(ex) ex.parentNode.removeChild(ex); return; }
  if(!ex){
    ex = document.createElement('div');
    ex.id = 'tbd-refresh-overlay';
    document.body.appendChild(ex);
  }
  opts = opts || {};
  if(state==='busy'){
    ex.innerHTML = '<div class="tbd-rf-card">'+
      '<div class="tbd-rf-spin"></div>'+
      '<div class="tbd-rf-h">'+esc(L==='en'?'Updating data…':L==='pt'?'Atualizando dados…':'Actualizando data…')+'</div>'+
      '<div class="tbd-rf-b">'+esc(L==='en'?'The calendar day changed, so the source numbers were refreshed. This takes a few seconds and you will come back to the same tab.'
        :L==='pt'?'O dia do calendario mudou, entao os numeros de origem foram atualizados. Leva alguns segundos e voce volta para a mesma aba.'
        :'Cambio el dia de calendario, asi que se volvieron a pedir los numeros de origen. Tarda unos segundos y vuelves a la misma pestana.')+'</div>'+
    '</div>';
    return;
  }
  if(state==='error'){
    ex.innerHTML = '<div class="tbd-rf-card">'+
      '<div class="tbd-rf-h">'+esc(L==='en'?'Could not refresh the data':L==='pt'?'Nao foi possivel atualizar os dados':'No se pudo actualizar la data')+'</div>'+
      '<div class="tbd-rf-b">'+esc(opts.msg||'')+' '+esc(L==='en'?'You are still looking at the numbers loaded on '+(TBD_DATA_DAY||'?')+'. Reload the page to try again.'
        :L==='pt'?'Voce ainda esta vendo os numeros carregados em '+(TBD_DATA_DAY||'?')+'. Recarregue a pagina para tentar de novo.'
        :'Sigues viendo los numeros cargados el '+(TBD_DATA_DAY||'?')+'. Recarga la pagina para volver a intentarlo.')+'</div>'+
      '<button class="tbd-rf-btn" data-close="1">'+esc(L==='en'?'Keep working':L==='pt'?'Continuar':'Seguir trabajando')+'</button>'+
    '</div>';
  }
  if(state==='snapshot'){
    ex.innerHTML = '<div class="tbd-rf-card">'+
      '<div class="tbd-rf-h">'+esc(L==='en'?'This file is a snapshot':L==='pt'?'Este arquivo e um retrato fixo':'Este archivo es una foto fija')+'</div>'+
      '<div class="tbd-rf-b">'+esc(L==='en'?'The calendar day changed while this was open. This is the downloadable version, with the data baked in, so it cannot refresh itself — its numbers are the ones from the day it was generated. Open the live dashboard to see today’s numbers.'
        :L==='pt'?'O dia do calendario mudou enquanto isto estava aberto. Esta e a versao para download, com os dados embutidos, entao nao consegue se atualizar — seus numeros sao os do dia em que foi gerada. Abra o dashboard ao vivo para ver os numeros de hoje.'
        :'Cambio el dia de calendario mientras esto estaba abierto. Esta es la version descargable, con la data embebida, asi que no puede actualizarse sola — sus numeros son los del dia en que se genero. Abre el dashboard en vivo para ver los numeros de hoy.')+'</div>'+
      '<button class="tbd-rf-btn" data-close="1">'+esc(L==='en'?'Understood':L==='pt'?'Entendido':'Entendido')+'</button>'+
    '</div>';
  }
  var btn = ex.querySelector('[data-close]');
  if(btn) btn.addEventListener('click', function(){ tbdRefreshOverlay('hide'); });
}

/* ---------- refresco real ---------- */
function tbdRefreshLiveData(){
  if(TBD_REFRESH_BUSY) return;
  // Standalone: la data va embebida, volver a pedirla daria lo mismo.
  if(typeof window.__TVADS_RELOAD_LIVE__ !== 'function'){
    if(TBD_SNAPSHOT_NOTICE_SHOWN) return;
    TBD_SNAPSHOT_NOTICE_SHOWN = true;
    TBD_DATA_DAY = tbdLocalDay();   // no se vuelve a avisar cada minuto
    tbdRefreshOverlay('snapshot');
    return;
  }
  TBD_REFRESH_BUSY = true;
  var keepTab = TBD_STATE.tab;
  var scroller = document.getElementById('tbd-main');
  var keepScroll = scroller ? scroller.scrollTop : 0;
  tbdRefreshOverlay('busy');
  window.__TVADS_RELOAD_LIVE__().then(function(){
    TBD_DATA_DAY = tbdLocalDay();
    TBD_STATE.tab = keepTab;
    tbdRenderNav();
    tbdRenderTab();
    tbdRenderStamp();
    var sc = document.getElementById('tbd-main');
    if(sc) sc.scrollTop = keepScroll;
    tbdSaveSession();
    tbdRefreshOverlay('hide');
    showToast(LANG==='en'?'Data updated to '+TBD_DATA_DAY+'.':LANG==='pt'?'Dados atualizados para '+TBD_DATA_DAY+'.':'Data actualizada al '+TBD_DATA_DAY+'.');
  }).catch(function(e){
    tbdRefreshOverlay('error', { msg: e && e.message ? e.message : '' });
  }).then(function(){ TBD_REFRESH_BUSY = false; });
}
function tbdCheckDayRollover(){
  if(!TBD_DATA_DAY) { TBD_DATA_DAY = tbdLocalDay(); return; }
  if(!document.getElementById('tbdShell')) return;
  var shell = document.getElementById('tbdShell');
  if(shell && shell.style.display === 'none') return;   // solo mientras TBD esta a la vista
  if(tbdLocalDay() !== TBD_DATA_DAY) tbdRefreshLiveData();
}
function tbdStartDayWatcher(){
  if(window.__TBD_DAY_WATCHER__) return;
  window.__TBD_DAY_WATCHER__ = true;
  TBD_DATA_DAY = TBD_DATA_DAY || tbdLocalDay();
  // Un minuto basta: el objetivo es que nadie lea data de ayer, no reaccionar
  // al segundo exacto de la medianoche.
  setInterval(tbdCheckDayRollover, 60000);
  // Cerrar y reabrir la laptop es el caso mas comun: al recuperar visibilidad
  // o foco se revisa de inmediato, sin esperar el siguiente tick.
  document.addEventListener('visibilitychange', function(){ if(!document.hidden) tbdCheckDayRollover(); });
  window.addEventListener('focus', tbdCheckDayRollover);
}
/* Sello visible de a que dia corresponde la data que se esta viendo. */
function tbdRenderStamp(){
  var el = document.getElementById('tbd-data-stamp');
  if(!el) return;
  var L = LANG, live = (typeof window.__TVADS_RELOAD_LIVE__==='function');
  el.textContent = (L==='en'?'Data as of ':L==='pt'?'Dados de ':'Data al ')+(TBD_DATA_DAY||'—')+(live?'':(L==='en'?' · snapshot':L==='pt'?' · retrato fixo':' · foto fija'));
}
function tbdBoot(){
  TBD_TERRITORIES = ['Brazil'].concat((COUNTRIES||[]).filter(function(c){ return c!=='TV LATAM Excl Arg Mex'; }).sort());
  if(TBD_TERRITORIES.indexOf(TBD_STATE.territory)===-1) TBD_STATE.territory = TBD_TERRITORIES[0];
  /* La sesion guardada se aplica PRIMERO y el hash la pisa despues: un enlace
     directo tiene que ganarle siempre a la ultima preferencia del usuario. */
  var sess = tbdRestoreSession();
  if(sess){
    if(sess.org && TBD_ORGS.indexOf(sess.org)!==-1) TBD_STATE.org = sess.org;
    if(sess.territory && TBD_TERRITORIES.indexOf(sess.territory)!==-1) TBD_STATE.territory = sess.territory;
    if(sess.tab && TBD_RENDERERS[sess.tab]) TBD_STATE.tab = sess.tab;
  }
  var h = tbdParseHash();
  if(h.tab) TBD_STATE.tab = h.tab;
  if(h.territory && TBD_TERRITORIES.indexOf(h.territory)!==-1) TBD_STATE.territory = h.territory;
  if(h.org && TBD_ORGS.indexOf(h.org)!==-1) TBD_STATE.org = h.org;
  if(TBD_STATE.org==='Open English Junior' && TBD_NAV.filter(function(g){return g.oeOnly;}).some(function(g){return g.items.some(function(it){return it.id===TBD_STATE.tab;});})) TBD_STATE.tab = 'portfolio';
  if(!window.__TBD_HASHCHANGE_WIRED__){ window.__TBD_HASHCHANGE_WIRED__ = true; window.addEventListener('hashchange', tbdOnHashChange); }
  tbdApplyBrandTheme();
  tbdRenderShell();
  tbdRenderLangBtns();
  tbdRenderLayoutToggle();
  tbdApplyTooltips();
  tbdWireSidebarToggle();
  tbdRenderNav();
  tbdRenderTab();
  if(!window.__TBD_PPT_WIRED__){ window.__TBD_PPT_WIRED__ = true; document.getElementById('tbd-btn-ppt').addEventListener('click', tbdDownloadPPT); tbdWireCreativeClicks(); tbdWireModalCleanup(); tbdWireTour(); }
  tbdApplySessionSidebar(sess);
  tbdStartDayWatcher();
  tbdRenderStamp();
  tbdSaveSession();
  if(!window.__TBD_APP_TOUR_DONE__){ window.__TBD_APP_TOUR_DONE__ = true; setTimeout(tbdMaybeAutoStartTour, 300); }
}
function tbdParseHash(){
  var m = /^#\/tbd\/([^/]+)(?:\/([^/]+))?(?:\/(.+))?$/.exec(location.hash);
  if(!m) return {};
  return { tab: m[1], territory: m[2] ? decodeURIComponent(m[2]) : null, org: m[3] ? decodeURIComponent(m[3]) : null };
}
function tbdHashString(){
  return '#/tbd/'+TBD_STATE.tab+'/'+encodeURIComponent(TBD_STATE.territory)+'/'+encodeURIComponent(TBD_STATE.org);
}
function tbdSetHash(){
  location.hash = tbdHashString();
  tbdSaveSession();
}
/* Actualiza la URL para que quede marcable (bookmarkeable) SIN disparar
   hashchange -- usado por el modo "vista continua" para que un clic de nav
   solo haga scroll a la seccion (nunca re-renderiza toda la pagina). */
function tbdSetHashSilent(){
  history.replaceState(null, '', tbdHashString());
}
function tbdOnHashChange(){
  if(!document.getElementById('tbdShell').classList.contains('ready')) return;
  var h = tbdParseHash();
  if(!h.tab) return;
  TBD_STATE.tab = h.tab;
  if(h.territory && TBD_TERRITORIES.indexOf(h.territory)!==-1) TBD_STATE.territory = h.territory;
  if(h.org && TBD_ORGS.indexOf(h.org)!==-1) TBD_STATE.org = h.org;
  tbdApplyBrandTheme();
  tbdRenderNav();
  tbdRenderFilters();
  tbdRenderTab();
}
function tbdRenderShell(){
  tbdRenderFilters();
}
function tbdRenderFilters(){
  var el = document.getElementById('tbd-filters');
  var collapsed = !!TBD_STATE.filtersCollapsed;
  var toggleTitle = collapsed
    ? (LANG==='en'?'Show filters':LANG==='pt'?'Mostrar filtros':'Mostrar filtros')
    : (LANG==='en'?'Hide filters':LANG==='pt'?'Ocultar filtros':'Ocultar filtros');
  var toggleBtn = '<button class="iconbtn" id="tbd-filters-toggle" title="'+escAttr(toggleTitle)+'">'+(collapsed?'▸':'◂')+'</button>';
  if(collapsed){
    var shortOrg = TBD_STATE.org==='Open English Junior' ? 'OE Jr' : 'OE';
    el.innerHTML = toggleBtn+'<div class="tbd-period-label" style="margin-left:8px;font-weight:700;color:var(--ink);">'+esc(shortOrg)+' · '+esc(TBD_STATE.territory)+'</div>';
    el.querySelector('#tbd-filters-toggle').addEventListener('click', function(){ TBD_STATE.filtersCollapsed = false; tbdRenderFilters(); });
    return;
  }
  el.innerHTML = toggleBtn+
    '<div class="tbd-seg" id="tbd-sel-org">'+TBD_ORGS.map(function(o){
    var short = o==='Open English Junior' ? 'Open English Junior' : 'Open English';
    return '<button data-o="'+escAttr(o)+'" class="'+(o===TBD_STATE.org?'active':'')+'">'+esc(short)+'</button>';
  }).join('')+'</div>'+
    '<div class="tbd-topbar-divider"></div>'+
    '<select class="tbd-select" id="tbd-sel-territory">'+TBD_TERRITORIES.map(function(t){
    return '<option value="'+escAttr(t)+'"'+(t===TBD_STATE.territory?' selected':'')+'>'+esc(t)+'</option>';
  }).join('')+'</select>'+
    '<div class="tbd-period-label">'+esc(tbdS('period_label'))+'</div>';
  el.querySelector('#tbd-filters-toggle').addEventListener('click', function(){ TBD_STATE.filtersCollapsed = true; tbdRenderFilters(); });
  Array.from(el.querySelectorAll('#tbd-sel-org button')).forEach(function(b){
    b.addEventListener('click', function(){
      TBD_STATE.org = b.dataset.o;
      if(TBD_STATE.org==='Open English Junior' && TBD_NAV.filter(function(g){return g.oeOnly;}).some(function(g){return g.items.some(function(it){return it.id===TBD_STATE.tab;});})) TBD_STATE.tab = 'portfolio';
      tbdSetHash();
    });
  });
  el.querySelector('#tbd-sel-territory').addEventListener('change', function(e){ TBD_STATE.territory = e.target.value; tbdSetHash(); });
}
/* Tooltips (title=) de los botones del header: viven en el HTML estatico, asi
   que hay que reescribirlos cada vez que cambia el idioma o quedarian
   congelados en ingles. */
function tbdApplyTooltips(){
  var L = LANG;
  var t = {
    tour: L==='en'?'Guided tour of the whole report':L==='pt'?'Tour guiado do relatório inteiro':'Recorrido guiado de todo el reporte',
    theme: L==='en'?'Switch between light and dark mode':L==='pt'?'Alternar entre modo claro e escuro':'Alternar entre modo claro y oscuro',
    ppt: L==='en'?'Download the PowerPoint (Spanish, English and Portuguese)':L==='pt'?'Baixar o PowerPoint (espanhol, inglês e português)':'Descargar el PowerPoint (español, inglés y portugués)',
    sidebar: L==='en'?'Show / hide the filters panel':L==='pt'?'Mostrar / ocultar o painel de filtros':'Mostrar / ocultar el panel de filtros',
  };
  function set(id, txt){ var el=document.getElementById(id); if(el) el.setAttribute('title', txt); }
  set('tbd-btn-tour', t.tour);
  set('tbd-btn-theme', t.theme);
  set('tbd-btn-ppt', t.ppt);
  set('tbd-sidebar-toggle', t.sidebar);
}
/* Colapsar el panel de filtros de 20% a 0% -- mismo comportamiento que el
   boton del dashboard "TV Ads Performance". */
function tbdWireSidebarToggle(){
  var btn = document.getElementById('tbd-sidebar-toggle');
  if(!btn || btn.dataset.wired) return;
  btn.dataset.wired = '1';
  btn.addEventListener('click', function(){
    document.getElementById('tbdShell').classList.toggle('sb-collapsed');
    tbdSaveSession();
  });
}
function tbdRenderLangBtns(){
  var el = document.getElementById('tbd-lang-btns');
  if(!el) return;
  el.innerHTML = ['en','es','pt'].map(function(l){ return '<button class="iconbtn'+(LANG===l?' active':'')+'" data-lang="'+l+'">'+l.toUpperCase()+'</button>'; }).join('');
  Array.from(el.querySelectorAll('button')).forEach(function(b){
    b.addEventListener('click', function(){ LANG=b.dataset.lang; localStorage.setItem('tvads_lang',LANG); tbdRenderLangBtns(); tbdRenderLayoutToggle(); tbdApplyTooltips(); tbdRenderNav(); tbdRenderFilters(); tbdRenderTab(); });
  });
}
/* grupos colapsables del nav -- mismo patron que SB_COLLAPSED/sbGroup() del
   dashboard principal (reusa esas mismas clases CSS .sb-group*), asi el
   usuario puede plegar dimensiones que no le interesan por ahora y quedarse
   solo con las que si. */
var TBD_NAV_COLLAPSED = {};
function tbdRenderNav(){
  var el = document.getElementById('tbd-nav');
  var groups = TBD_NAV.filter(function(g){ return !g.oeOnly || TBD_STATE.org!=='Open English Junior'; });
  el.innerHTML = groups.map(function(g){
    var collapsed = !!TBD_NAV_COLLAPSED[g.key];
    var body = g.items.map(function(it){
      return '<a class="tbd-nav-link'+(it.id===TBD_STATE.tab?' active':'')+'" data-tab="'+it.id+'">'+esc(tbdT(it.label))+'</a>';
    }).join('');
    return '<div class="sb-group tbd-nav-sbgroup'+(collapsed?' collapsed':'')+'">'+
      '<div class="sb-group-head" data-tbdnavtoggle="'+escAttr(g.key)+'"><span>'+esc(tbdT(g.group))+'</span><span class="sb-group-chevron">▾</span></div>'+
      '<div class="sb-group-body">'+body+'</div>'+
    '</div>';
  }).join('');
  Array.from(el.querySelectorAll('[data-tbdnavtoggle]')).forEach(function(h){
    h.addEventListener('click', function(){ var k=h.dataset.tbdnavtoggle; TBD_NAV_COLLAPSED[k]=!TBD_NAV_COLLAPSED[k]; tbdRenderNav(); });
  });
  Array.from(el.querySelectorAll('.tbd-nav-link')).forEach(function(a){
    a.addEventListener('click', function(){
      TBD_STATE.tab = a.dataset.tab;
      // en vista continua todo el contenido ya esta en el DOM -- un clic de
      // nav solo tiene que desplazar hacia esa seccion (ancla), nunca
      // re-renderizar toda la pagina de nuevo.
      if(TBD_STATE.viewLayout==='continuous' && document.getElementById('tbd-sec-'+TBD_STATE.tab)){
        tbdSetHashSilent();
        tbdRenderNav();
        tbdScrollToSection(TBD_STATE.tab, false);
      } else {
        tbdSetHash();
      }
    });
  });
}
function tbdScrollToSection(tabId, instant){
  var sec = document.getElementById('tbd-sec-'+tabId);
  if(!sec) return;
  // mientras dura el scroll programatico el spy no debe reescribir la
  // seccion activa con las secciones por las que va pasando
  TBD_SPY_SUPPRESS_UNTIL = Date.now() + (instant ? 150 : 900);
  sec.scrollIntoView({ behavior: instant?'auto':'smooth', block:'start' });
}
function tbdRenderLayoutToggle(){
  var el = document.getElementById('tbd-layout-toggle-wrap');
  if(!el) return;
  var L = LANG;
  var checked = TBD_STATE.viewLayout==='continuous';
  var label = checked
    ? (L==='en'?'Continuous view':L==='pt'?'Vista contínua':'Vista continua')
    : (L==='en'?'Isolated view':L==='pt'?'Vista isolada':'Vista aislada');
  el.className = 'tbd-layout-toggle';
  el.innerHTML = '<label class="tbd-switch" title="'+escAttr(L==='en'?'Switch between isolated tabs and one continuous scrolling page':L==='pt'?'Alterna entre abas isoladas e uma página contínua com scroll':'Alterna entre pestañas aisladas y una página continua con scroll')+'">'+
    '<input type="checkbox" id="tbd-layout-toggle"'+(checked?' checked':'')+'><span class="tbd-switch-slider"></span></label>'+
    '<span class="tbd-layout-toggle-label" id="tbd-layout-label">'+esc(label)+'</span>';
  document.getElementById('tbd-layout-toggle').addEventListener('change', function(e){
    TBD_STATE.viewLayout = e.target.checked ? 'continuous' : 'isolated';
    tbdRenderLayoutToggle();
    tbdRenderTab();
  });
}
function tbdCurrentData(){
  var territory = TBD_STATE.territory, region = tbdRegionOf(territory), pais = tbdPaisOf(territory);
  var d25 = tbdCreativesForPeriod(territory, region, '2025', pais, null);
  var d26 = tbdCreativesForPeriod(territory, region, '2026', pais, null);
  var v25 = tbdVideoRowsForPeriod(territory, region, '2025', pais, null);
  var v26 = tbdVideoRowsForPeriod(territory, region, '2026', pais, null);
  return { territory:territory, region:region, pais:pais, y25:d25, y26:d26, v25:v25, v26:v26, p25: tbdPortfolio(d25), p26: tbdPortfolio(d26) };
}
var TBD_LAST_DATA = null;
function tbdRenderTab(){
  var data = tbdCurrentData();
  TBD_LAST_DATA = data;
  TBD_DRILL = {}; // el DOM anterior se descarta entero: los ids viejos ya no existen
  if(TBD_STATE.viewLayout==='continuous'){ tbdRenderContinuousPage(data); return; }
  document.getElementById('tbd-page').scrollTop = 0;
  var fn = TBD_RENDERERS[TBD_STATE.tab] || TBD_RENDERERS.portfolio;
  document.getElementById('tbd-page').innerHTML = fn(data);
  Array.from(document.querySelectorAll('[data-tbd-jump]')).forEach(function(a){
    a.addEventListener('click', function(){ TBD_STATE.tab = a.dataset.tbdJump; tbdSetHash(); });
  });
}
/* "Vista continua": todas las pestanas concatenadas en una sola pagina
   larga, cada una en su propia <section id="tbd-sec-{id}">. Los links de
   nav (ver tbdRenderNav) y los [data-tbd-jump] internos hacen scroll suave
   a la seccion en vez de reemplazar el contenido. */
function tbdRenderContinuousPage(data){
  var el = document.getElementById('tbd-page');
  var groups = TBD_NAV.filter(function(g){ return !g.oeOnly || TBD_STATE.org!=='Open English Junior'; });
  var html = '';
  groups.forEach(function(g){
    g.items.forEach(function(it){
      var fn = TBD_RENDERERS[it.id];
      if(!fn) return;
      var body;
      try{ body = fn(data); }catch(e){ body = '<p style="color:var(--bad);">'+esc(it.id)+': '+esc(e.message)+'</p>'; }
      html += '<section id="tbd-sec-'+it.id+'" class="tbd-cont-section">'+body+'</section>';
    });
  });
  el.innerHTML = html;
  Array.from(el.querySelectorAll('[data-tbd-jump]')).forEach(function(a){
    a.addEventListener('click', function(){ TBD_STATE.tab = a.dataset.tbdJump; tbdSetHashSilent(); tbdRenderNav(); tbdScrollToSection(TBD_STATE.tab, false); });
  });
  // Al re-renderizar por un toggle local, hay que volver a la seccion donde
  // estaba el usuario (la del toggle), no a TBD_STATE.tab -- si no, la pagina
  // "salta" a otra seccion al cambiar Ad Name/Video Name.
  var target = TBD_RESTORE_SECTION || TBD_STATE.tab;
  TBD_RESTORE_SECTION = null;
  tbdScrollToSection(target, true);
  tbdWireScrollSpy();
}
/* ---------- scroll spy (solo vista continua) ----------
   Mantiene el menu izquierdo sincronizado con la seccion que el usuario
   realmente esta viendo. Sin esto, TBD_STATE.tab se queda con la ultima
   seccion clicada y cualquier re-render (ej. un toggle local) devuelve el
   scroll a esa seccion vieja. */
var TBD_RESTORE_SECTION = null;
var TBD_SPY_WIRED = false;
var TBD_SPY_SUPPRESS_UNTIL = 0;
function tbdSectionInView(){
  var main = document.getElementById('tbd-main');
  if(!main) return null;
  var secs = document.querySelectorAll('.tbd-cont-section');
  if(!secs.length) return null;
  var mainTop = main.getBoundingClientRect().top;
  var best = null, bestTop = -Infinity;
  for(var i=0;i<secs.length;i++){
    var top = secs[i].getBoundingClientRect().top - mainTop;
    if(top <= 90 && top > bestTop){ bestTop = top; best = secs[i]; }
  }
  if(!best) best = secs[0];
  return best.id.replace('tbd-sec-','');
}
function tbdHighlightNav(tabId){
  Array.from(document.querySelectorAll('.tbd-nav-link')).forEach(function(a){
    a.classList.toggle('active', a.dataset.tab===tabId);
  });
}
function tbdWireScrollSpy(){
  if(TBD_SPY_WIRED) return;
  TBD_SPY_WIRED = true;
  var main = document.getElementById('tbd-main');
  if(!main) return;
  var pending = false;
  main.addEventListener('scroll', function(){
    if(TBD_STATE.viewLayout!=='continuous') return;
    if(pending) return;
    pending = true;
    requestAnimationFrame(function(){
      pending = false;
      // ignora el scroll programatico inmediato tras un clic de nav/ancla
      if(Date.now() < TBD_SPY_SUPPRESS_UNTIL) return;
      var id = tbdSectionInView();
      if(!id || id===TBD_STATE.tab) return;
      TBD_STATE.tab = id;
      tbdHighlightNav(id);
      tbdSetHashSilent();
    });
  }, {passive:true});
}
/* Delegacion de click para nombres de creativo (nunca cambian de referencia
   en el DOM porque #tbd-page se reemplaza entero en cada render -- por eso
   un solo listener delegado alcanza, sin importar cuantas veces se re-dibuje). */
function tbdWireCreativeClicks(){
  document.getElementById('tbd-page').addEventListener('click', function(e){
    var vt = e.target.closest('[data-tbd-viewtoggle]');
    if(vt){
      var tabOfToggle = vt.dataset.tbdViewtoggle;
      TBD_STATE.viewMode[tabOfToggle] = vt.dataset.mode;
      if(TBD_STATE.viewLayout==='continuous'){
        // el usuario esta parado en la seccion de ese toggle: no lo muevas
        TBD_STATE.tab = tabOfToggle;
        TBD_RESTORE_SECTION = tabOfToggle;
        tbdHighlightNav(tabOfToggle);
      }
      tbdRenderTab();
      return;
    }
    var a = e.target.closest('[data-tbd-creative]');
    if(a){ tbdOpenCreativeModal(a.dataset.tbdCreative, a.dataset.tbdYear); return; }
    var dr = e.target.closest('[data-tbd-drill]');
    if(dr){ tbdOpenDimDrillModal(dr.dataset.tbdDrill, dr.dataset.tbdCat); }
  });
  // dentro del modal de desglose, el nombre del creativo abre su propia ficha
  document.getElementById('modal-body').addEventListener('click', function(e){
    var a = e.target.closest('[data-tbd-creative]');
    if(!a) return;
    tbdOpenCreativeModal(a.dataset.tbdCreative, a.dataset.tbdYear);
  });
}
/* ---------- toggle local Ad Name (agrupado) / Video Name (por version), uno
   por seccion -- cada tab de listado de creativos (Portfolio/Promo/Generic)
   lo controla independientemente via TBD_STATE.viewMode[tabId]. ---------- */
function tbdViewToggleHTML(tabId){
  var mode = TBD_STATE.viewMode[tabId] || 'adname';
  var L = LANG;
  var lbl1 = L==='en'?'Ad Name (grouped)':L==='pt'?'Ad Name (agrupado)':'Ad Name (agrupado)';
  var lbl2 = L==='en'?'Video Name (by version)':L==='pt'?'Video Name (por versão)':'Video Name (por versión)';
  return '<div class="tbd-viewtoggle"><div class="tbd-seg">'+
    '<button data-tbd-viewtoggle="'+tabId+'" data-mode="adname" class="'+(mode==='adname'?'active':'')+'">'+esc(lbl1)+'</button>'+
    '<button data-tbd-viewtoggle="'+tabId+'" data-mode="video" class="'+(mode==='video'?'active':'')+'">'+esc(lbl2)+'</button>'+
    '</div></div>';
}

/* ============================ helpers de formato/HTML ============================ */
function tbdArrow(v25, v26, higherBetter){
  if(v25==null || v26==null) return '';
  var delta = v26-v25, good = higherBetter ? delta>=0 : delta<=0;
  return ' <span style="font-size:10px;font-weight:800;color:'+(good?'var(--good)':'var(--bad)')+'">'+(delta>=0?'▲':'▼')+'</span>';
}
function tbdKpiCard(label, v25, v26, fmtFn, higherBetter){
  return '<div class="tbd-kpi-card"><div class="tbd-kpi-label">'+esc(label)+'</div>'+
    '<div class="tbd-kpi-value">'+fmtFn(v25)+' → '+fmtFn(v26)+tbdArrow(v25,v26,higherBetter)+'</div>'+
    '<div class="tbd-kpi-sub">'+esc(tbdS('y25_label'))+' → '+esc(tbdS('y26_label'))+'</div></div>';
}
function tbdCreativeNameLinkHTML(r, year, showPain){
  var pain = showPain && r.pain_point ? '<br><small class="tbd-pain">'+esc(r.pain_point)+'</small>' : '';
  return '<a class="tbd-name-link" data-tbd-creative="'+escAttr(r.nombre)+'" data-tbd-year="'+year+'">'+esc(r.nombre)+(r.is_grouped?' <span class="tbd-badge">'+r.versions.length+'v</span>':'')+'</a>'+pain;
}
/* ---------- color condicional por columna (verde=top, rojo=bottom, ---------- por
   columna, no por fila -- espejo de la funcion sv() del proyecto de referencia
   (top=3, bottom=2), con guarda para listas chicas donde eso sobre-colorearia
   casi toda la tabla. */
function tbdRankColor(items, valFn, higherBetter){
  var vals = items.map(valFn).filter(function(v){ return v!=null && isFinite(v); });
  var uniq = Array.from(new Set(vals));
  // Con 2+ valores distintos ya tiene sentido marcar mejor/peor. El numero de
  // celdas marcadas escala con el tamano de la tabla (top 3 / bottom 2 en
  // tablas grandes, 1 y 1 en tablas chicas) para que el color siga siendo una
  // senal y no pinte la tabla entera.
  if(uniq.length<2) return function(){ return ''; };
  var top = uniq.length>=5 ? 3 : 1, bot = uniq.length>=5 ? 2 : 1;
  var asc = uniq.slice().sort(function(a,b){return a-b;}), desc = asc.slice().reverse();
  var bestSet = new Set((higherBetter?desc:asc).slice(0,top));
  var worstSet = new Set((higherBetter?asc:desc).slice(0,bot));
  return function(v){
    if(v==null || !isFinite(v)) return '';
    if(bestSet.has(v)) return 'color:var(--good);font-weight:700;';
    if(worstSet.has(v)) return 'color:var(--bad);font-weight:700;';
    return '';
  };
}
function tbdCreativeRowsHTML(items, year){
  var cL1k = tbdRankColor(items, function(r){return r.l1k;}, true);
  var cL1kAdj = tbdRankColor(items, function(r){return r.l1k_adj;}, true);
  var cCpl = tbdRankColor(items, function(r){return r.cpl_adj;}, false);
  var cCvr = tbdRankColor(items, function(r){return r.cvr;}, true);
  var cMncc = tbdRankColor(items, function(r){return r.mncc;}, true);
  return items.map(function(r, i){
    return '<tr><td>'+(i+1)+'</td><td>'+tbdCreativeNameLinkHTML(r, year, true)+
      '</td><td><span class="tbd-badge">'+esc(r.ad_type||'—')+'</span></td><td>'+fmtNum(r.l,0)+'</td><td style="'+cL1k(r.l1k)+'">'+fmtNum(r.l1k,0)+'</td>'+
      '<td class="tbd-adj" style="'+cL1kAdj(r.l1k_adj)+'"><b>'+fmtNum(r.l1k_adj,0)+'</b></td><td class="tbd-adj" style="'+cCpl(r.cpl_adj)+'">'+fmt$(r.cpl_adj,2)+'</td><td>'+r.n+'</td><td>'+fmt$(r.s,0)+'</td><td style="'+cCvr(r.cvr)+'">'+fmtPct(r.cvr,1)+'</td><td style="'+cMncc(r.mncc)+'">'+fmtPct(r.mncc,1)+'</td></tr>';
  }).join('') || '<tr><td colspan="10" style="text-align:center;color:var(--ink-faint);padding:16px;">'+T('sin_datos_filtro')+'</td></tr>';
}
function tbdCreativeTableHTML(items, yearLabel, year){
  return '<div><div style="font-size:11px;font-weight:800;text-transform:uppercase;color:var(--ink-faint);margin-bottom:6px;">'+esc(yearLabel)+' · '+items.length+' '+esc(tbdS('creatives_word'))+'</div>'+
    '<div style="overflow-x:auto;"><table class="tbd-table"><thead><tr><th>'+esc(tbdS('col_hash'))+'</th><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdS('col_type'))+'</th><th>'+esc(tbdS('col_leads'))+'</th><th>'+esc(tbdS('col_l1k'))+'</th><th>'+esc(tbdS('col_l1k_adj'))+'</th><th>'+esc(tbdS('col_cpl_adj'))+'</th><th>'+esc(tbdS('col_days'))+'</th><th>'+esc(tbdS('col_spend'))+'</th><th>'+esc(tbdS('col_cvr'))+'</th><th>'+esc(tbdS('col_mncc'))+'</th></tr></thead>'+
    '<tbody>'+tbdCreativeRowsHTML(items, year)+'</tbody></table></div></div>';
}
/* ---------- drill-down de dimensiones: registro por render ----------
   Cada tabla de dimension registra aqui los creativos crudos que la componen,
   para que un clic en una fila pueda abrir el desglose y mostrar de donde
   sale la matematica. Se limpia en cada tbdRenderTab() porque #tbd-page se
   reemplaza entero (los ids viejos dejarian de existir en el DOM). */
var TBD_DRILL = {};
var TBD_DRILL_SEQ = 0;
function tbdRegisterDrill(items, keyFn, title, yearLabel, year){
  var id = 'd'+(++TBD_DRILL_SEQ);
  TBD_DRILL[id] = { items:items, keyFn:keyFn, title:title, yearLabel:yearLabel, year:year };
  return id;
}
function tbdDimTableHTML(rollup, title, items, keyFn, yearLabel, year){
  var drillId = (items && keyFn) ? tbdRegisterDrill(items, keyFn, title, yearLabel, year) : null;
  var cL1kAdj = tbdRankColor(rollup, function(r){return r.l1k_adj;}, true);
  var cCpl = tbdRankColor(rollup, function(r){return r.cpl_adj;}, false);
  var cCvr = tbdRankColor(rollup, function(r){return r.cvr;}, true);
  var rows = rollup.map(function(r){
    var attrs = drillId ? ' class="tbd-drill-row" data-tbd-drill="'+drillId+'" data-tbd-cat="'+escAttr(r.label)+'"' : '';
    return '<tr'+attrs+'><td>'+esc(r.label)+(drillId?' <span class="tbd-drill-hint">▸</span>':'')+'</td><td>'+r.n+'</td>'+
      '<td class="tbd-adj" style="'+cL1kAdj(r.l1k_adj)+'"><b>'+fmtNum(r.l1k_adj,0)+'</b></td>'+
      '<td class="tbd-adj" style="'+cCpl(r.cpl_adj)+'">'+fmt$(r.cpl_adj,2)+'</td>'+
      '<td style="'+cCvr(r.cvr)+'">'+fmtPct(r.cvr,1)+'</td><td>'+fmt$(r.s,0)+'</td></tr>';
  }).join('') || '<tr><td colspan="6" style="text-align:center;color:var(--ink-faint);padding:16px;">'+T('sin_datos_filtro')+'</td></tr>';
  return '<div style="overflow-x:auto;"><table class="tbd-table"><thead><tr><th>'+esc(title)+'</th><th>'+esc(tbdS('col_creatives_n'))+'</th><th>'+esc(tbdS('col_l1k_adj'))+'</th><th>'+esc(tbdS('col_cpl_adj'))+'</th><th>'+esc(tbdS('col_cvr'))+'</th><th>'+esc(tbdS('col_spend'))+'</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
}
/* Desglose de una categoria: los creativos que la componen + la fila TOTAL
   (que debe reconciliar exactamente con la fila de la tabla de dimension).
   El total se recalcula con tbdDimensionRollup sobre el mismo subconjunto,
   nunca se copia el numero de la tabla -- asi el modal es una verificacion
   real de la matematica, no un eco de ella. */
function tbdOpenDimDrillModal(drillId, category){
  var reg = TBD_DRILL[drillId];
  if(!reg) return;
  var members = reg.items.filter(function(r){ return String(reg.keyFn(r))===String(category); });
  if(!members.length) return;
  var total = tbdDimensionRollup(members, function(){ return 'TOTAL'; })[0];
  var L = LANG;
  var sorted = members.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; });
  var cL1k = tbdRankColor(sorted, function(r){return r.l1k;}, true);
  var cL1kAdj = tbdRankColor(sorted, function(r){return r.l1k_adj;}, true);
  var cCpl = tbdRankColor(sorted, function(r){return r.cpl_adj;}, false);
  var cCvr = tbdRankColor(sorted, function(r){return r.cvr;}, true);
  var head = '<tr><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdS('col_leads'))+'</th><th>'+esc(tbdS('col_spend'))+'</th><th>'+esc(tbdS('col_days'))+'</th><th>'+esc(tbdS('col_l1k'))+'</th><th>'+esc(tbdS('col_l1k_adj'))+'</th><th>'+esc(tbdS('col_cpl_adj'))+'</th><th>'+esc(tbdS('col_cvr'))+'</th></tr>';
  var body = sorted.map(function(r){
    return '<tr><td>'+tbdCreativeNameLinkHTML(r, reg.year, false)+'</td><td>'+fmtNum(r.l,0)+'</td><td>'+fmt$(r.s,0)+'</td><td>'+r.n+'</td>'+
      '<td style="'+cL1k(r.l1k)+'">'+fmtNum(r.l1k,0)+'</td>'+
      '<td class="tbd-adj" style="'+cL1kAdj(r.l1k_adj)+'"><b>'+fmtNum(r.l1k_adj,0)+'</b></td>'+
      '<td class="tbd-adj" style="'+cCpl(r.cpl_adj)+'">'+fmt$(r.cpl_adj,2)+'</td>'+
      '<td style="'+cCvr(r.cvr)+'">'+fmtPct(r.cvr,1)+'</td></tr>';
  }).join('');
  var totalLabel = L==='en'?'TOTAL (this is the row in the table)':L==='pt'?'TOTAL (é esta a linha da tabela)':'TOTAL (esta es la fila de la tabla)';
  var totalLeads = members.reduce(function(s,r){return s+r.l;},0);
  var totalSpend = members.reduce(function(s,r){return s+r.s;},0);
  var totalDays = members.reduce(function(s,r){return s+r.n;},0);
  var totalRow = '<tr class="tbd-drill-total"><td>'+esc(totalLabel)+'</td><td>'+fmtNum(totalLeads,0)+'</td><td>'+fmt$(totalSpend,0)+'</td><td>'+totalDays+'</td>'+
    '<td>'+fmtNum(total.l1k,0)+'</td><td class="tbd-adj"><b>'+fmtNum(total.l1k_adj,0)+'</b></td><td class="tbd-adj">'+fmt$(total.cpl_adj,2)+'</td><td>'+fmtPct(total.cvr,1)+'</td></tr>';
  var mathNote = L==='en'
    ? 'The TOTAL row is not an average of the rows above it: leads and spend are summed first, then L/$1k = total leads ÷ total spend × 1,000. That is why a creative with few days can show a high L/$1k of its own and still barely move the total. "Days" adds up each creative\'s own active days, so it can exceed the calendar days of the period when several creatives aired the same day.'
    : L==='pt'
    ? 'A linha TOTAL não é uma média das linhas acima: leads e gasto são somados primeiro, e então L/$1k = leads totais ÷ gasto total × 1.000. Por isso um criativo com poucos dias pode ter um L/$1k próprio alto e ainda assim mal mexer no total. "Dias" soma os dias ativos de cada criativo, então pode passar dos dias corridos do período quando vários criativos foram ao ar no mesmo dia.'
    : 'La fila TOTAL no es un promedio de las filas de arriba: primero se suman leads y gasto, y después L/$1k = leads totales ÷ gasto total × 1.000. Por eso un creativo con pocos días puede tener un L/$1k propio alto y aun así mover muy poco el total. "Días" suma los días activos de cada creativo, así que puede superar los días calendario del período cuando varios creativos salieron al aire el mismo día.';
  var eyebrow = (reg.yearLabel? reg.yearLabel+' · ':'')+reg.title+' · '+members.length+' '+tbdS('creatives_word');
  document.getElementById('modal-card').classList.add('tbd-wide');
  document.getElementById('modal-eyebrow').textContent = eyebrow;
  document.getElementById('modal-title').textContent = String(category);
  document.getElementById('modal-body').innerHTML =
    '<div class="tbd-note">'+esc(mathNote)+'</div>'+
    '<div style="overflow-x:auto;"><table class="tbd-table"><thead>'+head+'</thead><tbody>'+body+totalRow+'</tbody></table></div>';
  document.getElementById('modal-backdrop').classList.add('open');
}
/* ============================ tarjetas "cómo se lee" + "insight experto" por pestana ============================
   Cada pestana del nav (19 en total) debe traer AMBAS tarjetas: una que explica
   como leer esa vista puntual (TBD_HOWTO, texto fijo trilingue) y una con
   interpretacion real hecha sobre los datos de esa vista (nunca solo repetir
   la tabla) -- ver tbdHowToCard()/tbdTakeawayBox() y las funciones tbd*Insight
   de mas abajo, una por pestana que no tenia ya una (promo/generic/jrhalo/
   launch/wearout/adjkpi/insights/tests/methodology). */
var TBD_HOWTO = {
  adjkpi: {en:'This page explains, in words, the single most important idea in the whole app: why raw numbers alone can lie about a creative\'s quality. Read it once before trusting any ranking elsewhere.', es:'Esta página explica, en palabras, la idea más importante de toda la app: por qué los números crudos solos pueden mentir sobre la calidad de un creativo. Léela una vez antes de confiar en cualquier ranking del resto del dashboard.', pt:'Esta página explica, em palavras, a ideia mais importante de todo o app: por que os números brutos sozinhos podem enganar sobre a qualidade de um criativo. Leia uma vez antes de confiar em qualquer ranking do resto do dashboard.'},
  portfolio: {en:'The 5 cards compare the WHOLE portfolio, 2025 vs 2026 (not one creative). The two tables below show the Top 10 creatives of each year by demand-adjusted L/$1k — use them to spot which names repeat at the top across years. The toggle above the tables switches between Ad Name (versions merged) and Video Name (each version competing on its own).', es:'Las 5 tarjetas comparan el portafolio COMPLETO, 2025 vs 2026 (no un creativo puntual). Las dos tablas de abajo muestran el Top 10 de creativos de cada año por L/$1k ajustado por demanda — úsalas para ver qué nombres se repiten arriba entre años. El interruptor arriba de las tablas cambia entre Ad Name (versiones fusionadas) y Video Name (cada versión compitiendo por su cuenta).', pt:'Os 5 cartões comparam o portfólio INTEIRO, 2025 vs 2026 (não um criativo específico). As duas tabelas abaixo mostram o Top 10 de criativos de cada ano por L/$1k ajustado por demanda — use-as para ver quais nomes se repetem no topo entre os anos. O alternador acima das tabelas muda entre Ad Name (versões fundidas) e Video Name (cada versão competindo por conta própria).'},
  promo: {en:'Ranked by demand-adjusted L/$1k (★), highest first — this is the fair ranking across months. Raw L/$1k next to it is only useful for planning actual volume in a specific flight window, not for comparing creative quality. Toggle to Video Name to see V1/V2/V3 compete directly instead of merged into one Ad Name.', es:'Ordenado por L/$1k ajustado por demanda (★), de mayor a menor — ese es el ranking justo entre meses. El L/$1k crudo al lado solo sirve para planear volumen real en una ventana de flight específica, no para comparar calidad creativa. Cambia a Video Name para ver a V1/V2/V3 competir directamente en vez de fusionados en un solo Ad Name.', pt:'Ordenado por L/$1k ajustado por demanda (★), do maior para o menor — esse é o ranking justo entre meses. O L/$1k bruto ao lado só serve para planejar volume real numa janela de flight específica, não para comparar qualidade criativa. Mude para Video Name para ver V1/V2/V3 competindo diretamente em vez de fundidos num só Ad Name.'},
  generic: {en:'Same ranking logic as Promo, but only for creatives with no explicit offer — compare this list against Promo\'s to see whether an explicit offer is actually needed to perform well in this territory. Toggle to Video Name to see V1/V2/V3 compete directly.', es:'Misma lógica de ranking que Promo, pero solo para creativos sin oferta explícita — compara esta lista contra la de Promo para ver si de verdad hace falta una oferta explícita para rendir bien en este territorio. Cambia a Video Name para ver a V1/V2/V3 competir directamente.', pt:'Mesma lógica de ranking que Promo, mas só para criativos sem oferta explícita — compare esta lista com a de Promo para ver se realmente é preciso uma oferta explícita para performar bem neste território. Mude para Video Name para ver V1/V2/V3 competindo diretamente.'},
  pvg: {en:'Two one-row rollups (all Promo creatives combined vs. all Generic combined), not individual creatives — this answers "does having an offer help on average", separate from which specific creative wins.', es:'Dos rollups de una fila (todos los Promo combinados vs. todos los Generic combinados), no creativos individuales — esto responde "¿ayuda tener oferta en promedio?", aparte de cuál creativo puntual gana.', pt:'Dois rollups de uma linha (todos os Promo combinados vs. todos os Generic combinados), não criativos individuais — isso responde "ter oferta ajuda em média?", à parte de qual criativo específico vence.'},
  tone: {en:'Creatives grouped by tone (Humor, Motivational, Corporative, Commemorative) and rolled up — a tone with few creatives (small n) can look artificially strong, always check n before trusting the top row.', es:'Creativos agrupados por tono (Humor, Motivational, Corporative, Commemorative) y sumados — un tono con pocos creativos (n chico) puede verse artificialmente fuerte, siempre revisa n antes de confiar en la fila de arriba.', pt:'Criativos agrupados por tom (Humor, Motivational, Corporative, Commemorative) e somados — um tom com poucos criativos (n pequeno) pode parecer artificialmente forte, sempre confira o n antes de confiar na linha do topo.'},
  hooks: {en:'Two separate rollups stacked: how the creative opens its AUDIO, then how it opens VISUALLY — a hook type can win on audio and lose on visual (or vice versa), read both before recommending one.', es:'Dos rollups separados, uno debajo del otro: cómo abre el AUDIO del creativo, y cómo abre VISUALMENTE — un tipo de hook puede ganar en audio y perder en visual (o al revés), lee ambos antes de recomendar uno.', pt:'Dois rollups separados, um embaixo do outro: como o ÁUDIO do criativo abre, e como ele abre VISUALMENTE — um tipo de hook pode vencer no áudio e perder no visual (ou o contrário), leia os dois antes de recomendar um.'},
  versions: {en:'Uses raw Video Names (V1/V2/V3), unlike every other tab which groups by Ad Name — this is the one place designed specifically to see whether a "V2" revision actually improved on its "V1".', es:'Usa los Video Names crudos (V1/V2/V3), a diferencia de cualquier otra pestaña que agrupa por Ad Name — este es el único lugar diseñado específicamente para ver si una revisión "V2" de verdad mejoró sobre su "V1".', pt:'Usa os Video Names brutos (V1/V2/V3), diferente de qualquer outra aba que agrupa por Ad Name — este é o único lugar desenhado especificamente para ver se uma revisão "V2" realmente melhorou sobre sua "V1".'},
  campaigns: {en:'Rolled up by campaign_name — useful to see if a campaign\'s strength comes from one hero creative or is consistent across everything tagged under it.', es:'Sumado por campaign_name — útil para ver si la fuerza de una campaña viene de un solo creativo estrella o es pareja entre todo lo etiquetado bajo ella.', pt:'Somado por campaign_name — útil para ver se a força de uma campanha vem de um único criativo âncora ou é consistente entre tudo o que está marcado sob ela.'},
  promo_type: {en:'Promo creatives only, split by the specific offer/pain point they lead with — this is the closest thing to "which discount or angle actually converts" in this dashboard.', es:'Solo creativos Promo, divididos por la oferta/pain point específico con el que abren — esto es lo más cercano a "qué descuento o ángulo realmente convierte" en este dashboard.', pt:'Apenas criativos Promo, divididos pela oferta/pain point específico com que abrem — isso é o mais próximo de "qual desconto ou ângulo realmente converte" neste dashboard.'},
  theme: {en:'Rolled up by the creative\'s thematic mechanism (the underlying story device, not just Promo/Generic) — use it to see which storytelling angle actually pulls its weight.', es:'Sumado por el mecanismo temático del creativo (el recurso narrativo de fondo, no solo Promo/Generic) — úsalo para ver qué ángulo narrativo realmente rinde.', pt:'Somado pelo mecanismo temático do criativo (o recurso narrativo de fundo, não só Promo/Generic) — use para ver qual ângulo narrativo realmente rende.'},
  ai_vs_real: {en:'Splits creatives by PRODUCTION METHOD (type_of_production: FILMED / B-ROLL / AI-GENERATED / ZOOM RECORDING) — not by the hook\'s theme. This is scoped to the brand currently selected (top left): if a bucket looks empty, switch brands before assuming a data error — e.g. today, AI-generated production only exists for Open English Junior, not adult Open English.', es:'Divide los creativos por MÉTODO DE PRODUCCIÓN (type_of_production: FILMED / B-ROLL / AI-GENERATED / ZOOM RECORDING) — no por el tema del hook. Esto está limitado a la marca seleccionada actualmente (arriba a la izquierda): si un grupo se ve vacío, cambia de marca antes de asumir un error de datos — por ejemplo, hoy la producción con IA solo existe en Open English Junior, no en Open English adulto.', pt:'Divide os criativos por MÉTODO DE PRODUÇÃO (type_of_production: FILMED / B-ROLL / AI-GENERATED / ZOOM RECORDING) — não pelo tema do hook. Isso está restrito à marca selecionada atualmente (acima à esquerda): se um grupo parecer vazio, mude de marca antes de assumir um erro de dados — por exemplo, hoje a produção com IA só existe na Open English Junior, não na Open English adulta.'},
  jrhalo: {en:'The halo column holds REAL leads of the OTHER brand (from Junior\'s own deck) tagged as generated by Open English\'s spend, prorated per creative-day. Compare "JR L/$1k adj" against "OE L/$1k adj (ref)" on the same row to see which creatives punch above their own weight once you count their cross-brand halo too.', es:'"Leads JR" son leads REALES de Open English Junior (de su propio deck) etiquetados como generados por la inversión de Open English, prorrateados por día de creativo. Compara "JR L/$1k adj" contra "OE L/$1k adj (ref)" en la misma fila para ver qué creativos rinden más de lo que parecen una vez que cuentas también su halo entre marcas.', pt:'"Leads JR" são leads REAIS de Open English Junior (do próprio deck da Junior) marcados como gerados pelo investimento da Open English, prorrateados por dia de criativo. Compare "JR L/$1k adj" com "OE L/$1k adj (ref)" na mesma linha para ver quais criativos rendem mais do que parecem quando você conta também o halo entre marcas.'},
  launch: {en:'"TV-on days" here is capped at the creative\'s first 7 calendar days on air, not its whole flight — this isolates first-impression performance from how it holds up later (see Wear-Out for that).', es:'"Días TV-on" aquí queda limitado a los primeros 7 días calendario del creativo al aire, no todo su flight — esto aísla el desempeño de primera impresión de cómo se sostiene después (ver Desgaste para eso).', pt:'"Dias TV-on" aqui fica limitado aos primeiros 7 dias corridos do criativo no ar, não o flight inteiro — isso isola a performance de primeira impressão de como ele se sustenta depois (ver Desgaste para isso).'},
  wearout: {en:'Each creative\'s own run is split in half by day count (not calendar week), each half independently demand-adjusted — a real drop of more than 20% from its first half on air to its second half (flagged "⚠ pull") means the creative itself is tiring out, not that a slow month made it look worse.', es:'El recorrido de cada creativo se parte por la mitad por conteo de días (no semana calendario), cada mitad ajustada por demanda de forma independiente — una caída real de más de 20% de su primera mitad al aire a su segunda mitad (marcada "⚠ pull") significa que el creativo en sí se está desgastando, no que un mes flojo lo hizo ver peor.', pt:'O percurso de cada criativo é dividido ao meio por contagem de dias (não semana corrida), cada metade ajustada por demanda de forma independente — uma queda real de mais de 20% da primeira metade no ar para a segunda metade (marcada "⚠ pull") significa que o criativo em si está se desgastando, não que um mês fraco o fez parecer pior.'},
  seasonality: {en:'This is NOT TV performance — it is pure organic search interest, independent of any ad spend, and it is the divisor behind every "adj." number in the app. Read the table top to bottom: the factor is what a month is normally worth, the margin is how much of that is noise, and a month tagged "not significant" is one where the adjustment cannot be told apart from doing nothing. There is ONE table because the factors are fixed — the same January applies to 2025 and to 2026. The market rising or falling between years is a different thing and lives in its own card below, on purpose.', es:'Esto NO es performance de TV — es puro interés de búsqueda orgánica, independiente de cualquier inversión publicitaria, y es el divisor detrás de cada número "adj." de la app. Lee la tabla de arriba a abajo: el factor es lo que vale normalmente ese mes, el margen es cuánto de eso es ruido, y un mes marcado como "no significativo" es uno donde el ajuste no se distingue de no hacer nada. Hay UNA sola tabla porque los factores son fijos — el mismo enero aplica a 2025 y a 2026. Que el mercado suba o baje entre años es otra cosa distinta y vive en su propia tarjeta más abajo, a propósito.', pt:'Isto NÃO é performance de TV — é puro interesse de busca orgânica, independente de qualquer investimento, e é o divisor por trás de cada número "adj." do app. Leia a tabela de cima a baixo: o fator é o que aquele mês vale normalmente, a margem é quanto disso é ruído, e um mês marcado como "não significativo" é um onde o ajuste não se distingue de não fazer nada. Há UMA tabela só porque os fatores são fixos — o mesmo janeiro vale para 2025 e para 2026. O mercado subir ou cair entre anos é outra coisa e fica no seu próprio card abaixo, de propósito.'},
  insights: {en:'Every card below crosses at least two signals and only appears when the effect is large enough to act on — sorted strongest-first. This is the closest thing to an automated "what should I actually do differently" page in the whole app.', es:'Cada tarjeta de abajo cruza al menos dos señales y solo aparece cuando el efecto es lo bastante grande para actuar sobre él — ordenadas de más a menos fuerte. Es lo más cercano a una página automática de "qué debería hacer distinto de verdad" en toda la app.', pt:'Cada cartão abaixo cruza pelo menos dois sinais e só aparece quando o efeito é grande o suficiente para agir — ordenados do mais forte para o mais fraco. É o mais próximo de uma página automática de "o que eu deveria realmente fazer diferente" em todo o app.'},
  direction: {en:'The 4 cards translate the data into a creative direction (keep/stop/untested/rules); the "Brief" box below turns that into plain-language instructions you can hand directly to a creative team, split by Generic vs. Promo since the winning formula differs between them.', es:'Las 4 tarjetas traducen los datos en una dirección creativa (mantener/parar/sin probar/reglas); la caja de "Brief" de abajo convierte eso en instrucciones en lenguaje simple que puedes entregarle directo a un equipo creativo, separadas por Generic vs. Promo porque la fórmula ganadora es distinta entre los dos.', pt:'Os 4 cartões traduzem os dados numa direção criativa (manter/parar/não testado/regras); a caixa de "Brief" abaixo transforma isso em instruções em linguagem simples que você pode entregar direto a uma equipe criativa, separadas por Generic vs. Promo porque a fórmula vencedora é diferente entre os dois.'},
  tests: {en:'Column A costs nothing to try (existing creatives/rotation changes only); Column B requires new production. Both lists are generated from this territory\'s own real numbers on every load — not a fixed checklist.', es:'La columna A no cuesta nada probar (solo creativos existentes/cambios de rotación); la columna B requiere producción nueva. Ambas listas se generan desde los números reales de este territorio en cada carga — no es un checklist fijo.', pt:'A coluna A não custa nada testar (só criativos existentes/mudanças de rotação); a coluna B requer nova produção. Ambas as listas são geradas a partir dos números reais deste território a cada carregamento — não é um checklist fixo.'},
  methodology: {en:'This is the audit trail, not an analysis — cite it whenever someone asks "where does this number come from". It never changes based on territory or period.', es:'Esto es el rastro de auditoría, no un análisis — cítalo cuando alguien pregunte "¿de dónde sale este número?". No cambia según territorio o período.', pt:'Isto é a trilha de auditoria, não uma análise — cite quando alguém perguntar "de onde vem esse número?". Não muda conforme território ou período.'},
};
function tbdHowToCard(tabId){
  var h = TBD_HOWTO[tabId];
  if(!h) return '';
  var label = LANG==='en'?'How to read this tab':LANG==='pt'?'Como ler esta aba':'Cómo leer esta pestaña';
  return '<div class="card tbd-howto"><div class="tbd-howto-label">📖 '+esc(label)+'</div><div class="tbd-howto-body">'+esc(tbdT(h))+'</div></div>';
}
/* Tarjeta UNICA de insights por pestana: en vez de apilar una caja por
   agente, se consolidan en una sola con vinetas. Cada vineta puede traer la
   estructura Hallazgo / Hipotesis / Comprobacion que pidio el usuario. */

/* ---------- Hipotesis + Comprobacion ----------
   Cada hallazgo importante debe venir con (a) una teoria de negocio que
   explique el porque y (b) un intento REAL de validarla cruzando con otra
   data del reporte. Si no hay con que comprobarla, se dice explicitamente
   que habria que investigar. Nunca se afirma una causa como si estuviera
   probada. */
function tbdHC(hypothesis, check){ return { hypothesis:hypothesis, check:check }; }
function tbdNoDataCheck(what){
  var L=LANG;
  return L==='en' ? 'This report has no data to confirm it. To settle it, look at '+what+'.'
    : L==='pt' ? 'Este relatorio nao tem dados para confirmar. Para resolver, olhe '+what+'.'
    : 'Este reporte no tiene datos para confirmarlo. Para resolverlo, hay que mirar '+what+'.';
}
/* enriquece un hallazgo ya construido con su teoria y su comprobacion */
function tbdEnrich(finding, hc){
  if(!finding || !hc) return finding;
  finding.hypothesis = hc.hypothesis;
  finding.check = hc.check;
  return finding;
}
function tbdInsightBullet(item){
  if(!item) return '';
  if(typeof item === 'string') return '<li>'+item+'</li>';
  var L = LANG;
  var lblH = L==='en'?'Why this happens':L==='pt'?'Por que isso acontece':'Por que pasa esto';
  var lblC = L==='en'?'Cross-check':L==='pt'?'Comprovacao':'Comprobacion';
  var out = '<li>'+(item.title?('<b>'+esc(item.title)+'.</b> '):'')+(item.body||'');
  if(item.hypothesis) out += '<div class="tbd-sub-line"><span class="tbd-sub-tag">'+esc(lblH)+'</span> '+item.hypothesis+'</div>';
  if(item.check) out += '<div class="tbd-sub-line"><span class="tbd-sub-tag">'+esc(lblC)+'</span> '+item.check+'</div>';
  return out+'</li>';
}
/* Consolida en UNA tarjeta las lineas de estacionalidad de la pestana mas
   los hallazgos de los detectores. Reemplaza el apilado de N cajas azules. */
function tbdTabInsights(data, seasonDimKey, findings){
  var items = [];
  if(seasonDimKey){
    var lines = tbdSeasonalityCardFor(data, seasonDimKey) || [];
    lines.forEach(function(l){ items.push(l); });
  }
  (findings||[]).forEach(function(f){
    if(!f) return;
    if(typeof f === 'string'){ items.push(f); return; }
    items.push({ title:f.title, body:f.body, hypothesis:f.hypothesis, check:f.check });
  });
  return tbdUnifiedInsightCard(items);
}
function tbdUnifiedInsightCard(items){
  var list = (items||[]).filter(Boolean);
  if(!list.length) return '';
  var L = LANG;
  var label = L==='en'?'What the analysis found':L==='pt'?'O que a analise encontrou':'Lo que encontro el analisis';
  return '<div class="tbd-takeaway"><div class="tbd-insight-label">🧠 '+esc(label)+'</div>'+
    '<ul class="tbd-bullets">'+list.map(tbdInsightBullet).join('')+'</ul></div>';
}
function tbdTakeawayBox(innerHtml){
  if(!innerHtml) return '';
  var label = LANG==='en'?'Expert insight':LANG==='pt'?'Insight de especialista':'Insight experto';
  return '<div class="tbd-takeaway"><div class="tbd-insight-label">🧠 '+esc(label)+'</div>'+innerHtml+'</div>';
}
function tbdDimensionTakeaway(r25, r26, title){
  if(r26.length<2) return '';
  var best=r26[0], worst=r26[r26.length-1];
  if(worst.l1k_adj<=0) return '';
  var gap = (best.l1k_adj-worst.l1k_adj)/worst.l1k_adj*100;
  if(gap<12) return '';
  var prior = r25.filter(function(x){return x.label===best.label;})[0];
  var consistent = prior && r25.length && r25[0].label===best.label;
  return LANG==='en'
    ? '<b>Takeaway:</b> "'+best.label+'" outperforms "'+worst.label+'" by '+fmtNum(gap,0)+'% in 2026 (L/$1k adj. '+fmtNum(best.l1k_adj,0)+' vs '+fmtNum(worst.l1k_adj,0)+', '+best.n+' vs '+worst.n+' creatives). '+(consistent?'It also led in 2025 — this is a durable pattern worth briefing as a default, not a one-off result.':(prior?'In 2025 the leader was different ("'+r25[0].label+'") — treat this as an emerging signal, not yet a proven rule.':'There is no 2025 data to confirm this is consistent, treat with caution.'))
    : LANG==='pt'
    ? '<b>Takeaway:</b> "'+best.label+'" supera "'+worst.label+'" em '+fmtNum(gap,0)+'% em 2026 (L/$1k adj. '+fmtNum(best.l1k_adj,0)+' vs '+fmtNum(worst.l1k_adj,0)+', '+best.n+' vs '+worst.n+' criativos). '+(consistent?'Também liderou em 2025 — é um padrão durável que vale a pena usar como padrão de briefing, não um resultado isolado.':(prior?'Em 2025 o líder foi outro ("'+r25[0].label+'") — trate isso como um sinal emergente, ainda não uma regra comprovada.':'Não há dados de 2025 para confirmar consistência, trate com cautela.'))
    : '<b>Takeaway:</b> "'+best.label+'" rinde '+fmtNum(gap,0)+'% mejor que "'+worst.label+'" en 2026 (L/$1k adj. '+fmtNum(best.l1k_adj,0)+' vs '+fmtNum(worst.l1k_adj,0)+', '+best.n+' vs '+worst.n+' creativos). '+(consistent?'También lideró en 2025 — es un patrón durable, vale la pena briefearlo como default, no como resultado aislado.':(prior?'En 2025 el líder fue distinto ("'+r25[0].label+'") — trata esto como una señal emergente, todavía no una regla comprobada.':'No hay datos de 2025 para confirmar que sea consistente, trátalo con cautela.'));
}
function tbdDrillHintHTML(){
  var L = LANG;
  var txt = L==='en'?'Click any row in the tables below to see the individual creatives behind that number and how they add up to the total.'
    : L==='pt'?'Clique em qualquer linha das tabelas abaixo para ver os criativos individuais por trás daquele número e como eles somam o total.'
    : 'Haz clic en cualquier fila de las tablas de abajo para ver los creativos individuales detrás de ese número y cómo suman el total.';
  return '<div class="tbd-drill-hint-bar">🖱 '+esc(txt)+'</div>';
}
function tbdSafeDetect(fn){
  var args = Array.prototype.slice.call(arguments,1);
  try{ return fn.apply(null,args); }catch(e){ return null; }
}
function tbdDimensionPage(data, keyFn, title, subtitle, tabId, items25, items26, extraFindings, seasonDimKey){
  var src25 = items25||data.y25, src26 = items26||data.y26;
  var r25 = tbdDimensionRollup(src25, keyFn), r26 = tbdDimensionRollup(src26, keyFn);
  var dimFinding = tbdDimensionTakeaway(r25, r26, title);
  var allFindings = (dimFinding ? [dimFinding] : []).concat(extraFindings||[]);
  var insightHtml = tbdTabInsights(data, seasonDimKey, allFindings);
  return '<h2 class="tbd-section-title">'+esc(title)+'</h2><p style="font-size:12px;color:var(--ink-faint);margin-top:-8px;">'+esc(subtitle)+'</p>'+
    tbdHowToCard(tabId)+tbdDrillHintHTML()+
    '<div class="tbd-two-col"><div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y25_label'))+'</div>'+tbdDimTableHTML(r25,title,src25,keyFn,tbdS('y25_label'),'2025')+'</div>'+
    '<div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y26_label'))+'</div>'+tbdDimTableHTML(r26,title,src26,keyFn,tbdS('y26_label'),'2026')+'</div></div>'+
    insightHtml;
}

/* ============================ render por pestana ============================ */
var TBD_RENDERERS = {
  adjkpi: function(data){ return tbdAdjKpiHTML(data)+tbdTakeawayBox(tbdAdjKpiInsight(data)); },
  portfolio: function(data){
    var p25=data.p25, p26=data.p26;
    var mode = TBD_STATE.viewMode.portfolio || 'adname';
    var src25 = mode==='video' ? data.v25 : data.y25, src26 = mode==='video' ? data.v26 : data.y26;
    var top25 = src25.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;}).slice(0,10);
    var top26 = src26.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;}).slice(0,10);
    var insight = mode==='video' ? tbdVersionSplitInsight(src26) : tbdPortfolioTakeaway(data);
    return '<h2 class="tbd-section-title">'+esc(data.territory)+' · '+esc(tbdS('title_portfolio'))+' · '+esc(tbdS('period_label'))+'</h2>'+
      tbdLeadsDefinitionBox()+
      tbdHowToCard('portfolio')+
      '<div class="tbd-kpi-grid">'+
      tbdKpiCard(tbdS('kpi_l1k_adj'), p25.l1k_adj, p26.l1k_adj, function(v){return fmtNum(v,0);}, true)+
      tbdKpiCard(tbdS('kpi_cpl_adj'), p25.cpl_adj, p26.cpl_adj, function(v){return fmt$(v,2);}, false)+
      tbdKpiCard(tbdS('kpi_cvr'), p25.cvr, p26.cvr, function(v){return fmtPct(v,1);}, true)+
      tbdKpiCard(tbdS('kpi_mncc'), p25.mncc, p26.mncc, function(v){return fmtPct(v,1);}, true)+
      tbdKpiCard(tbdS('kpi_creatives'), p25.num_creatives, p26.num_creatives, function(v){return fmtNum(v,0);}, true)+
      '</div>'+
      tbdTabInsights(data, 'ad_type', (mode==='video' ? [insight] : [
        insight,
        tbdSafeDetect(tbdDetectSpendConcentrationRisk,data),
        tbdSafeDetect(tbdDetectMixShift,data,'ad_type'),
        tbdSafeDetect(tbdDetectSimpsonReversal,data),
        tbdSafeDetect(tbdDetectDimRowFragility,data),
        tbdSafeDetect(tbdDetectDimScaleCeiling,data),
        tbdSafeDetect(tbdDetectGrowthWithoutQuality,data),
        tbdSafeDetect(tbdDetectCostPerSaleReversal,data)
      ]))+
      tbdViewToggleHTML('portfolio')+
      '<div class="tbd-two-col"><div>'+tbdCreativeTableHTML(top25, tbdS('top10')+' · '+tbdS('y25_label'), '2025')+'</div><div>'+tbdCreativeTableHTML(top26, tbdS('top10')+' · '+tbdS('y26_label'), '2026')+'</div></div>';
  },
  promo: function(data){
    var mode = TBD_STATE.viewMode.promo || 'adname';
    var f = function(items){ return items.filter(function(r){ return r.ad_type==='PROMO'; }); };
    var f25 = f(mode==='video' ? data.v25 : data.y25), f26 = f(mode==='video' ? data.v26 : data.y26);
    var insight = mode==='video' ? tbdVersionSplitInsight(f26) : tbdCreativeTypeInsight(f26, f25, 'PROMO');
    return '<h2 class="tbd-section-title">'+esc(tbdS('title_promo'))+'</h2>'+
      tbdHowToCard('promo')+
      tbdViewToggleHTML('promo')+
      '<div class="tbd-two-col"><div>'+tbdCreativeTableHTML(f25, 'Promo · '+tbdS('y25_label'), '2025')+'</div><div>'+tbdCreativeTableHTML(f26, 'Promo · '+tbdS('y26_label'), '2026')+'</div></div>'+
      tbdTabInsights(data, 'pain_point', [insight, tbdSafeDetect(tbdDetectVolumeMarginDecouple,data,['pain_point'])]);
  },
  generic: function(data){
    var mode = TBD_STATE.viewMode.generic || 'adname';
    var f = function(items){ return items.filter(function(r){ return r.ad_type==='GENERIC'; }); };
    var f25 = f(mode==='video' ? data.v25 : data.y25), f26 = f(mode==='video' ? data.v26 : data.y26);
    var insight = mode==='video' ? tbdVersionSplitInsight(f26) : tbdCreativeTypeInsight(f26, f25, 'GENERIC');
    return '<h2 class="tbd-section-title">'+esc(tbdS('title_generic'))+'</h2>'+
      tbdHowToCard('generic')+
      tbdViewToggleHTML('generic')+
      '<div class="tbd-two-col"><div>'+tbdCreativeTableHTML(f25, 'Generic · '+tbdS('y25_label'), '2025')+'</div><div>'+tbdCreativeTableHTML(f26, 'Generic · '+tbdS('y26_label'), '2026')+'</div></div>'+
      tbdTabInsights(data, 'theme_mechanism_code', [insight, tbdSafeDetect(tbdDetectDimRowFragility,data,['theme_mechanism_code'])]);
  },
  pvg: function(data){ return tbdDimensionPage(data, function(r){ return r.ad_type==='PROMO'?'Promo Ads':'Generic Ads'; }, tbdS('title_pvg'), tbdS('sub_pvg'), 'pvg', null, null, [tbdSafeDetect(tbdDetectSimpsonReversal,data), tbdSafeDetect(tbdDetectMixShift,data,'ad_type'), tbdSafeDetect(tbdDetectPainPointAdTypeMismatch,data)], 'ad_type'); },
  tone: function(data){ return tbdDimensionPage(data, function(r){ return r.tone_category||'—'; }, tbdS('title_tone'), tbdS('sub_tone'), 'tone', null, null, [tbdSafeDetect(tbdDetectFearNeedsHumor,data), tbdSafeDetect(tbdDetectVolumeMarginDecouple,data,['tone_category']), tbdSafeDetect(tbdDetectDimRowFragility,data,['tone_category']), tbdSafeDetect(tbdDetectDimScaleCeiling,data,['tone_category'])], 'tone_category'); },
  hooks: function(data){
    return '<h2 class="tbd-section-title">'+esc(tbdS('title_hooks'))+'</h2>'+
      tbdHowToCard('hooks')+
      tbdDimensionPage(data, function(r){ return r.hook_audio_type_code||'—'; }, tbdS('title_hook_audio'), tbdS('sub_hook_audio'), null)+
      '<div style="height:18px;"></div>'+
      tbdDimensionPage(data, function(r){ return r.hook_visual_type_code||'—'; }, tbdS('title_hook_visual'), tbdS('sub_hook_visual'), null)+
      tbdTabInsights(data, 'hook_audio_type_code', [
        tbdSafeDetect(tbdDetectHookPairInteraction,data),
        tbdSafeDetect(tbdDetectDimRowFragility,data,['hook_audio_type_code','hook_visual_type_code']),
        tbdSafeDetect(tbdDetectCostPerSaleReversal,data,['hook_visual_type_code'])
      ]);
  },
  versions: function(data){ return tbdDimensionPage(data, function(r){ return r.version ? ('V'+r.version) : 'V1'; }, tbdS('title_versions'), tbdS('sub_versions'), 'versions', data.v25, data.v26, [], null); },
  campaigns: function(data){ return tbdDimensionPage(data, function(r){ return r.campaign_name||'—'; }, tbdS('title_campaigns'), tbdS('sub_campaigns'), 'campaigns', null, null, [tbdSafeDetect(tbdDetectCampaignHiddenStar,data), tbdSafeDetect(tbdDetectCampaignZombie,data)], 'campaign_name'); },
  promo_type: function(data){ return tbdDimensionPage(data, function(r){ return r.ad_type==='PROMO' ? (r.pain_point||'—') : null; }, tbdS('title_promo_type'), tbdS('sub_promo_type'), 'promo_type', null, null, [tbdSafeDetect(tbdDetectCtaEmotionalMismatch,data), tbdSafeDetect(tbdDetectVolumeMarginDecouple,data,['pain_point'])], 'pain_point'); },
  theme: function(data){ return tbdDimensionPage(data, function(r){ return r.theme||'—'; }, tbdS('title_theme'), tbdS('sub_theme'), 'theme', null, null, [tbdSafeDetect(tbdDetectMechanismFatigue,data), tbdSafeDetect(tbdDetectMechanismPainPointFit,data), tbdSafeDetect(tbdDetectDimRowFragility,data,['theme_mechanism_code']), tbdSafeDetect(tbdDetectDimScaleCeiling,data,['theme_mechanism_code'])], 'theme_mechanism_code'); },
  ai_vs_real: function(data){ return tbdDimensionPage(data, function(r){ return r.type_of_production||'—'; }, tbdS('title_ai_vs_real'), tbdS('sub_ai_vs_real'), 'ai_vs_real', null, null, [tbdSafeDetect(tbdDetectCheapFormatMarginLeak,data), tbdSafeDetect(tbdDetectDimRowFragility,data,['type_of_production']), tbdSafeDetect(tbdDetectMixShift,data,'type_of_production')], 'type_of_production'); },
  jrhalo: function(data){
    var mode = TBD_STATE.viewMode.jrhalo || 'adname';
    var src25 = mode==='video' ? data.v25 : data.y25, src26 = mode==='video' ? data.v26 : data.y26;
    var r25 = src25.slice().sort(function(a,b){return b.jr_l1k_adj-a.jr_l1k_adj;});
    var r26 = src26.slice().sort(function(a,b){return b.jr_l1k_adj-a.jr_l1k_adj;});
    var rows = function(items, year){
      var cJrL = tbdRankColor(items, function(r){return r.jr_l;}, true);
      var cJrAdj = tbdRankColor(items, function(r){return r.jr_l1k_adj;}, true);
      var cOe = tbdRankColor(items, function(r){return r.l1k_adj;}, true);
      return items.map(function(r){
      return '<tr><td>'+tbdCreativeNameLinkHTML(r,year)+'</td><td style="'+cJrL(r.jr_l)+'">'+fmtNum(r.jr_l,0)+'</td><td class="tbd-adj" style="'+cJrAdj(r.jr_l1k_adj)+'"><b>'+fmtNum(r.jr_l1k_adj,0)+'</b></td><td class="tbd-adj" style="'+cOe(r.l1k_adj)+'">'+fmtNum(r.l1k_adj,0)+'</td></tr>';
      }).join('') || '<tr><td colspan="4" style="text-align:center;color:var(--ink-faint);padding:16px;">'+T('sin_datos_filtro')+'</td></tr>'; };
    return '<h2 class="tbd-section-title">'+esc(tbdHaloTitle())+'</h2>'+
      '<p style="font-size:12px;color:var(--ink-faint);margin-top:-8px;">'+esc(tbdHaloSub())+'</p>'+
      tbdHowToCard('jrhalo')+tbdViewToggleHTML('jrhalo')+
      '<div class="tbd-two-col"><div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y25_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead><tr><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdHaloColLeads())+'</th><th>'+esc(tbdHaloColAdj())+'</th><th>'+esc(tbdHaloColRef())+'</th></tr></thead><tbody>'+rows(r25,'2025')+'</tbody></table></div></div>'+
      '<div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y26_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead><tr><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdHaloColLeads())+'</th><th>'+esc(tbdHaloColAdj())+'</th><th>'+esc(tbdHaloColRef())+'</th></tr></thead><tbody>'+rows(r26,'2026')+'</tbody></table></div></div></div>'+
      tbdTabInsights(data, 'ad_type', [{title:null, body:tbdJrHaloInsight(data)}]);
  },
  launch: function(data){
    var mode = TBD_STATE.viewMode.launch || 'adname';
    var src25 = mode==='video' ? data.v25 : data.y25, src26 = mode==='video' ? data.v26 : data.y26;
    var build = function(items){ return items.map(function(r){ var lw = tbdLaunchWeek(r); return {row:r, nombre:r.nombre, lw:lw}; }).filter(function(x){return x.lw;}).sort(function(a,b){return b.lw.l1k_adj-a.lw.l1k_adj;}); };
    var rows = function(list, year){
      var cAdj = tbdRankColor(list, function(x){return x.lw.l1k_adj;}, true);
      var cCpl = tbdRankColor(list, function(x){return x.lw.cpl_adj;}, false);
      return list.map(function(x){
      return '<tr><td>'+tbdCreativeNameLinkHTML(x.row,year)+'</td><td>'+x.lw.n+'</td><td class="tbd-adj" style="'+cAdj(x.lw.l1k_adj)+'"><b>'+fmtNum(x.lw.l1k_adj,0)+'</b></td><td class="tbd-adj" style="'+cCpl(x.lw.cpl_adj)+'">'+fmt$(x.lw.cpl_adj,2)+'</td></tr>';
      }).join('') || '<tr><td colspan="4" style="text-align:center;color:var(--ink-faint);padding:16px;">'+T('sin_datos_filtro')+'</td></tr>'; };
    var head = '<tr><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdS('col_tvon_days'))+'</th><th>'+esc(tbdS('col_l1k_adj'))+'</th><th>'+esc(tbdS('col_cpl_adj'))+'</th></tr>';
    return '<h2 class="tbd-section-title">'+esc(tbdS('title_launch'))+'</h2>'+
      tbdHowToCard('launch')+tbdViewToggleHTML('launch')+
      '<div class="tbd-two-col"><div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y25_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead>'+head+'</thead><tbody>'+rows(build(src25),'2025')+'</tbody></table></div></div>'+
      '<div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y26_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead>'+head+'</thead><tbody>'+rows(build(src26),'2026')+'</tbody></table></div></div></div>'+
      tbdTabInsights(data, 'ad_type', [{title:null, body:tbdLaunchInsight(data)}]);
  },
  wearout: function(data){
    var mode = TBD_STATE.viewMode.wearout || 'adname';
    var src25 = mode==='video' ? data.v25 : data.y25, src26 = mode==='video' ? data.v26 : data.y26;
    var build = function(items){ return items.map(function(r){ var w = tbdWearout(r); return {row:r, nombre:r.nombre, w:w}; }).filter(function(x){return x.w.pct!=null;}).sort(function(a,b){return a.w.pct-b.w.pct;}); };
    // El delta NO es una columna "adj" (no lleva fondo azul) y su color es
    // semantico, no por ranking: crecer es bueno, caer >20% es la senal de
    // desgaste real que la pestana existe para detectar.
    var rows = function(list, year){
      var cH1 = tbdRankColor(list, function(x){return x.w.h1.l1k_adj;}, true);
      var cH2 = tbdRankColor(list, function(x){return x.w.h2.l1k_adj;}, true);
      return list.map(function(x){
      var flag = x.w.pct<-20 ? ' <span style="color:var(--bad);font-weight:800;">⚠ pull</span>' : '';
      var deltaStyle = x.w.pct<=-20 ? 'color:var(--bad);font-weight:700;' : (x.w.pct>=5 ? 'color:var(--good);font-weight:700;' : '');
      return '<tr><td>'+tbdCreativeNameLinkHTML(x.row,year)+'</td><td class="tbd-adj" style="'+cH1(x.w.h1.l1k_adj)+'">'+fmtNum(x.w.h1.l1k_adj,0)+'</td><td class="tbd-adj" style="'+cH2(x.w.h2.l1k_adj)+'">'+fmtNum(x.w.h2.l1k_adj,0)+'</td><td style="'+deltaStyle+'"><b>'+fmtPct(x.w.pct/100,1)+'</b>'+flag+'</td></tr>';
      }).join('') || '<tr><td colspan="4" style="text-align:center;color:var(--ink-faint);padding:16px;">'+T('sin_datos_filtro')+'</td></tr>'; };
    var head = '<tr><th>'+esc(tbdS('col_creative'))+'</th><th>'+esc(tbdS('col_h1'))+'</th><th>'+esc(tbdS('col_h2'))+'</th><th>'+esc(tbdS('col_delta'))+'</th></tr>';
    return '<h2 class="tbd-section-title">'+esc(tbdS('title_wearout'))+'</h2>'+
      '<p style="font-size:12px;color:var(--ink-faint);margin-top:-8px;">'+esc(tbdS('sub_wearout'))+'</p>'+
      tbdHowToCard('wearout')+tbdViewToggleHTML('wearout')+
      '<div class="tbd-two-col"><div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y25_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead>'+head+'</thead><tbody>'+rows(build(src25),'2025')+'</tbody></table></div></div>'+
      '<div><div style="font-weight:700;font-size:12px;margin-bottom:6px;">'+esc(tbdS('y26_label'))+'</div><div style="overflow-x:auto;"><table class="tbd-table"><thead>'+head+'</thead><tbody>'+rows(build(src26),'2026')+'</tbody></table></div></div></div>'+
      tbdTabInsights(data, 'theme_mechanism_code', [{title:null, body:tbdWearoutInsight(data)}]);
  },
  seasonality: function(data){
    var s = TBD_SEASONALITY[data.territory];
    if(!s || !s.factorsIndex) return '<p>'+esc(tbdS('no_data'))+'</p>';
    var L = LANG;
    var MM = ['01','02','03','04','05','06','07','08','09','10','11','12'];
    var months = MM.map(mesLabel);
    var f = s.factorsIndex;              // 12 factores fijos, promedian 100
    var grey = s.grey || [];
    var errPct = tbdSeasonErrPct(data.territory);   // +/- % al 95%
    var maxv = Math.max.apply(null, f);

    /* ---------- tabla unica de 12 factores ---------- */
    var frows = f.map(function(v,i){
      var pct = Math.max(2, v/maxv*100);
      var isGrey = !!grey[i];
      var tone = isGrey ? 'var(--ink-faint)' : (v>=105 ? 'var(--good)' : (v<=95 ? 'var(--bad)' : 'var(--ink)'));
      var band = errPct==null ? '' : '&plusmn;'+fmtNum(errPct,1)+'%';
      var mark = isGrey
        ? '<span class="tbd-season-grey-tag" title="'+esc(L==='en'?'Not distinguishable from a normal month at 95% confidence':L==='pt'?'Não distinguível de um mês normal com 95% de confiança':'No se distingue de un mes normal con 95% de confianza')+'">'+esc(L==='en'?'not significant':L==='pt'?'não significativo':'no significativo')+'</span>'
        : '';
      return '<tr'+(isGrey?' class="tbd-season-grey"':'')+'>'+
        '<td style="width:78px;font-weight:700;">'+esc(months[i])+'</td>'+
        '<td style="width:56px;text-align:right;font-weight:800;color:'+tone+';">'+fmtNum(v,0)+'</td>'+
        '<td style="width:70px;text-align:right;font-size:11px;color:var(--ink-faint);">x'+fmtNum(v/100,2)+'</td>'+
        '<td style="width:64px;text-align:right;font-size:11px;color:var(--ink-faint);">'+band+'</td>'+
        '<td><div class="tbd-season-bartrack"><div class="tbd-season-barfill '+(isGrey?'grey':'y26')+'" style="width:'+pct+'%;"></div></div></td>'+
        '<td style="width:110px;font-size:11px;">'+mark+'</td>'+
      '</tr>';
    }).join('');

    var tblHead = '<tr>'+
      '<th>'+esc(L==='en'?'Month':'Mes')+'</th>'+
      '<th style="text-align:right;">'+esc(L==='en'?'Factor':'Factor')+'</th>'+
      '<th style="text-align:right;">'+esc(L==='en'?'Multiplier':L==='pt'?'Multiplicador':'Multiplicador')+'</th>'+
      '<th style="text-align:right;">'+esc(L==='en'?'Margin':L==='pt'?'Margem':'Margen')+'</th>'+
      '<th></th><th></th></tr>';

    var tblTitle = L==='en'
      ? 'The 12 seasonal factors of '+data.territory+' &mdash; the same ones for 2025 and for 2026'
      : L==='pt'
      ? 'Os 12 fatores sazonais de '+data.territory+' &mdash; os mesmos para 2025 e para 2026'
      : 'Los 12 factores de estacionalidad de '+data.territory+' &mdash; los mismos para 2025 y para 2026';
    var tblSub = L==='en'
      ? 'These are fixed. January is worth the same in 2025 as in 2026, so any number published here can be reproduced later. The 12 average exactly 100.'
      : L==='pt'
      ? 'São fixos. Janeiro vale o mesmo em 2025 e em 2026, então qualquer número publicado aqui pode ser reproduzido depois. Os 12 têm média exatamente 100.'
      : 'Son fijos. Enero vale lo mismo en 2025 que en 2026, así que cualquier número que se publique acá se puede reproducir después. Los 12 promedian exactamente 100.';

    var factorTable = '<div class="tbd-season-year">'+
      '<div class="tbd-season-year-head">'+tblTitle+'</div>'+
      '<div style="font-size:11px;color:var(--ink-faint);margin:-2px 0 8px;">'+tblSub+'</div>'+
      '<div style="overflow-x:auto;"><table class="tbd-table"><thead>'+tblHead+'</thead><tbody>'+frows+'</tbody></table></div>'+
    '</div>';

    /* ---------- semaforo del pais ---------- */
    var gate = tbdSeasonGate(data.territory) || {};
    var gLbl = gate.label || '-';
    var gCls = gLbl==='VERDE' ? 'ok' : (gLbl==='AMBAR' ? 'warn' : 'bad');
    var gName = L==='en' ? (gLbl==='VERDE'?'GREEN':gLbl==='AMBAR'?'AMBER':'RED')
              : L==='pt' ? (gLbl==='VERDE'?'VERDE':gLbl==='AMBAR'?'AMBAR':'VERMELHO') : gLbl;
    var gTxt = L==='en'
      ? (gLbl==='VERDE'
          ? 'Tested on months the model had never seen, the seasonal pattern of '+data.territory+' predicted '+fmtNum(gate.skill,0)+'% better than assuming every month is the same. The adjustment is trustworthy here.'
          : gLbl==='AMBAR'
          ? 'Tested on months the model had never seen, the pattern of '+data.territory+' only beat "every month is the same" by '+fmtNum(gate.skill,0)+'%. The adjustment points the right way but is weak: use it for direction, not for close calls.'
          : 'Out of sample the pattern did not beat assuming every month is the same, so the factors were forced to 1.00 and no seasonal adjustment is applied to '+data.territory+'.')
      : L==='pt'
      ? (gLbl==='VERDE'
          ? 'Testado em meses que o modelo nunca tinha visto, o padrão sazonal de '+data.territory+' acertou '+fmtNum(gate.skill,0)+'% melhor do que supor que todo mês é igual. O ajuste é confiável aqui.'
          : gLbl==='AMBAR'
          ? 'Testado em meses que o modelo nunca tinha visto, o padrão de '+data.territory+' superou "todo mês é igual" em apenas '+fmtNum(gate.skill,0)+'%. O ajuste aponta a direção certa mas é fraco: use para direção, não para decidir empates.'
          : 'Fora da amostra o padrão não superou supor que todo mês é igual, então os fatores foram forçados a 1,00 e nenhum ajuste sazonal é aplicado a '+data.territory+'.')
      : (gLbl==='VERDE'
          ? 'Probado contra meses que el modelo nunca había visto, el patrón estacional de '+data.territory+' acertó '+fmtNum(gate.skill,0)+'% mejor que suponer que todos los meses son iguales. Acá el ajuste es confiable.'
          : gLbl==='AMBAR'
          ? 'Probado contra meses que el modelo nunca había visto, el patrón de '+data.territory+' le ganó a "todos los meses son iguales" por apenas '+fmtNum(gate.skill,0)+'%. El ajuste apunta en la dirección correcta pero es débil: úsalo para dirección, no para desempatar.'
          : 'Fuera de muestra el patrón no le ganó a suponer que todos los meses son iguales, así que los factores se forzaron a 1,00 y a '+data.territory+' no se le aplica ningún ajuste estacional.');
    var gateHead = L==='en'?'How much can you trust this adjustment in '+data.territory+'?'
      : L==='pt'?'Quanto dá para confiar neste ajuste em '+data.territory+'?'
      : 'Cuánto se puede confiar en este ajuste en '+data.territory+'?';
    var gateCard = '<div class="tbd-gate tbd-gate-'+gCls+'">'+
      '<div class="tbd-gate-head"><span class="tbd-gate-chip">'+esc(gName)+'</span> '+esc(gateHead)+'</div>'+
      '<div class="tbd-gate-body">'+esc(gTxt)+
      (errPct!=null ? ' <b>'+esc(L==='en'?'Practical rule: do not rank two creatives apart on an adjusted difference smaller than '+fmtNum(errPct,1)+'% — that is the error of the adjustment itself.'
        : L==='pt'?'Regra prática: não separe dois criativos no ranking por uma diferença ajustada menor que '+fmtNum(errPct,1)+'% — esse é o erro do próprio ajuste.'
        : 'Regla práctica: no separes a dos creativos en el ranking por una diferencia ajustada menor a '+fmtNum(errPct,1)+'% — ese es el error del ajuste mismo.')+'</b>' : '')+
      '</div></div>';

    /* ---------- explicacion con manzanas ---------- */
    var explain = L==='en'
      ? '<div class="tbd-explain"><div class="tbd-explain-h">What this number is, in plain terms</div><ul class="tbd-explain-list">'+
        '<li><b>Think of an ice-cream shop.</b> It sells more in December than in June. If you want to know whether the new flavour is any good, you cannot compare a December week against a June week &mdash; December would win even with a bad flavour. First you strip out "how much December usually sells", and only then you compare flavours. That is exactly what this index does with creatives.</li>'+
        '<li><b>The factor</b> is how much a given month usually moves versus a normal month, in '+esc(data.territory)+'. <b>100 = a normal month.</b> It comes from real Ahrefs search volume for "open english" + "cursos de ingles", using every month since January 2023.</li>'+
        '<li><b>Why "usually" matters.</b> We do not use what happened in that one month. We use the pattern that repeats every year, after removing the market\'s own upward or downward drift. That is why the same January is worth the same in 2025 and in 2026 &mdash; and why the number does not move again next time you open this dashboard.</li>'+
        '<li><b>Nothing to do with TV.</b> This is the market moving on its own: with zero ads on air, more people still look for courses in some months than in others.</li>'+
        '</ul></div>'
      : L==='pt'
      ? '<div class="tbd-explain"><div class="tbd-explain-h">O que e este numero, em termos simples</div><ul class="tbd-explain-list">'+
        '<li><b>Pense numa sorveteria.</b> Ela vende mais em dezembro do que em junho. Se você quer saber se o sabor novo é bom, não pode comparar uma semana de dezembro com uma de junho &mdash; dezembro venceria até com um sabor ruim. Primeiro você tira "quanto dezembro costuma vender", e só então compara os sabores. É exatamente isso que este índice faz com os criativos.</li>'+
        '<li><b>O fator</b> é quanto um mês costuma se mover em relação a um mês normal, em '+esc(data.territory)+'. <b>100 = mês normal.</b> Vem do volume real de busca do Ahrefs para "open english" + "cursos de ingles", usando todos os meses desde janeiro de 2023.</li>'+
        '<li><b>Por que "costuma" importa.</b> Não usamos o que aconteceu naquele mês específico. Usamos o padrão que se repete todo ano, depois de remover a subida ou queda do próprio mercado. Por isso o mesmo janeiro vale o mesmo em 2025 e em 2026 &mdash; e por isso o número não muda de novo na próxima vez que você abrir este dashboard.</li>'+
        '<li><b>Nada a ver com TV.</b> É o mercado se movendo sozinho: com zero anúncios no ar, mais gente ainda procura cursos em alguns meses do que em outros.</li>'+
        '</ul></div>'
      : '<div class="tbd-explain"><div class="tbd-explain-h">Que es este numero, explicado con manzanas</div><ul class="tbd-explain-list">'+
        '<li><b>Piensa en una heladería.</b> Vende más en diciembre que en junio. Si quieres saber si el sabor nuevo es bueno, no puedes comparar una semana de diciembre contra una de junio &mdash; diciembre ganaría incluso con un sabor malo. Primero le quitas "cuánto suele vender diciembre", y recién ahí comparas sabores. Eso es exactamente lo que hace este índice con los creativos.</li>'+
        '<li><b>El factor</b> es cuánto se suele mover un mes frente a un mes normal, en '+esc(data.territory)+'. <b>100 = un mes normal.</b> Sale del volumen real de búsquedas de Ahrefs para "open english" + "cursos de ingles", usando todos los meses desde enero de 2023.</li>'+
        '<li><b>Por qué importa el "suele".</b> No usamos lo que pasó en ese mes puntual. Usamos el patrón que se repite todos los años, después de quitarle la subida o la caída propia del mercado. Por eso el mismo enero vale igual en 2025 y en 2026 &mdash; y por eso el número no se vuelve a mover la próxima vez que abras este dashboard.</li>'+
        '<li><b>No tiene nada que ver con la TV.</b> Es el mercado moviéndose solo: aunque no salga ni un anuncio al aire, en unos meses la gente busca cursos más que en otros.</li>'+
        '</ul></div>';

    /* ---------- mecanica paso a paso, con el ejemplo del mes real mas alto y mas bajo ---------- */
    var hiIdx = f.indexOf(Math.max.apply(null, f)), loIdx = f.indexOf(Math.min.apply(null, f));
    var hiM = months[hiIdx], loM = months[loIdx], hiV = f[hiIdx], loV = f[loIdx];
    var baseLeads = 1000;
    var hiMult = Math.round(hiV)/100, loMult = Math.round(loV)/100;
    var hiProj = Math.round(baseLeads*hiMult), loProj = Math.round(baseLeads*loMult);

    var mechanics = L==='en'
      ? '<div class="tbd-explain"><div class="tbd-explain-h">How the factor is applied, step by step</div><ol class="tbd-explain-list">'+
        '<li><b>To forecast the leads of a month:</b> take your baseline expectation and MULTIPLY by that month\'s multiplier. With a baseline of '+fmtNum(baseLeads,0)+' leads: in <b>'+esc(hiM)+'</b> (factor '+fmtNum(hiV,0)+') you would expect '+fmtNum(baseLeads,0)+' x '+fmtNum(hiMult,2)+' = <b>'+fmtNum(hiProj,0)+' leads</b>; in <b>'+esc(loM)+'</b> (factor '+fmtNum(loV,0)+'), '+fmtNum(baseLeads,0)+' x '+fmtNum(loMult,2)+' = <b>'+fmtNum(loProj,0)+' leads</b>. Same budget, same creatives &mdash; the month alone explains the gap.</li>'+
        '<li><b>To judge a creative fairly (what the adj. columns do):</b> go the other way and DIVIDE, to strip the month out. L/$1k adj. = raw L/$1k / multiplier. A creative that scored 60 in <b>'+esc(hiM)+'</b> is really worth '+fmtNum(60/hiMult,0)+' once the tailwind is removed; one that scored 60 in <b>'+esc(loM)+'</b> is really worth '+fmtNum(60/loMult,0)+'.</li>'+
        '<li><b>Which multiplier each creative gets:</b> not the month it launched, but a blend of every day it was on air, weighted by the spend of each day. A creative that spent most of its budget in a peak month carries a high multiplier even if it also aired in the valley.</li>'+
        '<li><b>What is NOT in the divisor:</b> the market going up or down between years. That is a real business fact, not a measurement bias, so it is reported separately below and never divided out.</li>'+
        '</ol></div>'
      : L==='pt'
      ? '<div class="tbd-explain"><div class="tbd-explain-h">Como o fator e aplicado, passo a passo</div><ol class="tbd-explain-list">'+
        '<li><b>Para projetar os leads de um mes:</b> pegue sua expectativa base e MULTIPLIQUE pelo multiplicador daquele mes. Com base de '+fmtNum(baseLeads,0)+' leads: em <b>'+esc(hiM)+'</b> (fator '+fmtNum(hiV,0)+') voce esperaria '+fmtNum(baseLeads,0)+' x '+fmtNum(hiMult,2)+' = <b>'+fmtNum(hiProj,0)+' leads</b>; em <b>'+esc(loM)+'</b> (fator '+fmtNum(loV,0)+'), '+fmtNum(baseLeads,0)+' x '+fmtNum(loMult,2)+' = <b>'+fmtNum(loProj,0)+' leads</b>. Mesmo orcamento, mesmos criativos &mdash; so o mes explica a diferenca.</li>'+
        '<li><b>Para julgar um criativo de forma justa (o que fazem as colunas adj.):</b> faca o contrario e DIVIDA. L/$1k adj. = L/$1k bruto / multiplicador. Um criativo que fez 60 em <b>'+esc(hiM)+'</b> na verdade vale '+fmtNum(60/hiMult,0)+'; um que fez 60 em <b>'+esc(loM)+'</b> vale '+fmtNum(60/loMult,0)+'.</li>'+
        '<li><b>Qual multiplicador cada criativo recebe:</b> nao e o do mes de estreia, e sim uma mistura de todos os dias no ar, ponderada pelo gasto de cada dia.</li>'+
        '<li><b>O que NAO entra no divisor:</b> o mercado subir ou cair entre anos. Isso e um fato real do negocio, nao um vies de medicao, entao e reportado separadamente abaixo e nunca dividido.</li>'+
        '</ol></div>'
      : '<div class="tbd-explain"><div class="tbd-explain-h">Como se aplica el factor, paso a paso</div><ol class="tbd-explain-list">'+
        '<li><b>Para proyectar los leads de un mes:</b> tomas tu expectativa base y la MULTIPLICAS por el multiplicador de ese mes. Con una base de '+fmtNum(baseLeads,0)+' leads: en <b>'+esc(hiM)+'</b> (factor '+fmtNum(hiV,0)+') esperarías '+fmtNum(baseLeads,0)+' x '+fmtNum(hiMult,2)+' = <b>'+fmtNum(hiProj,0)+' leads</b>; en <b>'+esc(loM)+'</b> (factor '+fmtNum(loV,0)+'), '+fmtNum(baseLeads,0)+' x '+fmtNum(loMult,2)+' = <b>'+fmtNum(loProj,0)+' leads</b>. Mismo presupuesto, mismos creativos &mdash; la diferencia la explica solo el mes.</li>'+
        '<li><b>Para juzgar un creativo de forma justa (esto hacen las columnas adj.):</b> vas al revés y DIVIDES, para quitarle el mes. L/$1k adj. = L/$1k crudo / multiplicador. Un creativo que hizo 60 en <b>'+esc(hiM)+'</b> en realidad vale '+fmtNum(60/hiMult,0)+' una vez le quitas el viento a favor; uno que hizo 60 en <b>'+esc(loM)+'</b> en realidad vale '+fmtNum(60/loMult,0)+'.</li>'+
        '<li><b>Que multiplicador le toca a cada creativo:</b> no el del mes en que se lanzó, sino una mezcla de todos los días que estuvo al aire, ponderada por cuánto se gastó cada día. Un creativo que gastó casi todo su presupuesto en un mes pico carga un multiplicador alto aunque también haya salido en el valle.</li>'+
        '<li><b>Que NO entra en el divisor:</b> que el mercado suba o baje entre años. Eso es un hecho real del negocio, no un sesgo de medición, así que se reporta aparte acá abajo y nunca se divide.</li>'+
        '</ol></div>';

    /* ---------- nivel de mercado: CONTEXTO, no divisor ---------- */
    var mkt = '';
    if(s.market_25!=null && s.market_26!=null){
      var yoy = s.market_yoy;
      var dir = yoy>2 ? (L==='en'?'grew':L==='pt'?'cresceu':'creció')
              : yoy<-2 ? (L==='en'?'shrank':L==='pt'?'encolheu':'se encogió')
              : (L==='en'?'stayed flat':L==='pt'?'ficou estavel':'se mantuvo plano');
      var mHead = L==='en'?'Separately: the market itself, Jan–Jul 2025 vs Jan–Jul 2026'
        : L==='pt'?'Separadamente: o próprio mercado, Jan–Jul 2025 vs Jan–Jul 2026'
        : 'Aparte: el mercado en sí, Ene–Jul 2025 vs Ene–Jul 2026';
      var mBody = L==='en'
        ? 'Once the repeating month pattern is removed, demand in '+data.territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% between the two periods (level '+fmtNum(s.market_25,1)+' → '+fmtNum(s.market_26,1)+', where 100 = the 2023 average). <b>This number is context, not a correction.</b> It is deliberately kept out of the divisor: if we also divided by it, a creative that ran in a collapsing market would look better precisely because the market collapsed. Read it as the headwind or tailwind the team was working against.'
        : L==='pt'
        ? 'Removido o padrão de mês que se repete, a demanda em '+data.territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% entre os dois periodos (nivel '+fmtNum(s.market_25,1)+' → '+fmtNum(s.market_26,1)+', onde 100 = media de 2023). <b>Este número é contexto, não correção.</b> Fica de propósito fora do divisor: se dividíssemos por ele também, um criativo que rodou num mercado em queda pareceria melhor justamente porque o mercado caiu. Leia como o vento contra ou a favor que o time enfrentou.'
        : 'Una vez removido el patrón de mes que se repite, la demanda en '+data.territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% entre los dos periodos (nivel '+fmtNum(s.market_25,1)+' → '+fmtNum(s.market_26,1)+', donde 100 = el promedio de 2023). <b>Este número es contexto, no una corrección.</b> Se deja a propósito fuera del divisor: si también dividiéramos por él, un creativo que corrió en un mercado que se derrumbó se vería mejor justamente porque el mercado se derrumbó. Léelo como el viento en contra o a favor que tuvo el equipo.';
      mkt = '<div class="tbd-explain tbd-explain-alt"><div class="tbd-explain-h">'+esc(mHead)+'</div>'+
        '<div style="font-size:12px;line-height:1.55;">'+mBody+'</div></div>';
    }

    /* ---------- advertencias honestas ---------- */
    var wHead = L==='en'?'Three limits you should know before leaning on this'
      : L==='pt'?'Três limites que você deve saber antes de se apoiar nisto'
      : 'Tres límites que conviene saber antes de apoyarse en esto';
    var w1 = L==='en'
      ? '<b>The signal is search, not sales.</b> We measure how many people searched, and assume that translates one-to-one into how many would convert. If in some months searchers are more casual than in others, the adjustment is slightly off.'
      : L==='pt'
      ? '<b>O sinal é busca, não venda.</b> Medimos quantas pessoas buscaram e assumimos que isso se traduz um-para-um em quantas converteriam. Se em alguns meses quem busca é mais casual, o ajuste fica levemente errado.'
      : '<b>La señal es búsqueda, no venta.</b> Medimos cuánta gente buscó y asumimos que eso se traduce uno a uno en cuánta convertiría. Si en algunos meses el que busca es más casual que en otros, el ajuste queda ligeramente corrido.';
    var w2 = L==='en'
      ? '<b>Part of the search is caused by us.</b> Brand searches for "open english" go up partly because our own TV is on air. So the index is not a perfectly clean outside measure of the market &mdash; in heavy TV months it is inflated by our own activity, which makes the adjustment slightly conservative.'
      : L==='pt'
      ? '<b>Parte da busca é causada por nós.</b> Buscas de marca por "open english" sobem em parte porque nossa própria TV está no ar. Então o índice não é uma medida externa perfeitamente limpa do mercado &mdash; em meses de TV pesada ele é inflado pela nossa própria atividade, o que torna o ajuste levemente conservador.'
      : '<b>Parte de la búsqueda la causamos nosotros.</b> Las búsquedas de marca de "open english" suben en parte porque nuestra propia TV está al aire. Así que el índice no es una medida externa perfectamente limpia del mercado &mdash; en meses de TV pesada está inflado por nuestra propia actividad, lo que vuelve el ajuste ligeramente conservador.';
    var w3 = errPct!=null
      ? (L==='en'
        ? '<b>Grey months are noise.</b> The rows marked "not significant" have a factor that cannot be told apart from a normal month at 95% confidence. The adjustment is still applied there (it is the best single estimate we have), but do not build an argument on a difference smaller than '+fmtNum(errPct,1)+'%.'
        : L==='pt'
        ? '<b>Meses cinzas são ruído.</b> As linhas marcadas como "não significativo" têm um fator que não se distingue de um mês normal com 95% de confiança. O ajuste continua sendo aplicado ali (é a melhor estimativa única que temos), mas não construa um argumento sobre uma diferença menor que '+fmtNum(errPct,1)+'%.'
        : '<b>Los meses en gris son ruido.</b> Las filas marcadas como "no significativo" tienen un factor que no se distingue de un mes normal con 95% de confianza. El ajuste igual se aplica ahí (es la mejor estimación puntual que tenemos), pero no armes un argumento sobre una diferencia menor a '+fmtNum(errPct,1)+'%.')
      : '';
    var warn = '<div class="tbd-alertbox tbd-alertbox-neutral">'+
      '<div class="tbd-alertbox-h">⚠ '+esc(wHead)+'</div>'+
      '<ul class="tbd-alertbox-list"><li>'+w1+'</li><li>'+w2+'</li>'+(w3?'<li>'+w3+'</li>':'')+'</ul></div>';

    return '<h2 class="tbd-section-title">'+esc(tbdS('title_seasonality'))+' - '+esc(data.territory)+'</h2>'+
      tbdHowToCard('seasonality')+
      explain+
      factorTable+
      gateCard+
      mechanics+
      mkt+
      warn+
      tbdTakeawayBox(tbdSeasonalityTakeaway(data.territory));
  },
  insights: function(data){ return tbdInsightsHTML(data)+tbdTakeawayBox(tbdInsightsMetaInsight(data)); },
  direction: function(data){ return tbdDirectionHTML(data); },
  tests: function(data){ return tbdTestsHTML(data)+tbdTakeawayBox(tbdTestsInsight(data)); },
  methodology: function(data){ return tbdMethodologyHTML(); },
};

/* ============================ takeaways / insights / tests (texto generado desde datos reales) ============================ */
function tbdPortfolioTakeaway(data){
  var p25=data.p25, p26=data.p26;
  if(p25.l1k_adj==null || p26.l1k_adj==null) return tbdS('no_data');
  var deltaQuality = (p26.l1k_adj - p25.l1k_adj) / p25.l1k_adj * 100;
  var deltaSpend = (p26.s - p25.s) / p25.s * 100;
  var deltaLeads = (p26.l - p25.l) / p25.l * 100;
  var flat = Math.abs(deltaQuality) < 8;
  var qualityTxt = LANG==='en'
    ? (flat ? 'creative quality is essentially the same between years (demand-adjusted L/$1k is nearly identical)' : (deltaQuality>0 ? 'creative quality genuinely improved (demand-adjusted L/$1k rose '+fmtNum(deltaQuality,1)+'%)' : 'creative quality genuinely worsened (demand-adjusted L/$1k fell '+fmtNum(Math.abs(deltaQuality),1)+'%)'))
    : LANG==='pt'
    ? (flat ? 'a qualidade dos criativos é praticamente a mesma entre os anos (L/$1k ajustado por demanda quase idêntico)' : (deltaQuality>0 ? 'a qualidade dos criativos melhorou de fato (L/$1k ajustado subiu '+fmtNum(deltaQuality,1)+'%)' : 'a qualidade dos criativos piorou de fato (L/$1k ajustado caiu '+fmtNum(Math.abs(deltaQuality),1)+'%)'))
    : (flat ? 'la calidad de los creativos es prácticamente la misma entre años (L/$1k ajustado por demanda casi idéntico)' : (deltaQuality>0 ? 'la calidad de los creativos mejoró de forma real (L/$1k ajustado subió '+fmtNum(deltaQuality,1)+'%)' : 'la calidad de los creativos empeoró de forma real (L/$1k ajustado bajó '+fmtNum(Math.abs(deltaQuality),1)+'%)'));
  return LANG==='en'
    ? '<b>Takeaway:</b> '+qualityTxt+'. The difference in total leads between years ('+fmtNum(deltaLeads,1)+'%) is mostly explained by the change in spend ('+fmtNum(deltaSpend,1)+'% of budget) and by demand seasonality, not creative performance alone.'
    : LANG==='pt'
    ? '<b>Takeaway:</b> '+qualityTxt+'. A diferença de leads totais entre os anos ('+fmtNum(deltaLeads,1)+'%) se explica principalmente pela mudança de investimento ('+fmtNum(deltaSpend,1)+'% de gasto) e pela sazonalidade de demanda, não apenas pelo desempenho dos criativos.'
    : '<b>Takeaway:</b> '+qualityTxt+'. La diferencia de leads totales entre años ('+fmtNum(deltaLeads,1)+'%) se explica principalmente por el cambio de inversión ('+fmtNum(deltaSpend,1)+'% de gasto) y por estacionalidad de demanda, no solo por el desempeño de los creativos.';
}
function tbdSeasonalityTakeaway(territory){
  var s = TBD_SEASONALITY[territory];
  if(!s || !s.factorsIndex) return tbdS('no_data');
  var f = s.factorsIndex, MM=['01','02','03','04','05','06','07','08','09','10','11','12'];
  var months = MM.map(mesLabel);
  var hi=f.indexOf(Math.max.apply(null,f)), lo=f.indexOf(Math.min.apply(null,f));
  var swing=(f[hi]-f[lo])/f[lo]*100;
  var yoy = s.market_yoy;
  var L=LANG;
  var part1 = L==='en'
    ? '<b>Takeaway:</b> in '+esc(territory)+' the calendar alone moves demand '+fmtNum(swing,0)+'% between the strongest month ('+esc(months[hi])+', x'+fmtNum(f[hi]/100,2)+') and the weakest ('+esc(months[lo])+', x'+fmtNum(f[lo]/100,2)+'). Any two creatives that aired in different months are not comparable on their raw numbers.'
    : L==='pt'
    ? '<b>Takeaway:</b> em '+esc(territory)+' só o calendário move a demanda '+fmtNum(swing,0)+'% entre o mês mais forte ('+esc(months[hi])+', x'+fmtNum(f[hi]/100,2)+') e o mais fraco ('+esc(months[lo])+', x'+fmtNum(f[lo]/100,2)+'). Dois criativos que foram ao ar em meses diferentes não são comparáveis pelos números brutos.'
    : '<b>Takeaway:</b> en '+esc(territory)+' solo el calendario mueve la demanda '+fmtNum(swing,0)+'% entre el mes más fuerte ('+esc(months[hi])+', x'+fmtNum(f[hi]/100,2)+') y el más débil ('+esc(months[lo])+', x'+fmtNum(f[lo]/100,2)+'). Dos creativos que salieron en meses distintos no son comparables por sus números crudos.';
  if(yoy==null) return part1;
  var part2 = L==='en'
    ? ' Separately, the market itself '+(yoy>2?'grew':yoy<-2?'fell':'held flat')+' '+fmtNum(Math.abs(yoy),1)+'% between Jan–Jul 2025 and Jan–Jul 2026 — that is the headwind or tailwind behind the year-over-year numbers, and it is deliberately not divided out.'
    : L==='pt'
    ? ' Separadamente, o próprio mercado '+(yoy>2?'cresceu':yoy<-2?'caiu':'ficou estável')+' '+fmtNum(Math.abs(yoy),1)+'% entre Jan–Jul 2025 e Jan–Jul 2026 — esse é o vento por trás dos números ano a ano, e de propósito não é dividido.'
    : ' Aparte, el mercado en sí '+(yoy>2?'creció':yoy<-2?'cayó':'se mantuvo plano')+' '+fmtNum(Math.abs(yoy),1)+'% entre Ene–Jul 2025 y Ene–Jul 2026 — ese es el viento detrás de los números año contra año, y a propósito no se divide.';
  return part1+part2;
}
/* ---------- insights nuevos por pestana (promo/generic/jrhalo/launch/wearout/adjkpi/insights-meta/tests) ----------
   Mismo criterio que los detectores de mas abajo: cruzan al menos dos senales
   reales de la vista puntual y solo devuelven texto si el patron es lo
   bastante grande para actuar sobre el -- si no, null (la pestana no muestra
   tarjeta de insight ese dia, en vez de rellenar con obviedades). */
/* ---------- insight de modo "Video Name" (por version) -- SOLO tiene sentido
   cuando la seccion esta desagrupada: compara V1 contra su propia V2/V3 real,
   algo que el modo Ad Name (fusionado) no puede mostrar por diseño. Nunca
   reusa el texto del modo agrupado -- es una pregunta distinta ("¿la revision
   realmente mejoro?" vs "¿que Ad Name gana?"). ---------- */
function tbdVersionSplitInsight(itemsVideo){
  var L = LANG;
  if(!itemsVideo || itemsVideo.length<2) return null;
  var byAdName = {};
  itemsVideo.forEach(function(r){ (byAdName[r.ad_name||r.nombre]=byAdName[r.ad_name||r.nombre]||[]).push(r); });
  var withRevisions = Object.keys(byAdName).map(function(k){ return byAdName[k]; }).filter(function(arr){ return arr.length>=2; });
  if(!withRevisions.length){
    return L==='en' ? 'No Ad Name in this list has more than one Video Name version airing in this window — there is nothing to compare yet in this view.'
      : L==='pt' ? 'Nenhum Ad Name desta lista tem mais de uma versão de Video Name no ar nesta janela — não há nada para comparar ainda nesta visão.'
      : 'Ningún Ad Name de esta lista tiene más de una versión de Video Name al aire en esta ventana — todavía no hay nada que comparar en esta vista.';
  }
  var best = null;
  withRevisions.forEach(function(arr){
    var sortedV = arr.slice().sort(function(a,b){ return (a.version||1)-(b.version||1); });
    var v1 = sortedV[0];
    if(v1.l1k_adj<=0) return;
    sortedV.slice(1).forEach(function(vN){
      var gap = (vN.l1k_adj-v1.l1k_adj)/v1.l1k_adj*100;
      if(!best || Math.abs(gap)>Math.abs(best.gap)) best = {v1:v1, vN:vN, gap:gap, adName:v1.ad_name||v1.nombre};
    });
  });
  if(!best || Math.abs(best.gap)<15){
    return L==='en' ? withRevisions.length+' Ad Name(s) have a tested revision (V2/V3) in this window, and none moved the demand-adjusted L/$1k by more than ~15% either way — revisions here look like cosmetic/legal tweaks, not creative changes that shift performance.'
      : L==='pt' ? withRevisions.length+' Ad Name(s) têm uma revisão testada (V2/V3) nesta janela, e nenhuma moveu o L/$1k ajustado por demanda em mais de ~15% para nenhum lado — as revisões aqui parecem ajustes cosméticos/legais, não mudanças criativas que alterem a performance.'
      : withRevisions.length+' Ad Name(s) tienen una revisión probada (V2/V3) en esta ventana, y ninguna movió el L/$1k ajustado por demanda más de ~15% en ningún sentido — las revisiones acá se ven como ajustes cosméticos/legales, no cambios creativos que muevan el desempeño.';
  }
  var up = best.gap>0;
  return L==='en'
    ? '<b>Version check:</b> for "'+best.adName+'", "'+best.vN.nombre+'" '+(up?'outperforms':'underperforms')+' its own "'+best.v1.nombre+'" by '+fmtNum(Math.abs(best.gap),0)+'% (adj. L/$1k '+fmtNum(best.v1.l1k_adj,0)+' → '+fmtNum(best.vN.l1k_adj,0)+') — the merged Ad Name view hides this: '+(up?'the revision is the one worth crediting and repeating, not the original cut.':'the original cut was doing the real work; whatever changed in this revision should be reverted or re-tested.')
    : L==='pt'
    ? '<b>Checagem de versão:</b> para "'+best.adName+'", "'+best.vN.nombre+'" '+(up?'supera':'rende pior que')+' sua própria "'+best.v1.nombre+'" em '+fmtNum(Math.abs(best.gap),0)+'% (L/$1k adj. '+fmtNum(best.v1.l1k_adj,0)+' → '+fmtNum(best.vN.l1k_adj,0)+') — a visão fundida por Ad Name esconde isso: '+(up?'a revisão é a que vale creditar e repetir, não o corte original.':'o corte original é que estava fazendo o trabalho real; o que mudou nesta revisão deveria ser revertido ou re-testado.')
    : '<b>Chequeo de versión:</b> para "'+best.adName+'", "'+best.vN.nombre+'" '+(up?'rinde mejor que':'rinde peor que')+' su propia "'+best.v1.nombre+'" en '+fmtNum(Math.abs(best.gap),0)+'% (L/$1k adj. '+fmtNum(best.v1.l1k_adj,0)+' → '+fmtNum(best.vN.l1k_adj,0)+') — la vista fusionada por Ad Name esconde esto: '+(up?'la revisión es la que vale la pena acreditar y repetir, no el corte original.':'el corte original era el que hacía el trabajo real; lo que se cambió en esta revisión debería revertirse o volver a probarse.');
}
function tbdCreativeTypeInsight(items26, items25, adType){
  if(items26.length<4) return null;
  var sorted = items26.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; });
  var half = Math.max(1, Math.floor(sorted.length/2));
  var top = sorted.slice(0,half), bottom = sorted.slice(sorted.length-half);
  function mode(arr, keyFn){
    var counts = {}; arr.forEach(function(r){ var k=keyFn(r)||'—'; counts[k]=(counts[k]||0)+1; });
    var best=null; Object.keys(counts).forEach(function(k){ if(!best || counts[k]>counts[best]) best=k; });
    return best;
  }
  var avgTop = top.reduce(function(s,r){return s+r.l1k_adj;},0)/top.length;
  var avgBottom = bottom.reduce(function(s,r){return s+r.l1k_adj;},0)/bottom.length;
  if(avgBottom<=0) return null;
  var gap = (avgTop-avgBottom)/avgBottom*100;
  if(gap<20) return null;
  var topTone = mode(top, function(r){return r.tone_category;});
  var bottomTone = mode(bottom, function(r){return r.tone_category;});
  var toneDiffers = topTone && bottomTone && topTone!==bottomTone;
  var countDelta = items26.length - items25.length;
  var typeLabel = adType==='PROMO' ? 'Promo' : 'Generic';
  return LANG==='en'
    ? 'The top half of '+typeLabel+' creatives outperforms the bottom half by '+fmtNum(gap,0)+'% (L/$1k adj. '+fmtNum(avgTop,1)+' vs '+fmtNum(avgBottom,1)+', '+top.length+' vs '+bottom.length+' creatives). '+(toneDiffers?'The gap tracks tone: top performers skew "'+topTone+'", the bottom skew "'+bottomTone+'" — tone, not just execution, is separating winners from losers here.':'No single tone explains the gap — the spread looks more like execution quality than a formula difference.')+(countDelta!==0?(' 2026 is running '+Math.abs(countDelta)+' '+(countDelta>0?'more':'fewer')+' '+typeLabel+' creatives than the same window in 2025.'):'')
    : LANG==='pt'
    ? 'A metade superior dos criativos '+typeLabel+' supera a metade inferior em '+fmtNum(gap,0)+'% (L/$1k adj. '+fmtNum(avgTop,1)+' vs '+fmtNum(avgBottom,1)+', '+top.length+' vs '+bottom.length+' criativos). '+(toneDiffers?'A diferença acompanha o tom: os melhores puxam para "'+topTone+'", os piores para "'+bottomTone+'" — o tom, não só a execução, está separando vencedores de perdedores aqui.':'Nenhum tom único explica a diferença — parece mais qualidade de execução do que uma fórmula diferente.')+(countDelta!==0?(' 2026 está rodando '+Math.abs(countDelta)+' criativos '+typeLabel+' '+(countDelta>0?'a mais':'a menos')+' que a mesma janela em 2025.'):'')
    : 'La mitad superior de los creativos '+typeLabel+' rinde '+fmtNum(gap,0)+'% mejor que la mitad inferior (L/$1k adj. '+fmtNum(avgTop,1)+' vs '+fmtNum(avgBottom,1)+', '+top.length+' vs '+bottom.length+' creativos). '+(toneDiffers?'La brecha coincide con el tono: los mejores se inclinan a "'+topTone+'", los peores a "'+bottomTone+'" — el tono, no solo la ejecución, está separando ganadores de perdedores acá.':'Ningún tono en particular explica la brecha — se ve más a calidad de ejecución que a una fórmula distinta.')+(countDelta!==0?(' 2026 corre con '+Math.abs(countDelta)+' creativos '+typeLabel+' '+(countDelta>0?'más':'menos')+' que la misma ventana en 2025.'):'');
}
function tbdJrHaloInsight(data){
  var jh = tbdDetectJrHaloShare(data);
  if(jh) return jh.body;
  return LANG==='en' ? 'No material Junior halo detected this period (Junior leads attributed to Open English spend are below the threshold worth acting on).'
    : LANG==='pt' ? 'Nenhum halo Junior relevante detectado neste período (leads Junior atribuídos ao investimento da Open English estão abaixo do limite que vale a pena agir).'
    : 'No se detecta un halo de Junior relevante en este período (los leads de Junior atribuidos a la inversión de Open English están por debajo del umbral que vale la pena accionar).';
}
function tbdLaunchInsight(data){
  var items = data.y26.filter(function(r){ return r.n>=10; });
  var pairs = items.map(function(r){ var lw=tbdLaunchWeek(r); return lw && lw.l1k_adj>0 ? {full:r.l1k_adj, lw:lw.l1k_adj, nombre:r.nombre} : null; }).filter(Boolean);
  if(pairs.length<4) return null;
  var hot = pairs.filter(function(p){ return (p.lw-p.full)/p.full > 0.15; });
  var slow = pairs.filter(function(p){ return (p.full-p.lw)/p.full > 0.15; });
  if(hot.length===0 && slow.length===0) return null;
  var majority = hot.length>slow.length ? 'hot' : 'slow';
  return LANG==='en'
    ? (majority==='hot'
      ? fmtNum(hot.length,0)+' of '+pairs.length+' creatives with enough runway perform BETTER in their first 7 days than over their full flight — a "hot start, cool down" pattern. Judge a new launch by week 1, but don\'t assume it will hold at that level; budget for a natural cooldown.'
      : fmtNum(slow.length,0)+' of '+pairs.length+' creatives with enough runway perform WORSE in their first 7 days than over their full flight — a "slow burn" pattern. Don\'t kill a new creative just because week 1 looks weak; give it more runway before judging.')
    : LANG==='pt'
    ? (majority==='hot'
      ? fmtNum(hot.length,0)+' de '+pairs.length+' criativos com fôlego suficiente performam MELHOR nos primeiros 7 dias do que no flight inteiro — um padrão de "início quente, depois esfria". Julgue um novo lançamento pela semana 1, mas não assuma que vai se manter nesse nível; planeje um resfriamento natural.'
      : fmtNum(slow.length,0)+' de '+pairs.length+' criativos com fôlego suficiente performam PIOR nos primeiros 7 dias do que no flight inteiro — um padrão de "queima lenta". Não mate um criativo novo só porque a semana 1 parece fraca; dê mais fôlego antes de julgar.')
    : (majority==='hot'
      ? fmtNum(hot.length,0)+' de '+pairs.length+' creativos con suficiente recorrido rinden MEJOR en sus primeros 7 días que en todo su flight — un patrón de "arranque caliente, después se enfría". Juzga un lanzamiento nuevo por la semana 1, pero no asumas que se va a sostener en ese nivel; presupuesta un enfriamiento natural.'
      : fmtNum(slow.length,0)+' de '+pairs.length+' creativos con suficiente recorrido rinden PEOR en sus primeros 7 días que en todo su flight — un patrón de "quema lenta". No mates un creativo nuevo solo porque la semana 1 se ve floja; dale más recorrido antes de juzgarlo.');
}
function tbdWearoutInsight(data){
  var list = data.y26.map(function(r){ return {row:r, w:tbdWearout(r)}; }).filter(function(x){ return x.w.pct!=null; });
  if(list.length<3) return null;
  var avg = list.reduce(function(s,x){return s+x.w.pct;},0)/list.length;
  var flagged = list.filter(function(x){ return x.w.pct<-20; });
  return LANG==='en'
    ? 'Across '+list.length+' creatives with enough days to measure, demand-adjusted L/$1k moves '+fmtNum(avg,1)+'% on average from its first half on air to its second half, and '+flagged.length+' ('+fmtNum(flagged.length/list.length*100,0)+'%) show a real wear-out drop (>20%). '+(flagged.length ? 'Prioritize refreshing: '+flagged.slice(0,3).map(function(x){return '"'+x.row.nombre+'"';}).join(', ')+'.' : 'No creative shows a real wear-out signal this period — current flights can keep running as-is.')
    : LANG==='pt'
    ? 'Entre '+list.length+' criativos com dias suficientes para medir, o L/$1k ajustado por demanda muda '+fmtNum(avg,1)+'% em média da primeira metade no ar para a segunda metade, e '+flagged.length+' ('+fmtNum(flagged.length/list.length*100,0)+'%) mostram uma queda real de desgaste (>20%). '+(flagged.length ? 'Priorize renovar: '+flagged.slice(0,3).map(function(x){return '"'+x.row.nombre+'"';}).join(', ')+'.' : 'Nenhum criativo mostra um sinal real de desgaste neste período — os flights atuais podem continuar rodando como estão.')
    : 'Entre '+list.length+' creativos con suficientes días para medir, el L/$1k ajustado por demanda se mueve '+fmtNum(avg,1)+'% en promedio de su primera mitad al aire a su segunda mitad, y '+flagged.length+' ('+fmtNum(flagged.length/list.length*100,0)+'%) muestran una caída real de desgaste (>20%). '+(flagged.length ? 'Prioriza renovar: '+flagged.slice(0,3).map(function(x){return '"'+x.row.nombre+'"';}).join(', ')+'.' : 'Ningún creativo muestra una señal real de desgaste este período — los flights actuales pueden seguir corriendo tal cual.');
}
function tbdAdjKpiInsight(data){
  var s = TBD_SEASONALITY[data.territory];
  if(!s) return null;
  var arr = s.jan_jul_2026;
  var max = Math.max.apply(null, arr), min = Math.min.apply(null, arr);
  if(min<=0) return null;
  var swing = (max-min)/min*100;
  if(swing<10) return null;
  var months = ['01','02','03','04','05','06','07'].map(mesLabel);
  var maxM = months[arr.indexOf(max)], minM = months[arr.indexOf(min)];
  return LANG==='en'
    ? 'In '+esc(data.territory)+', the 2026 demand index swings '+fmtNum(swing,0)+'% between its lowest ('+minM+', index '+fmtNum(min,0)+') and highest ('+maxM+', index '+fmtNum(max,0)+') month. That is how much raw L/$1k can be distorted by timing alone here — a real reason to always check the "adj." column before comparing two creatives that aired in different months.'
    : LANG==='pt'
    ? 'Em '+esc(data.territory)+', o índice de demanda de 2026 varia '+fmtNum(swing,0)+'% entre seu mês mais baixo ('+minM+', índice '+fmtNum(min,0)+') e mais alto ('+maxM+', índice '+fmtNum(max,0)+'). É o quanto o L/$1k bruto pode ser distorcido só pelo timing aqui — uma razão real para sempre checar a coluna "adj." antes de comparar dois criativos que foram ao ar em meses diferentes.'
    : 'En '+esc(data.territory)+', el índice de demanda de 2026 varía '+fmtNum(swing,0)+'% entre su mes más bajo ('+minM+', índice '+fmtNum(min,0)+') y más alto ('+maxM+', índice '+fmtNum(max,0)+'). Eso es cuánto se puede distorsionar el L/$1k crudo solo por timing acá — una razón real para siempre revisar la columna "adj." antes de comparar dos creativos que salieron al aire en meses distintos.';
}
function tbdInsightsMetaInsight(data){
  var found = tbdDeepInsights(data);
  if(!found.length) return null;
  var top = found[0];
  return LANG==='en'
    ? 'This load surfaced '+found.length+' cross-signal finding'+(found.length===1?'':'s')+' for '+esc(data.territory)+'. The strongest one: "'+top.title+'".'
    : LANG==='pt'
    ? 'Esta carga encontrou '+found.length+' achado'+(found.length===1?'':'s')+' de sinais cruzados para '+esc(data.territory)+'. O mais forte: "'+top.title+'".'
    : 'Esta carga encontró '+found.length+' hallazgo'+(found.length===1?'':'s')+' de señales cruzadas para '+esc(data.territory)+'. El más fuerte: "'+top.title+'".';
}
/* tbdTestsInsight() se elimino: tenia el umbral -20 escrito a mano y apuntaba
   al test A2, que ya no existe. El insight de la pestana ahora sale del propio
   motor de reglas. */
function tbdTestsInsight(data){
  var res = data.__tbdRes || (data.__tbdRes = tbdRunRules(data));
  if(!res.tests.length) return res.vacios.tests.length ? res.vacios.tests[0] : tbdLimiteDeteccion(res.ctx);
  var ctx = res.ctx;
  return tbdL('<b>Takeaway:</b> '+res.tests.length+' test(s) are readable in '+ctx.pais+' for '+ctx.marca+' given its '+tbdNP1(ctx.err)+' adjustment error and '+tbdUSD(ctx.spd)+'/day of spend. Everything that could not be read at this budget is listed as discarded, with what it would take.',
    '<b>Takeaway:</b> '+res.tests.length+' teste(s) sao legiveis em '+ctx.pais+' para '+ctx.marca+' dado seu erro de ajuste de '+tbdNP1(ctx.err)+' e '+tbdUSD(ctx.spd)+'/dia de gasto. Tudo que nao pode ser lido com este orcamento aparece como descartado, com o que faltaria.',
    '<b>Takeaway:</b> '+res.tests.length+' test(s) son legibles en '+ctx.pais+' para '+ctx.marca+' dado su error de ajuste de '+tbdNP1(ctx.err)+' y '+tbdUSD(ctx.spd)+'/dia de gasto. Todo lo que no se pudo leer con este presupuesto queda listado como descartado, con lo que le faltaria.');
}
/* ============================ motor de insights por correlacion ============================
   Cada detector cruza AL MENOS dos senales (nunca "el mejor de X" solo) y solo
   emite un hallazgo si el efecto supera un umbral minimo -- si no hay patron
   real, el detector no aporta nada (no se rellena con relleno). `strength`
   ordena que tan grande/accionable es el hallazgo, para mostrar primero lo
   mas fuerte. Disenado para correr igual, automaticamente, en CUALQUIER
   territorio -- no hay nada hardcodeado por pais. */
function tbdMonthlySpendByMonth(items){
  var out = {}; // 'YYYY-MM' -> spend
  items.forEach(function(r){ r._dailyItems.forEach(function(d){ var m=d.date.slice(0,7); out[m]=(out[m]||0)+d.s; }); });
  return out;
}
function tbdDetectSpendVsDemandTiming(data, year){
  var items = year==='2025' ? data.y25 : data.y26;
  var s = TBD_SEASONALITY[data.territory];
  if(!s || !items.length) return null;
  var spendByMonth = tbdMonthlySpendByMonth(items);
  var idxArr = year==='2025' ? s.jan_jul_2025 : s.jan_jul_2026;
  var months = ['01','02','03','04','05','06','07'].map(function(m){ return year+'-'+m; });
  var totalSpend = 0; months.forEach(function(m){ totalSpend += spendByMonth[m]||0; });
  if(totalSpend<=0) return null;
  // correlacion simple: peso de gasto de cada mes vs su indice de demanda (ambos normalizados a %)
  var weightedDemand = 0;
  months.forEach(function(m,i){ weightedDemand += ((spendByMonth[m]||0)/totalSpend) * idxArr[i]; });
  var flatDemand = idxArr.reduce(function(a,b){return a+b;},0)/idxArr.length;
  var gap = (weightedDemand-flatDemand)/flatDemand*100;
  if(Math.abs(gap)<6) return null;
  var bestIdx = idxArr.indexOf(Math.max.apply(null, idxArr));
  var worstIdx = idxArr.indexOf(Math.min.apply(null, idxArr));
  var monthNames = ['01','02','03','04','05','06','07'].map(mesLabel);
  return {
    strength: Math.abs(gap),
    icon: gap<0 ? '⚠' : '✓',
    title: (LANG==='en'?'Spend timing vs. natural demand — ':LANG==='pt'?'Timing de gasto vs. demanda natural — ':'Timing de gasto vs. demanda natural — ')+year,
    body: gap<0
      ? (LANG==='en'?'Spend is concentrated in months with BELOW-average natural demand (weighted demand index '+fmtNum(weightedDemand,0)+' vs. period average '+fmtNum(flatDemand,0)+'). The portfolio is fighting the tide: shifting budget toward '+monthNames[bestIdx]+' (the highest-demand month) instead of '+monthNames[worstIdx]+' would likely raise raw leads without spending more.'
        :LANG==='pt'?'O gasto está concentrado em meses com demanda natural ABAIXO da média (índice de demanda ponderado '+fmtNum(weightedDemand,0)+' vs. média do período '+fmtNum(flatDemand,0)+'). O portfólio está remando contra a maré: mover orçamento para '+monthNames[bestIdx]+' (o mês de maior demanda) em vez de '+monthNames[worstIdx]+' provavelmente aumentaria os leads brutos sem gastar mais.'
        :'El gasto está concentrado en meses con demanda natural POR DEBAJO del promedio (índice de demanda ponderado '+fmtNum(weightedDemand,0)+' vs. promedio del período '+fmtNum(flatDemand,0)+'). El portafolio está remando contra la corriente: mover presupuesto hacia '+monthNames[bestIdx]+' (el mes de mayor demanda) en vez de '+monthNames[worstIdx]+' probablemente subiría los leads crudos sin gastar más.')
      : (LANG==='en'?'Spend is well-timed: concentrated in months with ABOVE-average natural demand (weighted demand index '+fmtNum(weightedDemand,0)+' vs. period average '+fmtNum(flatDemand,0)+'). This is a real tailwind, not just creative quality — keep timing spend around '+monthNames[bestIdx]+'.'
        :LANG==='pt'?'O gasto está bem cronometrado: concentrado em meses com demanda natural ACIMA da média (índice de demanda ponderado '+fmtNum(weightedDemand,0)+' vs. média do período '+fmtNum(flatDemand,0)+'). Isso é um vento a favor real, não apenas qualidade criativa — mantenha o timing do gasto perto de '+monthNames[bestIdx]+'.'
        :'El gasto está bien cronometrado: concentrado en meses con demanda natural POR ENCIMA del promedio (índice de demanda ponderado '+fmtNum(weightedDemand,0)+' vs. promedio del período '+fmtNum(flatDemand,0)+'). Esto es un viento a favor real, no solo calidad creativa — mantén el timing de gasto cerca de '+monthNames[bestIdx]+'.'),
  };
}
function tbdDetectToneByAdType(data){
  var promo = tbdDimensionRollup(data.y26.filter(function(r){return r.ad_type==='PROMO';}), function(r){return r.tone_category||null;});
  var generic = tbdDimensionRollup(data.y26.filter(function(r){return r.ad_type==='GENERIC';}), function(r){return r.tone_category||null;});
  if(promo.length<2 || generic.length<2) return null;
  var bestPromo = promo[0], bestGeneric = generic[0];
  if(bestPromo.label===bestGeneric.label) return null; // no hay divergencia -> no es un hallazgo
  var promoOfThatToneInGeneric = generic.filter(function(x){return x.label===bestPromo.label;})[0];
  var genericOfThatToneInPromo = promo.filter(function(x){return x.label===bestGeneric.label;})[0];
  if(!promoOfThatToneInGeneric || !genericOfThatToneInPromo) return null;
  var gapPromoTone = (bestPromo.l1k_adj-promoOfThatToneInGeneric.l1k_adj)/promoOfThatToneInGeneric.l1k_adj*100;
  if(Math.abs(gapPromoTone)<15) return null;
  return {
    strength: Math.abs(gapPromoTone),
    icon:'→',
    title: LANG==='en'?'The winning tone is not the same for Promo and Generic':LANG==='pt'?'O tom vencedor não é o mesmo para Promo e Genérico':'El tono ganador no es el mismo para Promo y Genérico',
    body: (LANG==='en'?'"'+bestPromo.label+'" is the strongest tone in Promo creatives (L/$1k adj. '+fmtNum(bestPromo.l1k_adj,0)+') but only '+fmtNum(promoOfThatToneInGeneric.l1k_adj,0)+' in Generic — a '+fmtNum(Math.abs(gapPromoTone),0)+'% gap. Meanwhile "'+bestGeneric.label+'" leads Generic. This means tone selection should be briefed differently per ad type, not applied as one blanket creative direction.'
      :LANG==='pt'?'"'+bestPromo.label+'" é o tom mais forte em criativos Promo (L/$1k adj. '+fmtNum(bestPromo.l1k_adj,0)+') mas só '+fmtNum(promoOfThatToneInGeneric.l1k_adj,0)+' em Genérico — uma diferença de '+fmtNum(Math.abs(gapPromoTone),0)+'%. Enquanto isso "'+bestGeneric.label+'" lidera em Genérico. Isso significa que a escolha de tom deve ser briefada de forma diferente por tipo de anúncio, não como uma única direção criativa.'
      :'"'+bestPromo.label+'" es el tono más fuerte en creativos Promo (L/$1k adj. '+fmtNum(bestPromo.l1k_adj,0)+') pero solo '+fmtNum(promoOfThatToneInGeneric.l1k_adj,0)+' en Genérico — una brecha de '+fmtNum(Math.abs(gapPromoTone),0)+'%. Mientras tanto "'+bestGeneric.label+'" lidera en Genérico. Esto significa que la elección de tono debería briefearse distinto por tipo de anuncio, no como una sola dirección creativa pareja.'),
  };
}
function tbdDetectHookWearout(data){
  var byHook = {};
  data.y26.forEach(function(r){
    var w = tbdWearout(r);
    if(w.pct==null) return;
    var k = r.hook_audio_type_code||'—';
    (byHook[k]=byHook[k]||[]).push(w.pct);
  });
  var rows = Object.keys(byHook).filter(function(k){ return byHook[k].length>=2; }).map(function(k){
    var arr = byHook[k]; return {label:k, avg: arr.reduce(function(a,b){return a+b;},0)/arr.length, n:arr.length};
  });
  if(rows.length<2) return null;
  rows.sort(function(a,b){ return a.avg-b.avg; });
  var worst = rows[0], best = rows[rows.length-1];
  if(worst.avg>=-10 || (best.avg-worst.avg)<15) return null;
  return {
    strength: Math.abs(worst.avg),
    icon:'⚠',
    title: LANG==='en'?'One hook type wears out structurally faster':LANG==='pt'?'Um tipo de hook desgasta estruturalmente mais rápido':'Un tipo de hook se desgasta estructuralmente más rápido',
    body: (LANG==='en'?'Creatives using "'+worst.label+'" as audio hook lose '+fmtNum(Math.abs(worst.avg),0)+'% of their demand-adjusted L/$1k on average from their first half on air to their second half ('+worst.n+' creatives) — vs. "'+best.label+'" which holds up ('+fmtNum(best.avg,0)+'%). This looks like fatigue built into the hook mechanic itself, not into any single creative — worth avoiding for long flights.'
      :LANG==='pt'?'Criativos que usam "'+worst.label+'" como hook de áudio perdem '+fmtNum(Math.abs(worst.avg),0)+'% do L/$1k ajustado em média da primeira metade no ar para a segunda metade ('+worst.n+' criativos) — vs. "'+best.label+'" que se sustenta ('+fmtNum(best.avg,0)+'%). Isso parece ser fadiga embutida no próprio mecanismo do hook, não em um criativo específico — vale evitar em flights longos.'
      :'Los creativos que usan "'+worst.label+'" como hook de audio pierden '+fmtNum(Math.abs(worst.avg),0)+'% de su L/$1k ajustado en promedio de su primera mitad al aire a su segunda mitad ('+worst.n+' creativos) — vs. "'+best.label+'" que se sostiene ('+fmtNum(best.avg,0)+'%). Esto parece ser desgaste propio del mecanismo del hook, no de un creativo puntual — vale la pena evitarlo en flights largos.'),
  };
}
function tbdDetectNewVsRecurring(data){
  var names25 = {}; data.y25.forEach(function(r){ names25[r.nombre]=r; });
  var recurring = [], fresh = [];
  data.y26.forEach(function(r){ (names25[r.nombre] ? recurring : fresh).push(r); });
  if(recurring.length<2 || fresh.length<2) return null;
  var avg = function(arr){ return arr.reduce(function(s,r){return s+r.l1k_adj;},0)/arr.length; };
  var avgRec = avg(recurring), avgFresh = avg(fresh);
  var gap = (avgFresh-avgRec)/avgRec*100;
  if(Math.abs(gap)<12) return null;
  return {
    strength: Math.abs(gap),
    icon: gap>0?'✓':'✗',
    title: LANG==='en'?'New 2026 creatives vs. carried-over ones':LANG==='pt'?'Novos criativos de 2026 vs. os que continuaram':'Creativos nuevos de 2026 vs. los que se mantuvieron',
    body: gap>0
      ? (LANG==='en'?'The '+fresh.length+' creatives launched fresh in 2026 average L/$1k adj. of '+fmtNum(avgFresh,1)+', '+fmtNum(gap,0)+'% ABOVE the '+recurring.length+' carried over from 2025 ('+fmtNum(avgRec,1)+'). New creative development is paying off — worth protecting/growing that budget line.'
        :LANG==='pt'?'Os '+fresh.length+' criativos lançados em 2026 têm média de L/$1k adj. de '+fmtNum(avgFresh,1)+', '+fmtNum(gap,0)+'% ACIMA dos '+recurring.length+' que continuaram de 2025 ('+fmtNum(avgRec,1)+'). O desenvolvimento de novos criativos está valendo a pena — vale proteger/crescer essa linha de orçamento.'
        :'Los '+fresh.length+' creativos lanzados nuevos en 2026 promedian L/$1k adj. de '+fmtNum(avgFresh,1)+', '+fmtNum(gap,0)+'% POR ENCIMA de los '+recurring.length+' que se mantuvieron desde 2025 ('+fmtNum(avgRec,1)+'). La producción de creativos nuevos está rindiendo — vale la pena proteger/crecer esa línea de presupuesto.')
      : (LANG==='en'?'The '+recurring.length+' creatives carried over from 2025 still outperform the '+fresh.length+' new ones launched in 2026 by '+fmtNum(Math.abs(gap),0)+'% (L/$1k adj. '+fmtNum(avgRec,1)+' vs. '+fmtNum(avgFresh,1)+'). New production has not yet beaten the proven library — treat 2026 launches as tests, not replacements, until they catch up.'
        :LANG==='pt'?'Os '+recurring.length+' criativos que continuaram de 2025 ainda superam os '+fresh.length+' novos lançados em 2026 em '+fmtNum(Math.abs(gap),0)+'% (L/$1k adj. '+fmtNum(avgRec,1)+' vs. '+fmtNum(avgFresh,1)+'). A nova produção ainda não superou a biblioteca comprovada — trate os lançamentos de 2026 como testes, não substituições, até que alcancem.'
        :'Los '+recurring.length+' creativos que se mantuvieron desde 2025 todavía rinden '+fmtNum(Math.abs(gap),0)+'% mejor que los '+fresh.length+' nuevos lanzados en 2026 (L/$1k adj. '+fmtNum(avgRec,1)+' vs. '+fmtNum(avgFresh,1)+'). La producción nueva todavía no supera a la librería probada — trata los lanzamientos de 2026 como pruebas, no reemplazos, hasta que la alcancen.'),
  };
}
function tbdDetectRankReversal(data){
  var items = data.y26.filter(function(r){ return r.n>=3; });
  if(items.length<4) return null;
  var byRaw = items.slice().sort(function(a,b){ return b.l1k-a.l1k; });
  var byAdj = items.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; });
  var rawRank = {}, adjRank = {};
  byRaw.forEach(function(r,i){ rawRank[r.nombre]=i; });
  byAdj.forEach(function(r,i){ adjRank[r.nombre]=i; });
  var maxShift = null;
  items.forEach(function(r){
    var shift = rawRank[r.nombre]-adjRank[r.nombre]; // positivo = sube al ajustar por demanda
    if(!maxShift || Math.abs(shift)>Math.abs(maxShift.shift)) maxShift = {r:r, shift:shift};
  });
  if(!maxShift || Math.abs(maxShift.shift)<3) return null;
  var r = maxShift.r, up = maxShift.shift>0;
  return {
    strength: Math.abs(maxShift.shift)*4,
    icon: up?'★':'⚠',
    title: LANG==='en'?'Seasonality is hiding a creative’s true rank':LANG==='pt'?'A estacionalidade está escondendo o ranking real de um criativo':'La estacionalidad está escondiendo el ranking real de un creativo',
    body: (up
      ? (LANG==='en'?'"'+r.nombre+'" looks mid-pack on raw L/$1k (rank #'+(rawRank[r.nombre]+1)+') but jumps to #'+(adjRank[r.nombre]+1)+' once demand-adjusted — it aired during a low-demand stretch and is actually one of the strongest creatives once that’s corrected for. It is being undervalued by anyone reading raw numbers only.'
        :LANG==='pt'?'"'+r.nombre+'" parece mediano no L/$1k bruto (posição #'+(rawRank[r.nombre]+1)+') mas sobe para #'+(adjRank[r.nombre]+1)+' uma vez ajustado por demanda — foi ao ar num período de baixa demanda e na verdade é um dos criativos mais fortes já corrigido isso. Está sendo subestimado por quem olha só o número bruto.'
        :'"'+r.nombre+'" se ve mediano en L/$1k crudo (puesto #'+(rawRank[r.nombre]+1)+') pero sube a #'+(adjRank[r.nombre]+1)+' una vez ajustado por demanda — salió al aire en un tramo de baja demanda y en realidad es uno de los creativos más fuertes una vez corregido eso. Se está subestimando si solo se mira el número crudo.')
      : (LANG==='en'?'"'+r.nombre+'" looks strong on raw L/$1k (rank #'+(rawRank[r.nombre]+1)+') but drops to #'+(adjRank[r.nombre]+1)+' once demand-adjusted — most of its apparent performance is a high-demand tailwind, not creative quality. Do not use it as the creative brief template.'
        :LANG==='pt'?'"'+r.nombre+'" parece forte no L/$1k bruto (posição #'+(rawRank[r.nombre]+1)+') mas cai para #'+(adjRank[r.nombre]+1)+' uma vez ajustado por demanda — a maior parte da sua performance aparente é um vento a favor de alta demanda, não qualidade criativa. Não o use como modelo de briefing criativo.'
        :'"'+r.nombre+'" se ve fuerte en L/$1k crudo (puesto #'+(rawRank[r.nombre]+1)+') pero cae a #'+(adjRank[r.nombre]+1)+' una vez ajustado por demanda — la mayor parte de su performance aparente es viento a favor de alta demanda, no calidad creativa. No lo uses como plantilla de brief creativo.')),
  };
}
function tbdDetectJrHaloShare(data){
  /* El halo es bidireccional: viendo Open English son leads de Junior que el
     sistema atribuyo al gasto adulto, y viendo Junior es exactamente al reves.
     Antes la direccion estaba escrita a mano en los 3 idiomas, asi que quien
     miraba Junior leia un texto redactado para OE. Ahora se nombra con
     tbdOrgName()/tbdHaloTargetName(), igual que el resto del reporte. */
  var totalJr = 0, totalOe = 0;
  data.y26.forEach(function(r){ totalJr += (r.jr_l||0); totalOe += r.l; });
  if(totalOe <= 0 || totalJr <= 0) return null;
  var pct = totalJr/totalOe*100;
  if(pct < 3) return null;
  var aport = data.y26.filter(function(r){ return (r.jr_l||0) > 0; })
    .sort(function(a,b){ return b.jr_l - a.jr_l; });
  var L = LANG, from = tbdOrgName(), to = tbdHaloTargetName();
  var top = aport[0];
  return {
    strength: pct*2, icon: '\u{1F517}',
    f: { pct: pct, totalJr: totalJr, totalOe: totalOe, topAportantes: aport.slice(0,3), nAportantes: aport.length },
    title: L==='en' ? 'TV spend on '+from+' is also producing '+to+' leads'
      : L==='pt' ? 'O investimento de TV em '+from+' tambem esta gerando leads de '+to
      : 'La inversion en TV de '+from+' tambien esta generando leads de '+to,
    body: L==='en'
      ? 'For every 100 '+from+' leads this period, another '+fmtNum(pct,0)+' real '+to+' leads came in that the source system attributed to '+from+' spend ('+fmtNum(totalJr,0)+' leads across '+aport.length+' creatives'+(top?', led by "'+top.nombre+'" with '+fmtNum(top.jr_l,0):'')+'). They are not counted anywhere in the '+from+' numbers, so the real return on this budget is higher than the tables show.'
      : L==='pt'
      ? 'A cada 100 leads de '+from+' neste periodo, entraram outros '+fmtNum(pct,0)+' leads reais de '+to+' que o sistema de origem atribuiu ao gasto de '+from+' ('+fmtNum(totalJr,0)+' leads em '+aport.length+' criativos'+(top?', puxados por "'+top.nombre+'" com '+fmtNum(top.jr_l,0):'')+'). Nao estao contados em nenhum numero de '+from+', entao o retorno real deste orcamento e maior do que as tabelas mostram.'
      : 'Por cada 100 leads de '+from+' de este periodo entraron otros '+fmtNum(pct,0)+' leads reales de '+to+' que el sistema de origen le atribuyo al gasto de '+from+' ('+fmtNum(totalJr,0)+' leads repartidos en '+aport.length+' creativos'+(top?', encabezados por "'+top.nombre+'" con '+fmtNum(top.jr_l,0):'')+'). No estan contados en ningun numero de '+from+', asi que el retorno real de este presupuesto es mayor que el que muestran las tablas.'
  };
}
function tbdDetectCvrDivergence(data){
  var items = data.y26.filter(function(r){ return r.n>=3; });
  if(items.length<4) return null;
  var avgCvr = items.reduce(function(s,r){return s+r.cvr;},0)/items.length;
  var byL1k = items.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;});
  var topLeadGen = byL1k[0];
  if(!topLeadGen || avgCvr<=0) return null;
  var cvrGap = (topLeadGen.cvr-avgCvr)/avgCvr*100;
  if(cvrGap>-25) return null; // solo interesa si el mejor generador de leads convierte MUCHO peor que el promedio
  return {
    strength: Math.abs(cvrGap),
    icon:'⚠',
    title: LANG==='en'?'The top lead generator converts worse than average':LANG==='pt'?'O maior gerador de leads converte pior que a média':'El mayor generador de leads convierte peor que el promedio',
    body: (LANG==='en'?'"'+topLeadGen.nombre+'" is the #1 creative by L/$1k adj. ('+fmtNum(topLeadGen.l1k_adj,0)+') but its conversion rate ('+fmtPct(topLeadGen.cvr,1)+') is '+fmtNum(Math.abs(cvrGap),0)+'% below the portfolio average ('+fmtPct(avgCvr,1)+'). It is winning on lead VOLUME per dollar, not lead QUALITY — worth checking whether it is attracting less-qualified prospects before scaling it further.'
      :LANG==='pt'?'"'+topLeadGen.nombre+'" é o criativo #1 por L/$1k adj. ('+fmtNum(topLeadGen.l1k_adj,0)+') mas sua taxa de conversão ('+fmtPct(topLeadGen.cvr,1)+') está '+fmtNum(Math.abs(cvrGap),0)+'% abaixo da média do portfólio ('+fmtPct(avgCvr,1)+'). Ele está ganhando em VOLUME de leads por dólar, não em QUALIDADE — vale checar se está atraindo prospects menos qualificados antes de escalar ainda mais.'
      :'"'+topLeadGen.nombre+'" es el creativo #1 por L/$1k adj. ('+fmtNum(topLeadGen.l1k_adj,0)+') pero su tasa de conversión ('+fmtPct(topLeadGen.cvr,1)+') está '+fmtNum(Math.abs(cvrGap),0)+'% por debajo del promedio del portafolio ('+fmtPct(avgCvr,1)+'). Está ganando en VOLUMEN de leads por dólar, no en CALIDAD — vale la pena revisar si está atrayendo prospectos menos calificados antes de escalarlo más.'),
  };
}
/* ============================================================
   MOTORES DE ANALISIS PROFUNDO (panel de 5 expertos por pestana)
   ------------------------------------------------------------
   Diseñados por un panel de 5 lentes (big data/estadistica, CMO,
   psicologia del consumidor, audiovisual, comunicacion) que analizo CADA
   tabla por separado, seguido de un revisor adversarial que endurecio
   umbrales y descarto 14 detectores por no ser verificables con estos datos.

   Reglas que cumplen TODOS los motores de esta seccion:
   - Toda razon se calcula pooled sobre sumas crudas (Σl/Σs), NUNCA
     promediando razones por creativo.
   - Los gates de muestra se evaluan ANTES de cualquier division.
   - Si el patron no supera el umbral, devuelven null: el silencio es una
     respuesta valida y esperada en muchos slices.
   ============================================================ */

/* Spearman con empates por rango promedio (no Pearson: las metricas por
   creativo son fuertemente asimetricas y unos pocos vuelos cortos con
   l1k alto dominarian una correlacion lineal). */
function tbdRanks(arr){
  var idx = arr.map(function(v,i){ return {v:v,i:i}; }).sort(function(a,b){ return a.v-b.v; });
  var ranks = new Array(arr.length);
  var k=0;
  while(k<idx.length){
    var j=k; while(j+1<idx.length && idx[j+1].v===idx[k].v) j++;
    var avg=(k+j)/2+1;
    for(var m=k;m<=j;m++) ranks[idx[m].i]=avg;
    k=j+1;
  }
  return ranks;
}
function tbdSpearman(xs, ys){
  var n=xs.length;
  if(n<4) return null;
  var rx=tbdRanks(xs), ry=tbdRanks(ys);
  var mx=rx.reduce(function(a,b){return a+b;},0)/n, my=ry.reduce(function(a,b){return a+b;},0)/n;
  var num=0, dx=0, dy=0;
  for(var i=0;i<n;i++){ var a=rx[i]-mx, b=ry[i]-my; num+=a*b; dx+=a*a; dy+=b*b; }
  if(dx<=0||dy<=0) return null;
  return num/Math.sqrt(dx*dy);
}
/* pooled sobre un subconjunto arbitrario, misma matematica que tbdDimensionRollup */
function tbdPooled(items){
  if(!items || !items.length) return null;
  var tl=0,ts=0,te=0,tc=0,dw=0,days=0;
  items.forEach(function(r){ tl+=r.l; ts+=r.s; te+=r.e; tc+=(r.c||0); dw+=r.dem*r.s; days+=r.n; });
  if(ts<=0) return null;
  var di = dw/ts;
  return { l:tl, s:ts, e:te, c:tc, days:days, n:items.length, dem:di,
    l1k: tl/ts*1000, l1k_adj: tl/ts*1000/(di/100),
    cpl_adj: tl>0 ? ts/tl*(di/100) : null,
    cvr: tl>0 ? te/tl : 0, mncc: tc>0 ? (tc-ts)/tc : 0 };
}

/* ---------- G3 · AUDITORIA DEL AJUSTE ----------
   Pregunta que ninguna pestana hacia: ¿el indice de Ahrefs esta realmente
   limpiando el calendario? Si la correlacion entre demanda y rendimiento
   SOBREVIVE al ajuste, el ranking que el usuario lee sigue contaminado por
   el mes. Se compara rho crudo vs rho ajustado -- mirar solo el ajustado
   seria el error. rhoCrit se endurece cuando hay menos creativos. */
function tbdSeasonAdjustmentAudit(items){
  var u = items.filter(function(r){ return r.n>=5 && r.s>0 && r.l>0; });
  var N = u.length;
  if(N<8) return null;
  var dem = u.map(function(r){return r.dem;});
  var rhoRaw = tbdSpearman(dem, u.map(function(r){return r.l1k;}));
  var rhoAdj = tbdSpearman(dem, u.map(function(r){return r.l1k_adj;}));
  if(rhoRaw==null||rhoAdj==null) return null;
  var rhoCrit = Math.max(2/Math.sqrt(N-1), 0.55);
  if(Math.abs(rhoAdj) < rhoCrit) return null;
  if(Math.abs(rhoRaw)>0 && Math.abs(rhoAdj) < 0.60*Math.abs(rhoRaw)) return null; // el ajuste si funciono
  var absorbed = Math.abs(rhoRaw)>0 ? Math.max(0,(1-Math.abs(rhoAdj)/Math.abs(rhoRaw))*100) : 0;
  var under = rhoAdj>0;
  var L=LANG;
  return { strength: Math.abs(rhoAdj)*100, icon:'⚖',
    title: L==='en'?'The demand adjustment isn\'t fully cleaning the calendar here':L==='pt'?'O ajuste por demanda não está limpando o calendário aqui':'El ajuste por demanda no está limpiando del todo el calendario aquí',
    body: (L==='en'
      ? 'Across '+N+' creatives, the correlation between the demand index and performance is '+fmtNum(rhoRaw,2)+' on raw L/$1k and still '+fmtNum(rhoAdj,2)+' after adjusting (chance threshold '+fmtNum(rhoCrit,2)+'). The index only absorbed '+fmtNum(absorbed,0)+'% of the seasonal signal, so the order you are reading is still partly calendar. '+(under?'It UNDER-corrects: creatives that aired in high-demand months keep an edge they did not earn.':'It OVER-corrects: creatives that aired in high-demand months are being penalised too hard.')+' Until this is recalibrated, compare creatives within the same demand band, not across the whole list.'
      : L==='pt'
      ? 'Entre '+N+' criativos, a correlação entre o índice de demanda e a performance é '+fmtNum(rhoRaw,2)+' no L/$1k bruto e ainda '+fmtNum(rhoAdj,2)+' depois de ajustar (limite de acaso '+fmtNum(rhoCrit,2)+'). O índice só absorveu '+fmtNum(absorbed,0)+'% do sinal sazonal, então a ordem que você lê ainda é em parte calendário. '+(under?'Ele SUB-corrige: criativos que foram ao ar em meses de alta demanda mantêm uma vantagem que não conquistaram.':'Ele SOBRE-corrige: criativos que foram ao ar em meses de alta demanda estão sendo penalizados demais.')+' Até recalibrar, compare criativos dentro da mesma faixa de demanda, não na lista inteira.'
      : 'Entre '+N+' creativos, la correlación entre el índice de demanda y el rendimiento es '+fmtNum(rhoRaw,2)+' en L/$1k crudo y sigue en '+fmtNum(rhoAdj,2)+' después de ajustar (umbral de azar '+fmtNum(rhoCrit,2)+'). El índice solo absorbió '+fmtNum(absorbed,0)+'% de la señal estacional, así que el orden que estás leyendo sigue siendo en parte calendario. '+(under?'SUB-corrige: los creativos que salieron en meses de alta demanda conservan una ventaja que no se ganaron.':'SOBRE-corrige: los creativos que salieron en meses de alta demanda están siendo castigados de más.')+' Hasta recalibrarlo, compara creativos dentro de la misma banda de demanda, no contra toda la lista.') };
}

/* ---------- G1 · ELASTICIDAD POR BANDA DE DEMANDA ----------
   El corazon del "analizar estacionalidad en TODAS las tablas": para cada
   valor de una dimension, separa sus creativos entre los que volaron en
   demanda ALTA y en demanda BAJA y compara su rendimiento AJUSTADO en cada
   banda. Distingue dos perfiles que el ranking plano confunde:
     - "surfista de ola": solo gana en demanda alta -> su puesto es calendario
     - "motor de valle": sostiene o mejora en demanda baja -> el mensaje si carga
   Devuelve una lista de perfiles, no un unico hallazgo. */
function tbdSeasonBands(items, keyFn, opts){
  opts = opts || {};
  var minCre = opts.minCre || 2, minDays = opts.minDays || 6, minSpend = opts.minSpend || 1500;
  var u = items.filter(function(r){ return r.s>0 && r.n>=3; });
  if(u.length<6) return null;
  var dems = u.map(function(r){return r.dem;}).sort(function(a,b){return a-b;});
  var med = dems[Math.floor(dems.length/2)];
  var p25 = dems[Math.floor(dems.length*0.25)], p75 = dems[Math.floor(dems.length*0.75)];
  if((p75-p25) < 6) return null; // sin dispersion real de demanda la pregunta no aplica
  var buckets = {};
  u.forEach(function(r){
    var k = keyFn(r); if(k==null||k==='') return;
    if(!buckets[k]) buckets[k] = {hi:[], lo:[]};
    if(r.dem >= med+3) buckets[k].hi.push(r);
    else if(r.dem <= med-3) buckets[k].lo.push(r);
  });
  var out = [];
  Object.keys(buckets).forEach(function(k){
    var b = buckets[k];
    if(b.hi.length<minCre || b.lo.length<minCre) return;
    var hi = tbdPooled(b.hi), lo = tbdPooled(b.lo);
    if(!hi||!lo) return;
    if(hi.days<minDays || lo.days<minDays || hi.s<minSpend || lo.s<minSpend) return;
    if(lo.l1k_adj<=0) return;
    out.push({ label:k, hi:hi, lo:lo, gap:(hi.l1k_adj-lo.l1k_adj)/lo.l1k_adj*100 });
  });
  if(!out.length) return null;
  return { median:med, profiles: out.sort(function(a,b){ return Math.abs(b.gap)-Math.abs(a.gap); }) };
}
/* ---------- G2 · SESGO DE EXPOSICION ----------
   ¿Esta dimension fue programada sistematicamente en meses mejores o peores
   que el resto del portafolio? Un valor puede verse bien solo porque le
   tocaron los meses buenos -- eso el ranking ajustado corrige en la metrica,
   pero NO le dice al planner que su calendario esta sesgado. */
function tbdSeasonExposure(items, keyFn, opts){
  opts = opts || {};
  var minDays = opts.minDays || 10, minSpend = opts.minSpend || 3000;
  var u = items.filter(function(r){ return r.s>0 && r.n>=3; });
  var all = tbdPooled(u);
  if(!all) return null;
  var roll = {};
  u.forEach(function(r){ var k=keyFn(r); if(k==null||k==='') return; (roll[k]=roll[k]||[]).push(r); });
  var out = [];
  Object.keys(roll).forEach(function(k){
    var p = tbdPooled(roll[k]);
    if(!p || p.days<minDays || p.s<minSpend) return;
    out.push({ label:k, dem:p.dem, gap:p.dem-all.dem, share:p.s/all.s, pooled:p });
  });
  if(out.length<2) return null;
  out.sort(function(a,b){ return Math.abs(b.gap)-Math.abs(a.gap); });
  return { portfolioDem: all.dem, rows: out };
}

/* ---------- G6 · FRAGILIDAD DE FILA (leave-one-out) ----------
   ¿El liderazgo de una categoria sobrevive si le quitas su mejor creativo?
   Si no, la fila no describe una categoria: describe una sola pieza. Es el
   antidoto directo al error de briefear "usemos mas HUMOR" cuando en
   realidad habia un solo comercial bueno que resultaba ser HUMOR. */
function tbdDetectDimRowFragility(data, dims){
  dims = dims || ['tone_category','theme_mechanism_code','hook_audio_type_code','hook_visual_type_code','type_of_production'];
  var best=null;
  dims.forEach(function(dimKey){
    var keyFn = TBD_DIM_DEFS[dimKey].keyFn;
    var roll = tbdDimensionRollup(data.y26, keyFn).filter(function(x){ return x.days>=5 && x.n>=3; });
    if(roll.length<2) return;
    var leader = roll[0], runner = roll[1];
    var members = data.y26.filter(function(r){ return String(keyFn(r))===String(leader.label); });
    if(members.length<3) return;
    var top = members.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    var without = tbdPooled(members.filter(function(r){ return r!==top; }));
    if(!without || without.days<4) return;
    if(!(without.l1k_adj < runner.l1k_adj)) return; // sigue liderando: no es fragil
    var drop = (leader.l1k_adj-without.l1k_adj)/leader.l1k_adj*100;
    if(drop<15) return;
    var topShare = leader.s>0 ? top.s/leader.s : 0;
    if(!best || drop>best.drop) best = {dimKey:dimKey, leader:leader, runner:runner, top:top, without:without, drop:drop, topShare:topShare};
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  var hyp2 = L==='en'?'A category label is not a mechanism: one execution can be excellent for reasons that have nothing to do with the tag it carries, and the roll-up then credits the tag.'
    :L==='pt'?'Um rotulo de categoria nao e um mecanismo: uma execucao pode ser excelente por razoes que nada tem a ver com a tag que carrega, e o roll-up entao credita a tag.'
    :'Una etiqueta de categoria no es un mecanismo: una ejecucion puede ser excelente por razones que no tienen nada que ver con la etiqueta que carga, y el agregado le termina dando el credito a la etiqueta.';
  var others = best.leader.n - 1;
  var chk2 = L==='en'?'Cross-checked against the rest of the group: the other '+others+' creative(s) tagged "'+best.leader.label+'" only reach '+fmtNum(best.without.l1k_adj,0)+' between them, which is what the category is really worth without its outlier. Before scaling the tag, brief a second piece that copies what the outlier actually did.'
    :L==='pt'?'Comprovado contra o resto do grupo: os outros '+others+' criativo(s) marcados como "'+best.leader.label+'" chegam apenas a '+fmtNum(best.without.l1k_adj,0)+' entre eles, que e o que a categoria realmente vale sem seu outlier. Antes de escalar a tag, faca o brief de uma segunda peca que copie o que o outlier de fato fez.'
    :'Comprobado contra el resto del grupo: los otros '+others+' creativo(s) etiquetados como "'+best.leader.label+'" llegan apenas a '+fmtNum(best.without.l1k_adj,0)+' entre todos, que es lo que de verdad vale la categoria sin su pieza atipica. Antes de escalar la etiqueta, briefea una segunda pieza que copie lo que hizo esa pieza en concreto.';
  return { strength: best.drop, icon:'🎯', hypothesis:hyp2, check:chk2,
    title: L==='en'?'The leading '+dl+' is one creative, not a category':L==='pt'?'O '+dl+' líder é um criativo, não uma categoria':'El '+dl+' líder es un creativo, no una categoría',
    body: (L==='en'
      ? '"'+best.leader.label+'" tops the '+dl+' ranking (L/$1k adj. '+fmtNum(best.leader.l1k_adj,0)+' across '+best.leader.n+' creatives), but remove its single best piece ("'+best.top.nombre+'", '+fmtNum(best.topShare*100,0)+'% of the group\'s spend) and the group falls to '+fmtNum(best.without.l1k_adj,0)+' — below "'+best.runner.label+'" ('+fmtNum(best.runner.l1k_adj,0)+'), a '+fmtNum(best.drop,0)+'% drop. Briefing more of this '+dl+' is not the lesson; replicating what that one creative did is.'
      : L==='pt'
      ? '"'+best.leader.label+'" lidera o ranking de '+dl+' (L/$1k adj. '+fmtNum(best.leader.l1k_adj,0)+' em '+best.leader.n+' criativos), mas remova sua melhor peça ("'+best.top.nombre+'", '+fmtNum(best.topShare*100,0)+'% do gasto do grupo) e o grupo cai para '+fmtNum(best.without.l1k_adj,0)+' — abaixo de "'+best.runner.label+'" ('+fmtNum(best.runner.l1k_adj,0)+'), uma queda de '+fmtNum(best.drop,0)+'%. Briefar mais desse '+dl+' não é a lição; replicar o que aquele criativo fez, sim.'
      : '"'+best.leader.label+'" encabeza el ranking de '+dl+' (L/$1k adj. '+fmtNum(best.leader.l1k_adj,0)+' entre '+best.leader.n+' creativos), pero quítale su mejor pieza ("'+best.top.nombre+'", '+fmtNum(best.topShare*100,0)+'% del gasto del grupo) y el grupo cae a '+fmtNum(best.without.l1k_adj,0)+' — por debajo de "'+best.runner.label+'" ('+fmtNum(best.runner.l1k_adj,0)+'), una caída de '+fmtNum(best.drop,0)+'%. La lección no es briefear más de este '+dl+'; es replicar lo que hizo ese creativo puntual.') };
}

/* ---------- G4 · PARADOJA DE SIMPSON ----------
   El agregado dice una cosa y TODOS los estratos dicen la contraria. Ocurre
   cuando un grupo concentro su gasto en los meses buenos. Es el hallazgo
   mas contraintuitivo posible sobre una tabla y ninguna lectura plana lo ve. */
function tbdDetectSimpsonReversal(data, splitKeyFn, strataKeyFn, labelFn){
  splitKeyFn = splitKeyFn || function(r){ return r.ad_type==='PROMO'?'Promo':'Generic'; };
  strataKeyFn = strataKeyFn || function(r){ return (r._dailyItems&&r._dailyItems.length)? r._dailyItems[0].date.slice(0,7) : null; };
  var u = data.y26.filter(function(r){ return r.s>0 && r.n>=3; });
  if(u.length<6) return null;
  var groups = {};
  u.forEach(function(r){ var g=splitKeyFn(r); if(g==null) return; (groups[g]=groups[g]||[]).push(r); });
  var names = Object.keys(groups);
  if(names.length!==2) return null;
  var A = tbdPooled(groups[names[0]]), B = tbdPooled(groups[names[1]]);
  if(!A||!B||A.l1k_adj<=0||B.l1k_adj<=0) return null;
  var aggWinner = A.l1k_adj>=B.l1k_adj ? names[0] : names[1];
  // estratos: mes de arranque
  var strata = {};
  u.forEach(function(r){ var s=strataKeyFn(r); if(s==null) return; (strata[s]=strata[s]||[]).push(r); });
  var flipped=0, valid=0;
  Object.keys(strata).forEach(function(sk){
    var inS = strata[sk];
    var a = tbdPooled(inS.filter(function(r){ return splitKeyFn(r)===names[0]; }));
    var b = tbdPooled(inS.filter(function(r){ return splitKeyFn(r)===names[1]; }));
    if(!a||!b||a.days<4||b.days<4||a.s<1000||b.s<1000) return;
    valid++;
    var winner = a.l1k_adj>=b.l1k_adj ? names[0] : names[1];
    if(winner!==aggWinner) flipped++;
  });
  if(valid<3 || flipped<valid) return null; // exige reversion en TODOS los estratos validos
  var L=LANG;
  var loser = aggWinner===names[0]?names[1]:names[0];
  var lbl = labelFn || function(x){ return x; };
  var demA = A.dem, demB = B.dem;
  var winnerDem = aggWinner===names[0]?demA:demB, loserDem = aggWinner===names[0]?demB:demA;
  var hyp3 = LANG==='en'?'The apparent winner was scheduled into better months. When one group is concentrated in high-demand weeks, its pooled number inherits that tailwind even though month by month it is the weaker option.'
    :LANG==='pt'?'O vencedor aparente foi programado nos meses melhores. Quando um grupo se concentra em semanas de alta demanda, seu numero agregado herda esse vento a favor mesmo sendo, mes a mes, a opcao mais fraca.'
    :'Al ganador aparente le tocaron los meses mejores. Cuando un grupo se concentra en semanas de alta demanda, su numero agregado hereda ese viento a favor aunque mes a mes sea la opcion mas debil.';
  var chk3 = LANG==='en'?'Cross-checked with the demand index each group actually ran in: "'+lbl(aggWinner)+'" averaged an index of '+fmtNum(winnerDem,0)+' versus '+fmtNum(loserDem,0)+' for "'+lbl(loser)+'" — '+(winnerDem>loserDem?'which confirms the calendar explanation.':'which does NOT confirm the calendar explanation, so the reversal is being driven by something else — check spend concentration inside each group before acting.')
    :LANG==='pt'?'Comprovado com o indice de demanda em que cada grupo realmente rodou: "'+lbl(aggWinner)+'" teve indice medio de '+fmtNum(winnerDem,0)+' contra '+fmtNum(loserDem,0)+' de "'+lbl(loser)+'" — '+(winnerDem>loserDem?'o que confirma a explicacao de calendario.':'o que NAO confirma a explicacao de calendario, entao a inversao vem de outra coisa — verifique a concentracao de gasto dentro de cada grupo antes de agir.')
    :'Comprobado con el indice de demanda en que efectivamente corrio cada grupo: "'+lbl(aggWinner)+'" promedio un indice de '+fmtNum(winnerDem,0)+' contra '+fmtNum(loserDem,0)+' de "'+lbl(loser)+'" — '+(winnerDem>loserDem?'lo que confirma la explicacion de calendario.':'lo que NO confirma la explicacion de calendario, asi que la inversion viene de otra cosa — revisa la concentracion de gasto dentro de cada grupo antes de accionar.');
  return { strength: 60+valid*8, icon:'🔄', hypothesis:hyp3, check:chk3,
    title: L==='en'?'Simpson\'s paradox: the aggregate says the opposite of every month':L==='pt'?'Paradoxo de Simpson: o agregado diz o oposto de cada mês':'Paradoja de Simpson: el agregado dice lo contrario que cada mes',
    body: (L==='en'
      ? 'Taken as a whole, "'+lbl(aggWinner)+'" beats "'+lbl(loser)+'" (L/$1k adj. '+fmtNum(aggWinner===names[0]?A.l1k_adj:B.l1k_adj,0)+' vs '+fmtNum(aggWinner===names[0]?B.l1k_adj:A.l1k_adj,0)+'). But split the same data by launch month and "'+lbl(loser)+'" wins in ALL '+valid+' comparable months. The aggregate is being driven by WHEN each group aired, not by how it performed: the apparent winner simply concentrated its spend in better months. Trust the monthly reading and stop using the headline number to justify the mix.'
      : L==='pt'
      ? 'No agregado, "'+lbl(aggWinner)+'" supera "'+lbl(loser)+'" (L/$1k adj. '+fmtNum(aggWinner===names[0]?A.l1k_adj:B.l1k_adj,0)+' vs '+fmtNum(aggWinner===names[0]?B.l1k_adj:A.l1k_adj,0)+'). Mas separando os mesmos dados por mês de estreia, "'+lbl(loser)+'" vence em TODOS os '+valid+' meses comparáveis. O agregado é dirigido por QUANDO cada grupo foi ao ar, não pelo desempenho: o vencedor aparente apenas concentrou seu gasto nos meses melhores. Confie na leitura mensal e pare de usar o número de manchete para justificar o mix.'
      : 'Tomado en conjunto, "'+lbl(aggWinner)+'" le gana a "'+lbl(loser)+'" (L/$1k adj. '+fmtNum(aggWinner===names[0]?A.l1k_adj:B.l1k_adj,0)+' vs '+fmtNum(aggWinner===names[0]?B.l1k_adj:A.l1k_adj,0)+'). Pero al separar los MISMOS datos por mes de lanzamiento, "'+lbl(loser)+'" gana en LOS '+valid+' meses comparables. El agregado lo está manejando CUÁNDO salió cada grupo al aire, no su desempeño: el ganador aparente simplemente concentró su gasto en los meses buenos. Hazle caso a la lectura mensual y deja de usar el número de titular para justificar la mezcla.') };
}

/* ---------- G9 · TECHO DE ESCALA ----------
   El ganador de la tabla ¿ha demostrado capacidad a volumen, o solo brillo a
   escala chica? Un lider con una fraccion minima del gasto no ha probado que
   aguante el presupuesto que se le quiere dar. */
function tbdDetectDimScaleCeiling(data, dims){
  dims = dims || ['tone_category','theme_mechanism_code','type_of_production','hook_audio_type_code'];
  var best=null;
  dims.forEach(function(dimKey){
    var roll = tbdDimensionRollup(data.y26, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){ return x.days>=5; });
    if(roll.length<3) return;
    var total = roll.reduce(function(s,x){return s+x.s;},0);
    if(total<=0) return;
    var leader = roll[0];
    var share = leader.s/total;
    var biggest = roll.slice().sort(function(a,b){ return b.s-a.s; })[0];
    if(biggest.label===leader.label) return;           // el lider ya es el mas grande: si probo escala
    if(share>0.15) return;                              // ya tiene volumen relevante
    var ratio = biggest.s>0 ? leader.s/biggest.s : 0;
    if(ratio>0.4) return;
    var lift = biggest.l1k_adj>0 ? (leader.l1k_adj-biggest.l1k_adj)/biggest.l1k_adj*100 : 0;
    if(lift<15) return;
    if(!best || share<best.share) best = {dimKey:dimKey, leader:leader, biggest:biggest, share:share, lift:lift};
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  var hyp4 = L==='en'?'Small budgets buy the cheapest, most responsive inventory first. As spend grows you buy progressively worse slots and hit frequency saturation, so efficiency measured at low weight rarely survives at full weight.'
    :L==='pt'?'Orcamentos pequenos compram primeiro o inventario mais barato e responsivo. Conforme o gasto cresce voce compra espacos progressivamente piores e bate na saturacao de frequencia, entao a eficiencia medida com pouco peso raramente sobrevive no peso total.'
    :'Los presupuestos chicos compran primero el inventario mas barato y mas receptivo. A medida que crece el gasto vas comprando espacios progresivamente peores y chocas con saturacion de frecuencia, asi que la eficiencia medida con poco peso rara vez sobrevive a peso completo.';
  var chk4 = L==='en'?'Partial cross-check available: the workhorse "'+best.biggest.label+'" carries '+fmt$(best.biggest.s,0)+' and still delivers '+fmtNum(best.biggest.l1k_adj,0)+', which is the realistic benchmark at that weight. Scale the leader in steps and compare it against that number, not against its current small-budget figure.'
    :L==='pt'?'Comprovacao parcial disponivel: o cavalo de batalha "'+best.biggest.label+'" carrega '+fmt$(best.biggest.s,0)+' e ainda entrega '+fmtNum(best.biggest.l1k_adj,0)+', que e o benchmark realista nesse peso. Escale o lider por etapas e compare contra esse numero, nao contra a cifra atual de orcamento pequeno.'
    :'Hay comprobacion parcial: el caballo de batalla "'+best.biggest.label+'" carga '+fmt$(best.biggest.s,0)+' y aun asi entrega '+fmtNum(best.biggest.l1k_adj,0)+', que es el benchmark realista a ese peso. Escala al lider por etapas y compara contra ese numero, no contra su cifra actual de presupuesto chico.';
  return { strength: (0.15-best.share)*400+best.lift, icon:'📐', hypothesis:hyp4, check:chk4,
    title: L==='en'?'The winning '+dl+' has never been tested at scale':L==='pt'?'O '+dl+' vencedor nunca foi testado em escala':'El '+dl+' ganador nunca se ha probado a escala',
    body: (L==='en'
      ? '"'+best.leader.label+'" leads on L/$1k adj. ('+fmtNum(best.leader.l1k_adj,0)+', '+fmtNum(best.lift,0)+'% above the workhorse "'+best.biggest.label+'") but it only carries '+fmtNum(best.share*100,1)+'% of the '+dl+' spend, against '+fmt$(best.biggest.s,0)+' for the workhorse. Efficiency at small budget is not proof it holds at full weight — reach and frequency effects usually bite as spend grows. Scale it in steps and re-read before rewriting the plan around it.'
      : L==='pt'
      ? '"'+best.leader.label+'" lidera em L/$1k adj. ('+fmtNum(best.leader.l1k_adj,0)+', '+fmtNum(best.lift,0)+'% acima do cavalo de batalha "'+best.biggest.label+'") mas carrega apenas '+fmtNum(best.share*100,1)+'% do gasto de '+dl+', contra '+fmt$(best.biggest.s,0)+' do cavalo de batalha. Eficiência com orçamento pequeno não prova que se sustenta em peso total — efeitos de alcance e frequência costumam aparecer conforme o gasto cresce. Escale por etapas e releia antes de reescrever o plano em torno dele.'
      : '"'+best.leader.label+'" lidera en L/$1k adj. ('+fmtNum(best.leader.l1k_adj,0)+', '+fmtNum(best.lift,0)+'% por encima del caballo de batalla "'+best.biggest.label+'") pero solo carga '+fmtNum(best.share*100,1)+'% del gasto de '+dl+', contra '+fmt$(best.biggest.s,0)+' del caballo de batalla. Ser eficiente con presupuesto chico no prueba que aguante a peso completo — los efectos de alcance y frecuencia suelen aparecer al crecer el gasto. Escálalo por etapas y vuelve a leer antes de reescribir el plan alrededor de él.') };
}

/* ---------- G5 · DESCOMPOSICION MEZCLA vs TASA ----------
   El cambio ano contra ano ¿viene de que los creativos rinden distinto
   (tasa) o de que se repartio el gasto distinto entre categorias (mezcla)?
   Son dos conversaciones completamente distintas: una es creativa, la otra
   es de planeacion de medios. */
function tbdDetectMixShift(data, dimKey){
  dimKey = dimKey || 'ad_type';
  var keyFn = TBD_DIM_DEFS[dimKey].keyFn;
  var a = data.y25.filter(function(r){return r.s>0;}), b = data.y26.filter(function(r){return r.s>0;});
  var pa = tbdPooled(a), pb = tbdPooled(b);
  if(!pa||!pb||pa.l1k_adj<=0) return null;
  var ra = tbdDimensionRollup(a, keyFn), rb = tbdDimensionRollup(b, keyFn);
  if(ra.length<2||rb.length<2) return null;
  var ma={}, mb={};
  ra.forEach(function(x){ ma[x.label]=x; }); rb.forEach(function(x){ mb[x.label]=x; });
  var labels = Object.keys(ma).filter(function(k){ return mb[k]; });
  if(labels.length<2) return null;
  var wa={}, wb={}, maxShift=0, shiftLabel=null;
  labels.forEach(function(k){ wa[k]=ma[k].s/pa.s; wb[k]=mb[k].s/pb.s; var d=Math.abs(wb[k]-wa[k]); if(d>maxShift){maxShift=d; shiftLabel=k;} });
  if(maxShift<0.08) return null; // sin recomposicion real de la mezcla
  // efecto mezcla: pesos nuevos con tasas viejas; efecto tasa: pesos viejos con tasas nuevas
  var base=0, mixOnly=0, rateOnly=0;
  labels.forEach(function(k){ base+=wa[k]*ma[k].l1k_adj; mixOnly+=wb[k]*ma[k].l1k_adj; rateOnly+=wa[k]*mb[k].l1k_adj; });
  if(base<=0) return null;
  var mixEff=(mixOnly-base)/base*100, rateEff=(rateOnly-base)/base*100;
  var totalEff=(pb.l1k_adj-pa.l1k_adj)/pa.l1k_adj*100;
  if(Math.abs(mixEff)<5 && Math.abs(rateEff)<5) return null;
  var mixDominates = Math.abs(mixEff)>Math.abs(rateEff)*1.5;
  var rateDominates = Math.abs(rateEff)>Math.abs(mixEff)*1.5;
  if(!mixDominates && !rateDominates) return null;
  var L=LANG, dl=tbdDimLabel(dimKey);
  return { strength: Math.abs(mixDominates?mixEff:rateEff), icon:'⚗',
    title: mixDominates
      ? (L==='en'?'The year-over-year change is media mix, not creative':L==='pt'?'A mudança ano a ano é mix de mídia, não criativo':'El cambio año contra año es mezcla de medios, no creativo')
      : (L==='en'?'The year-over-year change is creative performance, not mix':L==='pt'?'A mudança ano a ano é performance criativa, não mix':'El cambio año contra año es desempeño creativo, no mezcla'),
    body: (L==='en'
      ? 'Portfolio L/$1k adj. moved '+fmtNum(totalEff,1)+'% from 2025 to 2026. Decomposing it by '+dl+': re-allocating spend across categories accounts for '+fmtNum(mixEff,1)+' points, while the categories\' own performance accounts for '+fmtNum(rateEff,1)+' points. The biggest reallocation was "'+shiftLabel+'" ('+fmtNum(wa[shiftLabel]*100,0)+'% → '+fmtNum(wb[shiftLabel]*100,0)+'% of spend). '+(mixDominates?'So this is a media-planning result, not a creative one — do not credit or blame the creative team for it.':'So this is a creative result, not a planning one — the mix barely moved the needle; the pieces themselves changed.')
      : L==='pt'
      ? 'O L/$1k adj. do portfólio mudou '+fmtNum(totalEff,1)+'% de 2025 para 2026. Decompondo por '+dl+': a realocação de gasto entre categorias responde por '+fmtNum(mixEff,1)+' pontos, enquanto a performance própria das categorias responde por '+fmtNum(rateEff,1)+' pontos. A maior realocação foi "'+shiftLabel+'" ('+fmtNum(wa[shiftLabel]*100,0)+'% → '+fmtNum(wb[shiftLabel]*100,0)+'% do gasto). '+(mixDominates?'Então este é um resultado de planejamento de mídia, não criativo — não credite nem culpe a equipe criativa por ele.':'Então este é um resultado criativo, não de planejamento — o mix mal moveu o ponteiro; as peças em si mudaram.')
      : 'El L/$1k adj. del portafolio se movió '+fmtNum(totalEff,1)+'% de 2025 a 2026. Al descomponerlo por '+dl+': reasignar gasto entre categorías explica '+fmtNum(mixEff,1)+' puntos, mientras que el desempeño propio de las categorías explica '+fmtNum(rateEff,1)+' puntos. La mayor reasignación fue "'+shiftLabel+'" ('+fmtNum(wa[shiftLabel]*100,0)+'% → '+fmtNum(wb[shiftLabel]*100,0)+'% del gasto). '+(mixDominates?'O sea que esto es un resultado de planeación de medios, no creativo — no le acredites ni le reclames al equipo creativo por él.':'O sea que esto es un resultado creativo, no de planeación — la mezcla casi no movió la aguja; cambiaron las piezas en sí.')) };
}

/* ---------- TARJETA DE ESTACIONALIDAD POR PESTANA ----------
   Requisito explicito: TODA tabla debe cruzar el indice de estacionalidad,
   no solo la pestana de Seasonality. Cada pestana recibe la pregunta
   estacional que SOLO ella puede responder, con la dimension que le
   corresponde. Combina tres lecturas:
     (1) sesgo de exposicion -- ¿le tocaron meses mejores o peores?
     (2) elasticidad por banda -- ¿gana solo en la ola o tambien en el valle?
     (3) auditoria del ajuste -- ¿el indice esta limpiando bien el calendario?
   Si ninguna supera sus gates, la tarjeta lo dice explicitamente en vez de
   inventar una frase. */
function tbdSeasonalityCardFor(data, dimKey){
  var L = LANG;
  var parts = [];
  var keyFn = dimKey && TBD_DIM_DEFS[dimKey] ? TBD_DIM_DEFS[dimKey].keyFn : null;
  var dl = dimKey && TBD_DIM_DEFS[dimKey] ? tbdDimLabel(dimKey) : (L==='en'?'creative':L==='pt'?'criativo':'creativo');

  if(keyFn){
    var exp = tbdSafeDetect(tbdSeasonExposure, data.y26, keyFn);
    if(exp && exp.rows.length && Math.abs(exp.rows[0].gap)>=5){
      var r = exp.rows[0];
      parts.push(L==='en'
        ? '<b>Calendar bias:</b> "'+esc(r.label)+'" ran in months averaging a demand index of '+fmtNum(r.dem,0)+' vs '+fmtNum(exp.portfolioDem,0)+' for the portfolio ('+(r.gap>0?'+':'')+fmtNum(r.gap,0)+' points). Its raw numbers are '+(r.gap>0?'flattered':'penalised')+' by the calendar it was given — the adj. column is the one to read for it.'
        : L==='pt'
        ? '<b>Viés de calendário:</b> "'+esc(r.label)+'" rodou em meses com índice de demanda médio de '+fmtNum(r.dem,0)+' vs '+fmtNum(exp.portfolioDem,0)+' do portfólio ('+(r.gap>0?'+':'')+fmtNum(r.gap,0)+' pontos). Seus números brutos estão '+(r.gap>0?'favorecidos':'penalizados')+' pelo calendário que recebeu — a coluna adj. é a que vale para ele.'
        : '<b>Sesgo de calendario:</b> "'+esc(r.label)+'" corrió en meses con índice de demanda promedio de '+fmtNum(r.dem,0)+' vs '+fmtNum(exp.portfolioDem,0)+' del portafolio ('+(r.gap>0?'+':'')+fmtNum(r.gap,0)+' puntos). Sus números crudos están '+(r.gap>0?'favorecidos':'castigados')+' por el calendario que le tocó — la columna adj. es la que vale para él.');
    }
    var bands = tbdSafeDetect(tbdSeasonBands, data.y26, keyFn);
    if(bands && bands.profiles.length){
      var p = bands.profiles[0];
      var isRider = p.gap >= 25, isValley = p.gap <= 10;
      if(isRider){
        parts.push(L==='en'
          ? '<b>Wave rider:</b> "'+esc(p.label)+'" delivers '+fmtNum(p.hi.l1k_adj,0)+' adj. L/$1k in high-demand months but only '+fmtNum(p.lo.l1k_adj,0)+' in low-demand ones ('+fmtNum(p.gap,0)+'% apart, even after adjusting). It needs the tide: do not schedule it as your valley workhorse.'
          : L==='pt'
          ? '<b>Surfista de onda:</b> "'+esc(p.label)+'" entrega '+fmtNum(p.hi.l1k_adj,0)+' de L/$1k adj. em meses de alta demanda mas só '+fmtNum(p.lo.l1k_adj,0)+' nos de baixa ('+fmtNum(p.gap,0)+'% de diferença, mesmo já ajustado). Ele precisa da maré: não o programe como cavalo de batalha do vale.'
          : '<b>Surfista de ola:</b> "'+esc(p.label)+'" entrega '+fmtNum(p.hi.l1k_adj,0)+' de L/$1k adj. en meses de alta demanda pero solo '+fmtNum(p.lo.l1k_adj,0)+' en los de baja ('+fmtNum(p.gap,0)+'% de diferencia, incluso ya ajustado). Necesita la marea: no lo programes como tu caballo de batalla del valle.');
      } else if(isValley){
        parts.push(L==='en'
          ? '<b>Valley engine:</b> "'+esc(p.label)+'" holds up in low-demand months ('+fmtNum(p.lo.l1k_adj,0)+' vs '+fmtNum(p.hi.l1k_adj,0)+' adj. L/$1k in the peak). Its ranking is the message doing the work, not the calendar — this is what you schedule when the market is quiet.'
          : L==='pt'
          ? '<b>Motor de vale:</b> "'+esc(p.label)+'" se sustenta em meses de baixa demanda ('+fmtNum(p.lo.l1k_adj,0)+' vs '+fmtNum(p.hi.l1k_adj,0)+' de L/$1k adj. no pico). Seu ranking é a mensagem funcionando, não o calendário — é isto que se programa quando o mercado está parado.'
          : '<b>Motor de valle:</b> "'+esc(p.label)+'" se sostiene en meses de baja demanda ('+fmtNum(p.lo.l1k_adj,0)+' vs '+fmtNum(p.hi.l1k_adj,0)+' de L/$1k adj. en el pico). Su ranking es el mensaje haciendo el trabajo, no el calendario — esto es lo que programas cuando el mercado está quieto.');
      }
    }
  }
  var audit = tbdSafeDetect(tbdSeasonAdjustmentAudit, data.y26);
  if(audit) parts.push('<b>'+esc(audit.title)+':</b> '+esc(audit.body));

  if(!parts.length){
    var s = TBD_SEASONALITY[data.territory];
    var swing = null;
    if(s && s.jan_jul_2026 && s.jan_jul_2026.length){
      var mx=Math.max.apply(null,s.jan_jul_2026), mn=Math.min.apply(null,s.jan_jul_2026);
      if(mn>0) swing=(mx-mn)/mn*100;
    }
    parts.push(L==='en'
      ? 'No seasonal distortion large enough to change how you read this table'+(swing!=null?' (the demand index swings '+fmtNum(swing,0)+'% across the period, but the categories here were exposed to it evenly)':'')+'. Read the adj. columns as they are.'
      : L==='pt'
      ? 'Nenhuma distorção sazonal grande o suficiente para mudar como você lê esta tabela'+(swing!=null?' (o índice de demanda varia '+fmtNum(swing,0)+'% no período, mas as categorias aqui foram expostas a ele de forma equilibrada)':'')+'. Leia as colunas adj. como estão.'
      : 'No hay distorsión estacional lo bastante grande como para cambiar cómo se lee esta tabla'+(swing!=null?' (el índice de demanda varía '+fmtNum(swing,0)+'% en el período, pero las categorías de aquí quedaron expuestas a él de forma pareja)':'')+'. Lee las columnas adj. tal cual.');
  }
  return parts;
}

/* ============================ panel de expertos: 15 detectores nuevos ============================
   Disenados por un flujo de 4 personas (CMO/Big Data, Psicologia del consumidor,
   Diseno audiovisual, Copywriting/Comunicacion) en paralelo + una sintesis que
   fusiono duplicados y descarto lo que no cruzaba dos senales reales. Mismo
   contrato que los detectores anteriores: cruzan >=2 senales, umbral de tamano
   de efecto explicito, null si no hay patron real. Los que reciben `dims`
   evaluan TODAS las dimensiones de esa lista con el MISMO umbral y devuelven
   solo el hallazgo mas fuerte -- si se les pasa un `dims` de un solo elemento
   (ver wiring por pestana mas abajo) quedan restringidos a esa dimension. */
function tbdDetectSpendConcentrationRisk(data){
  var items = data.y26.filter(function(r){ return r.n>=3; });
  if(items.length<6) return null;
  var totalS = items.reduce(function(s,r){return s+r.s;},0);
  if(totalS<=0) return null;
  var top1 = items.slice().sort(function(a,b){return b.s-a.s;})[0];
  var share = top1.s/totalS;
  if(share<0.30) return null;
  var totalC = items.reduce(function(s,r){return s+(r.c||0);},0);
  var mnccPortfolio = totalC>0 ? (totalC-totalS)/totalC : 0;
  if(!(top1.mncc<=mnccPortfolio-0.05 || top1.mncc<0)) return null;
  var L=LANG;
  // COMPROBACION: si esa pieza unica ademas ya se esta desgastando, el riesgo
  // deja de ser teorico. Se mide con su propio wear-out.
  var w = tbdWearout(top1);
  var chk;
  if(w && w.pct!=null){
    chk = w.pct <= -20
      ? (L==='en'?'Confirmed as a live risk: that same creative is already decaying '+fmtNum(Math.abs(w.pct),0)+'% from its first half on air to its second, so the concentration is sitting on a piece that is losing force right now.'
        :L==='pt'?'Confirmado como risco ativo: esse mesmo criativo ja esta caindo '+fmtNum(Math.abs(w.pct),0)+'% da primeira metade no ar para a segunda, entao a concentracao esta apoiada numa peca que ja esta perdendo forca.'
        :'Confirmado como riesgo vivo: ese mismo creativo ya viene cayendo '+fmtNum(Math.abs(w.pct),0)+'% de su primera mitad al aire a la segunda, o sea que la concentracion esta parada sobre una pieza que ya esta perdiendo fuerza.')
      : (L==='en'?'Partly reassuring: that creative is not decaying yet ('+fmtNum(w.pct,0)+'% between halves), so the risk is concentration itself, not fatigue. Re-check it if that number turns negative.'
        :L==='pt'?'Parcialmente tranquilizador: esse criativo ainda nao esta se desgastando ('+fmtNum(w.pct,0)+'% entre metades), entao o risco e a concentracao em si, nao a fadiga. Reveja se esse numero virar negativo.'
        :'Parcialmente tranquilizador: ese creativo todavia no se esta desgastando ('+fmtNum(w.pct,0)+'% entre mitades), asi que el riesgo es la concentracion en si, no la fatiga. Vuelve a mirarlo si ese numero se vuelve negativo.');
  } else {
    chk = tbdNoDataCheck(L==='en'?'whether that creative holds up over a longer flight (it has too few days to measure wear-out yet)'
      :L==='pt'?'se esse criativo se sustenta num voo mais longo (tem poucos dias para medir desgaste)'
      :'si ese creativo se sostiene en un vuelo mas largo (todavia tiene muy pocos dias para medir desgaste)');
  }
  var hyp = L==='en'?'Budget tends to follow last-period winners, so one piece that performed early keeps absorbing share until nobody is testing alternatives any more.'
    :L==='pt'?'O orcamento tende a seguir os vencedores do periodo anterior, entao uma peca que foi bem no inicio segue absorvendo share ate ninguem mais estar testando alternativas.'
    :'El presupuesto tiende a seguir al ganador del periodo anterior, asi que una pieza que rindio temprano sigue absorbiendo participacion hasta que ya nadie esta probando alternativas.';
  return { strength: share*100, icon:'⚠', hypothesis:hyp, check:chk,
    title: L==='en'?'The portfolio depends on a single creative':L==='pt'?'O portfólio depende de um único criativo':'El portafolio depende de un solo creativo',
    body: L==='en'?fmtNum(share*100,0)+'% of TV spend this period is concentrated in a single creative ("'+top1.nombre+'"), vs. '+items.length+' active creatives in the portfolio. Its margin (mncc) is '+fmtPct(top1.mncc,1)+' vs. '+fmtPct(mnccPortfolio,1)+' for the aggregate portfolio — if this creative fatigues, gets pulled, or loses channel approval, the whole period result is disproportionately exposed. Worth diversifying spend before scaling this single bet further.'
      :L==='pt'?fmtNum(share*100,0)+'% do gasto de TV neste período está concentrado num único criativo ("'+top1.nombre+'"), vs. '+items.length+' criativos ativos no portfólio. Sua margem (mncc) é de '+fmtPct(top1.mncc,1)+' vs. '+fmtPct(mnccPortfolio,1)+' do portfólio agregado — se esse criativo perder força, for retirado ou perder aprovação de canal, o resultado do período fica desproporcionalmente exposto. Vale diversificar o gasto antes de escalar ainda mais essa única aposta.'
      :fmtNum(share*100,0)+'% del gasto de TV en este período está concentrado en un solo creativo ("'+top1.nombre+'"), frente a '+items.length+' creativos activos en el portafolio. Su margen (mncc) es de '+fmtPct(top1.mncc,1)+' frente a '+fmtPct(mnccPortfolio,1)+' del portafolio agregado — si este creativo pierde fuerza, se retira o pierde aprobación de canal, el resultado del período se ve comprometido de forma desproporcionada. Vale la pena diversificar el gasto antes de seguir escalando esta única pieza.' };
}
function tbdDetectVolumeMarginDecouple(data, dims){
  dims = dims || ['tone_category','theme_mechanism_code','pain_point','hook_audio_type_code','hook_visual_type_code'];
  var best = null;
  dims.forEach(function(dimKey){
    var rollup = tbdDimensionRollup(data.y26, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){ return x.days>=5 && x.n>=3; });
    if(rollup.length<2) return;
    var byLeads = rollup.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;})[0];
    var byMargin = rollup.slice().sort(function(a,b){return b.mncc-a.mncc;})[0];
    if(byLeads.label===byMargin.label) return;
    var gapMncc = byMargin.mncc-byLeads.mncc;
    if(gapMncc<0.08) return;
    if(!best || gapMncc>best.gapMncc) best = {dimKey:dimKey, byLeads:byLeads, byMargin:byMargin, gapMncc:gapMncc};
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  return { strength: best.gapMncc*100, icon:'⇄',
    title: L==='en'?'The '+dl+' generating the most leads isn\'t the most profitable':L==='pt'?'O '+dl+' que mais gera leads não é o mais rentável':'El '+dl+' que más leads genera no es el más rentable',
    body: L==='en'?'"'+best.byLeads.label+'" is the '+dl+' generating the most leads (L/$1k adj. '+fmtNum(best.byLeads.l1k_adj,0)+') but its margin is only '+fmtPct(best.byLeads.mncc,1)+', vs. '+fmtPct(best.byMargin.mncc,1)+' for "'+best.byMargin.label+'" (L/$1k adj. '+fmtNum(best.byMargin.l1k_adj,0)+') — a '+fmtNum(best.gapMncc*100,0)+'pp gap. Scaling "'+best.byLeads.label+'" without revisiting offer/pricing may be buying volume at the expense of profitability.'
      :L==='pt'?'"'+best.byLeads.label+'" é o '+dl+' que mais gera leads (L/$1k adj. '+fmtNum(best.byLeads.l1k_adj,0)+') mas sua margem é de apenas '+fmtPct(best.byLeads.mncc,1)+', vs. '+fmtPct(best.byMargin.mncc,1)+' de "'+best.byMargin.label+'" (L/$1k adj. '+fmtNum(best.byMargin.l1k_adj,0)+') — uma diferença de '+fmtNum(best.gapMncc*100,0)+'pp. Escalar "'+best.byLeads.label+'" sem revisar oferta/preço pode estar comprando volume às custas de rentabilidade.'
      :'"'+best.byLeads.label+'" es el '+dl+' que más leads genera (L/$1k adj. '+fmtNum(best.byLeads.l1k_adj,0)+') pero su margen es de solo '+fmtPct(best.byLeads.mncc,1)+', frente a '+fmtPct(best.byMargin.mncc,1)+' de "'+best.byMargin.label+'" (L/$1k adj. '+fmtNum(best.byMargin.l1k_adj,0)+') — una brecha de '+fmtNum(best.gapMncc*100,0)+'pp. Escalar "'+best.byLeads.label+'" sin revisar oferta/precio puede estar comprando volumen a costa de rentabilidad.' };
}
function tbdDetectCostPerSaleReversal(data, dims){
  dims = dims || ['ad_type','type_of_production','theme_mechanism_code','hook_visual_type_code','cta_type_code'];
  var best = null;
  dims.forEach(function(dimKey){
    var rollup = tbdDimensionRollup(data.y26, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){ return x.days>=5 && x.cvr>0; });
    if(rollup.length<2) return;
    rollup.forEach(function(x){ x._costSale = x.cpl_adj/x.cvr; });
    var byCpl = rollup.slice().sort(function(a,b){return a.cpl_adj-b.cpl_adj;})[0];
    var bySale = rollup.slice().sort(function(a,b){return a._costSale-b._costSale;})[0];
    if(byCpl.label===bySale.label) return;
    var gapPct = (byCpl._costSale-bySale._costSale)/bySale._costSale*100;
    if(gapPct<25) return;
    if(!best || gapPct>best.gapPct) best = {dimKey:dimKey, byCpl:byCpl, bySale:bySale, gapPct:gapPct};
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  return { strength: best.gapPct, icon:'⇌',
    title: L==='en'?'The "cheap" lead isn\'t the cheapest once it converts':L==='pt'?'O lead "barato" não é o mais barato até a venda':'El lead "barato" no es el más barato hasta la venta',
    body: L==='en'?'"'+best.byCpl.label+'" ('+dl+') looks like the most cost-efficient option by CPL adj. ('+fmt$(best.byCpl.cpl_adj,2)+') but its '+fmtPct(best.byCpl.cvr,1)+' conversion means a real cost per enrollment of '+fmt$(best.byCpl._costSale,2)+' — '+fmtNum(best.gapPct,0)+'% more expensive than "'+best.bySale.label+'" (CPL adj. '+fmt$(best.bySale.cpl_adj,2)+', CVR '+fmtPct(best.bySale.cvr,1)+', cost per enrollment '+fmt$(best.bySale._costSale,2)+').'
      :L==='pt'?'"'+best.byCpl.label+'" ('+dl+') parece a opção mais eficiente em CPL adj. ('+fmt$(best.byCpl.cpl_adj,2)+') mas sua conversão de '+fmtPct(best.byCpl.cvr,1)+' implica um custo real por matrícula de '+fmt$(best.byCpl._costSale,2)+' — '+fmtNum(best.gapPct,0)+'% mais caro que "'+best.bySale.label+'" (CPL adj. '+fmt$(best.bySale.cpl_adj,2)+', CVR '+fmtPct(best.bySale.cvr,1)+', custo por matrícula '+fmt$(best.bySale._costSale,2)+').'
      :'"'+best.byCpl.label+'" ('+dl+') parece la opción más eficiente en CPL adj. ('+fmt$(best.byCpl.cpl_adj,2)+') pero su conversión de '+fmtPct(best.byCpl.cvr,1)+' implica un costo real por matrícula de '+fmt$(best.byCpl._costSale,2)+' — '+fmtNum(best.gapPct,0)+'% más caro que "'+best.bySale.label+'" (CPL adj. '+fmt$(best.bySale.cpl_adj,2)+', CVR '+fmtPct(best.bySale.cvr,1)+', costo por matrícula '+fmt$(best.bySale._costSale,2)+').' };
}
function tbdDetectGrowthWithoutQuality(data, dims){
  dims = dims || ['pain_point','theme_mechanism_code','tone_category'];
  var best = null;
  dims.forEach(function(dimKey){
    var r25 = tbdDimensionRollup(data.y25, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){return x.days>=5;});
    var r26 = tbdDimensionRollup(data.y26, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){return x.days>=5;});
    var map25 = {}; r25.forEach(function(x){map25[x.label]=x;});
    r26.forEach(function(x26){
      var x25 = map25[x26.label];
      if(!x25 || x25.l1k_adj<=0) return;
      var deltaL1k = (x26.l1k_adj-x25.l1k_adj)/x25.l1k_adj*100;
      var deltaCvr = (x26.cvr-x25.cvr)*100, deltaMncc = (x26.mncc-x25.mncc)*100;
      if(deltaL1k<20) return;
      if(!(deltaCvr<=-3 || deltaMncc<=-5)) return;
      if(!best || deltaL1k>best.deltaL1k) best = {dimKey:dimKey, label:x26.label, x25:x25, x26:x26, deltaL1k:deltaL1k, deltaCvr:deltaCvr, deltaMncc:deltaMncc};
    });
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  var cvrDir = best.deltaCvr<0 ? (L==='en'?'dropped':L==='pt'?'caiu':'cayó') : (L==='en'?'rose':L==='pt'?'subiu':'subió');
  var mnccDir = best.deltaMncc<0 ? (L==='en'?'dropped':L==='pt'?'caiu':'cayó') : (L==='en'?'rose':L==='pt'?'subiu':'subió');
  return { strength: best.deltaL1k, icon:'▲⚠',
    title: L==='en'?'More leads isn\'t more business':L==='pt'?'Mais leads não é mais negócio':'Más leads no es más negocio',
    body: L==='en'?'In '+dl+' "'+best.label+'", adjusted leads grew '+fmtNum(best.deltaL1k,0)+'% from 2025 to 2026 ('+fmtNum(best.x25.l1k_adj,0)+' → '+fmtNum(best.x26.l1k_adj,0)+'), but conversion '+cvrDir+' '+fmtNum(Math.abs(best.deltaCvr),1)+'pp ('+fmtPct(best.x25.cvr,1)+' → '+fmtPct(best.x26.cvr,1)+') and margin '+mnccDir+' '+fmtNum(Math.abs(best.deltaMncc),1)+'pp ('+fmtPct(best.x25.mncc,1)+' → '+fmtPct(best.x26.mncc,1)+'). More leads here isn\'t proportionally generating more real business.'
      :L==='pt'?'Em '+dl+' "'+best.label+'", os leads ajustados cresceram '+fmtNum(best.deltaL1k,0)+'% de 2025 para 2026 ('+fmtNum(best.x25.l1k_adj,0)+' → '+fmtNum(best.x26.l1k_adj,0)+'), mas a conversão '+cvrDir+' '+fmtNum(Math.abs(best.deltaCvr),1)+'pp ('+fmtPct(best.x25.cvr,1)+' → '+fmtPct(best.x26.cvr,1)+') e a margem '+mnccDir+' '+fmtNum(Math.abs(best.deltaMncc),1)+'pp ('+fmtPct(best.x25.mncc,1)+' → '+fmtPct(best.x26.mncc,1)+'). Mais leads aqui não está gerando proporcionalmente mais negócio real.'
      :'En '+dl+' "'+best.label+'", los leads ajustados crecieron '+fmtNum(best.deltaL1k,0)+'% de 2025 a 2026 ('+fmtNum(best.x25.l1k_adj,0)+' → '+fmtNum(best.x26.l1k_adj,0)+'), pero la conversión '+cvrDir+' '+fmtNum(Math.abs(best.deltaCvr),1)+'pp ('+fmtPct(best.x25.cvr,1)+' → '+fmtPct(best.x26.cvr,1)+') y el margen '+mnccDir+' '+fmtNum(Math.abs(best.deltaMncc),1)+'pp ('+fmtPct(best.x25.mncc,1)+' → '+fmtPct(best.x26.mncc,1)+'). Más leads en esta línea no está generando proporcionalmente más negocio real.' };
}
function tbdDetectFragileLeader(data, dims){
  dims = dims || ['tone_category','hook_audio_type_code','hook_visual_type_code','theme_mechanism_code','cta_type_code'];
  var best = null;
  dims.forEach(function(dimKey){
    var rollup = tbdDimensionRollup(data.y26, TBD_DIM_DEFS[dimKey].keyFn).filter(function(x){return x.days>=3;});
    if(rollup.length<3) return;
    var sorted = rollup.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;});
    var v1=sorted[0], v2=sorted[1];
    if(v2.l1k_adj<=0 || v2.days<=0) return;
    var brecha = (v1.l1k_adj-v2.l1k_adj)/v2.l1k_adj*100;
    var ratio = v1.days/v2.days;
    if(brecha>10 || ratio>0.4) return;
    var strength = (1-ratio)*100;
    if(!best || strength>best.strength) best = {dimKey:dimKey, v1:v1, v2:v2, brecha:brecha, strength:strength};
  });
  if(!best) return null;
  var L=LANG, dl=tbdDimLabel(best.dimKey);
  return { strength: best.strength, icon:'≈',
    title: L==='en'?'The current leader has little evidence behind it':L==='pt'?'O líder atual tem pouca evidência por trás':'El líder actual tiene poca evidencia detrás',
    body: L==='en'?'"'+best.v1.label+'" tops the '+dl+' ranking with L/$1k adj. '+fmtNum(best.v1.l1k_adj,0)+', barely '+fmtNum(best.brecha,0)+'% above "'+best.v2.label+'" ('+fmtNum(best.v2.l1k_adj,0)+') — but "'+best.v1.label+'" has only '+best.v1.days+' days on air vs. '+best.v2.days+' for "'+best.v2.label+'". It\'s a lead with very little evidence behind it; give it more test days before scaling it.'
      :L==='pt'?'"'+best.v1.label+'" lidera o ranking de '+dl+' com L/$1k adj. '+fmtNum(best.v1.l1k_adj,0)+', apenas '+fmtNum(best.brecha,0)+'% acima de "'+best.v2.label+'" ('+fmtNum(best.v2.l1k_adj,0)+') — mas "'+best.v1.label+'" tem apenas '+best.v1.days+' dias no ar vs. '+best.v2.days+' de "'+best.v2.label+'". É uma liderança com pouquíssima evidência; dê mais dias de teste antes de escalar.'
      :'"'+best.v1.label+'" encabeza el ranking de '+dl+' con L/$1k adj. '+fmtNum(best.v1.l1k_adj,0)+', apenas '+fmtNum(best.brecha,0)+'% arriba de "'+best.v2.label+'" ('+fmtNum(best.v2.l1k_adj,0)+') — pero "'+best.v1.label+'" tiene solo '+best.v1.days+' días de pantalla frente a los '+best.v2.days+' de "'+best.v2.label+'". Es un liderazgo con muy poca evidencia; antes de escalarlo conviene darle más días de prueba.' };
}
function tbdDetectSeasonalSpendMismatch(data){
  var items = data.y26.filter(function(r){return r.n>=3;});
  if(items.length<4) return null;
  var totalS = items.reduce(function(s,r){return s+r.s;},0);
  var totalDays = items.reduce(function(s,r){return s+r.n;},0);
  if(totalS<=0 || totalDays<=0) return null;
  var demBySpend = items.reduce(function(s,r){return s+r.dem*r.s;},0)/totalS;
  var demByDays = items.reduce(function(s,r){return s+r.dem*r.n;},0)/totalDays;
  var brechaDem = demByDays-demBySpend;
  var l1kAdjW = items.reduce(function(s,r){return s+r.l1k_adj*r.s;},0)/totalS;
  var l1kW = items.reduce(function(s,r){return s+r.l1k*r.s;},0)/totalS;
  if(l1kW<=0) return null;
  var gapAjuste = (l1kAdjW/l1kW-1)*100;
  if(brechaDem<8 || gapAjuste<10) return null;
  var L=LANG;
  return { strength: gapAjuste, icon:'◐',
    title: L==='en'?'Spend didn\'t follow demand':L==='pt'?'O gasto não seguiu a demanda':'El gasto no siguió a la demanda',
    body: L==='en'?'TV spend this period skewed toward weaker-demand weeks: the spend-weighted demand index was '+fmtNum(demBySpend,0)+' vs. '+fmtNum(demByDays,0)+' if spend had followed the same split as days on air — a '+fmtNum(brechaDem,0)+'-point gap. This lines up with adjusted L/$1k ('+fmtNum(l1kAdjW,0)+') beating raw ('+fmtNum(l1kW,0)+') by '+fmtNum(gapAjuste,0)+'%, a sign seasonality hid real efficiency. Reallocating budget toward high-demand weeks could capture that gap without spending more.'
      :L==='pt'?'O gasto de TV neste período ficou enviesado para semanas de demanda mais fraca: o índice de demanda ponderado pelo gasto foi '+fmtNum(demBySpend,0)+' vs. '+fmtNum(demByDays,0)+' se o gasto tivesse seguido a mesma divisão dos dias no ar — uma diferença de '+fmtNum(brechaDem,0)+' pontos. Isso combina com o L/$1k ajustado ('+fmtNum(l1kAdjW,0)+') superando o bruto ('+fmtNum(l1kW,0)+') em '+fmtNum(gapAjuste,0)+'%, sinal de que a sazonalidade escondeu eficiência real. Realocar orçamento para semanas de alta demanda poderia capturar essa diferença sem gastar mais.'
      :'El gasto de TV en este período estuvo sesgado hacia semanas de demanda débil: el índice de demanda ponderado por gasto fue '+fmtNum(demBySpend,0)+' vs. '+fmtNum(demByDays,0)+' si el gasto se hubiera repartido igual que los días en pantalla — una brecha de '+fmtNum(brechaDem,0)+' puntos. Esto coincide con que L/$1k ajustado ('+fmtNum(l1kAdjW,0)+') supera al crudo ('+fmtNum(l1kW,0)+') en '+fmtNum(gapAjuste,0)+'%, señal de que la estacionalidad escondió eficiencia real. Reasignar presupuesto hacia semanas de alta demanda podría capturar esa brecha sin gastar más.' };
}
function tbdDetectCampaignHiddenStar(data){
  var byCampaign = {};
  data.y26.forEach(function(r){ if(!r.campaign_name) return; (byCampaign[r.campaign_name]=byCampaign[r.campaign_name]||[]).push(r); });
  var best = null;
  Object.keys(byCampaign).forEach(function(camp){
    var arr = byCampaign[camp];
    var totalDays = arr.reduce(function(s,r){return s+r.n;},0);
    if(arr.length<4 || totalDays<10) return;
    var qualified = arr.filter(function(r){return r.n>=3;});
    if(!qualified.length) return;
    var m = qualified.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;})[0];
    var rest = arr.filter(function(r){return r!==m;});
    var restS = rest.reduce(function(s,r){return s+r.s;},0);
    if(restS<=0) return;
    var restAvg = rest.reduce(function(s,r){return s+r.l1k_adj*r.s;},0)/restS;
    if(restAvg<=0) return;
    var gapPct = (m.l1k_adj-restAvg)/restAvg*100;
    var totalS = arr.reduce(function(s,r){return s+r.s;},0);
    var spendShare = totalS>0 ? m.s/totalS : 0;
    if(gapPct<50 || spendShare>0.25) return;
    if(!best || gapPct>best.gapPct) best = {camp:camp, m:m, restAvg:restAvg, gapPct:gapPct, spendShare:spendShare, n:arr.length};
  });
  if(!best) return null;
  var L=LANG;
  return { strength: best.gapPct, icon:'★',
    title: L==='en'?'A clear winner is underfunded within its own campaign':L==='pt'?'Um vencedor claro está subfinanciado dentro da própria campanha':'Un ganador claro está subfinanciado dentro de su propia campaña',
    body: L==='en'?'Within campaign "'+best.camp+'" ('+best.n+' creatives), "'+best.m.nombre+'" outperforms the rest of the campaign by '+fmtNum(best.gapPct,0)+'% (L/$1k adj. '+fmtNum(best.m.l1k_adj,0)+' vs. '+fmtNum(best.restAvg,1)+') but only gets '+fmtNum(best.spendShare*100,0)+'% of the campaign\'s spend. Worth reallocating budget within the same campaign before asking for a new creative.'
      :L==='pt'?'Dentro da campanha "'+best.camp+'" ('+best.n+' criativos), "'+best.m.nombre+'" rende '+fmtNum(best.gapPct,0)+'% acima do resto da campanha (L/$1k adj. '+fmtNum(best.m.l1k_adj,0)+' vs. '+fmtNum(best.restAvg,1)+') mas recebe apenas '+fmtNum(best.spendShare*100,0)+'% do gasto da campanha. Vale realocar orçamento dentro da mesma campanha antes de pedir um criativo novo.'
      :'Dentro de la campaña "'+best.camp+'" ('+best.n+' creativos), "'+best.m.nombre+'" rinde '+fmtNum(best.gapPct,0)+'% por encima del resto de la campaña (L/$1k adj. '+fmtNum(best.m.l1k_adj,0)+' vs. '+fmtNum(best.restAvg,1)+') pero solo recibe '+fmtNum(best.spendShare*100,0)+'% del gasto de la campaña. Conviene reasignar presupuesto dentro de la misma campaña antes de pedir un creativo nuevo.' };
}
function tbdDetectCampaignZombie(data){
  var byCampaign = {};
  data.y26.forEach(function(r){ if(!r.campaign_name) return; (byCampaign[r.campaign_name]=byCampaign[r.campaign_name]||[]).push(r); });
  var best = null;
  Object.keys(byCampaign).forEach(function(camp){
    var arr = byCampaign[camp];
    var totalDays = arr.reduce(function(s,r){return s+r.n;},0);
    if(arr.length<4 || totalDays<10) return;
    var qualified = arr.filter(function(r){return r.n>=3;});
    if(!qualified.length) return;
    var w = qualified.slice().sort(function(a,b){return a.l1k_adj-b.l1k_adj;})[0];
    var rest = arr.filter(function(r){return r!==w;});
    var restC = rest.reduce(function(s,r){return s+(r.c||0);},0);
    var restS = rest.reduce(function(s,r){return s+r.s;},0);
    var mnccRest = restC>0 ? (restC-restS)/restC : 0;
    var totalS = arr.reduce(function(s,r){return s+r.s;},0);
    var spendShare = totalS>0 ? w.s/totalS : 0;
    if(spendShare<0.30 || !(w.mncc<=mnccRest-0.20)) return;
    var gapPts = (mnccRest-w.mncc)*100;
    if(!best || gapPts>best.gapPts) best = {camp:camp, w:w, mnccRest:mnccRest, spendShare:spendShare, gapPts:gapPts};
  });
  if(!best) return null;
  var L=LANG;
  return { strength: best.gapPts, icon:'⊘',
    title: L==='en'?'Zombie creative: spend concentrated in the campaign\'s worst margin':L==='pt'?'Criativo zumbi: gasto concentrado na pior margem da campanha':'Creativo zombie: gasto concentrado en el peor margen de la campaña',
    body: L==='en'?'In campaign "'+best.camp+'", "'+best.w.nombre+'" absorbs '+fmtNum(best.spendShare*100,0)+'% of the campaign\'s spend but its margin (mncc '+fmtPct(best.w.mncc,1)+') is '+fmtNum(best.gapPts,0)+' points below the rest ('+fmtPct(best.mnccRest,1)+'). It\'s a candidate for immediate pause, not "give it more time".'
      :L==='pt'?'Na campanha "'+best.camp+'", "'+best.w.nombre+'" absorve '+fmtNum(best.spendShare*100,0)+'% do gasto da campanha mas sua margem (mncc '+fmtPct(best.w.mncc,1)+') está '+fmtNum(best.gapPts,0)+' pontos abaixo do resto ('+fmtPct(best.mnccRest,1)+'). É candidato a pausa imediata, não a "dar mais tempo".'
      :'En la campaña "'+best.camp+'", "'+best.w.nombre+'" concentra '+fmtNum(best.spendShare*100,0)+'% del gasto de la campaña pero su margen (mncc '+fmtPct(best.w.mncc,1)+') está '+fmtNum(best.gapPts,0)+' puntos por debajo del resto ('+fmtPct(best.mnccRest,1)+'). Es candidato a pausa inmediata, no a "darle más tiempo".' };
}
function tbdDetectFearNeedsHumor(data){
  var fearItems = data.y26.filter(tbdIsFearPain);
  if(!fearItems.length) return null;
  var roll = tbdDimensionRollup(fearItems, function(r){return r.tone_category||null;}).filter(function(x){return x.days>=8;});
  var humor = roll.filter(function(x){return x.label==='HUMOR';})[0];
  var serious = roll.filter(function(x){return x.label==='MOTIVATIONAL'||x.label==='CORPORATIVE';}).sort(function(a,b){return b.days-a.days;})[0];
  if(!humor || !serious || serious.l1k_adj<=0) return null;
  var gap = (humor.l1k_adj-serious.l1k_adj)/serious.l1k_adj*100;
  if(gap<20) return null;
  var painLabel = fearItems[0].pain_point || 'Fear';
  var L=LANG;
  return { strength: gap, icon:'◐',
    title: L==='en'?'Humor cuts the tension better than a serious tone on fear pain points':L==='pt'?'O humor quebra a tensão melhor que o tom sério em pain points de medo':'El humor rompe la tensión mejor que el tono serio en pain points de miedo',
    body: L==='en'?'For fear-based pain points like "'+painLabel+'", humor cuts through better than a serious tone: "'+humor.label+'" reaches '+fmtNum(humor.l1k_adj,0)+' L/$1k adj. vs. only '+fmtNum(serious.l1k_adj,0)+' for "'+serious.label+'" — a '+fmtNum(gap,0)+'% edge. Fear without an escape valve may be triggering avoidance, not action.'
      :L==='pt'?'Para pain points de medo como "'+painLabel+'", o humor quebra a tensão melhor que o tom sério: "'+humor.label+'" alcança '+fmtNum(humor.l1k_adj,0)+' L/$1k adj. vs. apenas '+fmtNum(serious.l1k_adj,0)+' de "'+serious.label+'" — uma vantagem de '+fmtNum(gap,0)+'%. O medo sem válvula de escape pode estar gerando rejeição, não ação.'
      :'Para pain points de amenaza como "'+painLabel+'", el humor rompe la tensión mejor que el tono serio: "'+humor.label+'" logra '+fmtNum(humor.l1k_adj,0)+' L/$1k adj. vs. solo '+fmtNum(serious.l1k_adj,0)+' en "'+serious.label+'" — una ventaja de '+fmtNum(gap,0)+'%. El miedo sin válvula de escape puede estar generando rechazo, no acción.' };
}
function tbdDetectCheapFormatMarginLeak(data){
  var roll = tbdDimensionRollup(data.y26, function(r){return r.type_of_production||null;}).filter(function(x){return x.days>=8;});
  var filmed = roll.filter(function(x){return x.label==='FILMED';})[0];
  if(!filmed || filmed.l1k_adj<=0) return null;
  var best = null;
  roll.filter(function(x){return x.label!=='FILMED';}).forEach(function(x){
    var gapL1k = (x.l1k_adj-filmed.l1k_adj)/filmed.l1k_adj*100;
    var gapMncc = (x.mncc-filmed.mncc)*100;
    if(Math.abs(gapL1k)>10 || gapMncc>-8) return;
    if(!best || Math.abs(gapMncc)>Math.abs(best.gapMncc)) best = {x:x, gapL1k:gapL1k, gapMncc:gapMncc};
  });
  if(!best) return null;
  var L=LANG;
  return { strength: Math.abs(best.gapMncc), icon:'▽',
    title: L==='en'?'Production savings are being paid for with margin':L==='pt'?'A economia de produção está sendo paga com margem':'El ahorro en producción se financia con margen',
    body: L==='en'?'"'+best.x.label+'" matches Filmed on lead volume (L/$1k adj. '+fmtNum(best.x.l1k_adj,0)+' vs. '+fmtNum(filmed.l1k_adj,0)+', only '+fmtNum(Math.abs(best.gapL1k),0)+'% apart) but its margin is '+fmtPct(best.x.mncc,1)+' vs. '+fmtPct(filmed.mncc,1)+' for Filmed — '+fmtNum(Math.abs(best.gapMncc),0)+' points less (n='+best.x.days+' days). The production savings are leaking into lead quality: it isn\'t reaching the business result.'
      :L==='pt'?'"'+best.x.label+'" iguala Filmado em volume de leads (L/$1k adj. '+fmtNum(best.x.l1k_adj,0)+' vs. '+fmtNum(filmed.l1k_adj,0)+', apenas '+fmtNum(Math.abs(best.gapL1k),0)+'% de diferença) mas sua margem é '+fmtPct(best.x.mncc,1)+' vs. '+fmtPct(filmed.mncc,1)+' de Filmado — '+fmtNum(Math.abs(best.gapMncc),0)+' pontos a menos (n='+best.x.days+' dias). A economia de produção está vazando na qualidade do lead: não chega ao resultado de negócio.'
      :'"'+best.x.label+'" iguala a Filmado en volumen de leads (L/$1k adj. '+fmtNum(best.x.l1k_adj,0)+' vs. '+fmtNum(filmed.l1k_adj,0)+', solo '+fmtNum(Math.abs(best.gapL1k),0)+'% de diferencia) pero su margen es '+fmtPct(best.x.mncc,1)+' vs. '+fmtPct(filmed.mncc,1)+' de Filmado — '+fmtNum(Math.abs(best.gapMncc),0)+' puntos menos (n='+best.x.days+' días). El ahorro en producción se está filtrando en la calidad del lead: no llega al resultado de negocio.' };
}
function tbdDetectMechanismFatigue(data){
  var byMech = {};
  data.y26.forEach(function(r){ if(!r.theme_mechanism_code || r.n<3) return; (byMech[r.theme_mechanism_code]=byMech[r.theme_mechanism_code]||[]).push(r); });
  var best = null;
  Object.keys(byMech).forEach(function(mech){
    var arr = byMech[mech];
    if(arr.length<3) return;
    arr = arr.slice().sort(function(a,b){ var da=tbdLaunchDateOf(a), db=tbdLaunchDateOf(b); return (da||'')<(db||'')?-1:1; });
    var first = arr[0], reps = arr.slice(1);
    var repsDays = reps.reduce(function(s,r){return s+r.n;},0);
    if(repsDays<10 || first.l1k_adj<=0) return;
    var repsS = reps.reduce(function(s,r){return s+r.s;},0);
    if(repsS<=0) return;
    var repsAvg = reps.reduce(function(s,r){return s+r.l1k_adj*r.s;},0)/repsS;
    if(repsAvg>first.l1k_adj*0.80) return;
    var drop = (1-repsAvg/first.l1k_adj)*100;
    if(!best || drop>best.drop) best = {mech:mech, first:first, reps:reps, repsAvg:repsAvg, drop:drop};
  });
  if(!best) return null;
  var L=LANG;
  return { strength: best.drop, icon:'♻',
    title: L==='en'?'The mechanism wears out, not the creative':L==='pt'?'O mecanismo se desgasta, não o criativo':'El mecanismo se desgasta, no el creativo',
    body: L==='en'?'The "'+best.mech+'" mechanism has been recycled across '+(best.reps.length+1)+' distinct Ad Names. The first time it was used it hit '+fmtNum(best.first.l1k_adj,0)+' L/$1k adj.; across the '+best.reps.length+' repeats since, the average drops to '+fmtNum(best.repsAvg,1)+' ('+fmtNum(best.drop,0)+'% less). Even if the commercial "looks new," the audience already learned the trick, not the video.'
      :L==='pt'?'O mecanismo "'+best.mech+'" foi reciclado em '+(best.reps.length+1)+' Ad Names distintos. Na primeira vez que foi usado, rendeu '+fmtNum(best.first.l1k_adj,0)+' L/$1k adj.; nas '+best.reps.length+' repetições seguintes, a média cai para '+fmtNum(best.repsAvg,1)+' ('+fmtNum(best.drop,0)+'% menos). Mesmo que o comercial "pareça novo", a audiência já se habituou ao truque, não ao vídeo.'
      :'El mecanismo "'+best.mech+'" se ha reciclado en '+(best.reps.length+1)+' Ad Names distintos. La primera vez que se usó rindió '+fmtNum(best.first.l1k_adj,0)+' L/$1k adj.; en las '+best.reps.length+' repeticiones siguientes el promedio cae a '+fmtNum(best.repsAvg,1)+' ('+fmtNum(best.drop,0)+'% menos). Aunque el comercial "se vea nuevo", la audiencia ya se habituó al truco psicológico, no al video.' };
}
function tbdDetectCtaEmotionalMismatch(data){
  function cvrFor(items, ctaCode){
    var arr = items.filter(function(r){return r.cta_type_code===ctaCode;});
    var days = arr.reduce(function(s,r){return s+r.n;},0);
    if(days<5 || arr.length<3) return null;
    var totalL = arr.reduce(function(s,r){return s+r.l;},0), totalE = arr.reduce(function(s,r){return s+r.e;},0);
    if(totalL<=0) return null;
    return { cvr: totalE/totalL };
  }
  var procItems = data.y26.filter(function(r){ return tbdPainPrefix(r)==='PROC'; });
  var nonProcItems = data.y26.filter(function(r){ var p=tbdPainPrefix(r); return p==='EXC'||p==='MOV'; });
  var procWa = cvrFor(procItems,'qr_whatsapp_contact'), procDi = cvrFor(procItems,'qr_only_enrollment');
  var nonWa = cvrFor(nonProcItems,'qr_whatsapp_contact'), nonDi = cvrFor(nonProcItems,'qr_only_enrollment');
  if(!procWa||!procDi||!nonWa||!nonDi||procDi.cvr<=0||nonDi.cvr<=0) return null;
  var whatsappIdx = procWa.cvr/procDi.cvr, nonProcIdx = nonWa.cvr/nonDi.cvr;
  if(!(whatsappIdx>=1.25 && nonProcIdx<=0.90)) return null;
  var L=LANG;
  return { strength: (whatsappIdx/nonProcIdx-1)*100, icon:'◇',
    title: L==='en'?'The CTA should be briefed together with the pain point':L==='pt'?'O CTA deve ser briefado junto com o pain point':'El CTA debe briefearse junto con el pain point',
    body: L==='en'?'When the pain point is fear/skill-based (PROC), the "qr_whatsapp_contact" CTA converts '+fmtNum(whatsappIdx,2)+'x better than "qr_only_enrollment" (CVR '+fmtPct(procWa.cvr,1)+' vs. '+fmtPct(procDi.cvr,1)+'). But on offer/urgency pain points, that edge disappears or flips (CVR '+fmtPct(nonWa.cvr,1)+' vs. '+fmtPct(nonDi.cvr,1)+'). The CTA should be briefed together with the pain point, not generically.'
      :L==='pt'?'Quando o pain point é de medo/habilidade (PROC), o CTA "qr_whatsapp_contact" converte '+fmtNum(whatsappIdx,2)+'x melhor que "qr_only_enrollment" (CVR '+fmtPct(procWa.cvr,1)+' vs. '+fmtPct(procDi.cvr,1)+'). Mas em pain points de oferta/urgência, essa vantagem desaparece ou se inverte (CVR '+fmtPct(nonWa.cvr,1)+' vs. '+fmtPct(nonDi.cvr,1)+'). O CTA deveria ser briefado junto com o pain point, não de forma genérica.'
      :'Cuando el pain point es de miedo/habilidad (PROC), el CTA "qr_whatsapp_contact" convierte '+fmtNum(whatsappIdx,2)+'x más que "qr_only_enrollment" (CVR '+fmtPct(procWa.cvr,1)+' vs. '+fmtPct(procDi.cvr,1)+'). Pero en pain points de oferta/urgencia, esa ventaja desaparece o se invierte (CVR '+fmtPct(nonWa.cvr,1)+' vs. '+fmtPct(nonDi.cvr,1)+'). El CTA debería briefearse junto con el pain point, no de forma genérica.' };
}
function tbdDetectPainPointAdTypeMismatch(data){
  function l1kFor(items, fam, adType){
    var arr = items.filter(function(r){ return tbdPainPrefix(r)===fam && r.ad_type===adType; });
    var days = arr.reduce(function(s,r){return s+r.n;},0);
    if(days<5 || arr.length<3) return null;
    var roll = tbdDimensionRollup(arr, function(){return 'x';})[0];
    return roll ? roll.l1k_adj : null;
  }
  var excPromo = l1kFor(data.y26,'EXC','PROMO'), procPromo = l1kFor(data.y26,'PROC','PROMO');
  var excGeneric = l1kFor(data.y26,'EXC','GENERIC'), procGeneric = l1kFor(data.y26,'PROC','GENERIC');
  if(!excPromo||!procPromo||!excGeneric||!procGeneric||procPromo<=0||excGeneric<=0) return null;
  var excPromoIdx = excPromo/procPromo, excGenericIdx = excGeneric/procGeneric;
  var confirmed = excPromoIdx>=1.20 && excGenericIdx<=0.83;
  var inverted = excPromoIdx<=0.83 && excGenericIdx>=1.20;
  if(!confirmed && !inverted) return null;
  var L=LANG;
  var title = confirmed
    ? (L==='en'?'The pain point should change by ad type':L==='pt'?'O pain point deve mudar conforme o tipo de anúncio':'El pain point debe cambiar según el tipo de anuncio')
    : (L==='en'?'The pain-point casting intuition is backwards':L==='pt'?'A intuição de casting do pain point está invertida':'La intuición de casting de pain point está al revés');
  return { strength: (Math.abs(excPromoIdx-1)+Math.abs(excGenericIdx-1))*50, icon:'⇌', title: title,
    body: L==='en'?'In Promo, cost/urgency pain points (EXC) perform '+fmtNum(excPromoIdx,2)+'x vs. skill/trust ones (PROC): L/$1k adj. '+fmtNum(excPromo,1)+' vs. '+fmtNum(procPromo,1)+'. In Generic the relationship flips: PROC performs '+fmtNum(1/excGenericIdx,2)+'x more than EXC ('+fmtNum(procGeneric,1)+' vs. '+fmtNum(excGeneric,1)+'). The pain point should change by ad type, not repeat by default.'
      :L==='pt'?'Em Promo, os pain points de custo/urgência (EXC) rendem '+fmtNum(excPromoIdx,2)+'x vs. os de habilidade/confiança (PROC): L/$1k adj. '+fmtNum(excPromo,1)+' vs. '+fmtNum(procPromo,1)+'. Em Generic a relação se inverte: PROC rende '+fmtNum(1/excGenericIdx,2)+'x mais que EXC ('+fmtNum(procGeneric,1)+' vs. '+fmtNum(excGeneric,1)+'). O pain point deve mudar conforme o tipo de anúncio, não se repetir por padrão.'
      :'En Promo, los pain points de urgencia/costo (EXC) rinden '+fmtNum(excPromoIdx,2)+'x lo que rinden los de habilidad/confianza (PROC): L/$1k adj. '+fmtNum(excPromo,1)+' vs. '+fmtNum(procPromo,1)+'. En Generic la relación se invierte: PROC rinde '+fmtNum(1/excGenericIdx,2)+'x más que EXC ('+fmtNum(procGeneric,1)+' vs. '+fmtNum(excGeneric,1)+'). El pain point debe cambiar según el tipo de anuncio, no repetirse por default.' };
}
function tbdDetectHookPairInteraction(data){
  var items = data.y26.filter(function(r){ return r.hook_audio_type_code && r.hook_visual_type_code; });
  var combos = {};
  items.forEach(function(r){ var k=r.hook_audio_type_code+'|||'+r.hook_visual_type_code; (combos[k]=combos[k]||[]).push(r); });
  function pooledL1k(arr){ var roll = tbdDimensionRollup(arr, function(){return 'x';})[0]; return roll?roll.l1k_adj:null; }
  var best = null;
  Object.keys(combos).forEach(function(k){
    var arr = combos[k];
    var days = arr.reduce(function(s,r){return s+r.n;},0);
    if(days<5) return;
    var parts = k.split('|||'), audio=parts[0], visual=parts[1];
    var comboL1k = pooledL1k(arr);
    if(comboL1k==null) return;
    var audioSoloArr = items.filter(function(r){return r.hook_audio_type_code===audio && r.hook_visual_type_code!==visual;});
    var visualSoloArr = items.filter(function(r){return r.hook_visual_type_code===visual && r.hook_audio_type_code!==audio;});
    var audioSolo = audioSoloArr.length ? pooledL1k(audioSoloArr) : null;
    var visualSolo = visualSoloArr.length ? pooledL1k(visualSoloArr) : null;
    if(audioSolo==null || visualSolo==null) return;
    var maxSolo = Math.max(audioSolo, visualSolo), minSolo = Math.min(audioSolo, visualSolo);
    if(maxSolo>0 && comboL1k>=1.20*maxSolo){
      var synergyPct = (comboL1k/maxSolo-1)*100;
      if(!best || synergyPct>best.strength) best = {type:'synergy', audio:audio, visual:visual, comboL1k:comboL1k, audioSolo:audioSolo, visualSolo:visualSolo, days:days, strength:synergyPct};
    } else if(minSolo>0 && comboL1k<=0.80*minSolo){
      var conflictPct = (1-comboL1k/minSolo)*100;
      var weakLabel = audioSolo<visualSolo ? audio : visual, weakVal = Math.min(audioSolo,visualSolo);
      if(!best || conflictPct>best.strength) best = {type:'clash', audio:audio, visual:visual, comboL1k:comboL1k, weakLabel:weakLabel, weakVal:weakVal, days:days, strength:conflictPct};
    }
  });
  if(!best) return null;
  var L=LANG;
  if(best.type==='synergy'){
    return { strength: best.strength, icon:'⨯', type:'synergy',
      title: L==='en'?'The effect belongs to the pairing, not a single ingredient':L==='pt'?'O efeito é da dupla, não de um ingrediente isolado':'El efecto es de la pareja, no de un ingrediente suelto',
      body: L==='en'?'The pairing "'+best.audio+'" + "'+best.visual+'" reaches '+fmtNum(best.comboL1k,1)+' L/$1k adj. — '+fmtNum(best.strength,0)+'% more than "'+best.audio+'" with other visuals ('+fmtNum(best.audioSolo,1)+') and than "'+best.visual+'" with other audio ('+fmtNum(best.visualSolo,1)+') (n='+best.days+' days). Brief this exact combination, not just the hook type on its own.'
        :L==='pt'?'A dupla "'+best.audio+'" + "'+best.visual+'" rende '+fmtNum(best.comboL1k,1)+' L/$1k adj. — '+fmtNum(best.strength,0)+'% a mais que "'+best.audio+'" com outros visuais ('+fmtNum(best.audioSolo,1)+') e que "'+best.visual+'" com outro áudio ('+fmtNum(best.visualSolo,1)+') (n='+best.days+' dias). Faça o brief dessa combinação exata, não só do tipo de hook isolado.'
        :'La pareja "'+best.audio+'" + "'+best.visual+'" rinde '+fmtNum(best.comboL1k,1)+' en L/$1k adj. — un '+fmtNum(best.strength,0)+'% más que "'+best.audio+'" con otros visuales ('+fmtNum(best.audioSolo,1)+') y que "'+best.visual+'" con otro audio ('+fmtNum(best.visualSolo,1)+') (n='+best.days+' días). Briefear esta combinación exacta, no solo el tipo de hook por separado.' };
  }
  return { strength: best.strength, icon:'⨯', type:'clash',
    title: L==='en'?'This hook pairing cancels itself out':L==='pt'?'Essa dupla de hooks se anula ao se combinar':'Esta pareja de hooks se anula al combinarse',
    body: L==='en'?'The combination "'+best.audio+'" + "'+best.visual+'" reaches only '+fmtNum(best.comboL1k,1)+' L/$1k adj. — '+fmtNum(best.strength,0)+'% below its weakest ingredient on its own ("'+best.weakLabel+'": '+fmtNum(best.weakVal,1)+') (n='+best.days+' days). Each element works fine with other pairings; together they cancel out. Avoid briefing this specific combination even though both resources test well individually.'
      :L==='pt'?'A combinação "'+best.audio+'" + "'+best.visual+'" rende apenas '+fmtNum(best.comboL1k,1)+' L/$1k adj. — '+fmtNum(best.strength,0)+'% abaixo do seu ingrediente mais fraco isolado ("'+best.weakLabel+'": '+fmtNum(best.weakVal,1)+') (n='+best.days+' dias). Cada elemento funciona bem com outras duplas; juntos se anulam. Evite fazer o brief dessa combinação específica mesmo que os dois recursos testem bem individualmente.'
      :'La combinación "'+best.audio+'" + "'+best.visual+'" rinde solo '+fmtNum(best.comboL1k,1)+' en L/$1k adj. — un '+fmtNum(best.strength,0)+'% por debajo de su ingrediente más débil por separado ("'+best.weakLabel+'": '+fmtNum(best.weakVal,1)+') (n='+best.days+' días). Cada elemento funciona bien con otras parejas; juntos se anulan. Evitar briefear esta combinación específica aunque ambos recursos prueben bien por su cuenta.' };
}
function tbdDetectMechanismPainPointFit(data){
  var portfolioRoll = tbdDimensionRollup(data.y26, function(r){return r.pain_point||null;}).filter(function(x){return x.days>=3;});
  if(!portfolioRoll.length) return null;
  var portfolioBest = portfolioRoll[0];
  var byMech = {};
  data.y26.forEach(function(r){ if(!r.theme_mechanism_code) return; (byMech[r.theme_mechanism_code]=byMech[r.theme_mechanism_code]||[]).push(r); });
  var best = null;
  Object.keys(byMech).forEach(function(mech){
    var arr = byMech[mech];
    var distinctPains = new Set(arr.map(function(r){return r.pain_point;}).filter(Boolean));
    if(arr.length<3 || distinctPains.size<2) return;
    var roll = tbdDimensionRollup(arr, function(r){return r.pain_point||null;}).filter(function(x){return x.days>=3;});
    if(roll.length<2) return;
    var mechBest = roll[0];
    var mechDefault = roll.filter(function(x){return x.label===portfolioBest.label;})[0];
    if(!mechDefault || mechBest.label===portfolioBest.label || mechDefault.l1k_adj<=0) return;
    var gap = (mechBest.l1k_adj-mechDefault.l1k_adj)/mechDefault.l1k_adj*100;
    if(gap<20) return;
    if(!best || gap>best.gap) best = {mech:mech, mechBest:mechBest, mechDefault:mechDefault, gap:gap};
  });
  if(!best) return null;
  var L=LANG;
  return { strength: best.gap, icon:'◆',
    title: L==='en'?'Each narrative mechanism has its own winning pain point':L==='pt'?'Cada mecanismo narrativo tem seu próprio pain point vencedor':'Cada mecanismo tiene su propio pain point ganador',
    body: L==='en'?'The best-performing pain point isn\'t the same for every narrative mechanism: "'+best.mech+'" performs better with "'+best.mechBest.label+'" ('+fmtNum(best.mechBest.l1k_adj,0)+' L/$1k adj.) than with "'+best.mechDefault.label+'" ('+fmtNum(best.mechDefault.l1k_adj,0)+'), the portfolio\'s overall "champion" pain point — a '+fmtNum(best.gap,0)+'% difference. Briefing this mechanism with the default pain point leaves performance on the table.'
      :L==='pt'?'O pain point que melhor funciona não é o mesmo para todos os mecanismos narrativos: "'+best.mech+'" rende melhor com "'+best.mechBest.label+'" ('+fmtNum(best.mechBest.l1k_adj,0)+' L/$1k adj.) do que com "'+best.mechDefault.label+'" ('+fmtNum(best.mechDefault.l1k_adj,0)+'), o pain point "campeão geral" do portfólio — uma diferença de '+fmtNum(best.gap,0)+'%. Fazer o brief desse mecanismo com o pain point padrão deixa performance na mesa.'
      :'El pain point que mejor funciona no es el mismo para todos los mecanismos narrativos: "'+best.mech+'" rinde mejor con "'+best.mechBest.label+'" ('+fmtNum(best.mechBest.l1k_adj,0)+' L/$1k adj.) que con "'+best.mechDefault.label+'" ('+fmtNum(best.mechDefault.l1k_adj,0)+'), el pain point "campeón general" del portafolio — una diferencia de '+fmtNum(best.gap,0)+'%. Briefear este mecanismo con el pain point por defecto deja rendimiento sobre la mesa.' };
}
function tbdDeepInsights(data){
  var detectors = [tbdDetectRankReversal, tbdDetectToneByAdType, tbdDetectHookWearout, tbdDetectNewVsRecurring, tbdDetectJrHaloShare, tbdDetectCvrDivergence,
    function(d){ return tbdDetectSpendVsDemandTiming(d,'2026'); }, function(d){ return tbdDetectSpendVsDemandTiming(d,'2025'); },
    // panel de expertos (CMO/Big Data, Psicologia del consumidor, Audiovisual, Copywriting) -- ver especificacion sintetizada
    tbdDetectSpendConcentrationRisk, tbdDetectVolumeMarginDecouple, tbdDetectCostPerSaleReversal, tbdDetectGrowthWithoutQuality,
    tbdDetectFragileLeader, tbdDetectSeasonalSpendMismatch, tbdDetectCampaignHiddenStar, tbdDetectCampaignZombie,
    tbdDetectFearNeedsHumor, tbdDetectCheapFormatMarginLeak, tbdDetectMechanismFatigue, tbdDetectCtaEmotionalMismatch,
    tbdDetectPainPointAdTypeMismatch, tbdDetectHookPairInteraction, tbdDetectMechanismPainPointFit,
    // motores del panel por pestana (estadistica + planeacion)
    tbdSeasonAdjustmentAudit, tbdDetectDimRowFragility, tbdDetectSimpsonReversal, tbdDetectDimScaleCeiling,
    function(d){ return tbdDetectMixShift(d,'ad_type'); },
    function(d){ return tbdDetectMixShift(d,'type_of_production'); },
    function(d){ return tbdDetectMixShift(d,'tone_category'); }];
  var found = [];
  detectors.forEach(function(fn){ try{ var r = fn(data); if(r) found.push(r); }catch(e){} });
  return found.sort(function(a,b){ return b.strength-a.strength; });
}
/* ============================================================
   ACCIONABILIDAD PROFUNDA -- nucleo compartido.
   Ver tbdRunRules() más abajo para el registro de reglas.
   ============================================================ */
function tbdL(en, pt, es){ return LANG==='en' ? en : (LANG==='pt' ? pt : es); }
function tbdNL(v){ return fmtNum(v,0); }               /* leads: 0 decimales, regla de la casa */
function tbdNK(v){ return fmtNum(v,0); }               /* L/$1k y L/$1k adj.: 0 decimales */
function tbdNP(v){ return fmtNum(v,0)+'%'; }
function tbdNP1(v){ return fmtNum(v,1)+'%'; }
function tbdUSD(v){ return fmt$(v,0); }
function tbdPP(v){ return fmtNum(v,1)+' pp'; }
function tbdQ(x){ return '"'+String(x==null?'':x)+'"'; }

/* rollup con lo que el rollup viejo no da: n de creativos, días MINIMOS por
   pieza (el viejo suma días-creativo, que no sirve como compuerta), y los
   nombres, para poder citarlos en el texto. */
function tbdRollup2(items, keyFn){
  var b = {};
  items.forEach(function(r){
    var k = keyFn(r);
    if(k==null || k==='') return;
    var o = b[k] || (b[k] = { label:k, l:0, s:0, e:0, c:0, dw:0, nCre:0, dias:[], nombres:[] });
    o.l += r.l; o.s += r.s; o.e += (r.e||0); o.c += (r.c||0);
    o.dw += r.dem * r.s; o.nCre++; o.dias.push(r.n); o.nombres.push(r.nombre);
  });
  var out = [];
  Object.keys(b).forEach(function(k){
    var o = b[k];
    if(o.s <= 0) return;
    var di = o.dw / o.s;
    out.push({ label:o.label, nCre:o.nCre, l:o.l, s:o.s, e:o.e, c:o.c, dem:di,
      l1k: o.l/o.s*1000, l1k_adj: o.l/o.s*1000/(di/100),
      cpl_adj: o.l>0 ? (o.s/o.l)*(di/100) : null,
      cvr: o.l>0 ? o.e/o.l : 0, mncc: o.c>0 ? (o.c-o.s)/o.c : null,
      diasMin: Math.min.apply(null, o.dias), diasMax: Math.max.apply(null, o.dias),
      diasSum: o.dias.reduce(function(a,x){return a+x;},0),
      nombres: o.nombres });
  });
  return out.sort(function(x,y){ return y.l1k_adj - x.l1k_adj; });
}

/* Nivel de evidencia. Es lo que impide que una celda con n=1 se lea igual que
   una con n=8: el tier decide el verbo y el descargo. */
function tbdTier(nCre, diasMinPieza, gapPct, err){
  var g = Math.abs(gapPct||0), e = err==null ? 8 : err;
  if(nCre<=1 || g < e){
    return { tier:'INDICIO',
      verbo: tbdL('look at','olhe','mira'),
      prefijo: tbdL('Signal too thin to act on yet','Sinal fraco demais para agir ainda','Senal demasiado débil para accionar todavía') };
  }
  if(nCre>=3 && diasMinPieza>=6 && g >= Math.max(15, 2*e)){
    return { tier:'REGLA',
      verbo: tbdL('scale','escale','escala'),
      prefijo: tbdL('Enough evidence to make it the default','Evidencia suficiente para virar padrao','Evidencia suficiente para volverlo el default') };
  }
  return { tier:'APUESTA',
    verbo: tbdL('test','teste','proba'),
    prefijo: tbdL('Worth one controlled bet','Vale uma aposta controlada','Vale una apuesta controlada') };
}

/* Sobredispersion diaria de leads: sin esto, cualquier calculo de cuantos
   leads hace falta para leer un test subestima el ruido real de la TV. */
function tbdPhi(items){
  var byDate = {};
  items.forEach(function(r){ (r._dailyItems||[]).forEach(function(d){
    byDate[d.date] = (byDate[d.date]||0) + d.l; }); });
  var v = Object.keys(byDate).map(function(k){ return byDate[k]; });
  if(v.length < 8) return { phi:3, nFechas:v.length, supuesto:true };
  var m = v.reduce(function(a,x){return a+x;},0)/v.length;
  if(!(m>0)) return { phi:3, nFechas:v.length, supuesto:true };
  var s2 = v.reduce(function(a,x){return a+(x-m)*(x-m);},0)/(v.length-1);
  return { phi: Math.max(1, s2/m), nFechas:v.length, supuesto:false };
}
function tbdNLeads(delta, phi){
  var d = Math.abs(delta||0);
  if(d < 0.01) return Infinity;
  return Math.ceil(15.7*(phi||3)/(d*d));
}

/* Meses que QUEDAN por delante en el año, descartando los que el modelo v2026
   marco como no significativos: recomendar una ventana sobre un mes gris seria
   recomendar sobre ruido. */
function tbdMonthsAhead(territory){
  var t = TBD_SEASONALITY[territory] || {};
  var f = t.factorsIndex || [], grey = t.grey || [];
  var MM = ['01','02','03','04','05','06','07','08','09','10','11','12'];
  var hoyMes = (new Date()).getMonth(); // 0-11
  var cand = [];
  for(var m = hoyMes+1; m < 12; m++){
    if(f[m]==null) continue;
    if(grey[m]) continue;
    cand.push({ m:m, nombre: mesLabel(MM[m]), factor: f[m] });
  }
  var todosGrises = cand.length===0;
  var top = null, flojo = null;
  cand.forEach(function(c){
    if(!top || c.factor > top.factor) top = c;
    if(!flojo || c.factor < flojo.factor) flojo = c;
  });
  return { cand:cand, mesTop: top?top.nombre:null, facTop: top?top.factor:null,
           mesFlojo: flojo?flojo.nombre:null, facFlojo: flojo?flojo.factor:null,
           todosGrises: todosGrises, unico: cand.length===1 };
}
function tbdGreySpendShare(items, territory){
  var t = TBD_SEASONALITY[territory] || {}, grey = t.grey || [];
  var tot = 0, gris = 0, meses = {};
  var MM = ['01','02','03','04','05','06','07','08','09','10','11','12'];
  items.forEach(function(r){ (r._dailyItems||[]).forEach(function(d){
    var m = Number(d.date.slice(5,7))-1;
    tot += d.s;
    if(grey[m]){ gris += d.s; meses[mesLabel(MM[m])] = 1; }
  }); });
  return { pct: tot>0 ? gris/tot*100 : 0, meses: Object.keys(meses), nGrises: Object.keys(meses).length };
}
/* Deriva real del mercado dentro del período, leida del nivel desestacionalizado. */
function tbdMarketDrift(territory){
  var t = TBD_SEASONALITY[territory] || {};
  return t.market_yoy==null ? null : t.market_yoy;
}
function tbdRangoFactor(territory){
  var t = TBD_SEASONALITY[territory] || {};
  var f = (t.factorsIndex||[]).slice(0,7);
  if(!f.length) return null;
  return Math.max.apply(null,f) - Math.min.apply(null,f);
}
/* Pais de contraste: el que tenga el error de ajuste más distinto, para poder
   decir "acá no se puede afinar tanto como en X". */
function tbdPeerCountry(territory){
  var err = tbdSeasonErrPct(territory);
  if(err==null) return null;
  var best = null;
  (TBD_TERRITORIES||[]).forEach(function(t){
    if(t===territory) return;
    var e = tbdSeasonErrPct(t);
    if(e==null) return;
    if(!best || Math.abs(e-err) > Math.abs(best.err-err)) best = { pais:t, err:e };
  });
  return best;
}
/* Cubo de reparto sobre main_character. 6 cubos, sin inventar: lo que no
   encaje devuelve null y la regla no dispara. */
function tbdCastBucket(r){
  var mc = r && r.main_character;
  var txt = mc ? (typeof mc==='string' ? mc : (mc.es||mc.en||mc.pt||'')) : '';
  if(!txt) return null;
  var t = String(txt).split('—')[0].split(' - ')[0].toLowerCase();
  var nino = /niñ|nino|crian|kid|child|filh|hij/.test(t);
  var adulto = /adult|madre|padre|mam|pap|mujer|hombre|mãe|pai|estudiante|profesional/.test(t);
  if(/ceo|vocero|fundador|founder|spokes|andrei|andrey/.test(t)) return 'CEO_VOCERO';
  if(/disfraz|costume|mascota|personaje|character|fantasia/.test(t)) return 'PERSONAJE_DISFRAZ';
  if(nino && adulto) return 'ADULTO_MAS_NINO';
  if(nino) return 'NINO';
  if(adulto) return 'ADULTO';
  if(/sin persona|none|texto|animation|animaci|produto|producto/.test(t)) return 'SIN_PERSONA';
  return null;
}
function tbdSpd(items){
  var s = 0, d = {};
  items.forEach(function(r){ (r._dailyItems||[]).forEach(function(x){ s += x.s; d[x.date]=1; }); });
  var n = Object.keys(d).length;
  return n>0 ? s/n : 0;
}
function tbdMedian(arr){
  if(!arr.length) return 0;
  var a = arr.slice().sort(function(x,y){return x-y;});
  var m = Math.floor(a.length/2);
  return a.length%2 ? a[m] : (a[m-1]+a[m])/2;
}

/* ---------- CONTEXTO: se calcula UNA vez por render ---------- */
function tbdCtx(data){
  var pais = data.territory, marca = tbdOrgName(), esJr = marca==='Open English Junior';
  var gate = tbdSeasonGate(pais) || {};
  var err = tbdSeasonErrPct(pais);
  var sea = TBD_SEASONALITY[pais] || {};
  var y26f = data.y26.filter(function(r){ return r.n >= 3; });
  var gastoPeriodo = data.p26.s || 0;
  var gastoMes = gastoPeriodo / 7;   // el período son 7 meses (Ene-Jul)
  var ph = tbdPhi(data.y26);
  var nMedibles = data.y26.filter(function(r){ return tbdDaysUnique(r) >= 12; }).length;
  var ctx = {
    pais: pais, marca: marca, esJr: esJr,
    err: err, errOk: err!=null, gate: gate.label||null, skill: gate.skill,
    yoy: tbdMarketDrift(pais), market25: sea.market_25, market26: sea.market_26,
    factores: sea.factorsIndex || [], grey: sea.grey || [],
    meses: tbdMonthsAhead(pais), rangoFactor: tbdRangoFactor(pais),
    greySpend: tbdGreySpendShare(data.y26, pais),
    paisContraste: tbdPeerCountry(pais),
    y26f: y26f, nCre26: data.y26.length, nCre25: data.y25.length, nMedibles: nMedibles,
    l1kPort26: data.p26.l1k_adj, l1kPort25: data.p25.l1k_adj, mnccPort26: data.p26.mncc,
    spd: tbdSpd(data.y26), phi: ph.phi, nFechas: ph.nFechas, phiSupuesto: ph.supuesto,
    diasVueloTipico: tbdMedian(y26f.map(function(r){ return r.n; })),
    gastoPeriodo: gastoPeriodo, gastoMes: gastoMes,
    roll: {}
  };
  /* Tope de carga: cuánto dinero puede reasignar UNA lectura de este reporte.
     Se aprieta donde el ajuste es menos confiable -- en AMBAR no se mueve lo
     mismo que en VERDE. */
  ctx.topeCarga = gastoMes * (ctx.gate==='VERDE' ? 0.25 : 0.12);
  return ctx;
}
function tbdRollCached(ctx, items, dimKey, keyFn){
  if(ctx.roll[dimKey]) return ctx.roll[dimKey];
  ctx.roll[dimKey] = tbdRollup2(items, keyFn);
  return ctx.roll[dimKey];
}

/* ---------- LIBRO DE SALDO ----------
   Un solo tope por carga, compartido entre todas las reglas. Sin esto, tres
   reglas distintas pueden mandar a mover el mismo dolar y la misma pieza, y
   la suma de las recomendaciones supera el presupuesto del mes. */
function tbdLedgerNew(ctx){
  return { tope: ctx.topeCarga, saldo: ctx.topeCarga, piezas: {}, dims: {}, consumidores: [], errores: 0 };
}
function tbdLedgerClaimPiece(led, nombre, id){
  if(!nombre) return false;
  if(led.piezas[nombre]) return false;
  led.piezas[nombre] = id;
  return true;
}
function tbdLedgerClaimDim(led, dimKey, id){
  if(!dimKey) return false;
  if(led.dims[dimKey]) return false;
  led.dims[dimKey] = id;
  return true;
}
function tbdLedgerSpend(led, usd, id){
  if(!(usd>0)) return { ok:true, monto:0, saldo:led.saldo };
  if(led.saldo <= 0) return { ok:false, monto:0, saldo:0 };
  var monto = Math.min(usd, led.saldo);
  led.saldo -= monto;
  if(led.consumidores.indexOf(id)===-1) led.consumidores.push(id);
  return { ok:true, monto:monto, saldo:led.saldo };
}
function tbdLedgerWho(led){ return led.consumidores.join(', '); }

/* ---------- formato obligatorio de toda tarjeta ----------
   Hallazgo -> Hipotesis -> Comprobacion -> Accion (-> número de exito).
   La comprobación NUNCA puede quedar vacia: si no hay con que cruzarla, hay
   que decirlo y nombrar el dato que falta. */
function tbdCard(o){
  var L = {
    hall: tbdL('FINDING','ACHADO','HALLAZGO'),
    hip:  tbdL('HYPOTHESIS','HIPOTESE','HIPOTESIS'),
    comp: tbdL('CROSS-CHECK','COMPROVACAO','COMPROBACION'),
    acc:  tbdL('ACTION','ACAO','ACCION'),
    num:  tbdL('SUCCESS / REVERT','SUCESSO / REVERSAO','EXITO / REVERSION')
  };
  var t = L.hall+' — '+o.hallazgo+'\n'+
          L.hip+' — '+o.hipotesis+'\n'+
          L.comp+' — '+(o.comprobacion || tbdL('No way to check it inside this report.','Sem como comprovar dentro deste relatorio.','No hay con que comprobarlo dentro de este reporte.'))+'\n'+
          L.acc+' ('+o.verbo+') — '+o.accion;
  if(o.exito) t += '\n'+L.num+' — '+o.exito;
  if(t.length > 1400 && o.hipotesis && o.hipotesis.length > 80){
    /* si hay que recortar, se recorta la hipotesis: nunca el hallazgo ni la
       comprobación, que son los que sostienen el número. El corte tiene que
       avanzar SIEMPRE, si no la recursion no termina cuando el resto de las
       secciones ya supera el tope por si solo. */
    /* -2 y no -1: al recorte se le pega un '…', así que con -1 el texto
       quedaba del mismo largo y la recursion no terminaba nunca. */
    var largo = Math.max(60, Math.min(o.hipotesis.length - 2, o.hipotesis.length - (t.length-1400)));
    return tbdCard(Object.assign({}, o, { hipotesis: o.hipotesis.slice(0, largo) + '…' }));
  }
  return t;
}
function tbdSafeRule(rule, ctx, data, led){
  try{
    var c = rule.run(ctx, data, led);
    if(!c) return null;
    c.id = rule.id; c.dest = rule.dest; c.prio = rule.prio;
    c.usd = c.usd || 0; c.delta = c.delta || 0;
    c.conf = c.conf==null ? 0.5 : c.conf;
    c.ev = c.usd * Math.abs(c.delta) * c.conf;
    c.claims = c.claims || { piezas:[], dims:[] };
    return c;
  }catch(e){ led.errores++; return null; }
}
function tbdSafeVacio(rule, ctx, data){
  try{ return rule.vacio ? rule.vacio(ctx, data) : null; }catch(e){ return null; }
}

/* ============================ Direction + Brief ============================
   Puerto del bloque "Direction + Brief" del reporte de referencia: NO es un
   parrafo narrativo -- son 4 tarjetas (Keep&Scale / Stop&Avoid / Highest
   untested upside / Operational guidelines) + una caja de Brief separada con
   2 columnas (Generic / Promo), cada bullet compuesto desde datos reales de
   ESTE territorio/marca/período (nunca texto fijo por pais). */
function tbdModeOf(items, keyFn){
  var counts = {}; items.forEach(function(r){ var k=keyFn(r); if(k==null||k==='') return; counts[k]=(counts[k]||0)+1; });
  var best=null; Object.keys(counts).forEach(function(k){ if(!best || counts[k]>counts[best]) best=k; });
  return best;
}
/* ============================================================
   REGISTRO DE REGLAS
   dest: STOP | KEEP | UPSIDE | GUIDE | BRIEF | TEST
   prio: menor = se evalua e imprime primero (y reclama primero en el ledger)
   ============================================================ */
function tbdPainFam(r){
  var c = r && r.pain_point_code;
  return c ? String(c).split('-')[0] : null;
}
function tbdPainNombre(r){
  var pp = r && r.pain_point;
  if(!pp) return null;
  return String(typeof pp==='string' ? pp : (pp.es||pp.en||pp.pt||'')).replace(/\s*\([A-Z]+-[A-Za-z]+\)\s*$/,'').trim();
}
/* ventana recomendada, siempre en meses reales que quedan por delante en ESTE pais */
function tbdVentana(ctx){
  var m = ctx.meses;
  if(m.todosGrises) return tbdL('There is no month left this year whose seasonal factor is statistically distinguishable from a normal month, so pick the window on operational grounds, not on demand',
    'não resta nenhum mês do ano cujo fator sazonal se distinga de um mês normal, então escolha a janela por criterio operacional, não por demanda',
    'no queda ningun mes del año cuyo factor estacional se distinga de un mes normal, así que la ventana se elige por criterio operativo, no por demanda');
  /* Ojo: "el mejor mes que queda" puede seguir estando por debajo de lo normal.
     Decir solo "el más fuerte" lo vendia como bueno cuando no lo es. */
  var bajo = m.facTop < 100;
  return tbdL('Run it in '+m.mesTop+' (factor '+tbdNK(m.facTop)+' — '+(bajo?'the best month left this year here, though still below a normal month':'the strongest month left this year here')+')',
    'Rode em '+m.mesTop+' (fator '+tbdNK(m.facTop)+' — '+(bajo?'o melhor mês que resta no ano aqui, ainda assim abaixo de um mês normal':'o mês mais forte que resta no ano aqui')+')',
    'Córrelo en '+m.mesTop+' (factor '+tbdNK(m.facTop)+' — '+(bajo?'el mejor mes que queda del año acá, aunque todavía por debajo de un mes normal':'el mes más fuerte que queda del año acá')+')');
}
/* el lector de JR decide por su hijo; el de OE decide por si mismo. Esta es la
   diferencia que hace imposible reciclar un brief entre marcas. */
function tbdDecisor(ctx){
  return ctx.esJr
    ? tbdL('the parent who decides and pays, not the child who will take the class',
           'o pai ou a mãe que decide e paga, não a criança que vai ter a aula',
           'el padre o la madre que decide y paga, no en el niño que va a tomar la clase')
    : tbdL('the adult learner, who feels the problem and pays for it himself',
           'o aprendiz adulto, que sente o problema e paga por ele',
           'el aprendiz adulto, que siente el problema y lo paga el mismo');
}

var TBD_RULES = [];

/* ---------------- STOP ---------------- */
TBD_RULES.push({ id:'S-ZOMBIE', dest:'STOP', prio:10,
  run: function(ctx, data, led){
    var byCamp = tbdRollup2(data.y26, function(r){ return r.campaign_name||null; });
    if(byCamp.length < 2) return null;
    var peor = null;
    byCamp.forEach(function(c){
      var piezas = data.y26.filter(function(r){ return r.campaign_name===c.label; });
      if(piezas.length < 2) return;
      var w = piezas.slice().sort(function(a,b){ return a.l1k_adj-b.l1k_adj; })[0];
      var share = ctx.gastoPeriodo>0 ? w.s/ctx.gastoPeriodo*100 : 0;
      if(share < 3) return;
      var resto = piezas.filter(function(r){ return r!==w; });
      var rs = resto.reduce(function(a,r){return a+r.s;},0);
      var rl = resto.reduce(function(a,r){return a+r.l;},0);
      var rdw = resto.reduce(function(a,r){return a+r.dem*r.s;},0);
      if(rs<=0) return;
      var restoAdj = rl/rs*1000/((rdw/rs)/100);
      if(!(restoAdj>0)) return;
      var gap = (restoAdj - w.l1k_adj)/restoAdj*100;
      if(gap < Math.max(20, 2*(ctx.err||8))) return;
      if(!peor || gap > peor.gap) peor = { camp:c.label, w:w, restoAdj:restoAdj, gap:gap, share:share, nPiezas:piezas.length };
    });
    if(!peor) return null;
    if(!tbdLedgerClaimPiece(led, peor.w.nombre, 'S-ZOMBIE')) return null;
    var sp = tbdLedgerSpend(led, peor.w.s/7, 'S-ZOMBIE');
    var t = tbdTier(peor.nPiezas, peor.w.n, peor.gap, ctx.err);
    return { tier:t.tier, usd:sp.monto, delta:peor.gap/100, conf:0.8,
      claims:{piezas:[peor.w.nombre],dims:[]},
      texto: tbdCard({
        verbo: tbdL('pause','pause','pausa'),
        hallazgo: tbdL('In '+ctx.pais+', '+ctx.marca+', '+tbdQ(peor.w.nombre)+' is the weakest of the '+peor.nPiezas+' pieces in campaign '+tbdQ(peor.camp)+': '+tbdNK(peor.w.l1k_adj)+' L/$1k adj. against '+tbdNK(peor.restoAdj)+' for the rest of the same campaign ('+tbdNP(peor.gap)+' below), while absorbing '+tbdUSD(peor.w.s)+' — '+tbdNP(peor.share)+' of all TV spend in this country this period — over '+peor.w.n+' days on air.',
          'Em '+ctx.pais+', '+ctx.marca+', '+tbdQ(peor.w.nombre)+' e a peca mais fraca das '+peor.nPiezas+' da campanha '+tbdQ(peor.camp)+': '+tbdNK(peor.w.l1k_adj)+' L/$1k adj. contra '+tbdNK(peor.restoAdj)+' do resto da mesma campanha ('+tbdNP(peor.gap)+' abaixo), absorvendo '+tbdUSD(peor.w.s)+' — '+tbdNP(peor.share)+' de todo o gasto de TV neste pais no periodo — em '+peor.w.n+' dias no ar.',
          'En '+ctx.pais+', '+ctx.marca+', '+tbdQ(peor.w.nombre)+' es la pieza más débil de las '+peor.nPiezas+' de la campaña '+tbdQ(peor.camp)+': '+tbdNK(peor.w.l1k_adj)+' L/$1k adj. contra '+tbdNK(peor.restoAdj)+' del resto de la misma campaña ('+tbdNP(peor.gap)+' por debajo), y aun así se lleva '+tbdUSD(peor.w.s)+' — '+tbdNP(peor.share)+' de todo el gasto de TV de este país en el período — en '+peor.w.n+' días al aire.'),
        hipotesis: tbdL('Budget inside a campaign tends to stay where it was set at launch, so a piece that never worked keeps its slot because nobody re-cut the rotation. The alternative this report cannot rule out: it may be holding a daypart or a feed the others do not cover.',
          'O orçamento dentro de uma campanha tende a ficar onde foi definido no lancamento, então uma peca que nunca funcionou mantem seu espaco porque ninguem recortou a rotação. A alternativa que este relatorio não descarta: pode estar cobrindo um horario ou um feed que as outras não cobrem.',
          'El presupuesto dentro de una campaña tiende a quedarse donde se fijo al lanzarla, así que una pieza que nunca funciono conserva su lugar porque nadie volvió a cortar la rotación. La alternativa que este reporte no descarta: puede estar cubriendo una franja o un feed que las demas no cubren.'),
        comprobacion: (function(){
          var w2 = tbdWearout2(peor.w);
          if(w2.pct!=null) return tbdL('Cross-checked against its own trajectory: over '+(w2.d1+w2.d2)+' unique dates it went from '+tbdNK(w2.h1.l1k_adj)+' in its first half ('+w2.fIniH1+' to '+w2.fFinH1+') to '+tbdNK(w2.h2.l1k_adj)+' in its second ('+w2.fIniH2+' to '+w2.fFinH2+'), '+tbdNP(w2.pct)+'. It is not a slow start.',
            'Comprovado contra sua própria trajetoria: em '+(w2.d1+w2.d2)+' datas únicas passou de '+tbdNK(w2.h1.l1k_adj)+' na primeira metade ('+w2.fIniH1+' a '+w2.fFinH1+') para '+tbdNK(w2.h2.l1k_adj)+' na segunda ('+w2.fIniH2+' a '+w2.fFinH2+'), '+tbdNP(w2.pct)+'. Não e um comeco lento.',
            'Comprobado contra su propia trayectoria: en '+(w2.d1+w2.d2)+' fechas únicas pasó de '+tbdNK(w2.h1.l1k_adj)+' en su primera mitad ('+w2.fIniH1+' a '+w2.fFinH1+') a '+tbdNK(w2.h2.l1k_adj)+' en la segunda ('+w2.fIniH2+' a '+w2.fFinH2+'), '+tbdNP(w2.pct)+'. No es un arranque lento.');
          return tbdL('Cannot be checked against its own trajectory inside this report: it has '+tbdDaysUnique(peor.w)+' unique dates on air and 12 are needed to split the flight in two readable halves. What is measured is the gap against the rest of its own campaign, which shared the same months.',
            'Não da para comprovar contra sua trajetoria neste relatorio: tem '+tbdDaysUnique(peor.w)+' datas únicas no ar e são necessarias 12 para dividir o voo em duas metades legiveis. O que esta medido e a diferença contra o resto da própria campanha, que dividiu os mesmos meses.',
            'No hay con que comprobarlo contra su propia trayectoria en este reporte: tiene '+tbdDaysUnique(peor.w)+' fechas únicas al aire y hacen falta 12 para partir el vuelo en dos mitades legibles. Lo que si esta medido es la brecha contra el resto de su propia campaña, que compartio los mismos meses.');
        })(),
        accion: tbdL('Take it out of the rotation of '+tbdQ(peor.camp)+' and move its '+tbdUSD(sp.monto)+'/month to the pieces of that same campaign that are already above '+tbdNK(peor.restoAdj)+'. Keep the campaign, drop the piece.',
          'Tire-a da rotação de '+tbdQ(peor.camp)+' e mova seus '+tbdUSD(sp.monto)+'/mês para as pecas da mesma campanha que já estáo acima de '+tbdNK(peor.restoAdj)+'. Mantenha a campanha, tire a peca.',
          'Sácala de la rotación de '+tbdQ(peor.camp)+' y mueve sus '+tbdUSD(sp.monto)+'/mes a las piezas de esa misma campaña que ya están por encima de '+tbdNK(peor.restoAdj)+'. La campaña se queda, la pieza no.'),
        exito: tbdL('The campaign as a whole should land above '+tbdNK(peor.restoAdj*0.95)+' L/$1k adj. within 30 days. If it falls below '+tbdNK(peor.w.l1k_adj)+', the piece was covering something and it has to go back.',
          'A campanha inteira deve ficar acima de '+tbdNK(peor.restoAdj*0.95)+' L/$1k adj. em 30 dias. Se cair abaixo de '+tbdNK(peor.w.l1k_adj)+', a peca estava cobrindo algo e precisa voltar.',
          'La campaña completa debería quedar por encima de '+tbdNK(peor.restoAdj*0.95)+' L/$1k adj. en 30 días. Si cae por debajo de '+tbdNK(peor.w.l1k_adj)+', la pieza estaba cubriendo algo y hay que devolverla.')
      })
    };
  },
  vacio: function(ctx, data){
    var byCamp = tbdRollup2(data.y26, function(r){ return r.campaign_name||null; });
    if(byCamp.length < 2) return tbdL('In '+ctx.pais+', '+ctx.marca+': all '+ctx.nCre26+' creatives of the period belong to a single campaign, so there is no within-campaign comparison to find a zombie piece. Two campaigns with at least 2 pieces each are needed.',
      'Em '+ctx.pais+', '+ctx.marca+': os '+ctx.nCre26+' criativos do periodo pertencem a uma única campanha, então não ha comparacao interna para achar uma peca zumbi. São necessarias duas campanhas com ao menos 2 pecas cada.',
      'En '+ctx.pais+', '+ctx.marca+': los '+ctx.nCre26+' creativos del período pertenecen a una sola campaña, así que no hay comparacion interna con la que encontrar una pieza zombie. Hacen falta dos campañas con al menos 2 piezas cada una.');
    return tbdL('In '+ctx.pais+', '+ctx.marca+': across '+byCamp.length+' campaigns and '+ctx.nCre26+' creatives, no piece is both more than '+tbdNP(Math.max(20,2*(ctx.err||8)))+' below its own campaign and carrying at least 3% of the '+tbdUSD(ctx.gastoPeriodo)+' spent here. Nothing to pause on those grounds.',
      'Em '+ctx.pais+', '+ctx.marca+': entre '+byCamp.length+' campanhas e '+ctx.nCre26+' criativos, nenhuma peca esta ao mesmo tempo mais de '+tbdNP(Math.max(20,2*(ctx.err||8)))+' abaixo da própria campanha e carregando ao menos 3% dos '+tbdUSD(ctx.gastoPeriodo)+' gastos aqui. Nada a pausar por esse criterio.',
      'En '+ctx.pais+', '+ctx.marca+': entre '+byCamp.length+' campañas y '+ctx.nCre26+' creativos, ninguna pieza esta a la vez más de '+tbdNP(Math.max(20,2*(ctx.err||8)))+' por debajo de su propia campaña y cargando al menos 3% de los '+tbdUSD(ctx.gastoPeriodo)+' que se gastaron acá. No hay nada que pausar por ese criterio.');
  }
});

TBD_RULES.push({ id:'S-WEAR', dest:'STOP', prio:30,
  run: function(ctx, data, led){
    var umbral = -((ctx.err||8) + 10);
    var cands = [];
    data.y26.forEach(function(r){
      if(tbdDaysUnique(r) < 12) return;
      if(ctx.gastoPeriodo>0 && r.s/ctx.gastoPeriodo < 0.10) return;
      var w = tbdWearout2(r);
      if(w.pct==null || w.pct > umbral) return;
      if(w.leadsH1 < 30) return;
      cands.push({ r:r, w:w });
    });
    if(!cands.length) return null;
    cands.sort(function(a,b){ return a.w.pct-b.w.pct; });
    var pick = null;
    for(var i=0;i<cands.length;i++){ if(tbdLedgerClaimPiece(led, cands[i].r.nombre, 'S-WEAR')){ pick = cands[i]; break; } }
    if(!pick) return null;
    var sp = tbdLedgerSpend(led, pick.r.s/7*0.5, 'S-WEAR');
    var driftTxt = ctx.yoy==null ? null : tbdNP1(ctx.yoy);
    return { tier:'REGLA', usd:sp.monto, delta:Math.abs(pick.w.pct)/100, conf:0.75,
      claims:{piezas:[pick.r.nombre],dims:[]},
      texto: tbdCard({
        verbo: tbdL('cap','límite','limita'),
        hallazgo: tbdL(tbdQ(pick.r.nombre)+' in '+ctx.pais+' fell '+tbdNP(Math.abs(pick.w.pct))+' demand-adjusted between the two halves of its own flight — '+tbdNK(pick.w.h1.l1k_adj)+' L/$1k adj. over '+pick.w.d1+' days ('+pick.w.fIniH1+' to '+pick.w.fFinH1+', '+tbdNL(pick.w.leadsH1)+' leads) down to '+tbdNK(pick.w.h2.l1k_adj)+' L/$1k adj. over '+pick.w.d2+' days ('+pick.w.fIniH2+' to '+pick.w.fFinH2+', '+tbdNL(pick.w.leadsH2)+' leads) — while carrying '+tbdUSD(pick.r.s)+'.',
          tbdQ(pick.r.nombre)+' em '+ctx.pais+' caiu '+tbdNP(Math.abs(pick.w.pct))+' ajustado por demanda entre as duas metades do próprio voo — '+tbdNK(pick.w.h1.l1k_adj)+' L/$1k adj. em '+pick.w.d1+' dias ('+pick.w.fIniH1+' a '+pick.w.fFinH1+', '+tbdNL(pick.w.leadsH1)+' leads) para '+tbdNK(pick.w.h2.l1k_adj)+' L/$1k adj. em '+pick.w.d2+' dias ('+pick.w.fIniH2+' a '+pick.w.fFinH2+', '+tbdNL(pick.w.leadsH2)+' leads) — carregando '+tbdUSD(pick.r.s)+'.',
          tbdQ(pick.r.nombre)+' en '+ctx.pais+' cayó '+tbdNP(Math.abs(pick.w.pct))+' ya ajustado por demanda entre las dos mitades de su propio vuelo — '+tbdNK(pick.w.h1.l1k_adj)+' L/$1k adj. en '+pick.w.d1+' días ('+pick.w.fIniH1+' a '+pick.w.fFinH1+', '+tbdNL(pick.w.leadsH1)+' leads) a '+tbdNK(pick.w.h2.l1k_adj)+' L/$1k adj. en '+pick.w.d2+' días ('+pick.w.fIniH2+' a '+pick.w.fFinH2+', '+tbdNL(pick.w.leadsH2)+' leads) — cargando '+tbdUSD(pick.r.s)+'.'),
        hipotesis: tbdL('Frequency saturation: the audience that responds to this execution has already been reached, so extra weight buys repeats instead of new people. What this report cannot separate: a competitor may have entered the same window.',
          'Saturacao de frequência: a audiencia que responde a esta execução ja foi atingida, então peso extra compra repeticao em vez de gente nova. O que este relatorio não separa: um concorrente pode ter entrado na mesma janela.',
          'Saturacion de frecuencia: a la audiencia que responde a esta ejecución ya se la alcanzo, así que el peso extra compra repeticiones en vez de gente nueva. Lo que este reporte no puede separar: puede haber entrado un competidor en la misma ventana.'),
        comprobacion: (driftTxt
          ? tbdL('Checked against the market: the deseasonalised level of '+ctx.pais+' moved '+driftTxt+' between the two periods, far less than the '+tbdNP(Math.abs(pick.w.pct))+' this piece lost, so the fall is the creative and not the market. It also clears the '+tbdNP1(ctx.err)+' error margin of the adjustment here.',
              'Comprovado contra o mercado: o nível dessazonalizado de '+ctx.pais+' mudou '+driftTxt+' entre os dois periodos, muito menos que os '+tbdNP(Math.abs(pick.w.pct))+' que esta peca perdeu, então a queda e do criativo e não do mercado. Tambem supera a margem de erro de '+tbdNP1(ctx.err)+' do ajuste aqui.',
              'Comprobado contra el mercado: el nivel desestacionalizado de '+ctx.pais+' se movió '+driftTxt+' entre los dos periodos, muchisimo menos que el '+tbdNP(Math.abs(pick.w.pct))+' que perdió esta pieza, así que la caida es del creativo y no del mercado. Ademas supera el margen de error de '+tbdNP1(ctx.err)+' que tiene el ajuste acá.')
          : null),
        accion: tbdL('Cap its remaining flight at '+tbdUSD(sp.monto)+'/month and put the freed weight behind the pieces that are above '+tbdNK(ctx.l1kPort26)+' (the portfolio level here). Do not brief a V2 of the same execution: what saturated is the execution, not the offer.',
          'Limite o voo restante em '+tbdUSD(sp.monto)+'/mês e coloque o peso liberado nas pecas acima de '+tbdNK(ctx.l1kPort26)+' (o nível do portfolio aqui). Não peca uma V2 da mesma execução: o que saturou foi a execução, não a oferta.',
          'Limita su vuelo restante a '+tbdUSD(sp.monto)+'/mes y pon el peso liberado detras de las piezas que están por encima de '+tbdNK(ctx.l1kPort26)+' (el nivel del portafolio acá). No briefees una V2 de la misma ejecución: lo que se saturo es la ejecución, no la oferta.'),
        exito: tbdL('Two more weeks below '+tbdNK(pick.w.h2.l1k_adj)+' and it comes off air entirely. If it recovers above '+tbdNK(pick.w.h1.l1k_adj*0.9)+', it was a window effect and the cap can be lifted.',
          'Mais duas semanas abaixo de '+tbdNK(pick.w.h2.l1k_adj)+' e sai do ar de vez. Se recuperar acima de '+tbdNK(pick.w.h1.l1k_adj*0.9)+', foi efeito de janela e o limite pode ser retirado.',
          'Dos semanas más por debajo de '+tbdNK(pick.w.h2.l1k_adj)+' y sale del aire del todo. Si se recupera por encima de '+tbdNK(pick.w.h1.l1k_adj*0.9)+', fue efecto de ventana y se le puede quitar el tope.')
      })
    };
  },
  vacio: function(ctx, data){
    var umbral = ((ctx.err||8) + 10);
    return tbdL('In '+ctx.pais+', '+ctx.marca+': of '+ctx.nCre26+' creatives, '+ctx.nMedibles+' have the 12+ unique dates needed to split a flight into two readable halves, and none of those fell more than '+tbdNP(umbral)+' (the '+tbdNP1(ctx.err)+' error of the adjustment plus 10 points) while carrying 10% of spend. No real wear-out to act on.',
      'Em '+ctx.pais+', '+ctx.marca+': de '+ctx.nCre26+' criativos, '+ctx.nMedibles+' tem as 12+ datas únicas necessarias para dividir o voo em duas metades legiveis, e nenhum caiu mais de '+tbdNP(umbral)+' (os '+tbdNP1(ctx.err)+' de erro do ajuste mais 10 pontos) carregando 10% do gasto. Nenhum desgaste real para agir.',
      'En '+ctx.pais+', '+ctx.marca+': de '+ctx.nCre26+' creativos, '+ctx.nMedibles+' tienen las 12+ fechas únicas que hacen falta para partir un vuelo en dos mitades legibles, y ninguno de esos cayó más de '+tbdNP(umbral)+' (el '+tbdNP1(ctx.err)+' de error del ajuste más 10 puntos) cargando 10% del gasto. No hay desgaste real que accionar.');
  }
});

TBD_RULES.push({ id:'S-VOLMARGIN', dest:'STOP', prio:50,
  run: function(ctx, data, led){
    var dims = [['tone_category', function(r){return r.tone_category;}],
                ['theme_mechanism_code', function(r){return r.theme_mechanism_code;}],
                ['hook_audio_type_code', function(r){return r.hook_audio_type_code;}]];
    var best = null;
    dims.forEach(function(d){
      var roll = tbdRollup2(data.y26, d[1]).filter(function(c){ return c.mncc!=null && c.nCre>=2; });
      if(roll.length < 2) return;
      var porLeads = roll.slice().sort(function(a,b){ return b.l-a.l; })[0];
      var porMargen = roll.slice().sort(function(a,b){ return b.mncc-a.mncc; })[0];
      if(porLeads.label===porMargen.label) return;
      if(ctx.gastoPeriodo>0 && porLeads.s/ctx.gastoPeriodo < 0.15) return;
      var gapPts = (porMargen.mncc - porLeads.mncc)*100;
      if(gapPts < 8) return;
      if(!best || gapPts > best.gapPts) best = { dimKey:d[0], porLeads:porLeads, porMargen:porMargen, gapPts:gapPts };
    });
    if(!best) return null;
    if(!tbdLedgerClaimDim(led, best.dimKey, 'S-VOLMARGIN')) return null;
    var mover = best.porLeads.s/7*0.3;
    var sp = tbdLedgerSpend(led, mover, 'S-VOLMARGIN');
    return { tier:'APUESTA', usd:sp.monto, delta:best.gapPts/100, conf:0.6,
      claims:{piezas:[],dims:[best.dimKey]},
      texto: tbdCard({
        verbo: tbdL('rebalance','rebalanceie','rebalancea'),
        hallazgo: tbdL('In '+ctx.pais+', '+ctx.marca+', the '+tbdDimLabel(best.dimKey)+' that brings the most leads is not the one that brings the most business: '+tbdQ(best.porLeads.label)+' produced '+tbdNL(best.porLeads.l)+' leads across '+best.porLeads.nCre+' creatives on '+tbdUSD(best.porLeads.s)+', but its margin is '+tbdNP1(best.porLeads.mncc*100)+' against '+tbdNP1(best.porMargen.mncc*100)+' for '+tbdQ(best.porMargen.label)+' — a gap of '+tbdPP(best.gapPts)+'.',
          'Em '+ctx.pais+', '+ctx.marca+', o '+tbdDimLabel(best.dimKey)+' que traz mais leads não e o que traz mais negocio: '+tbdQ(best.porLeads.label)+' produziu '+tbdNL(best.porLeads.l)+' leads em '+best.porLeads.nCre+' criativos com '+tbdUSD(best.porLeads.s)+', mas sua margem e '+tbdNP1(best.porLeads.mncc*100)+' contra '+tbdNP1(best.porMargen.mncc*100)+' de '+tbdQ(best.porMargen.label)+' — diferença de '+tbdPP(best.gapPts)+'.',
          'En '+ctx.pais+', '+ctx.marca+', el '+tbdDimLabel(best.dimKey)+' que más leads trae no es el que más negocio trae: '+tbdQ(best.porLeads.label)+' produjo '+tbdNL(best.porLeads.l)+' leads en '+best.porLeads.nCre+' creativos con '+tbdUSD(best.porLeads.s)+', pero su margen es '+tbdNP1(best.porLeads.mncc*100)+' contra '+tbdNP1(best.porMargen.mncc*100)+' de '+tbdQ(best.porMargen.label)+' — una brecha de '+tbdPP(best.gapPts)+'.'),
        hipotesis: tbdL('Volume and quality of lead are not the same thing: an execution can pull a lot of people who were never close to enrolling. What this report cannot separate: the two groups may be reaching different audiences at different prices.',
          'Volume e qualidade de lead não são a mesma coisa: uma execução pode atrair muita gente que nunca esteve perto de se matricular. O que este relatorio não separa: os dois grupos podem atingir audiencias diferentes a precos diferentes.',
          'Volumen y calidad de lead no son lo mismo: una ejecución puede traer mucha gente que nunca estuvo cerca de matricularse. Lo que este reporte no puede separar: los dos grupos pueden estar alcanzando audiencias distintas a precios distintos.'),
        comprobacion: tbdL('Cross-checked with conversión: '+tbdQ(best.porLeads.label)+' converts at '+tbdNP1(best.porLeads.cvr*100)+' and '+tbdQ(best.porMargen.label)+' at '+tbdNP1(best.porMargen.cvr*100)+', which '+(best.porMargen.cvr>best.porLeads.cvr?'confirms the margin gap comes from lead quality, not from price.':'does NOT confirm it: conversión is similar, so the gap is price of media, not quality of lead — check the buy before moving budget.'),
          'Comprovado com conversão: '+tbdQ(best.porLeads.label)+' converte a '+tbdNP1(best.porLeads.cvr*100)+' e '+tbdQ(best.porMargen.label)+' a '+tbdNP1(best.porMargen.cvr*100)+', o que '+(best.porMargen.cvr>best.porLeads.cvr?'confirma que a diferença de margem vem da qualidade do lead, não do preco.':'NAO confirma: a conversão e parecida, então a diferença e preco de midia e não qualidade de lead — revise a compra antes de mover verba.'),
          'Comprobado con la conversión: '+tbdQ(best.porLeads.label)+' convierte a '+tbdNP1(best.porLeads.cvr*100)+' y '+tbdQ(best.porMargen.label)+' a '+tbdNP1(best.porMargen.cvr*100)+', lo que '+(best.porMargen.cvr>best.porLeads.cvr?'confirma que la brecha de margen viene de la calidad del lead y no del precio.':'NO lo confirma: la conversión es parecida, así que la brecha es precio de medios y no calidad de lead — revisa la compra antes de mover presupuesto.')),
        accion: tbdL('Move '+tbdUSD(sp.monto)+'/month from '+tbdQ(best.porLeads.label)+' to '+tbdQ(best.porMargen.label)+' and read the result on MNCC%, not on lead count. Leads will go down on purpose.',
          'Mova '+tbdUSD(sp.monto)+'/mês de '+tbdQ(best.porLeads.label)+' para '+tbdQ(best.porMargen.label)+' e leia o resultado em MNCC%, não em número de leads. Os leads vao cair de proposito.',
          'Mueve '+tbdUSD(sp.monto)+'/mes de '+tbdQ(best.porLeads.label)+' a '+tbdQ(best.porMargen.label)+' y lee el resultado en MNCC%, no en cantidad de leads. Los leads van a bajar a propósito.'),
        exito: tbdL('Portfolio MNCC% above '+tbdNP1((ctx.mnccPort26||0)*100 + best.gapPts*0.3)+' in 60 days. Revert if total enrollments fall more than 10%.',
          'MNCC% do portfolio acima de '+tbdNP1((ctx.mnccPort26||0)*100 + best.gapPts*0.3)+' em 60 dias. Reverta se as matrículas totais cairem mais de 10%.',
          'MNCC% del portafolio por encima de '+tbdNP1((ctx.mnccPort26||0)*100 + best.gapPts*0.3)+' en 60 días. Revierte si las matrículas totales caen más de 10%.')
      })
    };
  },
  vacio: function(ctx, data){
    return tbdL('In '+ctx.pais+', '+ctx.marca+': no dimension has its lead leader and its margin leader in different cells by more than 8 pp with both cells holding 2+ creatives. Volume and business point the same way here, across '+ctx.nCre26+' creatives and '+tbdUSD(ctx.gastoPeriodo)+'.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhuma dimensao tem o líder de leads e o líder de margem em celulas diferentes por mais de 8 pp com 2+ criativos em cada. Volume e negocio apontam para o mesmo lado aqui, em '+ctx.nCre26+' criativos e '+tbdUSD(ctx.gastoPeriodo)+'.',
      'En '+ctx.pais+', '+ctx.marca+': ninguna dimension tiene su líder de leads y su líder de margen en celdas distintas por más de 8 pp con 2+ creativos en cada una. Volumen y negocio apuntan al mismo lado acá, sobre '+ctx.nCre26+' creativos y '+tbdUSD(ctx.gastoPeriodo)+'.');
  }
});

/* ---------------- KEEP ---------------- */
TBD_RULES.push({ id:'K-HIDDEN', dest:'KEEP', prio:10,
  run: function(ctx, data, led){
    var byCamp = tbdRollup2(data.y26, function(r){ return r.campaign_name||null; });
    var best = null;
    byCamp.forEach(function(c){
      var piezas = data.y26.filter(function(r){ return r.campaign_name===c.label; });
      if(piezas.length < 2) return;
      var m = piezas.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
      if(m.n < 3) return;
      var resto = piezas.filter(function(r){ return r!==m; });
      var rs = resto.reduce(function(a,r){return a+r.s;},0);
      var rl = resto.reduce(function(a,r){return a+r.l;},0);
      var rdw = resto.reduce(function(a,r){return a+r.dem*r.s;},0);
      if(rs<=0) return;
      var restoAdj = rl/rs*1000/((rdw/rs)/100);
      if(!(restoAdj>0)) return;
      var gap = (m.l1k_adj-restoAdj)/restoAdj*100;
      if(gap < Math.max(15, 2*(ctx.err||8))) return;
      var share = c.s>0 ? m.s/c.s*100 : 0;
      if(share > 40) return; // ya esta bien financiado
      if(!best || gap > best.gap) best = { camp:c.label, m:m, restoAdj:restoAdj, gap:gap, share:share, nCre:piezas.length, campS:c.s };
    });
    if(!best) return null;
    if(!tbdLedgerClaimPiece(led, best.m.nombre, 'K-HIDDEN')) return null;
    var objetivo = Math.min(best.campS*0.40, best.campS*0.40) - best.m.s;
    var sp = tbdLedgerSpend(led, Math.max(0, objetivo/7), 'K-HIDDEN');
    var t = tbdTier(best.nCre, best.m.n, best.gap, ctx.err);
    return { tier:t.tier, usd:sp.monto, delta:best.gap/100, conf:0.7,
      claims:{piezas:[best.m.nombre],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('In '+ctx.pais+', '+ctx.marca+', '+tbdQ(best.m.nombre)+' is the best piece of campaign '+tbdQ(best.camp)+' — '+tbdNK(best.m.l1k_adj)+' L/$1k adj. against '+tbdNK(best.restoAdj)+' for the other '+(best.nCre-1)+' pieces, '+tbdNP(best.gap)+' better over '+best.m.n+' days — and yet it only holds '+tbdNP(best.share)+' of that campaign’s '+tbdUSD(best.campS)+'.',
          'Em '+ctx.pais+', '+ctx.marca+', '+tbdQ(best.m.nombre)+' e a melhor peca da campanha '+tbdQ(best.camp)+' — '+tbdNK(best.m.l1k_adj)+' L/$1k adj. contra '+tbdNK(best.restoAdj)+' das outras '+(best.nCre-1)+' pecas, '+tbdNP(best.gap)+' melhor em '+best.m.n+' dias — e ainda assim fica com apenas '+tbdNP(best.share)+' dos '+tbdUSD(best.campS)+' da campanha.',
          'En '+ctx.pais+', '+ctx.marca+', '+tbdQ(best.m.nombre)+' es la mejor pieza de la campaña '+tbdQ(best.camp)+' — '+tbdNK(best.m.l1k_adj)+' L/$1k adj. contra '+tbdNK(best.restoAdj)+' de las otras '+(best.nCre-1)+' piezas, '+tbdNP(best.gap)+' mejor en '+best.m.n+' días — y aun así solo se lleva '+tbdNP(best.share)+' de los '+tbdUSD(best.campS)+' de esa campaña.'),
        hipotesis: tbdL('Budget was split when the campaign launched, before anyone could know which execution would work, and nobody re-cut it afterwards. The alternative this report does not rule out: it may already be at the ceiling of the inventory it can buy cheaply.',
          'O orçamento foi dividido no lancamento da campanha, antes de saber qual execução funcionaria, e ninguem recortou depois. A alternativa que este relatorio não descarta: pode já estár no teto do inventario que consegue comprar barato.',
          'El presupuesto se repartió al lanzar la campaña, antes de que nadie pudiera saber qué ejecución iba a funcionar, y después nadie lo volvió a cortar. La alternativa que este reporte no descarta: puede estar ya en el techo del inventario que puede comprar barato.'),
        comprobacion: (function(){
          var w = tbdWearout2(best.m);
          if(w.pct!=null) return tbdL('Checked for fatigue before recommending more weight: over '+(w.d1+w.d2)+' unique dates it moved '+tbdNP(w.pct)+' between halves, so it is '+(w.pct<=-15?'already cooling and the increase should be gradual':'still holding')+'.',
            'Verificado quanto a fadiga antes de recomendar mais peso: em '+(w.d1+w.d2)+' datas únicas variou '+tbdNP(w.pct)+' entre metades, então '+(w.pct<=-15?'já está esfriando e o aumento deve ser gradual':'ainda se sustenta')+'.',
            'Se revisó fatiga antes de recomendar más peso: en '+(w.d1+w.d2)+' fechas únicas se movió '+tbdNP(w.pct)+' entre mitades, así que '+(w.pct<=-15?'ya viene enfriándose y la subida debe ser gradual':'todavía se sostiene')+'.');
          return tbdL('Fatigue cannot be checked yet: it has '+tbdDaysUnique(best.m)+' unique dates and 12 are needed. Raise it in steps and re-read after 12 dates, do not jump to full weight.',
            'A fadiga ainda não pode ser verificada: tem '+tbdDaysUnique(best.m)+' datas únicas e são necessarias 12. Aumente por etapas e releia após 12 datas, não va direto ao peso total.',
            'La fatiga todavía no se puede comprobar: tiene '+tbdDaysUnique(best.m)+' fechas únicas y hacen falta 12. Súbelo por escalones y vuelve a leer a las 12 fechas, no saltes a peso completo.');
        })(),
        accion: sp.monto>0
          ? tbdL('Raise it to 40% of '+tbdQ(best.camp)+' by adding '+tbdUSD(sp.monto)+'/month taken from the weakest pieces of that same campaign. '+tbdVentana(ctx)+'.',
              'Suba para 40% de '+tbdQ(best.camp)+' adicionando '+tbdUSD(sp.monto)+'/mês tirados das pecas mais fracas da mesma campanha. '+tbdVentana(ctx)+'.',
              'Súbelo a 40% de '+tbdQ(best.camp)+' agregando '+tbdUSD(sp.monto)+'/mes sacados de las piezas más débiles de esa misma campaña. '+tbdVentana(ctx)+'.')
          : tbdL('The reallocation budget for this reading is already committed by '+tbdLedgerWho(led)+', so this one is queued: apply it in the next cycle.',
              'O orçamento de realocação desta leitura ja foi comprometido por '+tbdLedgerWho(led)+', então este fica na fila: aplique no próximo ciclo.',
              'El presupuesto de reasignación de esta lectura ya lo comprometio '+tbdLedgerWho(led)+', así que este queda en cola: aplicalo en el próximo ciclo.'),
        exito: tbdL('Campaign '+tbdQ(best.camp)+' above '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. in 30 days. If '+tbdQ(best.m.nombre)+' itself drops below '+tbdNK(best.restoAdj)+' at the higher weight, it had a scale ceiling and the extra budget goes back.',
          'Campanha '+tbdQ(best.camp)+' acima de '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. em 30 dias. Se '+tbdQ(best.m.nombre)+' cair abaixo de '+tbdNK(best.restoAdj)+' com mais peso, tinha teto de escala e a verba extra volta.',
          'La campaña '+tbdQ(best.camp)+' por encima de '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. en 30 días. Si '+tbdQ(best.m.nombre)+' cae por debajo de '+tbdNK(best.restoAdj)+' con más peso, tenía techo de escala y el presupuesto extra se devuelve.')
      })
    };
  },
  vacio: function(ctx, data){
    return tbdL('In '+ctx.pais+', '+ctx.marca+': no campaign has a leader that beats its own campaign siblings by more than '+tbdNP(Math.max(15,2*(ctx.err||8)))+' while holding under 40% of that campaign budget. Across '+ctx.nCre26+' creatives, budget is already sitting where performance is.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhuma campanha tem líder que supere as irmas por mais de '+tbdNP(Math.max(15,2*(ctx.err||8)))+' ficando com menos de 40% da verba. Em '+ctx.nCre26+' criativos, a verba já está onde esta a performance.',
      'En '+ctx.pais+', '+ctx.marca+': ninguna campaña tiene un líder que le gane a sus propias hermanas por más de '+tbdNP(Math.max(15,2*(ctx.err||8)))+' llevandose menos del 40% de esa campaña. Sobre '+ctx.nCre26+' creativos, el presupuesto ya esta donde esta el desempenio.');
  }
});

/* ---------------- UPSIDE ---------------- */
TBD_RULES.push({ id:'U-HALO', dest:'UPSIDE', prio:20,
  run: function(ctx, data, led){
    var totalJr = 0, totalOe = 0;
    data.y26.forEach(function(r){ totalJr += (r.jr_l||0); totalOe += r.l; });
    if(totalOe<=0 || totalJr < 50) return null;
    var pct = totalJr/totalOe*100;
    if(pct < 3) return null;
    var aport = data.y26.filter(function(r){ return (r.jr_l||0)>0 && r.n>=5; })
      .sort(function(a,b){ return b.jr_l1k_adj-a.jr_l1k_adj; });
    if(!aport.length) return null;
    var top = aport[0];
    var otra = tbdHaloTargetName();
    return { tier:'APUESTA', usd:0, delta:pct/100, conf:0.65, claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: tbdL('brief','peca','briefea'),
        hallazgo: tbdL('In '+ctx.pais+', the '+tbdUSD(ctx.gastoPeriodo)+' spent on '+ctx.marca+' also produced '+tbdNL(totalJr)+' real '+otra+' leads — '+tbdNP(pct)+' on top of its own '+tbdNL(totalOe)+' — spread over '+aport.length+' creatives, led by '+tbdQ(top.nombre)+' at '+tbdNK(top.jr_l1k_adj)+' halo L/$1k adj. against its own '+tbdNK(top.l1k_adj)+'. Nobody has ever briefed a piece to do this on purpose.',
          'Em '+ctx.pais+', os '+tbdUSD(ctx.gastoPeriodo)+' gastos em '+ctx.marca+' tambem geraram '+tbdNL(totalJr)+' leads reais de '+otra+' — '+tbdNP(pct)+' alem dos seus próprios '+tbdNL(totalOe)+' — em '+aport.length+' criativos, liderados por '+tbdQ(top.nombre)+' com '+tbdNK(top.jr_l1k_adj)+' de L/$1k adj. de halo contra '+tbdNK(top.l1k_adj)+' próprio. Ninguem nunca pediu uma peca para fazer isso de proposito.',
          'En '+ctx.pais+', los '+tbdUSD(ctx.gastoPeriodo)+' gastados en '+ctx.marca+' también produjeron '+tbdNL(totalJr)+' leads reales de '+otra+' — '+tbdNP(pct)+' encima de sus propios '+tbdNL(totalOe)+' — repartidos en '+aport.length+' creativos, encabezados por '+tbdQ(top.nombre)+' con '+tbdNK(top.jr_l1k_adj)+' de L/$1k adj. de halo contra '+tbdNK(top.l1k_adj)+' propio. Nunca nadie briefeo una pieza para que esto pasara a propósito.'),
        hipotesis: ctx.esJr
          ? tbdL('A parent watching an ad for their child is also an adult who once gave up on English. The Junior spot is reactivating that personal frustration as a side effect.',
              'Um pai assistindo a um anuncio para o filho tambem e um adulto que um día desistiu do ingles. O comercial Junior esta reativando essa frustracao pessoal como efeito colateral.',
              'Un padre viendo un anuncio para su hijo también es un adulto que alguna vez abandono el ingles. El spot de Junior le esta reactivando esa frustracion personal como efecto secundario.')
          : tbdL('An adult who sees the value of English for themselves immediately thinks of their child. The adult spot is opening a door it never explicitly knocks on.',
              'Um adulto que ve o valor do ingles para si pensa imediatamente no filho. O comercial adulto abre uma porta na qual nunca bate explicitamente.',
              'Un adulto que le ve el valor al ingles para si mismo piensa de inmediato en su hijo. El spot adulto abre una puerta a la que nunca toca de forma explicita.'),
        comprobacion: tbdL('Cross-checked piece by piece: '+aport.length+' of the '+ctx.nCre26+' creatives produce halo with 5+ days on air, so this is not one lucky spot. The pieces that lead on halo are '+(aport[0].nombre===data.y26.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;})[0].nombre ? 'the same ones that lead on their own brand, which suggests general reach rather than a specific cross-brand mechanic.' : 'NOT the ones that lead on their own brand, which suggests something specific in those executions is doing it — that is what the brief should copy.'),
          'Comprovado peca a peca: '+aport.length+' dos '+ctx.nCre26+' criativos geram halo com 5+ dias no ar, então não e um comercial de sorte. As pecas que lideram em halo são '+(aport[0].nombre===data.y26.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;})[0].nombre ? 'as mesmas que lideram na própria marca, o que sugere alcance geral e não uma mecánica cruzada especifica.' : 'NAO as que lideram na própria marca, o que sugere que algo especifico nessas execucoes esta causando isso — e o que o brief deve copiar.'),
          'Comprobado pieza por pieza: '+aport.length+' de los '+ctx.nCre26+' creativos generan halo con 5+ días al aire, así que no es un spot con suerte. Las piezas que lideran en halo son '+(aport[0].nombre===data.y26.slice().sort(function(a,b){return b.l1k_adj-a.l1k_adj;})[0].nombre ? 'las mismas que lideran en su propia marca, lo que sugiere alcance general y no una mecánica cruzada especifica.' : 'NO las que lideran en su propia marca, lo que sugiere que algo especifico de esas ejecuciones lo esta causando — eso es lo que hay que copiar en el brief.')),
        accion: tbdL('Brief one piece that names both audiences explicitly, using '+tbdQ(top.nombre)+' (campaign '+tbdQ(top.campaign_name)+', tone '+tbdQ(top.tone_category)+') as the reference execution. '+tbdVentana(ctx)+'. Budget it as a normal production, not as an experiment: the halo already exists, this only makes it deliberate.',
          'Peca uma peca que nomeie as duas audiencias explicitamente, usando '+tbdQ(top.nombre)+' (campanha '+tbdQ(top.campaign_name)+', tom '+tbdQ(top.tone_category)+') como execução de referência. '+tbdVentana(ctx)+'. Orce como produção normal, não como experimento: o halo ja existe, isto so o torna deliberado.',
          'Briefea una pieza que nombre a las dos audiencias de forma explicita, usando '+tbdQ(top.nombre)+' (campaña '+tbdQ(top.campaign_name)+', tono '+tbdQ(top.tone_category)+') como ejecución de referencia. '+tbdVentana(ctx)+'. Presupuestala como una producción normal, no como un experimento: el halo ya existe, esto solo lo vuelve deliberado.'),
        exito: tbdL('Halo above '+tbdNK(top.jr_l1k_adj*1.2)+' L/$1k adj. for the new piece without its own '+ctx.marca+' number falling below '+tbdNK(ctx.l1kPort26)+'. If its own brand drops, the piece is cannibalising, not adding.',
          'Halo acima de '+tbdNK(top.jr_l1k_adj*1.2)+' L/$1k adj. para a peca nova sem que seu próprio número de '+ctx.marca+' caia abaixo de '+tbdNK(ctx.l1kPort26)+'. Se a própria marca cair, a peca esta canibalizando, não somando.',
          'Halo por encima de '+tbdNK(top.jr_l1k_adj*1.2)+' L/$1k adj. para la pieza nueva sin que su propio número de '+ctx.marca+' caiga por debajo de '+tbdNK(ctx.l1kPort26)+'. Si la marca propia baja, la pieza esta canibalizando, no sumando.')
      })
    };
  },
  vacio: function(ctx, data){
    var totalJr = 0, totalOe = 0;
    data.y26.forEach(function(r){ totalJr += (r.jr_l||0); totalOe += r.l; });
    var pct = totalOe>0 ? totalJr/totalOe*100 : 0;
    return tbdL('In '+ctx.pais+', '+ctx.marca+' produced '+tbdNL(totalJr)+' cross-brand leads against '+tbdNL(totalOe)+' of its own ('+tbdNP1(pct)+'), below the 3% and 50-lead floor needed to justify briefing a piece for it. Not worth a production here yet.',
      'Em '+ctx.pais+', '+ctx.marca+' gerou '+tbdNL(totalJr)+' leads cruzados contra '+tbdNL(totalOe)+' próprios ('+tbdNP1(pct)+'), abaixo do piso de 3% e 50 leads necessario para justificar uma peca dedicada. Ainda não vale uma produção aqui.',
      'En '+ctx.pais+', '+ctx.marca+' genero '+tbdNL(totalJr)+' leads cruzados contra '+tbdNL(totalOe)+' propios ('+tbdNP1(pct)+'), por debajo del piso de 3% y 50 leads que hace falta para justificar una pieza dedicada. Todavia no amerita una producción acá.');
  }
});

TBD_RULES.push({ id:'U-THIN', dest:'UPSIDE', prio:30,
  run: function(ctx, data, led){
    var e = ctx.err||8;
    var c = data.y26.filter(function(r){ return r.n>=2 && r.n<=4 && ctx.l1kPort26>0 && r.l1k_adj > ctx.l1kPort26*(1+e/100); })
      .sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    if(!c) return null;
    if(!tbdLedgerClaimPiece(led, c.nombre, 'U-THIN')) return null;
    var lift = (c.l1k_adj-ctx.l1kPort26)/ctx.l1kPort26*100;
    var faltan = Math.max(0, 6-c.n);
    return { tier:'INDICIO', usd:0, delta:lift/100, conf:0.3, claims:{piezas:[c.nombre],dims:[]},
      texto: tbdCard({
        verbo: tbdL('extend','estenda','extiende'),
        hallazgo: tbdL(tbdQ(c.nombre)+' (campaign '+tbdQ(c.campaign_name)+', '+tbdQ(c.tone_category)+' tone) in '+ctx.pais+' shows '+tbdNK(c.l1k_adj)+' L/$1k adj., '+tbdNP(lift)+' above the '+tbdNK(ctx.l1kPort26)+' of the '+ctx.marca+' portfolio here — but on only '+c.n+' days on air and '+tbdNL(c.l)+' leads, with '+tbdUSD(c.s)+' behind it. This is NOT a winner yet: with '+c.n+' days, the error of the adjustment alone in '+ctx.pais+' is '+tbdNP1(ctx.err)+'.',
          tbdQ(c.nombre)+' (campanha '+tbdQ(c.campaign_name)+', tom '+tbdQ(c.tone_category)+') em '+ctx.pais+' mostra '+tbdNK(c.l1k_adj)+' L/$1k adj., '+tbdNP(lift)+' acima dos '+tbdNK(ctx.l1kPort26)+' do portfolio '+ctx.marca+' aqui — mas em apenas '+c.n+' dias no ar e '+tbdNL(c.l)+' leads, com '+tbdUSD(c.s)+' por tras. Isto NAO e um vencedor ainda: com '+c.n+' dias, so o erro do ajuste em '+ctx.pais+' e '+tbdNP1(ctx.err)+'.',
          tbdQ(c.nombre)+' (campaña '+tbdQ(c.campaign_name)+', tono '+tbdQ(c.tone_category)+') en '+ctx.pais+' marca '+tbdNK(c.l1k_adj)+' L/$1k adj., '+tbdNP(lift)+' por encima de los '+tbdNK(ctx.l1kPort26)+' del portafolio de '+ctx.marca+' acá — pero con apenas '+c.n+' días al aire y '+tbdNL(c.l)+' leads, con '+tbdUSD(c.s)+' detras. Esto NO es un ganador todavía: con '+c.n+' días, solo el error del ajuste en '+ctx.pais+' ya es '+tbdNP1(ctx.err)+'.'),
        hipotesis: tbdL('Short flights land on the days that happened to be good. The fewer the days, the more the number is luck rather than quality.',
          'Voos curtos caem nos dias que por acaso foram bons. Quanto menos dias, mais o número e sorte e não qualidade.',
          'Los vuelos cortos caen en los días que por casualidad salieron buenos. Cuantos menos días, más el número es suerte y no calidad.'),
        comprobacion: tbdL('There is no way to confirm it inside this report: '+c.n+' days is below the 6 needed for a stable read here. What has to happen to settle it: '+faltan+' more days on air at similar weight.',
          'Não ha como confirmar dentro deste relatorio: '+c.n+' dias esta abaixo dos 6 necessarios para uma leitura estavel aqui. O que falta para resolver: '+faltan+' dias a mais no ar com peso similar.',
          'No hay con que comprobarlo dentro de este reporte: '+c.n+' días esta por debajo de los 6 que hacen falta para una lectura estable acá. Lo que falta para resolverlo: '+faltan+' días más al aire a peso similar.'),
        accion: tbdL('Give it '+faltan+' more days at the same daily weight ('+tbdUSD(ctx.spd)+'/day is the country average) before deciding anything. Do not scale it and do not kill it on '+c.n+' days.',
          'De a ela '+faltan+' dias a mais com o mesmo peso diario ('+tbdUSD(ctx.spd)+'/dia e a média do pais) antes de decidir. Não escale e não mate com '+c.n+' dias.',
          'Dale '+faltan+' días más al mismo peso diario ('+tbdUSD(ctx.spd)+'/día es el promedio del país) antes de decidir nada. Ni la escales ni la mates con '+c.n+' días.'),
        exito: tbdL('If it holds above '+tbdNK(ctx.l1kPort26*(1+ctx.err/100))+' after 6 days it becomes a real candidate to scale. If it lands below '+tbdNK(ctx.l1kPort26)+', it was the days and not the piece.',
          'Se ficar acima de '+tbdNK(ctx.l1kPort26*(1+ctx.err/100))+' após 6 dias vira candidata real. Se ficar abaixo de '+tbdNK(ctx.l1kPort26)+', foram os dias e não a peca.',
          'Si se sostiene por encima de '+tbdNK(ctx.l1kPort26*(1+ctx.err/100))+' a los 6 días, pasa a ser candidata real para escalar. Si cae por debajo de '+tbdNK(ctx.l1kPort26)+', fueron los días y no la pieza.')
      })
    };
  },
  vacio: function(ctx, data){
    return tbdL('In '+ctx.pais+', '+ctx.marca+': no creative with 2-4 days on air is above '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' (the '+tbdNK(ctx.l1kPort26)+' of the portfolio plus its '+tbdNP1(ctx.err)+' error margin). There is no promising short flight waiting for more days.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhum criativo com 2-4 dias no ar esta acima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' (os '+tbdNK(ctx.l1kPort26)+' do portfolio mais sua margem de '+tbdNP1(ctx.err)+'). Não ha voo curto promissor esperando mais dias.',
      'En '+ctx.pais+', '+ctx.marca+': ningun creativo con 2-4 días al aire esta por encima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' (los '+tbdNK(ctx.l1kPort26)+' del portafolio más su margen de '+tbdNP1(ctx.err)+'). No hay ningun vuelo corto prometedor esperando más días.');
  }
});

/* ---------------- GUIDE ---------------- */
TBD_RULES.push({ id:'G-GOV', dest:'GUIDE', prio:10,
  run: function(ctx, data, led){
    var gName = LANG==='en' ? (ctx.gate==='VERDE'?'GREEN':ctx.gate==='AMBAR'?'AMBER':ctx.gate) : ctx.gate;
    var grande = (ctx.err||0) >= 10;
    return { tier:'REGLA', usd:0, delta:0, conf:1, claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: tbdL('read','leia','lee'),
        hallazgo: tbdL('The demand adjustment in '+ctx.pais+' is rated '+gName+' (it beat "every month is the same" by '+tbdNP(ctx.skill)+' on months the model never saw) and carries '+tbdNP1(ctx.err)+' of error. The seasonal factors of Jan-Jul here span '+tbdNK(ctx.rangoFactor)+' points, and '+tbdNP(ctx.greySpend.pct)+' of the '+tbdUSD(ctx.gastoPeriodo)+' spent ran in months whose factor is not statistically distinguishable from a normal month'+(ctx.greySpend.nGrises?' ('+ctx.greySpend.meses.join(', ')+')':'')+'.',
          'O ajuste de demanda em '+ctx.pais+' esta como '+gName+' (superou "todo mês e igual" em '+tbdNP(ctx.skill)+' em meses que o modelo nunca viu) e carrega '+tbdNP1(ctx.err)+' de erro. Os fatores sazonais de Jan-Jul aqui variam '+tbdNK(ctx.rangoFactor)+' pontos, e '+tbdNP(ctx.greySpend.pct)+' dos '+tbdUSD(ctx.gastoPeriodo)+' gastos rodaram em meses cujo fator não se distingue de um mês normal'+(ctx.greySpend.nGrises?' ('+ctx.greySpend.meses.join(', ')+')':'')+'.',
          'El ajuste por demanda de '+ctx.pais+' esta calificado como '+gName+' (le ganó a "todos los meses son iguales" por '+tbdNP(ctx.skill)+' en meses que el modelo nunca vio) y carga '+tbdNP1(ctx.err)+' de error. Los factores estacionales de Ene-Jul acá abarcan '+tbdNK(ctx.rangoFactor)+' puntos, y '+tbdNP(ctx.greySpend.pct)+' de los '+tbdUSD(ctx.gastoPeriodo)+' gastados corrieron en meses cuyo factor no se distingue de un mes normal'+(ctx.greySpend.nGrises?' ('+ctx.greySpend.meses.join(', ')+')':'')+'.'),
        hipotesis: tbdL('An error margin is not a formality: it is the width below which two creatives are the same creative as far as this report can tell.',
          'Uma margem de erro não e formalidade: e a largura abaixo da qual dois criativos são o mesmo criativo para este relatorio.',
          'Un margen de error no es una formalidad: es el ancho por debajo del cual dos creativos son el mismo creativo para lo que este reporte puede distinguir.'),
        comprobacion: ctx.paisContraste
          ? tbdL('For scale: in '+ctx.paisContraste.pais+' the same adjustment carries '+tbdNP1(ctx.paisContraste.err)+', so a gap that is decisive there '+(ctx.paisContraste.err<ctx.err?'is not decisive here':'would not be decisive there')+'. The threshold is a property of the country, not of the creative.',
              'Para escala: em '+ctx.paisContraste.pais+' o mesmo ajuste carrega '+tbdNP1(ctx.paisContraste.err)+', então uma diferença decisiva la '+(ctx.paisContraste.err<ctx.err?'não e decisiva aqui':'não seria decisiva la')+'. O limiar e uma propriedade do pais, não do criativo.',
              'Para dar escala: en '+ctx.paisContraste.pais+' el mismo ajuste carga '+tbdNP1(ctx.paisContraste.err)+', así que una brecha que alla es decisiva '+(ctx.paisContraste.err<ctx.err?'acá no lo es':'alla no lo seria')+'. El umbral es una propiedad del país, no del creativo.')
          : null,
        accion: tbdL('Do not separate two creatives in '+ctx.pais+' on a gap smaller than '+tbdNP1(ctx.err)+'.'+(grande?' With an error this wide, most of the differences between creatives in this country are NOT decidable with this metric — treat every ranking here as provisional order and decide with spend and days, not with decimals.':'')+' The reallocation ceiling for one reading of this report here is '+tbdUSD(ctx.topeCarga)+'/month.',
          'Não separe dois criativos em '+ctx.pais+' por uma diferença menor que '+tbdNP1(ctx.err)+'.'+(grande?' Com um erro tao largo, a maioria das diferencas entre criativos neste pais NAO e decidivel com esta metrica — trate todo ranking aqui como ordem provisoria e decida com gasto e dias, não com decimais.':'')+' O teto de realocação para uma leitura deste relatorio aqui e '+tbdUSD(ctx.topeCarga)+'/mês.',
          'No separes a dos creativos en '+ctx.pais+' por una brecha menor a '+tbdNP1(ctx.err)+'.'+(grande?' Con un error así de ancho, la mayoria de las diferencias entre creativos de este país NO son decidibles con esta métrica — trata todo ranking de acá como orden provisional y decide con gasto y días, no con decimales.':'')+' El tope de reasignación para una lectura de este reporte acá es '+tbdUSD(ctx.topeCarga)+'/mes.'),
        exito: null
      })
    };
  }
});

TBD_RULES.push({ id:'G-MARKET', dest:'GUIDE', prio:20,
  run: function(ctx, data, led){
    if(ctx.yoy==null || Math.abs(ctx.yoy) < 3) return null;
    var sube = ctx.yoy > 0;
    return { tier:'REGLA', usd:0, delta:Math.abs(ctx.yoy)/100, conf:0.9, claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: tbdL('discount','desconte','descuenta'),
        hallazgo: tbdL('Beyond seasonality, the market itself in '+ctx.pais+' '+(sube?'grew':'shrank')+' '+tbdNP1(Math.abs(ctx.yoy))+' between Jan-Jul 2025 and Jan-Jul 2026 (level '+tbdNK(ctx.market25)+' to '+tbdNK(ctx.market26)+'). The '+ctx.marca+' portfolio went from '+tbdNK(ctx.l1kPort25)+' to '+tbdNK(ctx.l1kPort26)+' L/$1k adj. over the same window, on '+tbdUSD(ctx.gastoPeriodo)+' across '+ctx.nCre26+' creatives.',
          'Alem da sazonalidade, o próprio mercado em '+ctx.pais+' '+(sube?'cresceu':'encolheu')+' '+tbdNP1(Math.abs(ctx.yoy))+' entre Jan-Jul 2025 e Jan-Jul 2026 (nível '+tbdNK(ctx.market25)+' para '+tbdNK(ctx.market26)+'). O portfolio '+ctx.marca+' foi de '+tbdNK(ctx.l1kPort25)+' para '+tbdNK(ctx.l1kPort26)+' L/$1k adj. na mesma janela, com '+tbdUSD(ctx.gastoPeriodo)+' em '+ctx.nCre26+' criativos.',
          'Mas alla de la estacionalidad, el mercado mismo de '+ctx.pais+' '+(sube?'crecio':'se encogio')+' '+tbdNP1(Math.abs(ctx.yoy))+' entre Ene-Jul 2025 y Ene-Jul 2026 (nivel '+tbdNK(ctx.market25)+' a '+tbdNK(ctx.market26)+'). El portafolio de '+ctx.marca+' pasó de '+tbdNK(ctx.l1kPort25)+' a '+tbdNK(ctx.l1kPort26)+' L/$1k adj. en la misma ventana, sobre '+tbdUSD(ctx.gastoPeriodo)+' y '+ctx.nCre26+' creativos.'),
        hipotesis: sube
          ? tbdL('A rising market lifts every creative, so part of any year-on-year improvement here was not earned by the work.',
              'Um mercado em alta levanta todo criativo, então parte de qualquer melhora ano a ano aqui não foi merito do trabalho.',
              'Un mercado que sube levanta a todos los creativos, así que parte de cualquier mejora año contra año de acá no la ganó el trabajo.')
          : tbdL('A falling market drags every creative down, so a flat year-on-year number here is actually a gain against the field.',
              'Um mercado em queda arrasta todo criativo, então um número estavel ano a ano aqui e na verdade um ganho relativo.',
              'Un mercado que cae arrastra a todos los creativos, así que un número plano año contra año acá es en realidad una ganancia frente al campo.'),
        comprobacion: tbdL('This is deliberately NOT divided out of the adj. columns, because dividing by it would make a creative look better precisely because its market collapsed. It is stated here so the year-on-year reading is discounted by hand.',
          'Isto NAO e dividido nas colunas adj. de proposito, porque dividir faria um criativo parecer melhor justamente porque seu mercado caiu. Fica declarado aqui para que a leitura ano a ano seja descontada a mao.',
          'Esto a propósito NO se divide en las columnas adj., porque dividir por el haria que un creativo se vea mejor justamente porque su mercado se derrumbo. Se declara acá para que la lectura año contra año se descuente a mano.'),
        accion: tbdL('When you present '+ctx.pais+', say the '+tbdNP1(Math.abs(ctx.yoy))+' out loud before the creative verdict. '+(sube?'Any improvement below that number is the market, not the work.':'Anything that merely held flat outperformed the market by '+tbdNP1(Math.abs(ctx.yoy))+'.'),
          'Ao apresentar '+ctx.pais+', diga os '+tbdNP1(Math.abs(ctx.yoy))+' antes do veredicto criativo. '+(sube?'Qualquer melhora abaixo desse número e o mercado, não o trabalho.':'Qualquer coisa que apenas se manteve superou o mercado em '+tbdNP1(Math.abs(ctx.yoy))+'.'),
          'Cuando presentes '+ctx.pais+', di el '+tbdNP1(Math.abs(ctx.yoy))+' en voz alta antes del veredicto creativo. '+(sube?'Cualquier mejora por debajo de ese número es el mercado, no el trabajo.':'Cualquier cosa que apenas se mantuvo le ganó al mercado por '+tbdNP1(Math.abs(ctx.yoy))+'.')),
        exito: null
      })
    };
  },
  vacio: function(ctx, data){
    if(ctx.yoy==null) return null;
    return tbdL('In '+ctx.pais+' the deseasonalised market moved only '+tbdNP1(ctx.yoy)+' between the two periods (level '+tbdNK(ctx.market25)+' to '+tbdNK(ctx.market26)+'), below the 3% worth mentioning. The year-on-year comparison here needs no market discount.',
      'Em '+ctx.pais+' o mercado dessazonalizado moveu apenas '+tbdNP1(ctx.yoy)+' entre os dois periodos (nível '+tbdNK(ctx.market25)+' para '+tbdNK(ctx.market26)+'), abaixo dos 3% que valem mencao. A comparacao ano a ano aqui não precisa de desconto de mercado.',
      'En '+ctx.pais+' el mercado desestacionalizado se movió apenas '+tbdNP1(ctx.yoy)+' entre los dos periodos (nivel '+tbdNK(ctx.market25)+' a '+tbdNK(ctx.market26)+'), por debajo del 3% que amerita mencion. La comparacion año contra año de acá no necesita descuento de mercado.');
  }
});

/* ---------------- BRIEF (se corre dos veces: GENERIC y PROMO) ---------------- */
function tbdBriefCtx(ctx, data, T){
  var items = data.y26.filter(function(r){ return r.ad_type===T; });
  var conDias = items.filter(function(r){ return r.n>=3; });
  var base = conDias.length>=2 ? conDias : items;
  var s = 0, l = 0, dw = 0;
  base.forEach(function(r){ s+=r.s; l+=r.l; dw+=r.dem*r.s; });
  return { T:T, items:items, base:base, n:base.length,
    s:s, l:l, l1k_adj: s>0 ? l/s*1000/((dw/s)/100) : null,
    lider: base.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0] || null };
}
TBD_RULES.push({ id:'B-OPEN', dest:'BRIEF', prio:10,
  run: function(ctx, data, led, T){
    var b = tbdBriefCtx(ctx, data, T);
    if(!b.lider || b.n < 2) return null;
    var lid = b.lider;
    var ha = lid.hook_audio_type_code, hv = lid.hook_visual_type_code;
    if(!ha && !hv) return null;
    var k = b.base.filter(function(r){ return r.hook_audio_type_code===ha && r.hook_visual_type_code===hv; });
    var otros = b.base.filter(function(r){ return r!==lid; });
    var os_ = otros.reduce(function(a,r){return a+r.s;},0), ol = otros.reduce(function(a,r){return a+r.l;},0), odw = otros.reduce(function(a,r){return a+r.dem*r.s;},0);
    var otrosAdj = os_>0 ? ol/os_*1000/((odw/os_)/100) : null;
    var gap = otrosAdj>0 ? (lid.l1k_adj-otrosAdj)/otrosAdj*100 : 0;
    var t = tbdTier(k.length, lid.n, gap, ctx.err);
    var ah = lid.hook_audio ? tbdT(lid.hook_audio) : null;
    var vh = lid.hook_visual ? tbdT(lid.hook_visual) : null;
    return { tier:t.tier, usd:0, delta:gap/100, conf: Math.min(1, k.length/3), claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('The best '+T+' piece in '+ctx.pais+' for '+ctx.marca+' is '+tbdQ(lid.nombre)+' at '+tbdNK(lid.l1k_adj)+' L/$1k adj. over '+lid.n+' days, against '+tbdNK(otrosAdj)+' for the other '+otros.length+' '+T+' pieces ('+tbdNP(gap)+'). It opens on a '+tbdQ(ha)+' audio hook with a '+tbdQ(hv)+' visual'+(k.length>1?', a pairing shared by '+k.length+' pieces here':', and it is the only piece here that opens that way')+'.',
          'A melhor peca '+T+' em '+ctx.pais+' para '+ctx.marca+' e '+tbdQ(lid.nombre)+' com '+tbdNK(lid.l1k_adj)+' L/$1k adj. em '+lid.n+' dias, contra '+tbdNK(otrosAdj)+' das outras '+otros.length+' pecas '+T+' ('+tbdNP(gap)+'). Abre com hook de audio '+tbdQ(ha)+' e visual '+tbdQ(hv)+(k.length>1?', dupla compartilhada por '+k.length+' pecas aqui':', e e a única peca aqui que abre assim')+'.',
          'La mejor pieza '+T+' en '+ctx.pais+' para '+ctx.marca+' es '+tbdQ(lid.nombre)+' con '+tbdNK(lid.l1k_adj)+' L/$1k adj. en '+lid.n+' días, contra '+tbdNK(otrosAdj)+' de las otras '+otros.length+' piezas '+T+' ('+tbdNP(gap)+'). Abre con un hook de audio '+tbdQ(ha)+' y un visual '+tbdQ(hv)+(k.length>1?', una dupla que comparten '+k.length+' piezas acá':', y es la única pieza de acá que abre así')+'.'),
        hipotesis: tbdL('The first three seconds decide whether the rest gets watched, so the opening is the part of the execution most likely to transfer to a new script. What cannot be separated here: the opening may be working because of the specific performer, not the mechanic.',
          'Os primeiros tres segundos decidem se o resto será assistido, então a abertura e a parte mais transferivel para um roteiro novo. O que não da para separar aqui: a abertura pode estar funcionando pelo interprete especifico, não pela mecánica.',
          'Los primeros tres segundos deciden si se ve el resto, así que la apertura es la parte de la ejecución que más fácil se transfiere a un guion nuevo. Lo que acá no se puede separar: la apertura puede estar funcionando por el interprete concreto y no por la mecánica.'),
        comprobacion: k.length>1
          ? tbdL('Cross-checked inside this country: the '+k.length+' pieces that open with that same pairing average '+tbdNK(tbdRollup2(k, function(){return 'k';})[0].l1k_adj)+' L/$1k adj., so the opening travels beyond the one execution.',
              'Comprovado dentro deste pais: as '+k.length+' pecas que abrem com a mesma dupla tem média de '+tbdNK(tbdRollup2(k, function(){return 'k';})[0].l1k_adj)+' L/$1k adj., então a abertura viaja alem de uma execução.',
              'Comprobado dentro de este país: las '+k.length+' piezas que abren con esa misma dupla promedian '+tbdNK(tbdRollup2(k, function(){return 'k';})[0].l1k_adj)+' L/$1k adj., así que la apertura viaja más allá de una sola ejecución.')
          : tbdL('There is no way to confirm the opening travels: only 1 piece in '+ctx.pais+' opens this way. To settle it, the next '+T+' script has to reuse the same pairing with a different cast and setting.',
              'Não ha como confirmar que a abertura viaja: apenas 1 peca em '+ctx.pais+' abre assim. Para resolver, o próximo roteiro '+T+' precisa reusar a mesma dupla com elenco e cenario diferentes.',
              'No hay con que comprobar que la apertura viaja: solo 1 pieza en '+ctx.pais+' abre así. Para resolverlo, el próximo guion '+T+' tiene que reusar la misma dupla con otro reparto y otra locacion.'),
        accion: tbdL('Open the next '+T+' script the same way'+(ah?', on the audio side: '+String(ah).replace(/\.\s*$/,''):'')+(vh?'; on screen: '+String(vh).replace(/\.\s*$/,''):'')+'. Write it for '+tbdDecisor(ctx)+', from the first line.',
          'Abra o próximo roteiro '+T+' do mesmo jeito'+(ah?', no audio: '+String(ah).replace(/\.\s*$/,''):'')+(vh?'; na tela: '+String(vh).replace(/\.\s*$/,''):'')+'. Escreva pensando em '+tbdDecisor(ctx)+', desde a primeira linha.',
          'Abre el próximo guion '+T+' de la misma forma'+(ah?', en el audio: '+String(ah).replace(/\.\s*$/,''):'')+(vh?'; en pantalla: '+String(vh).replace(/\.\s*$/,''):'')+'. Escribe pensando en '+tbdDecisor(ctx)+', desde la primera línea.'),
        exito: tbdL('The new piece should clear '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. in its first 6 days. Below that, the opening was not what was working.',
          'A peca nova deve superar '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. nos primeiros 6 dias. Abaixo disso, a abertura não era o que funcionava.',
          'La pieza nueva debería superar '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. en sus primeros 6 días. Por debajo de eso, la apertura no era lo que funcionaba.')
      })
    };
  },
  vacio: function(ctx, data, T){
    var b = tbdBriefCtx(ctx, data, T);
    return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+' ads: there are '+b.items.length+' pieces of this type and '+b.base.length+' with 3+ days on air, below the 2 needed to compare an opening against anything. Nothing to brief from openings here.',
      'Em '+ctx.pais+', '+ctx.marca+', anuncios '+T+': ha '+b.items.length+' pecas deste tipo e '+b.base.length+' com 3+ dias no ar, abaixo das 2 necessarias para comparar uma abertura. Nada a instruir a partir de aberturas aqui.',
      'En '+ctx.pais+', '+ctx.marca+', anuncios '+T+': hay '+b.items.length+' piezas de este tipo y '+b.base.length+' con 3+ días al aire, por debajo de las 2 que hacen falta para comparar una apertura contra algo. No hay nada que briefear desde aperturas acá.');
  }
});

TBD_RULES.push({ id:'B-PAIN', dest:'BRIEF', prio:30,
  run: function(ctx, data, led, T){
    var b = tbdBriefCtx(ctx, data, T);
    if(b.n < 3) return null;
    /* 7 familias reales del catalogo (EXC, PROC, MOV, OPP, MET, AI, IMP) --
       usar solo 3 dejaba fuera 22% de los creativos, incluido OPP-Work que es
       el pain point más frecuente de OE. */
    var roll = tbdRollup2(b.base, tbdPainFam).filter(function(c){ return c.nCre>=1; });
    if(roll.length < 2) return null;
    var top = roll[0], last = roll[roll.length-1];
    var gap = last.l1k_adj>0 ? (top.l1k_adj-last.l1k_adj)/last.l1k_adj*100 : 0;
    if(gap < (ctx.err||8)) return null;
    var t = tbdTier(top.nCre, top.diasMin, gap, ctx.err);
    var ejemplo = b.base.filter(function(r){ return tbdPainFam(r)===top.label; })
      .sort(function(a,b2){ return b2.l1k_adj-a.l1k_adj; })[0];
    var nombreDolor = ejemplo ? tbdPainNombre(ejemplo) : null;
    var refPieza = ejemplo ? ejemplo.nombre : null;
    var refMec = ejemplo ? ejemplo.theme_mechanism_code : null;
    return { tier:t.tier, usd:0, delta:gap/100, conf: Math.min(1, top.nCre/3), claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('Among '+T+' ads in '+ctx.pais+' for '+ctx.marca+', the '+tbdQ(top.label)+' pain family leads with '+tbdNK(top.l1k_adj)+' L/$1k adj. across '+top.nCre+' creative(s) (min '+top.diasMin+' days each), against '+tbdNK(last.l1k_adj)+' for '+tbdQ(last.label)+' — a gap of '+tbdNP(gap)+' over the '+tbdNP1(ctx.err)+' error of the adjustment here'+(nombreDolor?'. The best-performing wording of it is '+tbdQ(nombreDolor)+', in '+tbdQ(refPieza)+' via the '+tbdQ(refMec)+' mechanism':'')+'.',
          'Entre anuncios '+T+' em '+ctx.pais+' para '+ctx.marca+', a familia de dor '+tbdQ(top.label)+' lidera com '+tbdNK(top.l1k_adj)+' L/$1k adj. em '+top.nCre+' criativo(s) (min '+top.diasMin+' dias cada), contra '+tbdNK(last.l1k_adj)+' de '+tbdQ(last.label)+' — diferença de '+tbdNP(gap)+' sobre o erro de '+tbdNP1(ctx.err)+' do ajuste aqui'+(nombreDolor?'. A formulacao de melhor desempenho e '+tbdQ(nombreDolor)+', em '+tbdQ(refPieza)+' pelo mecanismo '+tbdQ(refMec):'')+'.',
          'Entre los anuncios '+T+' de '+ctx.pais+' para '+ctx.marca+', la familia de dolor '+tbdQ(top.label)+' lidera con '+tbdNK(top.l1k_adj)+' L/$1k adj. en '+top.nCre+' creativo(s) (min '+top.diasMin+' días cada uno), contra '+tbdNK(last.l1k_adj)+' de '+tbdQ(last.label)+' — una brecha de '+tbdNP(gap)+' sobre el error de '+tbdNP1(ctx.err)+' que tiene el ajuste acá'+(nombreDolor?'. La formulacion que mejor rinde es '+tbdQ(nombreDolor)+', en '+tbdQ(refPieza)+' con el mecanismo '+tbdQ(refMec):'')+'.'),
        hipotesis: ctx.esJr
          ? tbdL('For Junior the person who feels the pain and the person who pays are two different people: the child lives the difficulty, the parent lives the guilt of not solving it. A pain that works here is one the parent recognises in their child.',
              'Para Junior quem sente a dor e quem paga são duas pessoas: a criança vive a dificuldade, o pai vive a culpa de não resolver. Uma dor que funciona aqui e a que o pai reconhece no filho.',
              'Para Junior quien siente el dolor y quien paga son dos personas distintas: el niño vive la dificultad, el padre vive la culpa de no resolverla. Un dolor que funciona acá es uno que el padre reconoce en su hijo.')
          : tbdL('For the adult learner the person who feels the pain, decides and pays is the same person, so the pain has to be one they will admit to themselves — shame works only if it comes with a way out in the same spot.',
              'Para o aprendiz adulto quem sente, decide e paga e a mesma pessoa, então a dor precisa ser uma que ele admita para si — vergonha so funciona se vier com uma saida no mesmo comercial.',
              'Para el aprendiz adulto quien siente el dolor, decide y paga es la misma persona, así que el dolor tiene que ser uno que se admita a si mismo — la vergüenza solo funciona si viene con una salida en el mismo spot.'),
        comprobacion: top.nCre>=2
          ? tbdL('Checked across executions: the '+top.nCre+' pieces in this family are not one creative — the family holds up with '+tbdNL(top.l)+' leads on '+tbdUSD(top.s)+'.',
              'Comprovado entre execucoes: as '+top.nCre+' pecas desta familia não são um único criativo — a familia se sustenta com '+tbdNL(top.l)+' leads em '+tbdUSD(top.s)+'.',
              'Comprobado entre ejecuciones: las '+top.nCre+' piezas de esta familia no son un solo creativo — la familia se sostiene con '+tbdNL(top.l)+' leads sobre '+tbdUSD(top.s)+'.')
          : tbdL('It cannot be confirmed as a family: only 1 '+T+' creative in '+ctx.pais+' uses it, so what is measured is that execution and not the pain. A second piece on the same pain with a different execution would settle it.',
              'Não da para confirmar como familia: apenas 1 criativo '+T+' em '+ctx.pais+' a usa, então o que esta medido e a execução e não a dor. Uma segunda peca na mesma dor com execução diferente resolveria.',
              'No se puede confirmar como familia: solo 1 creativo '+T+' de '+ctx.pais+' la usa, así que lo medido es esa ejecución y no el dolor. Una segunda pieza sobre el mismo dolor con otra ejecución lo resolveria.'),
        accion: tbdL('Anchor the next '+T+' script on the '+tbdQ(top.label)+' pain, written for '+tbdDecisor(ctx)+'. Do not open on '+tbdQ(last.label)+' in '+ctx.pais+' unless there is a reason outside this data.',
          'Ancore o próximo roteiro '+T+' na dor '+tbdQ(top.label)+', escrito para '+tbdDecisor(ctx)+'. Não abra com '+tbdQ(last.label)+' em '+ctx.pais+' sem uma razao fora destes dados.',
          'Ancla el próximo guion '+T+' en el dolor '+tbdQ(top.label)+', escrito para '+tbdDecisor(ctx)+'. No abras con '+tbdQ(last.label)+' en '+ctx.pais+' salvo que haya una razon fuera de estos datos.'),
        exito: tbdL('Above '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. in its first 6 days keeps the pain as the default for '+ctx.pais+'.',
          'Acima de '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. nos primeiros 6 días mantem a dor como padrao para '+ctx.pais+'.',
          'Por encima de '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. en sus primeros 6 días mantiene ese dolor como default para '+ctx.pais+'.')
      })
    };
  },
  vacio: function(ctx, data, T){
    var b = tbdBriefCtx(ctx, data, T);
    var roll = b.n ? tbdRollup2(b.base, tbdPainFam) : [];
    if(roll.length<2) return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+' ads: the '+b.n+' pieces with enough days all share '+(roll.length?'the same pain family ('+roll[0].label+')':'no coded pain family')+', so there is nothing to compare.',
      'Em '+ctx.pais+', '+ctx.marca+', anuncios '+T+': as '+b.n+' pecas com dias suficientes compartilham '+(roll.length?'a mesma familia de dor ('+roll[0].label+')':'nenhuma familia codificada')+', então não ha o que comparar.',
      'En '+ctx.pais+', '+ctx.marca+', anuncios '+T+': las '+b.n+' piezas con días suficientes comparten '+(roll.length?'la misma familia de dolor ('+roll[0].label+')':'ninguna familia codificada')+', así que no hay con que comparar.');
    var gap = roll[roll.length-1].l1k_adj>0 ? (roll[0].l1k_adj-roll[roll.length-1].l1k_adj)/roll[roll.length-1].l1k_adj*100 : 0;
    return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+' ads: the best pain family ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+') beats the worst ('+roll[roll.length-1].label+', '+tbdNK(roll[roll.length-1].l1k_adj)+') by only '+tbdNP(gap)+', under the '+tbdNP1(ctx.err)+' error of the adjustment. A brief cannot be decided on that.',
      'Em '+ctx.pais+', '+ctx.marca+', anuncios '+T+': a melhor familia de dor ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+') supera a pior ('+roll[roll.length-1].label+', '+tbdNK(roll[roll.length-1].l1k_adj)+') por apenas '+tbdNP(gap)+', abaixo do erro de '+tbdNP1(ctx.err)+'. Não se decide um brief com isso.',
      'En '+ctx.pais+', '+ctx.marca+', anuncios '+T+': la mejor familia de dolor ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+') le gana a la peor ('+roll[roll.length-1].label+', '+tbdNK(roll[roll.length-1].l1k_adj)+') por apenas '+tbdNP(gap)+', por debajo del '+tbdNP1(ctx.err)+' de error del ajuste. Con eso no se decide un brief.');
  }
});

TBD_RULES.push({ id:'B-CAST', dest:'BRIEF', prio:60,
  run: function(ctx, data, led, T){
    var b = tbdBriefCtx(ctx, data, T);
    if(b.n < 3) return null;
    var roll = tbdRollup2(b.base, tbdCastBucket).filter(function(c){ return c.label; });
    if(roll.length < 2) return null;
    var top = roll[0], last = roll[roll.length-1];
    var gap = last.l1k_adj>0 ? (top.l1k_adj-last.l1k_adj)/last.l1k_adj*100 : 0;
    if(gap < Math.max(15, (ctx.err||8))) return null;
    var t = tbdTier(top.nCre, top.diasMin, gap, ctx.err);
    var ejTop = top.nombres && top.nombres.length ? top.nombres[0] : null;
    var ejLast = last.nombres && last.nombres.length ? last.nombres[0] : null;
    var etq = { CEO_VOCERO: tbdL('the founder/spokesperson on camera','o fundador/porta-voz na camera','el fundador o vocero en camara'),
      PERSONAJE_DISFRAZ: tbdL('a costumed character','um personagem fantasiado','un personaje disfrazado'),
      NINO: tbdL('a child as the lead','uma crianca como protagonista','un niño como protagonista'),
      ADULTO: tbdL('an adult as the lead','um adulto como protagonista','un adulto como protagonista'),
      ADULTO_MAS_NINO: tbdL('an adult and a child together','um adulto e uma crianca juntos','un adulto y un niño juntos'),
      SIN_PERSONA: tbdL('no person on screen','sem pessoa na tela','sin persona en pantalla') };
    return { tier:t.tier, usd:0, delta:gap/100, conf:Math.min(1, top.nCre/3), claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('Casting in '+ctx.pais+' for '+ctx.marca+' ('+T+'): '+(etq[top.label]||top.label)+' delivers '+tbdNK(top.l1k_adj)+' L/$1k adj. across '+top.nCre+' piece(s) with at least '+top.diasMin+' days each, against '+tbdNK(last.l1k_adj)+' L/$1k adj. for '+(etq[last.label]||last.label)+' — '+tbdNP(gap)+' apart on '+tbdUSD(top.s+last.s)+' of combined spend'+(ejTop?', e.g. '+tbdQ(ejTop)+' against '+tbdQ(ejLast):'')+'.',
          'Elenco em '+ctx.pais+' para '+ctx.marca+' ('+T+'): '+(etq[top.label]||top.label)+' entrega '+tbdNK(top.l1k_adj)+' L/$1k adj. em '+top.nCre+' peca(s) com ao menos '+top.diasMin+' dias cada, contra '+tbdNK(last.l1k_adj)+' L/$1k adj. de '+(etq[last.label]||last.label)+' — '+tbdNP(gap)+' de diferença em '+tbdUSD(top.s+last.s)+' de gasto somado'+(ejTop?', ex. '+tbdQ(ejTop)+' contra '+tbdQ(ejLast):'')+'.',
          'Reparto en '+ctx.pais+' para '+ctx.marca+' ('+T+'): '+(etq[top.label]||top.label)+' entrega '+tbdNK(top.l1k_adj)+' L/$1k adj. en '+top.nCre+' pieza(s) con al menos '+top.diasMin+' días cada una, contra '+tbdNK(last.l1k_adj)+' L/$1k adj. de '+(etq[last.label]||last.label)+' — '+tbdNP(gap)+' de diferencia sobre '+tbdUSD(top.s+last.s)+' de gasto sumado'+(ejTop?', por ejemplo '+tbdQ(ejTop)+' contra '+tbdQ(ejLast):'')+'.'),
        hipotesis: ctx.esJr
          ? tbdL('Who appears on screen tells the parent whether the ad is talking to them or to their child. A child alone entertains the child; an adult present gives the parent someone to identify with while deciding.',
              'Quem aparece na tela diz ao pai se o anuncio fala com ele ou com o filho. Uma crianca sozinha entretem a crianca; um adulto presente da ao pai com quem se identificar ao decidir.',
              'Quien aparece en pantalla le dice al padre si el anuncio le habla a el o a su hijo. Un niño solo entretiene al niño; un adulto presente le da al padre con quien identificarse mientras decide.')
          : tbdL('The adult learner needs to see someone at their own level of failure, not someone who already succeeded. Casting decides whether the viewer thinks "that is me" or "that is not for me".',
              'O aprendiz adulto precisa ver alguem no seu próprio nível de fracasso, não alguem que ja teve sucesso. O elenco decide se o espectador pensa "sou eu" ou "isso não e para mim".',
              'El aprendiz adulto necesita ver a alguien en su mismo nivel de fracaso, no a alguien que ya lo logro. El reparto decide si el espectador piensa "ese soy yo" o "eso no es para mi".'),
        comprobacion: top.nCre>=2
          ? tbdL('Holds across '+top.nCre+' executions with at least '+top.diasMin+' days each, so it is the casting choice and not one performer.',
              'Se sustenta em '+top.nCre+' execucoes com ao menos '+top.diasMin+' dias cada, então e a escolha de elenco e não um interprete.',
              'Se sostiene en '+top.nCre+' ejecuciones con al menos '+top.diasMin+' días cada una, así que es la decision de reparto y no un interprete puntual.')
          : tbdL('One execution only, so this is that performer and not the casting rule. A second piece with the same casting and a different performer would settle it.',
              'Apenas uma execução, então isto e aquele interprete e não a regra de elenco. Uma segunda peca com o mesmo elenco e outro interprete resolveria.',
              'Una sola ejecución, así que esto es ese interprete y no la regla de reparto. Una segunda pieza con el mismo tipo de reparto y otro interprete lo resolveria.'),
        accion: tbdL('Cast the next '+T+' piece for '+ctx.pais+' with '+(etq[top.label]||top.label)+'.',
          'Escale a próxima peca '+T+' para '+ctx.pais+' com '+(etq[top.label]||top.label)+'.',
          'Reparte la proxima pieza '+T+' de '+ctx.pais+' con '+(etq[top.label]||top.label)+'.'),
        exito: tbdL('Above '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. confirms the casting rule for this country.',
          'Acima de '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. confirma a regra de elenco para este país.',
          'Por encima de '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. confirma la regla de reparto para este país.')
      })
    };
  },
  vacio: function(ctx, data, T){
    var b = tbdBriefCtx(ctx, data, T);
    var roll = b.n ? tbdRollup2(b.base, tbdCastBucket).filter(function(c){return c.label;}) : [];
    return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+': '+roll.length+' distinct casting type(s) across '+b.n+' pieces with enough days — not enough contrast to turn casting into a brief instruction.',
      'Em '+ctx.pais+', '+ctx.marca+', '+T+': '+roll.length+' tipo(s) de elenco em '+b.n+' pecas com dias suficientes — contraste insuficiente para virar instrucao de brief.',
      'En '+ctx.pais+', '+ctx.marca+', '+T+': '+roll.length+' tipo(s) de reparto entre '+b.n+' piezas con días suficientes — contraste insuficiente para convertir el reparto en instrucción de brief.');
  }
});

TBD_RULES.push({ id:'B-PROMO', dest:'BRIEF', prio:70, soloPromo:true,
  run: function(ctx, data, led, T){
    if(T!=='PROMO') return null;
    var b = tbdBriefCtx(ctx, data, T);
    if(b.n < 2) return null;
    var roll = tbdRollup2(b.base, function(r){ return r.promo_name||null; });
    if(roll.length < 2) return null;
    var top = roll[0], last = roll[roll.length-1];
    var gap = last.l1k_adj>0 ? (top.l1k_adj-last.l1k_adj)/last.l1k_adj*100 : 0;
    if(gap < (ctx.err||8)) return null;
    var mn = tbdRollup2(b.base, function(r){ return r.promo_name||null; }).filter(function(c){ return c.mncc!=null; });
    var topM = mn.length ? mn.slice().sort(function(a,b2){ return b2.mncc-a.mncc; })[0] : null;
    var t = tbdTier(top.nCre, top.diasMin, gap, ctx.err);
    return { tier:t.tier, usd:0, delta:gap/100, conf:Math.min(1, top.nCre/3), claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('Among the promo offers run in '+ctx.pais+' for '+ctx.marca+', '+tbdQ(top.label)+' leads with '+tbdNK(top.l1k_adj)+' L/$1k adj. over '+top.nCre+' piece(s) and '+tbdUSD(top.s)+', against '+tbdNK(last.l1k_adj)+' for '+tbdQ(last.label)+' ('+tbdNP(gap)+' apart)'+(topM && topM.label!==top.label ? '. But the best margin belongs to '+tbdQ(topM.label)+' at '+tbdNP1(topM.mncc*100)+' MNCC' : (topM ? '. It also holds the best margin, '+tbdNP1(topM.mncc*100)+' MNCC' : ''))+'.',
          'Entre as ofertas promo rodadas em '+ctx.pais+' para '+ctx.marca+', '+tbdQ(top.label)+' lidera com '+tbdNK(top.l1k_adj)+' L/$1k adj. em '+top.nCre+' peca(s) e '+tbdUSD(top.s)+', contra '+tbdNK(last.l1k_adj)+' de '+tbdQ(last.label)+' ('+tbdNP(gap)+')'+(topM && topM.label!==top.label ? '. Mas a melhor margem e de '+tbdQ(topM.label)+' com '+tbdNP1(topM.mncc*100)+' de MNCC' : (topM ? '. Tambem tem a melhor margem, '+tbdNP1(topM.mncc*100)+' de MNCC' : ''))+'.',
          'Entre las ofertas promo que corrieron en '+ctx.pais+' para '+ctx.marca+', '+tbdQ(top.label)+' lidera con '+tbdNK(top.l1k_adj)+' L/$1k adj. en '+top.nCre+' pieza(s) y '+tbdUSD(top.s)+', contra '+tbdNK(last.l1k_adj)+' de '+tbdQ(last.label)+' ('+tbdNP(gap)+' de diferencia)'+(topM && topM.label!==top.label ? '. Pero el mejor margen es de '+tbdQ(topM.label)+' con '+tbdNP1(topM.mncc*100)+' de MNCC' : (topM ? '. Ademas tiene el mejor margen, '+tbdNP1(topM.mncc*100)+' de MNCC' : ''))+'.'),
        hipotesis: tbdL('A discount buys attention, but the size of the discount also sets who shows up. The cheapest lead is not always the one that enrols.',
          'Um desconto compra atencao, más o tamanho do desconto tambem define quem aparece. O lead mais barato nem sempre e o que se matrícula.',
          'Un descuento compra atención, pero el tamanio del descuento también define quien aparece. El lead más barato no siempre es el que se matrícula.'),
        comprobacion: topM && topM.label!==top.label
          ? tbdL('Cross-checked on margin, and it disagrees: the offer that brings the cheapest leads is not the one that leaves the most money. Decide this one on MNCC, not on L/$1k.',
              'Comprovado na margem, e discorda: a oferta que traz os leads mais baratos não e a que deixa mais dinheiro. Decida pela MNCC, não pelo L/$1k.',
              'Comprobado contra el margen, y no coincide: la oferta que trae los leads más baratos no es la que deja más dinero. Esta se decide por MNCC, no por L/$1k.')
          : tbdL('Cross-checked on margin and it agrees: the same offer leads on both efficiency and margin, so there is no trade-off to arbitrate here.',
              'Comprovado na margem e concorda: a mesma oferta lidera em eficiencia e margem, então não ha trade-off a arbitrar.',
              'Comprobado contra el margen y coincide: la misma oferta lidera en eficiencia y en margen, así que acá no hay trade-off que arbitrar.'),
        accion: tbdL('Write the next promo script in '+ctx.pais+' around '+tbdQ((topM && topM.label!==top.label) ? topM.label : top.label)+', with the number in digits in the first 5 seconds and an action-first CTA.',
          'Escreva o próximo roteiro promo em '+ctx.pais+' em torno de '+tbdQ((topM && topM.label!==top.label) ? topM.label : top.label)+', com o número em digitos nos primeiros 5 segundos e um CTA de acao.',
          'Escribe el próximo guion promo de '+ctx.pais+' alrededor de '+tbdQ((topM && topM.label!==top.label) ? topM.label : top.label)+', con el número en digitos en los primeros 5 segundos y un CTA de accion primero.'),
        exito: tbdL('Above '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. and MNCC not below '+tbdNP1((ctx.mnccPort26||0)*100)+'.',
          'Acima de '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. e MNCC não abaixo de '+tbdNP1((ctx.mnccPort26||0)*100)+'.',
          'Por encima de '+tbdNK(top.l1k_adj*0.9)+' L/$1k adj. y MNCC no por debajo de '+tbdNP1((ctx.mnccPort26||0)*100)+'.')
      })
    };
  },
  vacio: function(ctx, data, T){
    if(T!=='PROMO') return null;
    var b = tbdBriefCtx(ctx, data, T);
    var roll = b.n ? tbdRollup2(b.base, function(r){ return r.promo_name||null; }) : [];
    return tbdL('In '+ctx.pais+', '+ctx.marca+': '+roll.length+' distinct promo offer(s) across '+b.items.length+' promo pieces — with fewer than 2 comparable offers there is no read on which discount to write next.',
      'Em '+ctx.pais+', '+ctx.marca+': '+roll.length+' oferta(s) promo distinta(s) em '+b.items.length+' pecas promo — com menos de 2 ofertas comparaveis não ha leitura sobre qual desconto escrever.',
      'En '+ctx.pais+', '+ctx.marca+': '+roll.length+' oferta(s) promo distinta(s) entre '+b.items.length+' piezas promo — con menos de 2 ofertas comparables no hay lectura de que descuento escribir después.');
  }
});

/* ---------------- TESTS ---------------- */
TBD_RULES.push({ id:'T-CTA', dest:'TEST', prio:20,
  run: function(ctx, data, led){
    var roll = tbdRollup2(data.y26, function(r){ return r.cta_type_code||null; })
      .filter(function(c){ return c.nCre>=2 && c.diasMin>=8 && c.l>0; });
    if(roll.length < 2) return null;
    var a = roll.slice().sort(function(x,y){ return y.cvr-x.cvr; })[0];
    var b = roll.slice().sort(function(x,y){ return x.cvr-y.cvr; })[0];
    var ppGap = (a.cvr-b.cvr)*100;
    if(ppGap < 2.0) return null;
    var delta = b.cvr>0 ? (a.cvr-b.cvr)/b.cvr : 0;
    var need = tbdNLeads(delta, ctx.phi);
    var diasNec = ctx.spd>0 && ctx.l1kPort26>0 ? Math.ceil(need / Math.max(1,(ctx.spd*ctx.l1kPort26/1000))) : null;
    return { tier:'APUESTA', usd:0, delta:delta, conf:Math.min(1, Math.min(a.l,b.l)/need), claims:{dims:['cta_type_code'],piezas:[]},
      texto: tbdCard({
        verbo: tbdL('test','teste','proba'),
        hallazgo: tbdL('In '+ctx.pais+' for '+ctx.marca+', CTA '+tbdQ(a.label)+' converts leads to enrolments at '+tbdNP1(a.cvr*100)+' across '+a.nCre+' creatives, against '+tbdNP1(b.cvr*100)+' for '+tbdQ(b.label)+' over '+b.nCre+' — '+tbdPP(ppGap)+' apart on '+tbdNL(a.l+b.l)+' combined leads.',
          'Em '+ctx.pais+' para '+ctx.marca+', o CTA '+tbdQ(a.label)+' converte leads em matrículas a '+tbdNP1(a.cvr*100)+' em '+a.nCre+' criativos, contra '+tbdNP1(b.cvr*100)+' de '+tbdQ(b.label)+' em '+b.nCre+' — '+tbdPP(ppGap)+' de diferença em '+tbdNL(a.l+b.l)+' leads somados.',
          'En '+ctx.pais+' para '+ctx.marca+', el CTA '+tbdQ(a.label)+' convierte leads en matrículas a '+tbdNP1(a.cvr*100)+' en '+a.nCre+' creativos, contra '+tbdNP1(b.cvr*100)+' de '+tbdQ(b.label)+' en '+b.nCre+' — '+tbdPP(ppGap)+' de diferencia sobre '+tbdNL(a.l+b.l)+' leads sumados.'),
        hipotesis: tbdL('The CTA decides how much friction sits between wanting it and asking for it, so it moves conversión far more than it moves lead volume.',
          'O CTA decide quanta friccao existe entre querer e pedir, então move a conversão muito mais que o volume de leads.',
          'El CTA decide cuánta fricción hay entre querer y pedir, así que mueve la conversión mucho más que el volumen de leads.'),
        comprobacion: tbdL('Not confirmed as causal: these CTAs did not run against each other on the same days, so the gap carries whatever else differed between those creatives. That is exactly what the test below settles.',
          'Não confirmado como causal: estes CTAs não rodaram um contra o outro nos mesmos dias, então a diferença carrega tudo o mais que difere entre esses criativos. E isso que o teste abaixo resolve.',
          'No confirmado como causal: estos CTA no corrieron uno contra otro los mismos días, así que la brecha carga con todo lo demas que diferia entre esos creativos. Eso es justo lo que resuelve el test de abajo.'),
        accion: tbdL('Produce the same script twice changing only the CTA ('+tbdQ(a.label)+' vs '+tbdQ(b.label)+') and alternate them in blocks of 3-4 days, discarding the first day of each block for carry-over. '+tbdVentana(ctx)+'. You need about '+tbdNL(need)+' leads per arm'+(diasNec?' — roughly '+diasNec+' days per arm at the '+tbdUSD(ctx.spd)+'/day this country runs':'')+'.',
          'Produza o mesmo roteiro duas vezes mudando so o CTA ('+tbdQ(a.label)+' vs '+tbdQ(b.label)+') e alterne em blocos de 3-4 dias, descartando o primeiro dia de cada bloco. '+tbdVentana(ctx)+'. Precisa de cerca de '+tbdNL(need)+' leads por braco'+(diasNec?' — algo como '+diasNec+' dias por braco ao ritmo de '+tbdUSD(ctx.spd)+'/dia deste pais':'')+'.',
          'Produce el mismo guion dos veces cambiando solo el CTA ('+tbdQ(a.label)+' vs '+tbdQ(b.label)+') y alternalos en bloques de 3-4 días, descartando el primer día de cada bloque por arrastre. '+tbdVentana(ctx)+'. Necesitas alrededor de '+tbdNL(need)+' leads por brazo'+(diasNec?' — unos '+diasNec+' días por brazo al ritmo de '+tbdUSD(ctx.spd)+'/día que lleva este país':'')+'.'),
        exito: tbdL('A gap that survives above '+tbdPP(2.0)+' with '+tbdNL(need)+' leads per arm makes '+tbdQ(a.label)+' the standard CTA for '+ctx.pais+'. Below that, CTA is not the lever here.',
          'Uma diferença que sobreviva acima de '+tbdPP(2.0)+' com '+tbdNL(need)+' leads por braco torna '+tbdQ(a.label)+' o CTA padrão de '+ctx.pais+'. Abaixo disso, CTA não e a alavanca aqui.',
          'Una brecha que sobreviva por encima de '+tbdPP(2.0)+' con '+tbdNL(need)+' leads por brazo vuelve a '+tbdQ(a.label)+' el CTA estandar de '+ctx.pais+'. Por debajo de eso, el CTA no es la palanca acá.')
      })
    };
  },
  vacio: function(ctx, data){
    var roll = tbdRollup2(data.y26, function(r){ return r.cta_type_code||null; });
    var ok = roll.filter(function(c){ return c.nCre>=2 && c.diasMin>=8; });
    return tbdL('In '+ctx.pais+', '+ctx.marca+': of '+roll.length+' CTA type(s) used, '+ok.length+' have 2+ creatives with 8+ days each. Two are needed to compare, so a CTA test cannot be read here yet.',
      'Em '+ctx.pais+', '+ctx.marca+': de '+roll.length+' tipo(s) de CTA usados, '+ok.length+' tem 2+ criativos com 8+ dias cada. São necessarios dois para comparar, então um teste de CTA ainda não e legivel aqui.',
      'En '+ctx.pais+', '+ctx.marca+': de '+roll.length+' tipo(s) de CTA usados, '+ok.length+' tienen 2+ creativos con 8+ días cada uno. Hacen falta dos para comparar, así que un test de CTA todavía no se puede leer acá.');
  }
});

TBD_RULES.push({ id:'T-REACTIVAR', dest:'TEST', prio:40,
  run: function(ctx, data, led){
    var vivos = {};
    data.y26.forEach(function(r){ vivos[r.nombre]=1; });
    var gasto25 = data.p25.s||0;
    var c = data.y25.filter(function(r){ return !vivos[r.nombre] && r.n>=5 && gasto25>0 && r.s/gasto25>=0.05; })
      .sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    if(!c) return null;
    if(ctx.l1kPort26>0 && c.l1k_adj < ctx.l1kPort26*(1+(ctx.err||8)/100)) return null;
    var lift = ctx.l1kPort26>0 ? (c.l1k_adj-ctx.l1kPort26)/ctx.l1kPort26*100 : 0;
    return { tier:'APUESTA', usd:0, delta:lift/100, conf:0.55, claims:{piezas:[c.nombre],dims:[]},
      texto: tbdCard({
        verbo: tbdL('reactivate','reative','reactiva'),
        hallazgo: tbdL(tbdQ(c.nombre)+' (campaign '+tbdQ(c.campaign_name)+', tone '+tbdQ(c.tone_category)+') ran in '+ctx.pais+' during Jan-Jul 2025 for '+c.n+' days on '+tbdUSD(c.s)+' and delivered '+tbdNK(c.l1k_adj)+' L/$1k adj. — '+tbdNP(lift)+' above the '+tbdNK(ctx.l1kPort26)+' the '+ctx.marca+' portfolio is doing here in 2026 — and it is not in the 2026 rotation at all.',
          tbdQ(c.nombre)+' (campanha '+tbdQ(c.campaign_name)+', tom '+tbdQ(c.tone_category)+') rodou em '+ctx.pais+' durante Jan-Jul 2025 por '+c.n+' dias com '+tbdUSD(c.s)+' e entregou '+tbdNK(c.l1k_adj)+' L/$1k adj. — '+tbdNP(lift)+' acima dos '+tbdNK(ctx.l1kPort26)+' que o portfolio '+ctx.marca+' faz aqui em 2026 — e não esta na rotação de 2026.',
          tbdQ(c.nombre)+' (campaña '+tbdQ(c.campaign_name)+', tono '+tbdQ(c.tone_category)+') corrió en '+ctx.pais+' durante Ene-Jul 2025 por '+c.n+' días con '+tbdUSD(c.s)+' y entrego '+tbdNK(c.l1k_adj)+' L/$1k adj. — '+tbdNP(lift)+' por encima de los '+tbdNK(ctx.l1kPort26)+' que hace el portafolio de '+ctx.marca+' acá en 2026 — y no esta en la rotación de 2026.'),
        hipotesis: tbdL('Rotations get rebuilt each year around what is new, and a piece that worked can fall off the list for calendar reasons rather than performance ones. What this report cannot tell: whether it was pulled for a legal or offer reason.',
          'As rotacoes são refeitas a cada ano em torno do que e novo, e uma peca que funcionava pode sair da lista por calendario e não por desempenho. O que este relatorio não diz: se foi retirada por questao legal ou de oferta.',
          'Las rotaciones se rearman cada año alrededor de lo nuevo, y una pieza que funcionaba puede caerse de la lista por calendario y no por desempenio. Lo que este reporte no puede decir: si se retiro por un tema legal o de oferta.'),
        comprobacion: tbdL('Checked against the seasonality it enjoyed: its 2025 number is already demand-adjusted with the same fixed factors used for 2026, so the comparison is not flattered by the months it ran in. Its spend-weighted factor was '+tbdNK(c.dem)+' against '+tbdNK(data.p26.dem)+' for the 2026 portfolio.',
          'Comprovado contra a sazonalidade que teve: seu número de 2025 já está ajustado com os mesmos fatores fixos de 2026, então a comparacao não e favorecida pelos meses em que rodou. Seu fator ponderado foi '+tbdNK(c.dem)+' contra '+tbdNK(data.p26.dem)+' do portfolio 2026.',
          'Comprobado contra la estacionalidad que le toco: su número de 2025 ya esta ajustado con los mismos factores fijos que se usan para 2026, así que la comparacion no esta favorecida por los meses en que corrió. Su factor ponderado por gasto fue '+tbdNK(c.dem)+' contra '+tbdNK(data.p26.dem)+' del portafolio 2026.'),
        accion: tbdL('Put it back on air unchanged, at '+tbdUSD(c.s/Math.max(1,c.n))+'/day (its own 2025 pace), for at least 6 days. '+tbdVentana(ctx)+'. Zero production cost — this is the cheapest thing on this page.',
          'Coloque-a no ar sem alteracoes, a '+tbdUSD(c.s/Math.max(1,c.n))+'/día (o proprio ritmo de 2025), por ao menos 6 días. '+tbdVentana(ctx)+'. Custo de producao zero — e o mais barato desta pagina.',
          'Vuelve a ponerla al aire sin cambios, a '+tbdUSD(c.s/Math.max(1,c.n))+'/día (su propio ritmo de 2025), por al menos 6 días. '+tbdVentana(ctx)+'. Costo de producción cero — es lo más barato de esta pagina.'),
        exito: tbdL('Above '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' L/$1k adj. in 6 days and it goes back into permanent rotation. Below '+tbdNK(ctx.l1kPort26)+' and it had aged out — stop there, do not extend.',
          'Acima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' L/$1k adj. em 6 dias e volta a rotação permanente. Abaixo de '+tbdNK(ctx.l1kPort26)+' envelheceu — pare ai, não estenda.',
          'Por encima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+' L/$1k adj. en 6 días y vuelve a rotación permanente. Por debajo de '+tbdNK(ctx.l1kPort26)+' ya envejecio — para ahí, no lo extiendas.')
      })
    };
  },
  vacio: function(ctx, data){
    var vivos = {}; data.y26.forEach(function(r){ vivos[r.nombre]=1; });
    var fuera = data.y25.filter(function(r){ return !vivos[r.nombre]; });
    return tbdL('In '+ctx.pais+', '+ctx.marca+': '+fuera.length+' of the '+ctx.nCre25+' creatives of 2025 are not running in 2026, but none of them combines 5+ days on air, 5% of the 2025 budget, and a number above '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+'. Nothing worth reactivating for free.',
      'Em '+ctx.pais+', '+ctx.marca+': '+fuera.length+' dos '+ctx.nCre25+' criativos de 2025 não rodam em 2026, mas nenhum combina 5+ dias no ar, 5% da verba de 2025 e número acima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+'. Nada que valha reativar de graca.',
      'En '+ctx.pais+', '+ctx.marca+': '+fuera.length+' de los '+ctx.nCre25+' creativos de 2025 no están corriendo en 2026, pero ninguno combina 5+ días al aire, 5% del presupuesto de 2025 y un número por encima de '+tbdNK(ctx.l1kPort26*(1+(ctx.err||8)/100))+'. No hay nada que valga la pena reactivar gratis.');
  }
});

TBD_RULES.push({ id:'T-FORMATO', dest:'TEST', prio:30,
  run: function(ctx, data, led){
    var roll = tbdRollup2(data.y26, function(r){ return r.type_of_production||null; });
    if(roll.length !== 1) return null;           // solo si el mercado es monoformato
    var unico = roll[0];
    if(unico.nCre < 4) return null;
    var tonoDom = tbdRollup2(data.y26, function(r){ return r.tone_category||null; }).slice().sort(function(a,b){ return b.s-a.s; })[0];
    var campDom = tbdRollup2(data.y26, function(r){ return r.campaign_name||null; }).slice().sort(function(a,b){ return b.s-a.s; })[0];
    /* referencia real: el mismo formato alternativo en OTRO pais de la misma marca */
    var otro = null;
    (TBD_TERRITORIES||[]).forEach(function(t){
      if(t===ctx.pais || otro) return;
      var d2;
      try{ d2 = tbdDataForOrgTerritory(ctx.marca, t); }catch(e){ return; }
      var r2 = tbdRollup2(d2.y26, function(r){ return r.type_of_production||null; })
        .filter(function(c){ return c.label!==unico.label && c.nCre>=2; })[0];
      if(r2) otro = { pais:t, roll:r2 };
    });
    var need = tbdNLeads(0.20, ctx.phi);
    var diasNec = ctx.spd>0 && ctx.l1kPort26>0 ? Math.ceil(need / Math.max(1,(ctx.spd*ctx.l1kPort26/1000))) : null;
    return { tier:'APUESTA', usd:0, delta:0.20, conf:0.4, claims:{dims:['type_of_production'],piezas:[]},
      texto: tbdCard({
        verbo: tbdL('test','teste','proba'),
        hallazgo: tbdL('All '+unico.nCre+' creatives that ran in '+ctx.pais+' for '+ctx.marca+' this period are '+tbdQ(unico.label)+', on '+tbdUSD(unico.s)+((tonoDom&&campDom)?', mostly in '+tbdQ(tonoDom.label)+' tone under campaign '+tbdQ(campDom.label):'')+'. There is no second production method in this country, so the report literally cannot say whether the alternative is better or worse here.',
          'Todos os '+unico.nCre+' criativos que rodaram em '+ctx.pais+' para '+ctx.marca+' neste periodo são '+tbdQ(unico.label)+', com '+tbdUSD(unico.s)+((tonoDom&&campDom)?', na maioria em tom '+tbdQ(tonoDom.label)+' sob a campanha '+tbdQ(campDom.label):'')+'. Não ha um segundo método de produção neste pais, então o relatorio literalmente não pode dizer se a alternativa e melhor ou pior aqui.',
          'Los '+unico.nCre+' creativos que corrieron en '+ctx.pais+' para '+ctx.marca+' este período son todos '+tbdQ(unico.label)+', sobre '+tbdUSD(unico.s)+((tonoDom&&campDom)?', en su mayoria en tono '+tbdQ(tonoDom.label)+' bajo la campaña '+tbdQ(campDom.label):'')+'. No hay un segundo método de producción en este país, así que el reporte literalmente no puede decir si la alternativa es mejor o peor acá.'),
        hipotesis: tbdL('A single production method is usually an operational habit, not a tested decision. The cost difference between methods is large enough that it deserves one measurement rather than an assumption.',
          'Um único método de produção costuma ser habito operacional, não decisao testada. A diferença de custo entre metodos e grande o bastante para merecer uma medicao em vez de uma suposicao.',
          'Un solo método de producción suele ser un habito operativo, no una decision probada. La diferencia de costo entre metodos es lo bastante grande como para merecer una medición en vez de un supuesto.'),
        comprobacion: otro
          ? tbdL('There is an external reference: in '+otro.pais+', same brand, '+tbdQ(otro.roll.label)+' runs '+otro.roll.nCre+' creatives at '+tbdNK(otro.roll.l1k_adj)+' L/$1k adj. That is a different country with a different adjustment error, so it is a reason to test here, not evidence for here.',
              'Ha uma referência externa: em '+otro.pais+', mesma marca, '+tbdQ(otro.roll.label)+' roda '+otro.roll.nCre+' criativos a '+tbdNK(otro.roll.l1k_adj)+' L/$1k adj. E outro pais com outro erro de ajuste, então e razao para testar aqui, não evidencia daqui.',
              'Hay una referencia externa: en '+otro.pais+', misma marca, '+tbdQ(otro.roll.label)+' corre '+otro.roll.nCre+' creativos a '+tbdNK(otro.roll.l1k_adj)+' L/$1k adj. Es otro país con otro error de ajuste, así que es razon para probar acá, no evidencia de acá.')
          : tbdL('There is no reference anywhere in this report: no country of '+ctx.marca+' runs a second production method with 2+ creatives, so this would be the first measurement of it in the whole portfolio.',
              'Não ha referência em nenhum lugar deste relatorio: nenhum pais de '+ctx.marca+' roda um segundo método com 2+ criativos, então esta seria a primeira medicao no portfolio inteiro.',
              'No hay referencia en ninguna parte de este reporte: ningun país de '+ctx.marca+' corre un segundo método de producción con 2+ creativos, así que esta seria la primera medición en todo el portafolio.'),
        accion: tbdL('Produce one piece with the alternative method, same script and same offer, and alternate it against the current rotation in blocks of 3-4 days. You need about '+tbdNL(need)+' leads per arm to read a 20% difference'+(diasNec?' — roughly '+diasNec+' days per arm at '+tbdUSD(ctx.spd)+'/day':'')+'. '+tbdVentana(ctx)+'.',
          'Produza uma peca com o método alternativo, mesmo roteiro e mesma oferta, e alterne contra a rotação atual em blocos de 3-4 dias. Precisa de cerca de '+tbdNL(need)+' leads por braco para ler 20% de diferença'+(diasNec?' — algo como '+diasNec+' dias por braco a '+tbdUSD(ctx.spd)+'/dia':'')+'. '+tbdVentana(ctx)+'.',
          'Produce una pieza con el método alternativo, mismo guion y misma oferta, y alternala contra la rotación actual en bloques de 3-4 días. Necesitas alrededor de '+tbdNL(need)+' leads por brazo para leer una diferencia de 20%'+(diasNec?' — unos '+diasNec+' días por brazo a '+tbdUSD(ctx.spd)+'/día':'')+'. '+tbdVentana(ctx)+'.'),
        exito: tbdL('If the alternative lands within '+tbdNP1(ctx.err)+' of '+tbdNK(unico.l1k_adj)+', switch on cost. If it lands below, '+tbdQ(unico.label)+' is confirmed as the method for '+ctx.pais+' and this stops being an open question.',
          'Se a alternativa ficar dentro de '+tbdNP1(ctx.err)+' de '+tbdNK(unico.l1k_adj)+', troque por custo. Se ficar abaixo, '+tbdQ(unico.label)+' fica confirmado como o método de '+ctx.pais+'.',
          'Si la alternativa queda dentro de '+tbdNP1(ctx.err)+' de '+tbdNK(unico.l1k_adj)+', cambia por costo. Si queda por debajo, '+tbdQ(unico.label)+' queda confirmado como el método de '+ctx.pais+' y esto deja de ser una pregunta abierta.')
      })
    };
  },
  vacio: function(ctx, data){
    /* nombrar los metodos concretos y su brecha: sin eso, este texto salia con
       el mismo esqueleto en 9 paises y solo cambiaban los números. */
    var roll = tbdRollup2(data.y26, function(r){ return r.type_of_production||null; });
    if(!roll.length) return tbdL('In '+ctx.pais+', '+ctx.marca+': none of the '+ctx.nCre26+' creatives of the period carries a coded production method, so the format question cannot even be posed here.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhum dos '+ctx.nCre26+' criativos do periodo tem método de produção codificado, então a questao de formato nem pode ser colocada aqui.',
      'En '+ctx.pais+', '+ctx.marca+': ninguno de los '+ctx.nCre26+' creativos del período trae método de producción codificado, así que la pregunta de formato ni siquiera se puede plantear acá.');
    if(roll.length===1) return tbdL('In '+ctx.pais+', '+ctx.marca+' runs only '+tbdQ(roll[0].label)+' ('+roll[0].nCre+' creatives, '+tbdUSD(roll[0].s)+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.) but fewer than the 4 pieces needed to make a format test worth its production cost.',
      'Em '+ctx.pais+', '+ctx.marca+' roda apenas '+tbdQ(roll[0].label)+' ('+roll[0].nCre+' criativos, '+tbdUSD(roll[0].s)+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.) mas menos que as 4 pecas necessarias para justificar o custo de um teste de formato.',
      'En '+ctx.pais+', '+ctx.marca+' corre solo '+tbdQ(roll[0].label)+' ('+roll[0].nCre+' creativos, '+tbdUSD(roll[0].s)+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.) pero con menos de las 4 piezas que hacen falta para que un test de formato pague su producción.');
    var a = roll[0], b = roll[roll.length-1];
    var gap = b.l1k_adj>0 ? (a.l1k_adj-b.l1k_adj)/b.l1k_adj*100 : 0;
    return tbdL('In '+ctx.pais+', '+ctx.marca+' already runs both '+tbdQ(a.label)+' ('+a.nCre+' pieces, '+tbdNK(a.l1k_adj)+' L/$1k adj.) and '+tbdQ(b.label)+' ('+b.nCre+' pieces, '+tbdNK(b.l1k_adj)+'), '+tbdNP(gap)+' apart on '+tbdUSD(a.s+b.s)+'. The format question is already being answered by the rotation — read it in the dimensions table, do not spend on a test.',
      'Em '+ctx.pais+', '+ctx.marca+' ja roda '+tbdQ(a.label)+' ('+a.nCre+' pecas, '+tbdNK(a.l1k_adj)+' L/$1k adj.) e '+tbdQ(b.label)+' ('+b.nCre+' pecas, '+tbdNK(b.l1k_adj)+'), '+tbdNP(gap)+' de diferença em '+tbdUSD(a.s+b.s)+'. A questao de formato já está sendo respondida pela rotação — leia na tabela de dimensoes, não gaste num teste.',
      'En '+ctx.pais+', '+ctx.marca+' ya corre tanto '+tbdQ(a.label)+' ('+a.nCre+' piezas, '+tbdNK(a.l1k_adj)+' L/$1k adj.) como '+tbdQ(b.label)+' ('+b.nCre+' piezas, '+tbdNK(b.l1k_adj)+'), con '+tbdNP(gap)+' de diferencia sobre '+tbdUSD(a.s+b.s)+'. La pregunta de formato ya la esta respondiendo la rotación — leela en la tabla de dimensiones, no gastes en un test.');
  }
});

/* ---------------- reglas adicionales ---------------- */
TBD_RULES.push({ id:'S-CONC', dest:'STOP', prio:20,
  run: function(ctx, data, led){
    if(data.y26.length < 3) return null;
    var top = data.y26.slice().sort(function(a,b){ return b.s-a.s; })[0];
    if(!top || ctx.gastoPeriodo<=0) return null;
    var share = top.s/ctx.gastoPeriodo*100;
    if(share < 35) return null;
    if(!tbdLedgerClaimPiece(led, top.nombre, 'S-CONC')) return null;
    var w = tbdWearout2(top);
    var resto = data.y26.filter(function(r){ return r!==top; });
    var rs = resto.reduce(function(a,r){return a+r.s;},0), rl = resto.reduce(function(a,r){return a+r.l;},0), rdw = resto.reduce(function(a,r){return a+r.dem*r.s;},0);
    var restoAdj = rs>0 ? rl/rs*1000/((rdw/rs)/100) : null;
    var mover = (top.s - ctx.gastoPeriodo*0.35)/7;
    var sp = tbdLedgerSpend(led, Math.max(0, mover), 'S-CONC');
    return { tier:'REGLA', usd:sp.monto, delta:share/100, conf:0.85, claims:{piezas:[top.nombre],dims:[]},
      texto: tbdCard({
        verbo: tbdL('diversify','diversifique','diversifica'),
        hallazgo: tbdL('In '+ctx.pais+', '+ctx.marca+' puts '+tbdNP(share)+' of its '+tbdUSD(ctx.gastoPeriodo)+' behind a single creative, '+tbdQ(top.nombre)+' ('+tbdUSD(top.s)+' over '+top.n+' days, '+tbdNK(top.l1k_adj)+' L/$1k adj.). The other '+(data.y26.length-1)+' creatives share the rest and average '+tbdNK(restoAdj)+'.',
          'Em '+ctx.pais+', '+ctx.marca+' coloca '+tbdNP(share)+' dos seus '+tbdUSD(ctx.gastoPeriodo)+' em um único criativo, '+tbdQ(top.nombre)+' ('+tbdUSD(top.s)+' em '+top.n+' dias, '+tbdNK(top.l1k_adj)+' L/$1k adj.). Os outros '+(data.y26.length-1)+' criativos dividem o resto e tem média de '+tbdNK(restoAdj)+'.',
          'En '+ctx.pais+', '+ctx.marca+' pone '+tbdNP(share)+' de sus '+tbdUSD(ctx.gastoPeriodo)+' detras de un solo creativo, '+tbdQ(top.nombre)+' ('+tbdUSD(top.s)+' en '+top.n+' días, '+tbdNK(top.l1k_adj)+' L/$1k adj.). Los otros '+(data.y26.length-1)+' creativos se reparten el resto y promedian '+tbdNK(restoAdj)+'.'),
        hipotesis: tbdL('Budget follows last period’s winner until nobody is testing alternatives any more, and the day that piece tires there is no bench to bring on.',
          'O orçamento segue o vencedor do periodo anterior ate ninguem mais testar alternativas, e no dia em que essa peca cansar não ha banco de reservas.',
          'El presupuesto sigue al ganador del período anterior hasta que ya nadie esta probando alternativas, y el día que esa pieza se canse no hay banca para hacer entrar.'),
        comprobacion: w.pct!=null
          ? tbdL('Checked whether the risk is already live: over '+(w.d1+w.d2)+' unique dates it moved '+tbdNP(w.pct)+' between halves, so it is '+(w.pct<=-20?'ALREADY decaying — the concentration is sitting on a piece that is losing force right now':'not decaying yet, so the risk is the concentration itself and not fatigue')+'.',
              'Verificado se o risco ja e real: em '+(w.d1+w.d2)+' datas únicas variou '+tbdNP(w.pct)+' entre metades, então '+(w.pct<=-20?'JA esta caindo — a concentracao esta apoiada numa peca que perde forca agora':'ainda não esta caindo, então o risco e a concentracao em si e não a fadiga')+'.',
              'Se comprobo si el riesgo ya esta vivo: en '+(w.d1+w.d2)+' fechas únicas se movió '+tbdNP(w.pct)+' entre mitades, así que '+(w.pct<=-20?'YA viene cayendo — la concentracion esta parada sobre una pieza que esta perdiendo fuerza ahora mismo':'todavía no se esta desgastando, así que el riesgo es la concentracion en si y no la fatiga')+'.')
          : tbdL('Fatigue cannot be checked: it has '+tbdDaysUnique(top)+' unique dates and 12 are needed. The concentration is a fact; whether it is already decaying is not measurable here yet.',
              'A fadiga não pode ser verificada: tem '+tbdDaysUnique(top)+' datas únicas e são necessarias 12. A concentracao e um fato; se já está caindo ainda não e mensuravel aqui.',
              'La fatiga no se puede comprobar: tiene '+tbdDaysUnique(top)+' fechas únicas y hacen falta 12. La concentracion es un hecho; si ya viene cayendo todavía no es medible acá.'),
        accion: tbdL('Cap it at 35% of the country budget by moving '+tbdUSD(sp.monto)+'/month to the next two pieces by adjusted performance. '+tbdVentana(ctx)+'.',
          'Limite a 35% da verba do pais movendo '+tbdUSD(sp.monto)+'/mês para as duas proximas pecas por desempenho ajustado. '+tbdVentana(ctx)+'.',
          'Limítalo al 35% del presupuesto del país moviendo '+tbdUSD(sp.monto)+'/mes a las dos piezas siguientes por desempenio ajustado. '+tbdVentana(ctx)+'.'),
        exito: tbdL('Country L/$1k adj. holds above '+tbdNK(ctx.l1kPort26*0.95)+' with no single piece above 35%. If it drops below '+tbdNK(ctx.l1kPort26*0.9)+', the concentration was earning its keep and can go back.',
          'L/$1k adj. do pais acima de '+tbdNK(ctx.l1kPort26*0.95)+' sem nenhuma peca acima de 35%. Se cair abaixo de '+tbdNK(ctx.l1kPort26*0.9)+', a concentracao valia e pode voltar.',
          'El L/$1k adj. del país se sostiene por encima de '+tbdNK(ctx.l1kPort26*0.95)+' sin ninguna pieza por encima de 35%. Si cae por debajo de '+tbdNK(ctx.l1kPort26*0.9)+', la concentracion se justificaba y puede volver.')
      })
    };
  },
  vacio: function(ctx, data){
    if(!data.y26.length) return null;
    var top = data.y26.slice().sort(function(a,b){ return b.s-a.s; })[0];
    var share = ctx.gastoPeriodo>0 ? top.s/ctx.gastoPeriodo*100 : 0;
    return tbdL('In '+ctx.pais+', '+ctx.marca+': the heaviest creative, '+tbdQ(top.nombre)+', holds '+tbdNP(share)+' of the '+tbdUSD(ctx.gastoPeriodo)+' spent, under the 35% that would make the portfolio depend on one piece. Spread across '+ctx.nCre26+' creatives, concentration is not a risk here.',
      'Em '+ctx.pais+', '+ctx.marca+': o criativo mais pesado, '+tbdQ(top.nombre)+', fica com '+tbdNP(share)+' dos '+tbdUSD(ctx.gastoPeriodo)+' gastos, abaixo dos 35% que fariam o portfolio depender de uma peca. Distribuido em '+ctx.nCre26+' criativos, a concentracao não e risco aqui.',
      'En '+ctx.pais+', '+ctx.marca+': el creativo más pesado, '+tbdQ(top.nombre)+', se lleva '+tbdNP(share)+' de los '+tbdUSD(ctx.gastoPeriodo)+' gastados, por debajo del 35% que haria depender al portafolio de una sola pieza. Repartido entre '+ctx.nCre26+' creativos, la concentracion no es un riesgo acá.');
  }
});

TBD_RULES.push({ id:'K-EXTEND', dest:'KEEP', prio:20,
  run: function(ctx, data, led){
    var cand = ctx.y26f.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    if(!cand || cand.n < 6) return null;
    var otros = data.y26.filter(function(r){ return r!==cand; });
    if(!otros.length) return null;
    var os_ = otros.reduce(function(a,r){return a+r.s;},0), ol = otros.reduce(function(a,r){return a+r.l;},0), odw = otros.reduce(function(a,r){return a+r.dem*r.s;},0);
    var otrosAdj = os_>0 ? ol/os_*1000/((odw/os_)/100) : null;
    if(!(otrosAdj>0)) return null;
    var gap = (cand.l1k_adj-otrosAdj)/otrosAdj*100;
    if(gap < Math.max(ctx.err||8, 10)) return null;
    var yaTomada = !tbdLedgerClaimPiece(led, cand.nombre, 'K-EXTEND');
    var w = tbdWearout2(cand);
    var sp = yaTomada ? { monto:0 } : tbdLedgerSpend(led, cand.s/7*0.25, 'K-EXTEND');
    var t = tbdTier(ctx.nCre26, cand.n, gap, ctx.err);
    var segundo = otros.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    return { tier:t.tier, usd:sp.monto, delta:gap/100, conf:0.7, claims:{piezas:[cand.nombre],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL(tbdQ(cand.nombre)+' (campaign '+tbdQ(cand.campaign_name)+', tone '+tbdQ(cand.tone_category)+') is the strongest piece in '+ctx.pais+' for '+ctx.marca+': '+tbdNK(cand.l1k_adj)+' L/$1k adj. over '+cand.n+' days and '+tbdNL(cand.l)+' leads, against '+tbdNK(otrosAdj)+' for the other '+otros.length+' creatives'+(segundo?' — the runner-up '+tbdQ(segundo.nombre)+' sits at '+tbdNK(segundo.l1k_adj):'')+' — '+tbdNP(gap)+' clear of the '+tbdNP1(ctx.err)+' error of the adjustment here.',
          tbdQ(cand.nombre)+' (campanha '+tbdQ(cand.campaign_name)+', tom '+tbdQ(cand.tone_category)+') e a peca mais forte em '+ctx.pais+' para '+ctx.marca+': '+tbdNK(cand.l1k_adj)+' L/$1k adj. em '+cand.n+' dias e '+tbdNL(cand.l)+' leads, contra '+tbdNK(otrosAdj)+' dos outros '+otros.length+' criativos'+(segundo?' — o vice '+tbdQ(segundo.nombre)+' esta em '+tbdNK(segundo.l1k_adj):'')+' — '+tbdNP(gap)+' acima do erro de '+tbdNP1(ctx.err)+' do ajuste aqui.',
          tbdQ(cand.nombre)+' (campaña '+tbdQ(cand.campaign_name)+', tono '+tbdQ(cand.tone_category)+') es la pieza más fuerte de '+ctx.pais+' para '+ctx.marca+': '+tbdNK(cand.l1k_adj)+' L/$1k adj. en '+cand.n+' días y '+tbdNL(cand.l)+' leads, contra '+tbdNK(otrosAdj)+' de los otros '+otros.length+' creativos'+(segundo?' — el segundo, '+tbdQ(segundo.nombre)+', queda en '+tbdNK(segundo.l1k_adj):'')+' — '+tbdNP(gap)+' por encima del error de '+tbdNP1(ctx.err)+' que tiene el ajuste acá.'),
        hipotesis: tbdL('A piece that stays ahead over enough days is usually carrying something repeatable — an opening, an offer or a cast — rather than a lucky week.',
          'Uma peca que se mantem a frente por dias suficientes costuma carregar algo repetivel — abertura, oferta ou elenco — e não uma semana de sorte.',
          'Una pieza que se mantiene adelante durante suficientes días suele estar cargando algo repetible — una apertura, una oferta o un reparto — y no una semana con suerte.'),
        comprobacion: w.pct!=null
          ? tbdL('Checked for fatigue before extending: over '+(w.d1+w.d2)+' unique dates it moved '+tbdNP(w.pct)+' between halves ('+tbdNK(w.h1.l1k_adj)+' to '+tbdNK(w.h2.l1k_adj)+'), so extending '+(w.pct<=-15?'should be capped — it is already cooling':'is safe on current evidence')+'.',
              'Verificado quanto a fadiga antes de estender: em '+(w.d1+w.d2)+' datas únicas variou '+tbdNP(w.pct)+' entre metades ('+tbdNK(w.h1.l1k_adj)+' para '+tbdNK(w.h2.l1k_adj)+'), então estender '+(w.pct<=-15?'deve ser limitado — já está esfriando':'e seguro pela evidencia atual')+'.',
              'Se revisó fatiga antes de extender: en '+(w.d1+w.d2)+' fechas únicas se movió '+tbdNP(w.pct)+' entre mitades ('+tbdNK(w.h1.l1k_adj)+' a '+tbdNK(w.h2.l1k_adj)+'), así que extenderlo '+(w.pct<=-15?'hay que acotarlo — ya viene enfriándose':'es seguro con la evidencia actual')+'.')
          : tbdL('Fatigue is not measurable yet: '+tbdDaysUnique(cand)+' unique dates against the 12 needed. Extend in one step and re-read, do not commit the whole quarter.',
              'A fadiga ainda não e mensuravel: '+tbdDaysUnique(cand)+' datas únicas contra as 12 necessarias. Estenda em uma etapa e releia, não comprometa o trimestre inteiro.',
              'La fatiga todavía no es medible: '+tbdDaysUnique(cand)+' fechas únicas contra las 12 que hacen falta. Extiende un escalon y vuelve a leer, no comprometas el trimestre entero.'),
        accion: yaTomada
          ? tbdL('Its budget was already claimed above, so here the instruction is editorial only: make the next '+ctx.pais+' script inherit its structure, and pull it the day it falls below '+tbdNK(otrosAdj)+'.',
              'Sua verba ja foi reclamada acima, então aqui a instrucao e editorial: faca o próximo roteiro de '+ctx.pais+' herdar sua estrutura e retire-a no dia em que cair abaixo de '+tbdNK(otrosAdj)+'.',
              'Su presupuesto ya lo reclamó una tarjeta de arriba, así que acá la instrucción es solo editorial: que el próximo guion de '+ctx.pais+' herede su estructura, y retírala el día que caiga por debajo de '+tbdNK(otrosAdj)+'.')
          : tbdL('Extend its flight with '+tbdUSD(sp.monto)+'/month more. '+tbdVentana(ctx)+'. Pull it the day it falls below '+tbdNK(otrosAdj)+'.',
              'Estenda o voo com mais '+tbdUSD(sp.monto)+'/mês. '+tbdVentana(ctx)+'. Retire no dia em que cair abaixo de '+tbdNK(otrosAdj)+'.',
              'Extiende su vuelo con '+tbdUSD(sp.monto)+'/mes más. '+tbdVentana(ctx)+'. Retírala el día que caiga por debajo de '+tbdNK(otrosAdj)+'.'),
        exito: tbdL('Holds above '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. through the extensión. Below that, the extensión bought saturation.',
          'Mantem-se acima de '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. durante a extensao. Abaixo disso, a extensao comprou saturacao.',
          'Se mantiene por encima de '+tbdNK(otrosAdj*(1+(ctx.err||8)/100))+' L/$1k adj. durante la extensión. Por debajo de eso, la extensión compró saturación.')
      })
    };
  },
  vacio: function(ctx, data){
    var cand = ctx.y26f.slice().sort(function(a,b){ return b.l1k_adj-a.l1k_adj; })[0];
    if(!cand) return tbdL('In '+ctx.pais+', '+ctx.marca+': none of the '+ctx.nCre26+' creatives has the 3+ days on air needed to be considered a leader worth extending.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhum dos '+ctx.nCre26+' criativos tem os 3+ dias no ar necessarios para ser líder a estender.',
      'En '+ctx.pais+', '+ctx.marca+': ninguno de los '+ctx.nCre26+' creativos tiene los 3+ días al aire que hacen falta para considerarlo un líder al que extenderle el vuelo.');
    return tbdL('In '+ctx.pais+', '+ctx.marca+': the leader '+tbdQ(cand.nombre)+' ('+tbdNK(cand.l1k_adj)+' over '+cand.n+' days) does not clear the rest of the portfolio by more than '+tbdNP(Math.max(ctx.err||8,10))+', so extending it would be buying noise at '+tbdNP1(ctx.err)+' of measurement error.',
      'Em '+ctx.pais+', '+ctx.marca+': o líder '+tbdQ(cand.nombre)+' ('+tbdNK(cand.l1k_adj)+' em '+cand.n+' dias) não supera o resto por mais de '+tbdNP(Math.max(ctx.err||8,10))+', então estende-lo seria comprar ruido com '+tbdNP1(ctx.err)+' de erro de medicao.',
      'En '+ctx.pais+', '+ctx.marca+': el líder '+tbdQ(cand.nombre)+' ('+tbdNK(cand.l1k_adj)+' en '+cand.n+' días) no le saca al resto del portafolio más de '+tbdNP(Math.max(ctx.err||8,10))+', así que extenderlo seria comprar ruido con '+tbdNP1(ctx.err)+' de error de medición.');
  }
});

TBD_RULES.push({ id:'U-SCALE', dest:'UPSIDE', prio:10,
  run: function(ctx, data, led){
    var dims = [['tone_category', function(r){return r.tone_category;}],
                ['theme_mechanism_code', function(r){return r.theme_mechanism_code;}],
                ['pain_point_code', function(r){return r.pain_point_code;}]];
    var best = null;
    dims.forEach(function(d){
      var roll = tbdRollup2(ctx.y26f, d[1]);
      if(roll.length < 2) return;
      var lider = roll[0];
      if(lider.nCre < 2) return;
      var share = ctx.gastoPeriodo>0 ? lider.s/ctx.gastoPeriodo*100 : 0;
      if(share > 20) return;                    // ya tiene peso
      var resto = roll.slice(1);
      var rs = resto.reduce(function(a,c){return a+c.s;},0), rl = resto.reduce(function(a,c){return a+c.l;},0);
      if(rs<=0) return;
      var restoAdj = rl/rs*1000/((ctx.factores.length? data.p26.dem : 100)/100);
      var lift = restoAdj>0 ? (lider.l1k_adj-restoAdj)/restoAdj*100 : 0;
      if(lift < Math.max(15, 2*(ctx.err||8))) return;
      if(!best || lift > best.lift) best = { dimKey:d[0], lider:lider, restoAdj:restoAdj, lift:lift, share:share };
    });
    if(!best) return null;
    if(!tbdLedgerClaimDim(led, best.dimKey, 'U-SCALE')) return null;
    var objetivo = ctx.gastoPeriodo*0.20 - best.lider.s;
    var sp = tbdLedgerSpend(led, Math.max(0, objetivo/7), 'U-SCALE');
    var t = tbdTier(best.lider.nCre, best.lider.diasMin, best.lift, ctx.err);
    return { tier:t.tier, usd:sp.monto, delta:best.lift/100, conf:Math.min(1,best.lider.nCre/3), claims:{piezas:[],dims:[best.dimKey]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('In '+ctx.pais+' for '+ctx.marca+', the '+tbdDimLabel(best.dimKey)+' '+tbdQ(best.lider.label)+' delivers '+tbdNK(best.lider.l1k_adj)+' L/$1k adj. across '+best.lider.nCre+' creatives (min '+best.lider.diasMin+' days each) against '+tbdNK(best.restoAdj)+' for everything else — '+tbdNP(best.lift)+' better — yet it only carries '+tbdNP(best.share)+' of the '+tbdUSD(ctx.gastoPeriodo)+' spent here.',
          'Em '+ctx.pais+' para '+ctx.marca+', o '+tbdDimLabel(best.dimKey)+' '+tbdQ(best.lider.label)+' entrega '+tbdNK(best.lider.l1k_adj)+' L/$1k adj. em '+best.lider.nCre+' criativos (min '+best.lider.diasMin+' dias cada) contra '+tbdNK(best.restoAdj)+' do resto — '+tbdNP(best.lift)+' melhor — mas carrega apenas '+tbdNP(best.share)+' dos '+tbdUSD(ctx.gastoPeriodo)+' gastos aqui.',
          'En '+ctx.pais+' para '+ctx.marca+', el '+tbdDimLabel(best.dimKey)+' '+tbdQ(best.lider.label)+' entrega '+tbdNK(best.lider.l1k_adj)+' L/$1k adj. en '+best.lider.nCre+' creativos (min '+best.lider.diasMin+' días cada uno) contra '+tbdNK(best.restoAdj)+' de todo lo demas — '+tbdNP(best.lift)+' mejor — y aun así solo carga '+tbdNP(best.share)+' de los '+tbdUSD(ctx.gastoPeriodo)+' que se gastaron acá.'),
        hipotesis: tbdL('Efficiency measured at low weight rarely survives at full weight: small budgets buy the cheapest, most responsive inventory first. The lift is real, the question is how much of it survives scale.',
          'Eficiencia medida com pouco peso raramente sobrevive no peso total: orcamentos pequenos compram primeiro o inventario mais barato e responsivo. O ganho e real, a duvida e quanto sobrevive a escala.',
          'La eficiencia medida a poco peso rara vez sobrevive a peso completo: los presupuestos chicos compran primero el inventario más barato y receptivo. El lift es real, la pregunta es cuánto sobrevive a la escala.'),
        comprobacion: (function(){
          /* la celda más PESADA de la misma dimension es el benchmark realista
             a peso; el rollup puede venir vacio, así que se comprueba antes */
          var kf = null;
          for(var i=0;i<dims.length;i++){ if(dims[i][0]===best.dimKey) kf = dims[i][1]; }
          var pesada = kf ? tbdRollup2(ctx.y26f, kf).slice().sort(function(a,b){ return b.s-a.s; })[0] : null;
          if(!pesada || pesada.label===best.lider.label)
            return tbdL('No benchmark at weight inside this dimension: the leader is also the heaviest cell, so there is no example here of what this '+tbdDimLabel(best.dimKey)+' does with a full budget. Scale it in steps and build that benchmark.',
              'Sem benchmark com peso nesta dimensao: o líder tambem e a celula mais pesada, então não ha exemplo aqui do que este '+tbdDimLabel(best.dimKey)+' faz com verba cheia. Escale por etapas e construa esse benchmark.',
              'No hay benchmark a peso dentro de esta dimension: el líder también es la celda más pesada, así que acá no hay ejemplo de que hace este '+tbdDimLabel(best.dimKey)+' con presupuesto completo. Escalalo por escalones y construi ese benchmark.');
          return tbdL('Cross-checked against the heaviest cell of the same dimension: '+tbdQ(pesada.label)+' carries '+tbdUSD(pesada.s)+' and still delivers '+tbdNK(pesada.l1k_adj)+', which is the realistic benchmark at weight — not the '+tbdNK(best.lider.l1k_adj)+' measured at '+tbdNP(best.share)+' of budget.',
            'Comprovado contra a celula mais pesada da mesma dimensao: '+tbdQ(pesada.label)+' carrega '+tbdUSD(pesada.s)+' e ainda entrega '+tbdNK(pesada.l1k_adj)+', que e o benchmark realista com peso — não os '+tbdNK(best.lider.l1k_adj)+' medidos com '+tbdNP(best.share)+' da verba.',
            'Comprobado contra la celda más pesada de la misma dimension: '+tbdQ(pesada.label)+' carga '+tbdUSD(pesada.s)+' y aun así entrega '+tbdNK(pesada.l1k_adj)+', que es el benchmark realista a peso — no los '+tbdNK(best.lider.l1k_adj)+' medidos con '+tbdNP(best.share)+' del presupuesto.');
        })(),
        accion: tbdL('Take it to 20% of the '+ctx.pais+' budget in steps, adding '+tbdUSD(sp.monto)+'/month. Compare each step against the benchmark at weight, not against its current small-budget figure.',
          'Leve a 20% da verba de '+ctx.pais+' por etapas, adicionando '+tbdUSD(sp.monto)+'/mês. Compare cada etapa contra o benchmark com peso, não contra a cifra atual.',
          'Llevalo al 20% del presupuesto de '+ctx.pais+' por escalones, agregando '+tbdUSD(sp.monto)+'/mes. Compara cada escalon contra el benchmark a peso, no contra su cifra actual de presupuesto chico.'),
        exito: tbdL('Still above '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. at double its current weight. If it falls to '+tbdNK(best.restoAdj)+', it had a scale ceiling and the budget goes back.',
          'Ainda acima de '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. com o dobro do peso atual. Se cair a '+tbdNK(best.restoAdj)+', tinha teto de escala e a verba volta.',
          'Sigue por encima de '+tbdNK(best.restoAdj*1.15)+' L/$1k adj. al doble de su peso actual. Si cae a '+tbdNK(best.restoAdj)+', tenía techo de escala y el presupuesto se devuelve.')
      })
    };
  },
  vacio: function(ctx, data){
    return tbdL('In '+ctx.pais+', '+ctx.marca+': no tone, mechanism or pain family leads by more than '+tbdNP(Math.max(15,2*(ctx.err||8)))+' while holding under 20% of the '+tbdUSD(ctx.gastoPeriodo)+' spent. Across '+ctx.y26f.length+' creatives with 3+ days, there is no under-funded winner to scale.',
      'Em '+ctx.pais+', '+ctx.marca+': nenhum tom, mecanismo ou familia de dor lidera por mais de '+tbdNP(Math.max(15,2*(ctx.err||8)))+' com menos de 20% dos '+tbdUSD(ctx.gastoPeriodo)+' gastos. Em '+ctx.y26f.length+' criativos com 3+ dias, não ha vencedor subfinanciado a escalar.',
      'En '+ctx.pais+', '+ctx.marca+': ningun tono, mecanismo ni familia de dolor lidera por más de '+tbdNP(Math.max(15,2*(ctx.err||8)))+' llevandose menos del 20% de los '+tbdUSD(ctx.gastoPeriodo)+' gastados. Entre '+ctx.y26f.length+' creativos con 3+ días, no hay ganador subfinanciado que escalar.');
  }
});

TBD_RULES.push({ id:'B-TONO', dest:'BRIEF', prio:50,
  run: function(ctx, data, led, T){
    var b = tbdBriefCtx(ctx, data, T);
    if(b.n < 3) return null;
    var roll = tbdRollup2(b.base, function(r){ return r.tone_category||null; });
    if(roll.length < 2) return null;
    var top = roll[0], last = roll[roll.length-1];
    var gap = last.l1k_adj>0 ? (top.l1k_adj-last.l1k_adj)/last.l1k_adj*100 : 0;
    if(gap < (ctx.err||8)) return null;
    var t = tbdTier(top.nCre, top.diasMin, gap, ctx.err);
    return { tier:t.tier, usd:0, delta:gap/100, conf:Math.min(1,top.nCre/3), claims:{piezas:[],dims:[]},
      texto: tbdCard({
        verbo: t.verbo,
        hallazgo: tbdL('Tone in '+ctx.pais+' for '+ctx.marca+' ('+T+' ads): '+tbdQ(top.label)+' runs at '+tbdNK(top.l1k_adj)+' L/$1k adj. over '+top.nCre+' piece(s) and '+tbdUSD(top.s)+', against '+tbdQ(last.label)+' at '+tbdNK(last.l1k_adj)+' — '+tbdNP(gap)+' apart, above the '+tbdNP1(ctx.err)+' error here.',
          'Tom em '+ctx.pais+' para '+ctx.marca+' (anuncios '+T+'): '+tbdQ(top.label)+' roda a '+tbdNK(top.l1k_adj)+' L/$1k adj. em '+top.nCre+' peca(s) e '+tbdUSD(top.s)+', contra '+tbdQ(last.label)+' com '+tbdNK(last.l1k_adj)+' — '+tbdNP(gap)+' de diferença, acima do erro de '+tbdNP1(ctx.err)+'.',
          'Tono en '+ctx.pais+' para '+ctx.marca+' (anuncios '+T+'): '+tbdQ(top.label)+' corre a '+tbdNK(top.l1k_adj)+' L/$1k adj. en '+top.nCre+' pieza(s) y '+tbdUSD(top.s)+', contra '+tbdQ(last.label)+' con '+tbdNK(last.l1k_adj)+' — '+tbdNP(gap)+' de diferencia, por encima del error de '+tbdNP1(ctx.err)+' de acá.'),
        hipotesis: ctx.esJr
          ? tbdL('A parent forgives humour about themselves but not about their child’s difficulty. Tone here is a trust decision before it is a creative one.',
              'Um pai perdoa humor sobre si mesmo, mas não sobre a dificuldade do filho. Tom aqui e decisao de confiança antes de ser criativa.',
              'Un padre perdona el humor sobre si mismo, pero no sobre la dificultad de su hijo. Aca el tono es una decision de confianza antes que creativa.')
          : tbdL('The adult learner laughs at the situation only if the ad is clearly laughing WITH them. The same joke told at them stops the sale.',
              'O aprendiz adulto ri da situacao so se o anuncio estiver rindo COM ele. A mesma piada contra ele mata a venda.',
              'El aprendiz adulto se rie de la situacion solo si el anuncio se esta riendo CON el. La misma broma dirigida a el corta la venta.'),
        comprobacion: top.nCre>=2
          ? tbdL('Holds across '+top.nCre+' executions, so it is the tone and not one script.',
              'Se sustenta em '+top.nCre+' execucoes, então e o tom e não um roteiro.',
              'Se sostiene en '+top.nCre+' ejecuciones, así que es el tono y no un guion suelto.')
          : tbdL('One execution only, so what is measured is that script and not the tone. A second piece in the same tone would settle it.',
              'Apenas uma execução, então o que esta medido e aquele roteiro e não o tom. Uma segunda peca no mesmo tom resolveria.',
              'Una sola ejecución, así que lo medido es ese guion y no el tono. Una segunda pieza en el mismo tono lo resolveria.'),
        accion: tbdL('Write the next '+T+' script for '+ctx.pais+' in '+tbdQ(top.label)+', aimed at '+tbdDecisor(ctx)+'.',
          'Escreva o próximo roteiro '+T+' de '+ctx.pais+' em '+tbdQ(top.label)+', dirigido a '+tbdDecisor(ctx)+'.',
          'Escribe el próximo guion '+T+' de '+ctx.pais+' en '+tbdQ(top.label)+', dirigido a '+tbdDecisor(ctx)+'.'),
        exito: tbdL('Above '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. keeps '+tbdQ(top.label)+' as the default tone here.',
          'Acima de '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. mantem '+tbdQ(top.label)+' como tom padrao aqui.',
          'Por encima de '+tbdNK(last.l1k_adj*(1+(ctx.err||8)/100))+' L/$1k adj. mantiene '+tbdQ(top.label)+' como tono default acá.')
      })
    };
  },
  vacio: function(ctx, data, T){
    var b = tbdBriefCtx(ctx, data, T);
    var roll = b.n ? tbdRollup2(b.base, function(r){ return r.tone_category||null; }) : [];
    if(roll.length<2) return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+': all '+b.n+' pieces with enough days share one tone'+(roll.length?' ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.)':'')+', so tone cannot be compared here.',
      'Em '+ctx.pais+', '+ctx.marca+', '+T+': as '+b.n+' pecas com dias suficientes compartilham um tom'+(roll.length?' ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.)':'')+', então o tom não pode ser comparado aqui.',
      'En '+ctx.pais+', '+ctx.marca+', '+T+': las '+b.n+' piezas con días suficientes comparten un solo tono'+(roll.length?' ('+roll[0].label+', '+tbdNK(roll[0].l1k_adj)+' L/$1k adj.)':'')+', así que acá el tono no se puede comparar.');
    var gap = roll[roll.length-1].l1k_adj>0 ? (roll[0].l1k_adj-roll[roll.length-1].l1k_adj)/roll[roll.length-1].l1k_adj*100 : 0;
    return tbdL('In '+ctx.pais+', '+ctx.marca+', '+T+': '+tbdQ(roll[0].label)+' ('+tbdNK(roll[0].l1k_adj)+') and '+tbdQ(roll[roll.length-1].label)+' ('+tbdNK(roll[roll.length-1].l1k_adj)+') differ by '+tbdNP(gap)+', inside the '+tbdNP1(ctx.err)+' error. Tone is not the lever here.',
      'Em '+ctx.pais+', '+ctx.marca+', '+T+': '+tbdQ(roll[0].label)+' ('+tbdNK(roll[0].l1k_adj)+') e '+tbdQ(roll[roll.length-1].label)+' ('+tbdNK(roll[roll.length-1].l1k_adj)+') diferem '+tbdNP(gap)+', dentro do erro de '+tbdNP1(ctx.err)+'. O tom não e a alavanca aqui.',
      'En '+ctx.pais+', '+ctx.marca+', '+T+': '+tbdQ(roll[0].label)+' ('+tbdNK(roll[0].l1k_adj)+') y '+tbdQ(roll[roll.length-1].label)+' ('+tbdNK(roll[roll.length-1].l1k_adj)+') difieren '+tbdNP(gap)+', dentro del error de '+tbdNP1(ctx.err)+'. Aca el tono no es la palanca.');
  }
});

/* ---------------- motor: corre el registro y arma la salida ---------------- */
var TBD_TOPES = { KEEP:3, STOP:4, UPSIDE:3, GUIDE:3, BRIEF:4, TEST:4 };
function tbdRunRules(data){
  var ctx = tbdCtx(data);
  var led = tbdLedgerNew(ctx);
  var out = { ctx:ctx, ledger:led, keep:[], stop:[], upside:[], guide:[],
              briefG:[], briefP:[], tests:[], descartes:[],
              vacios:{keep:[],stop:[],upside:[],guide:[],briefG:[],briefP:[],tests:[]},
              recortadas:{} };
  var porDest = {};
  TBD_RULES.forEach(function(r){ (porDest[r.dest] = porDest[r.dest] || []).push(r); });
  Object.keys(porDest).forEach(function(d){ porDest[d].sort(function(a,b){ return a.prio-b.prio; }); });

  /* STOP se evalua ANTES que KEEP: reclama piezas y dinero primero, para que
     dos tarjetas no manden a mover el mismo presupuesto. */
  ['STOP','KEEP','UPSIDE','GUIDE','TEST'].forEach(function(d){
    (porDest[d]||[]).forEach(function(rule){
      var c = tbdSafeRule(rule, ctx, data, led);
      if(c){ out[ d==='STOP'?'stop': d==='KEEP'?'keep': d==='UPSIDE'?'upside': d==='GUIDE'?'guide':'tests' ].push(c); }
      else {
        var v = tbdSafeVacio(rule, ctx, data);
        if(v) out.vacios[ d==='STOP'?'stop': d==='KEEP'?'keep': d==='UPSIDE'?'upside': d==='GUIDE'?'guide':'tests' ].push(v);
      }
    });
  });
  /* BRIEF se corre dos veces, una por ad_type */
  [['GENERIC','briefG'],['PROMO','briefP']].forEach(function(pair){
    (porDest['BRIEF']||[]).forEach(function(rule){
      var c = null;
      try{ c = rule.run(ctx, data, led, pair[0]); }catch(e){ led.errores++; c = null; }
      if(c){
        c.id = rule.id; c.dest='BRIEF'; c.prio=rule.prio;
        c.usd=c.usd||0; c.delta=c.delta||0; c.conf=c.conf==null?0.5:c.conf;
        c.ev = c.usd*Math.abs(c.delta)*c.conf;
        c.claims = c.claims||{piezas:[],dims:[]};
        out[pair[1]].push(c);
      } else {
        var v = null;
        try{ v = rule.vacio ? rule.vacio(ctx, data, pair[0]) : null; }catch(e){ v = null; }
        if(v) out.vacios[pair[1]].push(v);
      }
    });
  });

  /* orden: primero prioridad (respeta la precedencia del ledger), luego valor
     esperado. Y recorte con constancia: lo que sobra se dice, no se borra en
     silencio. */
  function ordenarYRecortar(arr, tope, key){
    arr.sort(function(a,b){ return a.prio!==b.prio ? a.prio-b.prio : b.ev-a.ev; });
    if(arr.length <= tope) return arr;
    var fuera = arr.slice(tope);
    out.recortadas[key] = fuera.map(function(c){ return c.id; });
    var keep = arr.slice(0, tope);
    var ids = fuera.map(function(c){ return c.id; }).join(', ');
    var ultimo = keep[keep.length-1];
    ultimo.texto += '\n' + tbdL(
      fuera.length+' more recommendation(s) did not fit here ('+ids+'), ordered by money at stake.',
      fuera.length+' recomendacao(oes) não couberam aqui ('+ids+'), ordenadas por dinheiro em jogo.',
      fuera.length+' recomendacion(es) más quedaron fuera por espacio ('+ids+'), ordenadas por dinero en juego.');
    return keep;
  }
  out.stop   = ordenarYRecortar(out.stop,   TBD_TOPES.STOP,   'stop');
  out.keep   = ordenarYRecortar(out.keep,   TBD_TOPES.KEEP,   'keep');
  out.upside = ordenarYRecortar(out.upside, TBD_TOPES.UPSIDE, 'upside');
  out.guide  = ordenarYRecortar(out.guide,  TBD_TOPES.GUIDE,  'guide');
  out.briefG = ordenarYRecortar(out.briefG, TBD_TOPES.BRIEF,  'briefG');
  out.briefP = ordenarYRecortar(out.briefP, TBD_TOPES.BRIEF,  'briefP');
  out.tests  = ordenarYRecortar(out.tests,  TBD_TOPES.TEST,   'tests');
  return out;
}
/* Límite de detección: lo que se dice cuando un destino queda sin nada Y sin
   ninguna razon medida. Nunca "no hay nada": siempre "no es medible, y esto es
   lo que falta para que lo sea". */
function tbdLimiteDeteccion(ctx){
  return tbdL('Detection limit in '+ctx.pais+' for '+ctx.marca+': of '+ctx.nCre26+' creatives in 2026, '+ctx.nMedibles+' have the 12+ unique dates needed to split a flight in two halves, and the adjustment carries '+tbdNP1(ctx.err)+' of error. This means NOT MEASURABLE, not "nothing here".',
    'Limite de deteccao em '+ctx.pais+' para '+ctx.marca+': de '+ctx.nCre26+' criativos em 2026, '+ctx.nMedibles+' tem as 12+ datas únicas necessarias para dividir um voo em duas metades, e o ajuste carrega '+tbdNP1(ctx.err)+' de erro. Isto significa NAO MENSURAVEL, não "não ha nada".',
    'Límite de detección en '+ctx.pais+' para '+ctx.marca+': de '+ctx.nCre26+' creativos de 2026, '+ctx.nMedibles+' tienen las 12+ fechas únicas que hacen falta para partir un vuelo en dos mitades, y el ajuste carga '+tbdNP1(ctx.err)+' de error. Esto significa NO MEDIBLE, no "acá no hay nada".');
}
function tbdSalidaDe(res, cards, vacios){
  if(cards.length) return cards.map(function(c){ return c.texto; });
  if(vacios.length) return vacios.slice(0,2);
  return [tbdLimiteDeteccion(res.ctx)];
}

/* Antes esta funcion armaba los 4 bloques a mano, empujaba el .body de ~25
   detectores (tirando su hipotesis y su comprobación) y cerraba con dos
   bullets fijos de metodologia identicos en los 17 paises. Ahora solo consume
   el motor de reglas, que ya trae cada tarjeta con hallazgo, hipotesis,
   comprobación, accion y número de reversion, y con el dinero contabilizado
   una sola vez. */
function tbdDirectionCards(data){
  var res = tbdRunRules(data);
  return {
    keep:   tbdSalidaDe(res, res.keep,   res.vacios.keep),
    stop:   tbdSalidaDe(res, res.stop,   res.vacios.stop),
    upside: tbdSalidaDe(res, res.upside, res.vacios.upside),
    guide:  tbdSalidaDe(res, res.guide,  res.vacios.guide),
    _res: res
  };
}
/* tbdBriefBullets() devolvia exactamente 3 bullets en las 12 combinaciones
   marca x pais -- siempre las mismas 3 plantillas (tono / pareja de hooks /
   pain point), calculadas como la moda del tercio superior, sin un solo
   numero y sin una sola referencia a la marca ni al pais. Se reemplaza por el
   motor de reglas, que si distingue GENERIC de PROMO y al aprendiz adulto del
   padre que decide. La firma se conserva para no tocar a los llamadores. */
function tbdBriefBullets(itemsOfType, data, adType){
  if(!data || !adType) return null;   // llamada vieja: sin contexto no hay brief
  var res = data.__tbdRes || (data.__tbdRes = tbdRunRules(data));
  var cards  = adType==='PROMO' ? res.briefP : res.briefG;
  var vacios = adType==='PROMO' ? res.vacios.briefP : res.vacios.briefG;
  var out = tbdSalidaDe(res, cards, vacios);
  return out.length ? out : null;
}
function tbdDirectionHTML(data){
  var L = LANG;
  var cards = tbdDirectionCards(data);
  var briefGeneric = tbdBriefBullets(null, data, 'GENERIC');
  var briefPromo = tbdBriefBullets(null, data, 'PROMO');
  function card(title, color, items){
    return '<div class="tbd-cd" style="border-top:3px solid '+color+';"><div class="tbd-cd-h" style="color:'+color+';">'+esc(title)+'</div>'+
      items.map(function(t){ return '<div class="tbd-cd-i">'+esc(t)+'</div>'; }).join('')+'</div>';
  }
  var titles = {
    keep: L==='en'?'What to keep and scale':L==='pt'?'O que manter e escalar':'Qué mantener y escalar',
    stop: L==='en'?'What to stop or avoid':L==='pt'?'O que parar ou evitar':'Qué parar o evitar',
    upside: L==='en'?'Highest untested upside':L==='pt'?'Maior potencial não testado':'Mayor potencial sin probar',
    guide: L==='en'?'Operational brief guidelines':L==='pt'?'Diretrizes operacionais de brief':'Lineamientos operativos de brief',
    briefTitle: L==='en'?'What to tell your creative team — plain-language brief':L==='pt'?'O que dizer à sua equipe criativa — brief em linguagem simples':'Qué decirle a tu equipo creativo — brief en lenguaje simple',
    briefGeneric: L==='en'?'For Generic (non-promo) ads:':L==='pt'?'Para anúncios Generic (sem promo):':'Para anuncios Generic (sin promo):',
    briefPromo: L==='en'?'For Promo ads:':L==='pt'?'Para anúncios Promo:':'Para anuncios Promo:',
    noBrief: L==='en'?'Not enough creatives of this type yet to synthesize a reliable brief.':L==='pt'?'Ainda não há criativos suficientes deste tipo para sintetizar um brief confiável.':'Todavía no hay suficientes creativos de este tipo para sintetizar un brief confiable.',
  };
  return '<h2 class="tbd-section-title">'+esc(tbdS('title_direction'))+' — '+esc(data.territory)+'</h2>'+tbdHowToCard('direction')+
    '<div class="tbd-cd-grid">'+
    card(titles.keep,'var(--good)',cards.keep)+card(titles.stop,'var(--bad)',cards.stop)+
    card(titles.upside,'var(--oe)',cards.upside)+card(titles.guide,'var(--tbd-deep)',cards.guide)+
    '</div>'+
    '<div class="tbd-brief-box"><div class="tbd-brief-h">'+esc(titles.briefTitle)+'</div>'+
    '<div class="tbd-brief-grid">'+
    '<div><div class="tbd-brief-sub">'+esc(titles.briefGeneric)+'</div>'+(briefGeneric?briefGeneric.map(function(t){return '<div class="tbd-brief-i">'+esc(t)+'</div>';}).join(''):'<div class="tbd-brief-i" style="opacity:.6;">'+esc(titles.noBrief)+'</div>')+'</div>'+
    '<div><div class="tbd-brief-sub">'+esc(titles.briefPromo)+'</div>'+(briefPromo?briefPromo.map(function(t){return '<div class="tbd-brief-i">'+esc(t)+'</div>';}).join(''):'<div class="tbd-brief-i" style="opacity:.6;">'+esc(titles.noBrief)+'</div>')+'</div>'+
    '</div></div>';
}
function tbdInsightsHTML(data){
  var cards = tbdDeepInsights(data);
  if(!cards.length) return '<h2 class="tbd-section-title">'+esc(tbdS('title_insights'))+' — '+esc(data.territory)+'</h2>'+tbdHowToCard('insights')+'<p style="color:var(--ink-faint);">'+esc(tbdS('no_data'))+'</p>';
  return '<h2 class="tbd-section-title">'+esc(tbdS('title_insights'))+' — '+esc(data.territory)+'</h2>'+tbdHowToCard('insights')+
    '<div class="tbd-two-col">'+cards.map(function(c){
    return '<div class="card" style="margin-bottom:12px;"><div style="font-size:20px;">'+c.icon+'</div><div style="font-weight:800;font-size:13px;margin:6px 0 4px;">'+esc(c.title)+'</div><div style="font-size:12px;color:var(--ink-faint);line-height:1.5;">'+esc(c.body)+'</div></div>';
  }).join('')+'</div>';
}
function tbdTestFieldHTML(label, text){
  return '<div class="tbd-test-label">'+esc(label)+'</div><div class="tbd-test-body">'+esc(text)+'</div>';
}
function tbdTestCardHTML(t, color, title, fields){
  return '<div class="card tbd-test-card" style="border-top:3px solid '+color+';">'+
    '<div class="tbd-test-eyebrow" style="color:'+color+';">'+esc(t)+'</div>'+
    '<div class="tbd-test-title">'+esc(title)+'</div>'+
    fields.map(function(f){ return tbdTestFieldHTML(f[0], f[1]); }).join('')+
    '</div>';
}
/* tbdComputeTests() devolvia exactamente 3 testsA + 3 testsB en las 12
   combinaciones, con A3 ("Semana 100% Generic") y B3 ("Creativo cruzado")
   de texto COMPLETAMENTE fijo -- y B3, en su rama else, mandaba a encargar una
   produccion nueva precisamente cuando el detector de halo no habia encontrado
   nada. Ahora los tests salen del motor: cada uno nace de un hallazgo medido
   de este pais, calcula cuantos leads por brazo hace falta para leerlo por
   encima del error del ajuste local, y si no se puede leer se declara
   descartado con lo que le falta.
   Se mantiene la particion A/B porque la pestana y el PPT la usan: A = lo que
   se hace moviendo la rotacion actual (produccion cero), B = lo que exige
   producir algo nuevo. */
function tbdComputeTests(data){
  var res = data.__tbdRes || (data.__tbdRes = tbdRunRules(data));
  var A = [], B = [];
  var colores = ['var(--oe)','var(--oejr)','var(--tbd-deep)','var(--bad)'];
  res.tests.forEach(function(c){
    var sinProduccion = (c.id==='T-REACTIVAR' || c.id==='T-SWITCH');
    var partes = String(c.texto).split('\n');
    var get = function(pref){
      for(var i=0;i<partes.length;i++){ if(partes[i].indexOf(pref)===0) return partes[i].slice(pref.length).replace(/^\s*—\s*/,''); }
      return '';
    };
    var card = {
      t: c.id,
      color: colores[(sinProduccion?0:1)],
      title: c.id.replace(/^T-/,''),
      situation: get(tbdL('FINDING','ACHADO','HALLAZGO')),
      what: get(tbdL('ACTION','ACAO','ACCION')),
      hypothesis: get(tbdL('HYPOTHESIS','HIPOTESE','HIPOTESIS')),
      check: get(tbdL('CROSS-CHECK','COMPROVACAO','COMPROBACION')),
      why: get(tbdL('SUCCESS / REVERT','SUCESSO / REVERSAO','EXITO / REVERSION')) ||
           get(tbdL('CROSS-CHECK','COMPROVACAO','COMPROBACION'))
    };
    (sinProduccion ? A : B).push(card);
  });
  /* si un lado quedo vacio, se dice por que -- con cifras, nunca en blanco */
  if(!A.length && res.vacios.tests.length) A.push({ t:'—', color:'var(--tbd-deep)',
    title: tbdL('No zero-cost test is readable here','Nenhum teste de custo zero e legivel aqui','Ningun test de costo cero es legible aca'),
    situation: res.vacios.tests[0], what:'', hypothesis:'', check:'', why:'' });
  if(!B.length && res.vacios.tests.length) B.push({ t:'—', color:'var(--tbd-deep)',
    title: tbdL('No new production is justified here yet','Nenhuma producao nova se justifica aqui ainda','Todavia no se justifica ninguna produccion nueva aca'),
    situation: res.vacios.tests[res.vacios.tests.length-1], what:'', hypothesis:'', check:'', why:'' });
  return { testsA:A, testsB:B };
}
function tbdTestsHTML(data){
  var L = LANG;
  var LBL_SITUATION = L==='en'?'The situation':L==='pt'?'A situação':'La situación';
  var LBL_WHATDO = L==='en'?'What to do':L==='pt'?'O que fazer':'Qué hacer';
  var LBL_HYPOTHESIS = L==='en'?'Hypothesis':L==='pt'?'Hipótese':'Hipótesis';
  var LBL_WHY = L==='en'?'Why it matters':L==='pt'?'Por que importa':'Por qué importa';
  var LBL_WHATPRODUCE = L==='en'?'What to produce':L==='pt'?'O que produzir':'Qué producir';
  var computed = tbdComputeTests(data);
  var testsA = computed.testsA, testsB = computed.testsB;

  function colA(list, title, intro){
    return '<div><h3 class="tbd-tests-col-title">'+esc(title)+'</h3><div class="tbd-note">'+esc(intro)+'</div><div class="tbd-tests-grid">'+list.map(function(x){
      return tbdTestCardHTML(x.t, x.color, x.title, [[LBL_SITUATION,x.situation],[LBL_WHATDO,x.what],[LBL_HYPOTHESIS,x.hypothesis],[LBL_WHY,x.why]]);
    }).join('')+'</div></div>';
  }
  function colB(list, title, intro){
    return '<div><h3 class="tbd-tests-col-title">'+esc(title)+'</h3><div class="tbd-note tbd-note-purple">'+esc(intro)+'</div><div class="tbd-tests-grid">'+list.map(function(x){
      return tbdTestCardHTML(x.t, 'var(--tbd-deep)', x.title, [[LBL_WHATPRODUCE,x.what],[LBL_HYPOTHESIS,x.hypothesis],[LBL_WHY,x.why]]);
    }).join('')+'</div></div>';
  }
  var introA = L==='en'?'Zero production cost — reshuffle existing creatives/rotation only.':L==='pt'?'Custo de produção zero — apenas reorganiza criativos/rotação existentes.':'Costo de producción cero — solo reordena creativos/rotación ya existentes.';
  var introB = L==='en'?'Requires briefing and shooting a new creative — higher cost, tests a specific hypothesis a reshuffle can\'t.':L==='pt'?'Requer brief e produção de um criativo novo — custo maior, testa uma hipótese específica que uma reorganização não consegue.':'Requiere briefear y producir un creativo nuevo — costo mayor, prueba una hipótesis específica que un reordenamiento no puede.';
  return '<h2 class="tbd-section-title">'+esc(tbdS('title_tests'))+' — '+esc(data.territory)+'</h2>'+tbdHowToCard('tests')+
    colA(testsA,tbdS('tests_col_a'),introA)+'<div style="height:16px;"></div>'+colB(testsB,tbdS('tests_col_b'),introB);
}

/* ============================================================
   DEFINICION DE LEADS -- caja de alerta destacada.
   Verificado contra engine.js: en la construccion del dia
   (`accum.leads += dLeads` solo cuando `mktOrg === organization`) el dashboard
   suma UNICAMENTE los leads cuya MarketingOrganization coincide con la
   Organization seleccionada. El halo de la otra marca NO entra en l1k ni en
   ningun KPI ajustado: se calcula aparte y solo se muestra en la pestana de
   halo entre marcas. El gasto es `mediaSpendReal`, siempre neto de SEM-Brand.
   ============================================================ */
function tbdLeadsDefinitionBox(){
  var L = LANG, from = tbdOrgName(), other = tbdHaloTargetName();
  var t;
  if(L==='en'){
    t = {
      head:'Before you read any number: which leads are being counted',
      l1:'<b>Organization = '+from+'</b> and <b>MarketingOrganization = '+from+'</b>. Both filters are set to the same brand.',
      l2:'So every "Leads", "L/$1k" and "L/$1k adj." figure on this page counts <b>only leads attributed to '+from+' itself</b>.',
      l3:'<b>The halo is NOT included.</b> Leads of '+other+' that this brand\'s spend generated are excluded from these numbers and reported separately in the Cross-brand halo tab, so they are never double-counted.',
      l4:'<b>Spend</b> is TV media spend <b>net of SEM-Brand</b>, always \u2014 it is not a switch you can turn off here.',
    };
  } else if(L==='pt'){
    t = {
      head:'Antes de ler qualquer numero: quais leads estao sendo contados',
      l1:'<b>Organization = '+from+'</b> e <b>MarketingOrganization = '+from+'</b>. Os dois filtros estao na mesma marca.',
      l2:'Portanto todo "Leads", "L/$1k" e "L/$1k adj." desta pagina conta <b>apenas leads atribuidos a '+from+'</b>.',
      l3:'<b>O halo NAO esta incluido.</b> Os leads de '+other+' que o investimento desta marca gerou ficam fora destes numeros e sao reportados a parte na aba de Halo entre marcas, para nunca serem contados duas vezes.',
      l4:'<b>O gasto</b> e a verba de midia de TV <b>liquida de SEM-Brand</b>, sempre \u2014 nao e um interruptor que se possa desligar aqui.',
    };
  } else {
    t = {
      head:'Antes de leer cualquier numero: que leads se estan contando',
      l1:'<b>Organization = '+from+'</b> y <b>MarketingOrganization = '+from+'</b>. Los dos filtros estan puestos en la misma marca.',
      l2:'Por eso cada "Leads", "L/$1k" y "L/$1k adj." de esta pagina cuenta <b>solo los leads atribuidos a '+from+'</b> en si.',
      l3:'<b>El halo NO esta incluido.</b> Los leads de '+other+' que genero la inversion de esta marca quedan fuera de estos numeros y se reportan aparte en la pestana de Halo entre marcas, para que nunca se cuenten dos veces.',
      l4:'<b>El gasto</b> es inversion de medios de TV <b>neta de SEM-Brand</b>, siempre \u2014 no es un interruptor que se pueda apagar aqui.',
    };
  }
  return '<div class="tbd-alertbox">'+
    '<div class="tbd-alertbox-h">\u26A0 '+esc(t.head)+'</div>'+
    '<ul class="tbd-alertbox-list"><li>'+t.l1+'</li><li>'+t.l2+'</li><li>'+t.l3+'</li><li>'+t.l4+'</li></ul>'+
  '</div>';
}
function tbdAdjKpiHTML(data){
  var L = LANG;
  var s = TBD_SEASONALITY[data.territory];
  // ejemplo trabajado con los meses reales mas alto y mas bajo del territorio
  var hiM='-', loM='-', hiMult=1.2, loMult=0.9;
  if(s && s.jan_jul_2026 && s.jan_jul_2026.length){
    var months=['01','02','03','04','05','06','07'].map(mesLabel);
    var arr=s.jan_jul_2026;
    var hi=arr.indexOf(Math.max.apply(null,arr)), lo=arr.indexOf(Math.min.apply(null,arr));
    hiM=months[hi]; loM=months[lo];
    hiMult=Math.round(arr[hi])/100; loMult=Math.round(arr[lo])/100;
  }
  var rawEx = 60;
  var hiAdj = rawEx/hiMult, loAdj = rawEx/loMult;

  var head = L==='en'?'Why we adjust, in one sentence':L==='pt'?'Por que ajustamos, em uma frase':'Por que ajustamos, en una frase';
  var oneLiner = L==='en'
    ? 'Two creatives can get the same result and one of them still be much better \u2014 because the market was not equally receptive in the months each of them aired. The adjustment puts them on the same footing.'
    : L==='pt'
    ? 'Dois criativos podem dar o mesmo resultado e um deles ainda ser muito melhor \u2014 porque o mercado nao estava igualmente receptivo nos meses em que cada um foi ao ar. O ajuste os coloca em pe de igualdade.'
    : 'Dos creativos pueden dar el mismo resultado y uno de los dos ser mucho mejor \u2014 porque el mercado no estaba igual de receptivo en los meses en que salio cada uno. El ajuste los pone en igualdad de condiciones.';

  var stepsHead = L==='en'?'How the adjustment works, step by step':L==='pt'?'Como o ajuste funciona, passo a passo':'Como funciona el ajuste, paso a paso';
  var steps = L==='en'
    ? '<ol class="tbd-explain-list">'+
      '<li><b>Start with the raw number.</b> L/$1k = leads divided by spend, times 1,000. If a creative brought '+fmtNum(rawEx,0)+' leads per $1,000, its raw L/$1k is '+fmtNum(rawEx,0)+'.</li>'+
      '<li><b>Look up how good its months were.</b> Each month has a demand multiplier: above 1.00 means the market was hotter than usual, below 1.00 means colder. A creative that aired across several months gets the average of those multipliers, weighted by how much was spent each day.</li>'+
      '<li><b>Divide by that multiplier.</b> That is the whole adjustment: <b>L/$1k adj. = raw L/$1k \u00f7 multiplier</b>.</li>'+
      '<li><b>Read the direction.</b> Aired in a hot month (multiplier above 1.00) \u2192 the adjusted number goes <b>DOWN</b>, because part of the result was the market, not the ad. Aired in a cold month (below 1.00) \u2192 it goes <b>UP</b>, because the ad achieved that against the tide.</li>'+
      '</ol>'
    : L==='pt'
    ? '<ol class="tbd-explain-list">'+
      '<li><b>Comece pelo numero bruto.</b> L/$1k = leads divididos pelo gasto, vezes 1.000. Se um criativo trouxe '+fmtNum(rawEx,0)+' leads por $1.000, seu L/$1k bruto e '+fmtNum(rawEx,0)+'.</li>'+
      '<li><b>Veja quao bons foram seus meses.</b> Cada mes tem um multiplicador de demanda: acima de 1,00 significa mercado mais quente que o normal, abaixo de 1,00 mais frio. Um criativo que passou por varios meses recebe a media desses multiplicadores, ponderada pelo gasto de cada dia.</li>'+
      '<li><b>Divida por esse multiplicador.</b> Esse e todo o ajuste: <b>L/$1k adj. = L/$1k bruto \u00f7 multiplicador</b>.</li>'+
      '<li><b>Leia a direcao.</b> Foi ao ar num mes quente (multiplicador acima de 1,00) \u2192 o numero ajustado <b>DESCE</b>, porque parte do resultado foi o mercado, nao o anuncio. Num mes frio (abaixo de 1,00) \u2192 <b>SOBE</b>, porque o anuncio conseguiu aquilo remando contra a mare.</li>'+
      '</ol>'
    : '<ol class="tbd-explain-list">'+
      '<li><b>Arranca del numero crudo.</b> L/$1k = leads dividido entre el gasto, por 1.000. Si un creativo trajo '+fmtNum(rawEx,0)+' leads por cada $1.000, su L/$1k crudo es '+fmtNum(rawEx,0)+'.</li>'+
      '<li><b>Mira que tan buenos fueron sus meses.</b> Cada mes tiene un multiplicador de demanda: arriba de 1,00 significa que el mercado estaba mas caliente de lo normal, abajo de 1,00 mas frio. Un creativo que estuvo al aire varios meses recibe el promedio de esos multiplicadores, ponderado por cuanto se gasto cada dia.</li>'+
      '<li><b>Divide entre ese multiplicador.</b> Ese es todo el ajuste: <b>L/$1k adj. = L/$1k crudo \u00f7 multiplicador</b>.</li>'+
      '<li><b>Lee la direccion.</b> Salio en un mes caliente (multiplicador arriba de 1,00) \u2192 el numero ajustado <b>BAJA</b>, porque parte del resultado fue el mercado y no el anuncio. Salio en un mes frio (abajo de 1,00) \u2192 <b>SUBE</b>, porque el anuncio logro eso remando contra la corriente.</li>'+
      '</ol>';

  var exHead = L==='en'?'The same number, two different months \u2014 with real data from '+data.territory:L==='pt'?'O mesmo numero, dois meses diferentes \u2014 com dados reais de '+data.territory:'El mismo numero, dos meses distintos \u2014 con datos reales de '+data.territory;
  var example = '<table class="tbd-table" style="margin-top:8px;"><thead><tr>'+
    '<th>'+esc(L==='en'?'Aired in':L==='pt'?'Foi ao ar em':'Salio al aire en')+'</th>'+
    '<th style="text-align:right;">'+esc(L==='en'?'Multiplier':'Multiplicador')+'</th>'+
    '<th style="text-align:right;">'+esc(L==='en'?'Raw L/$1k':L==='pt'?'L/$1k bruto':'L/$1k crudo')+'</th>'+
    '<th style="text-align:right;">'+esc(L==='en'?'Adjusted':L==='pt'?'Ajustado':'Ajustado')+'</th>'+
    '<th>'+esc(L==='en'?'Reading':L==='pt'?'Leitura':'Lectura')+'</th></tr></thead><tbody>'+
    '<tr><td><b>'+esc(hiM)+'</b> '+esc(L==='en'?'(hot month)':L==='pt'?'(mes quente)':'(mes caliente)')+'</td>'+
      '<td style="text-align:right;">x'+fmtNum(hiMult,2)+'</td><td style="text-align:right;">'+fmtNum(rawEx,0)+'</td>'+
      '<td style="text-align:right;" class="tbd-adj"><b>'+fmtNum(hiAdj,0)+'</b></td>'+
      '<td>'+esc(L==='en'?'Worth less than it looks: the market helped.':L==='pt'?'Vale menos do que parece: o mercado ajudou.':'Vale menos de lo que parece: el mercado ayudo.')+'</td></tr>'+
    '<tr><td><b>'+esc(loM)+'</b> '+esc(L==='en'?'(cold month)':L==='pt'?'(mes frio)':'(mes frio)')+'</td>'+
      '<td style="text-align:right;">x'+fmtNum(loMult,2)+'</td><td style="text-align:right;">'+fmtNum(rawEx,0)+'</td>'+
      '<td style="text-align:right;" class="tbd-adj"><b>'+fmtNum(loAdj,0)+'</b></td>'+
      '<td>'+esc(L==='en'?'Worth more than it looks: it swam upstream.':L==='pt'?'Vale mais do que parece: remou contra a mare.':'Vale mas de lo que parece: remo contra la corriente.')+'</td></tr>'+
    '</tbody></table>'+
    '<p style="font-size:12px;color:var(--ink-soft);margin-top:8px;">'+
    esc(L==='en'?'Both creatives brought exactly the same '+fmtNum(rawEx,0)+' leads per $1,000. After adjusting, the one from '+loM+' is the better creative \u2014 and that is the comparison the whole report is built on.'
      :L==='pt'?'Os dois criativos trouxeram exatamente os mesmos '+fmtNum(rawEx,0)+' leads por $1.000. Depois de ajustar, o de '+loM+' e o melhor criativo \u2014 e e nessa comparacao que todo o relatorio se apoia.'
      :'Los dos creativos trajeron exactamente los mismos '+fmtNum(rawEx,0)+' leads por cada $1.000. Despues de ajustar, el de '+loM+' es el mejor creativo \u2014 y esa es la comparacion sobre la que se apoya todo el reporte.')+'</p>';

  var cplHead = L==='en'?'And the adjusted CPL?':L==='pt'?'E o CPL ajustado?':'\u00bfY el CPL ajustado?';
  var cplTxt = L==='en'?'Exactly the same logic, but the other way around, because a cost is better when it is lower: <b>CPL adj. = raw CPL \u00d7 multiplier</b>. A cheap lead bought in a hot month is not as cheap as it looks.'
    :L==='pt'?'Exatamente a mesma logica, mas ao contrario, porque um custo e melhor quanto menor: <b>CPL adj. = CPL bruto \u00d7 multiplicador</b>. Um lead barato comprado num mes quente nao e tao barato quanto parece.'
    :'Exactamente la misma logica pero al reves, porque un costo es mejor mientras mas bajo: <b>CPL adj. = CPL crudo \u00d7 multiplicador</b>. Un lead barato comprado en un mes caliente no es tan barato como parece.';

  var useHead = L==='en'?'When to use which number':L==='pt'?'Quando usar cada numero':'Cuando usar cada numero';
  var useTxt = L==='en'
    ? '<ul class="tbd-explain-list"><li><b>Use the adjusted number</b> to decide which creative is better, to detect real wear-out, and for go/no-go calls.</li>'+
      '<li><b>Use the raw number</b> to plan actual lead volume and budget for a specific window \u2014 reality does not get adjusted, you really will get fewer leads in a cold month.</li></ul>'
    : L==='pt'
    ? '<ul class="tbd-explain-list"><li><b>Use o numero ajustado</b> para decidir qual criativo e melhor, detectar desgaste real e decisoes de go/no-go.</li>'+
      '<li><b>Use o numero bruto</b> para planejar volume real de leads e orcamento de uma janela especifica \u2014 a realidade nao se ajusta: voce realmente tera menos leads num mes frio.</li></ul>'
    : '<ul class="tbd-explain-list"><li><b>Usa el numero ajustado</b> para decidir que creativo es mejor, para detectar desgaste real y para decisiones de go/no-go.</li>'+
      '<li><b>Usa el numero crudo</b> para planear volumen real de leads y presupuesto de una ventana especifica \u2014 la realidad no se ajusta: en un mes frio de verdad vas a traer menos leads.</li></ul>';

  return '<h2 class="tbd-section-title">'+esc(tbdS('title_adjkpi'))+'</h2>'+
    tbdLeadsDefinitionBox()+
    tbdHowToCard('adjkpi')+
    '<div class="tbd-explain"><div class="tbd-explain-h">'+esc(head)+'</div><p style="font-size:12.5px;line-height:1.6;color:var(--ink-soft);">'+esc(oneLiner)+'</p></div>'+
    '<div class="tbd-explain"><div class="tbd-explain-h">'+esc(stepsHead)+'</div>'+steps+'</div>'+
    '<div class="tbd-explain"><div class="tbd-explain-h">'+esc(exHead)+'</div>'+example+'</div>'+
    '<div class="tbd-explain"><div class="tbd-explain-h">'+esc(cplHead)+'</div><p style="font-size:12.5px;line-height:1.6;color:var(--ink-soft);">'+cplTxt+'</p></div>'+
    '<div class="tbd-explain"><div class="tbd-explain-h">'+esc(useHead)+'</div>'+useTxt+'</div>';
}
var TBD_METHODOLOGY_ITEMS = [
  { label:{en:'Data source',es:'Fuente de datos',pt:'Fonte de dados'},
    text:{en:'The same 4 live JSON files (OE-LATAM, OE-BR, JR-LATAM, JR-BR) + rotation + taxonomy used by the "TV Ads Performance" dashboard — the same already-validated math, nothing recalculated differently. See <code>Documentacion/03_ESTADO_ACTUAL_Y_MATEMATICA.md</code>.',
      es:'Los mismos 4 JSON en vivo (OE-LATAM, OE-BR, JR-LATAM, JR-BR) + rotación + taxonomía que usa el dashboard "TV Ads Performance" — misma matemática ya validada, sin recalcular nada distinto. Ver <code>Documentacion/03_ESTADO_ACTUAL_Y_MATEMATICA.md</code>.',
      pt:'Os mesmos 4 JSON em tempo real (OE-LATAM, OE-BR, JR-LATAM, JR-BR) + rotação + taxonomia usados pelo dashboard "TV Ads Performance" — a mesma matemática já validada, sem recalcular nada diferente. Ver <code>Documentacion/03_ESTADO_ACTUAL_Y_MATEMATICA.md</code>.'} },
  { label:{en:'Organization',es:'Organization',pt:'Organization'},
    dynamic:function(){
      var L=LANG, from=tbdOrgName();
      return L==='en'
        ? 'Currently showing <b>'+from+'</b>. The switch at the top left changes which brand\u2019s creatives, KPIs, insights and PPT you are looking at; the maths is identical for both brands, only the slice of data changes. Everything on this page \u2014 including the cross-brand halo \u2014 is written from the point of view of the brand selected here.'
        : L==='pt'
        ? 'Mostrando atualmente <b>'+from+'</b>. O alternador no topo esquerdo muda de qual marca voc\u00ea v\u00ea criativos, KPIs, insights e PPT; a matem\u00e1tica \u00e9 id\u00eantica para as duas marcas, s\u00f3 muda a fatia de dados. Tudo nesta p\u00e1gina \u2014 inclusive o halo entre marcas \u2014 est\u00e1 escrito do ponto de vista da marca selecionada aqui.'
        : 'Ahora mismo est\u00e1s viendo <b>'+from+'</b>. El interruptor de arriba a la izquierda cambia de qu\u00e9 marca ves creativos, KPIs, insights y PPT; la matem\u00e1tica es id\u00e9ntica para ambas marcas, solo cambia la porci\u00f3n de datos. Todo lo de esta p\u00e1gina \u2014 incluido el halo entre marcas \u2014 est\u00e1 escrito desde el punto de vista de la marca seleccionada aqu\u00ed.';
    } },
  { label:{en:'Period',es:'Período',pt:'Período'},
    text:{en:'Always January 1 – July 31, comparing 2025 vs 2026, filtered by region/country.', es:'Siempre Enero 1 – Julio 31, comparando 2025 vs 2026, filtrado por región/país.', pt:'Sempre 1 de janeiro – 31 de julho, comparando 2025 vs 2026, filtrado por região/país.'} },
  { label:{en:'SEM-Brand',es:'SEM-Brand',pt:'SEM-Brand'},
    text:{en:'Always excluded from spend (permanent rule, not a toggle here).', es:'Siempre excluido del gasto (regla permanente, no es un interruptor aquí).', pt:'Sempre excluído do gasto (regra permanente, não é um alternador aqui).'} },
  { label:{en:'Demand adjustment (adj.)',es:'Ajuste por demanda (adj.)',pt:'Ajuste por demanda (adj.)'},
    dynamic: function(){
      var L=LANG, terr=TBD_STATE.territory, t=TBD_SEASONALITY[terr]||{};
      var gate=t.gate||'-', skill=t.skill, err=tbdSeasonErrPct(terr);
      var gName = L==='en' ? (gate==='VERDE'?'GREEN':gate==='AMBAR'?'AMBER':gate==='ROJO'?'RED':gate) : gate;
      var greyN = (t.grey||[]).filter(Boolean).length;
      var tail_en = ' The year-over-year movement of the market is deliberately NOT divided out \u2014 it is reported separately in the Seasonality tab.';
      var tail_pt = ' O movimento ano a ano do mercado deliberadamente N\u00c3O \u00e9 dividido \u2014 \u00e9 reportado \u00e0 parte na aba de Sazonalidade.';
      var tail_es = ' El movimiento a\u00f1o contra a\u00f1o del mercado a prop\u00f3sito NO se divide \u2014 se reporta aparte en la pesta\u00f1a de Estacionalidad.';
      var gate_en = ' In '+esc(terr)+' the out-of-sample gate is <b>'+esc(gName)+'</b>'+(skill!=null?' (it beats "every month is the same" by '+fmtNum(skill,0)+'% on months the model never saw)':'')+(err!=null?', the adjustment carries \u00b1'+fmtNum(err,1)+'% of error, and '+greyN+' of the 12 months are not statistically distinguishable from a normal month':'')+'.';
      var gate_pt = ' Em '+esc(terr)+' o sem\u00e1foro fora de amostra \u00e9 <b>'+esc(gName)+'</b>'+(skill!=null?' (supera "todo m\u00eas \u00e9 igual" em '+fmtNum(skill,0)+'% em meses que o modelo nunca viu)':'')+(err!=null?', o ajuste carrega \u00b1'+fmtNum(err,1)+'% de erro, e '+greyN+' dos 12 meses n\u00e3o s\u00e3o estatisticamente distingu\u00edveis de um m\u00eas normal':'')+'.';
      var gate_es = ' En '+esc(terr)+' el sem\u00e1foro fuera de muestra es <b>'+esc(gName)+'</b>'+(skill!=null?' (le gana a "todos los meses son iguales" por '+fmtNum(skill,0)+'% en meses que el modelo nunca vio)':'')+(err!=null?', el ajuste carga \u00b1'+fmtNum(err,1)+'% de error, y '+greyN+' de los 12 meses no se distinguen estad\u00edsticamente de un mes normal':'')+'.';
      if(L==='en') return 'L/$1k adj. = raw L/$1k \u00f7 (month factor/100). <b>Model v2026:</b> the factor is no longer that month\u2019s search volume \u2014 it is the month effect estimated by a log-additive regression over 44 months of Ahrefs volume (2023-01 to 2026-08) for "open english" + "cursos de ingles", with a piecewise-linear trend so the market\u2019s own rise or fall does not leak into the month, and James-Stein shrinkage so thin months are pulled toward normal instead of inventing a spike. The 12 factors average exactly 100 and are <b>fixed</b>: the same January applies to 2025 and to 2026, so a published number stays reproducible.'+gate_en+tail_en;
      if(L==='pt') return 'L/$1k adj. = L/$1k bruto \u00f7 (fator do m\u00eas/100). <b>Modelo v2026:</b> o fator j\u00e1 n\u00e3o \u00e9 o volume de busca daquele m\u00eas \u2014 \u00e9 o efeito de m\u00eas estimado por uma regress\u00e3o log-aditiva sobre 44 meses de volume Ahrefs (2023-01 a 2026-08) para "open english" + "cursos de ingles", com tend\u00eancia linear por trechos para que a alta ou queda do pr\u00f3prio mercado n\u00e3o vaze para o m\u00eas, e encolhimento James-Stein para que meses fracos sejam puxados para o normal em vez de inventar um pico. Os 12 fatores t\u00eam m\u00e9dia exatamente 100 e s\u00e3o <b>fixos</b>: o mesmo janeiro vale para 2025 e para 2026, ent\u00e3o um n\u00famero publicado continua reproduz\u00edvel.'+gate_pt+tail_pt;
      return 'L/$1k adj. = L/$1k crudo \u00f7 (factor del mes/100). <b>Modelo v2026:</b> el factor ya no es el volumen de b\u00fasqueda de ese mes \u2014 es el efecto de mes estimado por una regresi\u00f3n log-aditiva sobre 44 meses de volumen de Ahrefs (2023-01 a 2026-08) para "open english" + "cursos de ingles", con tendencia lineal por tramos para que la subida o ca\u00edda propia del mercado no se filtre dentro del mes, y encogimiento James-Stein para que los meses con poca se\u00f1al se jalen hacia lo normal en vez de inventar un pico. Los 12 factores promedian exactamente 100 y son <b>fijos</b>: el mismo enero aplica a 2025 y a 2026, as\u00ed que un n\u00famero publicado sigue siendo reproducible.'+gate_es+tail_es;
    } },
  { label:{en:'MNCC%',es:'MNCC%',pt:'MNCC%'},
    text:{en:'(New Cash Core − TV spend) ÷ New Cash Core. Not demand-adjusted — margin is not meaningfully driven by seasonal demand. Only shown on the individual creative ranking tables (Promo/Generic), not on dimension roll-ups.',
      es:'(New Cash Core − gasto de TV) ÷ New Cash Core. No se ajusta por demanda — el margen no depende de forma relevante de la estacionalidad. Solo se muestra en las tablas de ranking de creativos individuales (Promo/Generic), no en los roll-ups por dimensión.',
      pt:'(New Cash Core − gasto de TV) ÷ New Cash Core. Não é ajustado por demanda — a margem não depende de forma relevante da sazonalidade. Só é mostrado nas tabelas de ranking de criativos individuais (Promo/Generic), não nos roll-ups por dimensão.'} },
  { label:{en:'Cross-brand halo',es:'Halo entre marcas',pt:'Halo entre marcas'},
    dynamic:function(){
      var L=LANG, from=tbdOrgName(), to=tbdHaloTargetName();
      var mo = from;
      return L==='en'
        ? 'Real '+to+' leads (taken from '+to+'\u2019s own deck file) that the source system tagged with marketing_organization="'+mo+'", prorated by the same rotation % that the '+from+' creative had that day. It works in BOTH directions and the tab always shows the halo of the brand you have selected: with '+from+' selected you are seeing what '+from+' spend generated for '+to+'. Switch the brand switch to invert it.'
        : L==='pt'
        ? 'Leads reais de '+to+' (do pr\u00f3prio arquivo de deck da '+to+') que o sistema de origem marcou com marketing_organization="'+mo+'", prorrateados pelo mesmo % de rota\u00e7\u00e3o que o criativo de '+from+' teve naquele dia. Funciona nos DOIS sentidos e a aba sempre mostra o halo da marca selecionada: com '+from+' selecionada voc\u00ea v\u00ea o que o gasto de '+from+' gerou para '+to+'. Use o alternador de marca para inverter.'
        : 'Leads reales de '+to+' (de su propio archivo de deck) que el sistema de origen etiquet\u00f3 con marketing_organization="'+mo+'", prorrateados con el mismo % de rotaci\u00f3n que tuvo el creativo de '+from+' ese d\u00eda. Funciona en LOS DOS sentidos y la pesta\u00f1a siempre muestra el halo de la marca que tengas seleccionada: con '+from+' seleccionada est\u00e1s viendo lo que la inversi\u00f3n de '+from+' le gener\u00f3 a '+to+'. Cambia el interruptor de marca para invertirlo.';
    } },
  { label:{en:'Launch Week',es:'Launch Week',pt:'Launch Week'},
    text:{en:'First 7 calendar days from each creative\'s first air date (not 5 consecutive days — TV rotation is irregular).', es:'Primeros 7 días calendario desde la primera fecha de aire de cada creativo (no 5 días consecutivos — la rotación de TV es irregular).', pt:'Primeiros 7 dias corridos desde a primeira data de exibição de cada criativo (não 5 dias consecutivos — a rotação de TV é irregular).'} },
  { label:{en:'Wear-Out',es:'Wear-Out',pt:'Wear-Out'},
    text:{en:'Each creative\'s own active days split in half by COUNT (not calendar weeks): its first half on air vs. its second half, each half adjusted by its own demand index. Drop &gt;20% in L/$1k adj. = real wear-out signal.',
      es:'Los días activos de cada creativo partidos por la mitad por CONTEO (no semanas calendario): su primera mitad al aire vs. su segunda mitad, cada mitad ajustada por su propio índice de demanda. Caída &gt;20% en L/$1k adj. = señal de desgaste real.',
      pt:'Os dias ativos de cada criativo divididos ao meio por CONTAGEM (não semanas corridas): sua primeira metade no ar vs. sua segunda metade, cada metade ajustada pelo seu próprio índice de demanda. Queda &gt;20% em L/$1k adj. = sinal real de desgaste.'} },
  { label:{en:'Ad Name vs Video Name',es:'Ad Name vs Video Name',pt:'Ad Name vs Video Name'},
    text:{en:'All creative-listing tabs group by Ad Name by default (a V2/V3 minor revision counts as the same creative) — a local toggle in each section switches to Video Name to compete every version separately. The Versions tab always shows Video Name, since that comparison is its entire purpose.',
      es:'Todas las pestañas que listan creativos agrupan por Ad Name por defecto (una revisión menor V2/V3 cuenta como el mismo creativo) — un interruptor local en cada sección cambia a Video Name para hacer competir cada versión por separado. La pestaña Versions siempre muestra Video Name, ya que esa comparación es todo su propósito.',
      pt:'Todas as abas que listam criativos agrupam por Ad Name por padrão (uma revisão menor V2/V3 conta como o mesmo criativo) — um alternador local em cada seção muda para Video Name para colocar cada versão a competir separadamente. A aba Versions sempre mostra Video Name, já que essa comparação é todo o seu propósito.'} },
  { label:{en:'Insights and Tests',es:'Insights y Tests',pt:'Insights e Tests'},
    text:{en:'Generated automatically from each territory\'s real numbers on every load — not fixed text.', es:'Generados automáticamente a partir de los números reales de cada territorio en cada carga — no son texto fijo.', pt:'Gerados automaticamente a partir dos números reais de cada território a cada carregamento — não são texto fixo.'} },
];
function tbdMethodologyHTML(){
  return '<h2 class="tbd-section-title">'+esc(tbdS('title_methodology'))+'</h2>'+tbdHowToCard('methodology')+
    '<div class="card" style="font-size:12.5px; line-height:1.7;">'+
    TBD_METHODOLOGY_ITEMS.map(function(it){ return '<p><b>'+esc(tbdT(it.label))+':</b> '+(it.dynamic ? it.dynamic() : tbdT(it.text))+'</p>'; }).join('')+
    '</div>';
}

/* ============================ descarga a PowerPoint (pptxgenjs via CDN, carga perezosa) ============================ */
function tbdEnsurePptxLib(cb){
  if(window.PptxGenJS){ cb(); return; }
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js';
  s.onload = cb;
  s.onerror = function(){ showToast('No se pudo cargar la librería de PowerPoint (revisa tu conexión a internet).'); };
  document.head.appendChild(s);
}
/* Paleta de marca para el PPT (PptxGenJS no puede leer variables CSS) --
   espejo exacto de --oe/--oejr y sus tonos oscuros de dashboard.html. */
var TBD_PPT_PALETTE = {
  'Open English': { bg:'12234F', box:'1A3566', boxLabel:'8FA6D6', accent:'2B6CE8' },
  'Open English Junior': { bg:'4A2E15', box:'6B3D1C', boxLabel:'F5C89A', accent:'E8752D' },
};
/* Colores semanticos fijos (no de marca) -- espejo del PPTX de referencia:
   verde=positivo, rojo=detener, ambar=alerta, azul=hallazgo estructural,
   navy=neutral/dato duro, naranja=halo/oportunidad cruzada. */
var TBD_PPT_SEM = { green:'1A7A50', blue:'2A78D6', amber:'C47A00', red:'B83030', navy:'1D2D44', orange:'E0632A', bodyGray:'555555', borderGray:'DDDDDD', footerGray:'AAAAAA', tintKpi:'F5F4F2', tintDim:'F7F9FF', tintZebra:'F7F7F5' };

/* ---------- modal de eleccion de marca antes de generar el PPT -- el PPT
   puede ser de una marca DISTINTA a la que se esta viendo en pantalla, por
   eso siempre pregunta en vez de asumir TBD_STATE.org. DOM propio, separado
   del modal de detalle de creativo (que reusa #modal-backdrop). ---------- */
function tbdShowPptBrandModal(cb){
  var L = LANG;
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(8,10,16,.55);z-index:600;display:flex;align-items:center;justify-content:center;';
  var card = document.createElement('div');
  card.style.cssText = 'background:var(--surface);border-radius:14px;padding:26px 28px;max-width:380px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,.35);';
  var title = L==='en'?'Generate the PowerPoint for which brand?':L==='pt'?'Gerar o PowerPoint para qual marca?':'¿Generar el PowerPoint para qué marca?';
  var sub = L==='en'?'This can be different from the brand you\'re currently viewing on screen — the deck covers every territory with data, one after another.':L==='pt'?'Pode ser diferente da marca que você está vendo agora na tela — o deck cobre todos os territórios com dados, um após o outro.':'Puede ser distinta de la marca que estás viendo ahora en pantalla — el deck cubre todos los territorios con datos, uno tras otro.';
  var cancelLabel = L==='en'?'Cancel':L==='pt'?'Cancelar':'Cancelar';
  card.innerHTML = '<div style="font-size:15px;font-weight:800;margin-bottom:6px;color:var(--ink);">'+esc(title)+'</div>'+
    '<div style="font-size:12px;color:var(--ink-faint);margin-bottom:18px;line-height:1.4;">'+esc(sub)+'</div>'+
    '<div style="display:flex;flex-direction:column;gap:10px;">'+
    '<button data-brand="Open English" style="padding:12px;border-radius:9px;border:2px solid var(--oe);background:var(--oe-soft);color:var(--oe);font-weight:800;font-size:13px;cursor:pointer;">Open English</button>'+
    '<button data-brand="Open English Junior" style="padding:12px;border-radius:9px;border:2px solid var(--oejr);background:var(--oejr-soft);color:var(--oejr);font-weight:800;font-size:13px;cursor:pointer;">Open English Junior</button>'+
    '</div>'+
    '<button data-cancel="1" style="margin-top:14px;width:100%;padding:8px;border-radius:9px;border:1px solid var(--border);background:transparent;color:var(--ink-faint);font-size:12px;cursor:pointer;">'+esc(cancelLabel)+'</button>';
  overlay.appendChild(card);
  document.body.appendChild(overlay);
  function close(){ document.body.removeChild(overlay); }
  card.addEventListener('click', function(e){
    var b = e.target.closest('button');
    if(!b) return;
    if(b.dataset.cancel){ close(); return; }
    if(b.dataset.brand){ close(); cb(b.dataset.brand); }
  });
  overlay.addEventListener('click', function(e){ if(e.target===overlay) close(); });
}
/* Mismo shape que tbdCurrentData() pero para una marca/territorio explicitos,
   independientes de TBD_STATE (el PPT no debe depender de lo que este
   seleccionado en pantalla en ese momento). */
function tbdDataForOrgTerritory(org, territory){
  var savedOrg = TBD_STATE.org, savedTerritory = TBD_STATE.territory;
  TBD_STATE.org = org; TBD_STATE.territory = territory;
  var region = tbdRegionOf(territory), pais = tbdPaisOf(territory);
  var d25 = tbdCreativesForPeriod(territory, region, '2025', pais, null);
  var d26 = tbdCreativesForPeriod(territory, region, '2026', pais, null);
  var v25 = tbdVideoRowsForPeriod(territory, region, '2025', pais, null);
  var v26 = tbdVideoRowsForPeriod(territory, region, '2026', pais, null);
  var out = { territory:territory, region:region, pais:pais, y25:d25, y26:d26, v25:v25, v26:v26, p25: tbdPortfolio(d25), p26: tbdPortfolio(d26) };
  TBD_STATE.org = savedOrg; TBD_STATE.territory = savedTerritory;
  return out;
}
function tbdPptMasthead(slide, pres, pal, title, subtitle){
  slide.addShape(pres.ShapeType.rect, { x:0,y:0,w:13.3,h:1.05, fill:{color:pal.bg}, line:{color:pal.bg} });
  slide.addText(title, { x:0.35,y:0.08,w:12.6,h:0.5, fontSize:22, bold:true, color:'FFFFFF', fontFace:'Calibri' });
  slide.addText(subtitle, { x:0.35,y:0.62,w:12.6,h:0.35, fontSize:11, italic:true, color:pal.boxLabel, fontFace:'Calibri' });
}
function tbdPptFooter(slide, footerText){
  slide.addText(footerText, { x:0.35,y:7.15,w:12.6,h:0.3, fontSize:8, color:TBD_PPT_SEM.footerGray, fontFace:'Calibri' });
}
function tbdPptDividerSlide(pres, pal, territory){
  var s = pres.addSlide();
  s.background = { color:pal.bg };
  s.addText(esc0(territory), { x:0,y:3.1,w:13.3,h:1.3, fontSize:44, bold:true, color:'FFFFFF', align:'center', fontFace:'Calibri' });
  s.addText('Jan–Jul 2025 vs Jan–Jul 2026', { x:0,y:4.35,w:13.3,h:0.5, fontSize:14, italic:true, color:pal.boxLabel, align:'center', fontFace:'Calibri' });
}
function esc0(s){ return s==null ? '' : String(s); }
/* Slide A: KPIs (5 tarjetas) + hasta 6 hallazgos reales (nunca relleno --
   si tbdDeepInsights encuentra menos de 6, se muestran los que haya). */
function tbdPptKpiSlide(pres, pal, brand, territory, data, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, territory+' — TV Creatives Performance', brand+' · Brand TV Channels · TV-only spend · demand-adjusted KPIs (★ adj.) · '+data.p26.num_creatives+' creatives (2026)');
  var kpis = [
    ['L/$1K adj.★', fmtNum(data.p25.l1k_adj,0)+' → '+fmtNum(data.p26.l1k_adj,0)],
    ['CPL adj.★', fmt$(data.p25.cpl_adj,2)+' → '+fmt$(data.p26.cpl_adj,2)],
    ['CVR', fmtPct(data.p25.cvr,1)+' → '+fmtPct(data.p26.cvr,1)],
    ['TV Spend', fmt$(data.p25.s,0)+' → '+fmt$(data.p26.s,0)],
    ['Creatives', String(data.p25.num_creatives)+' → '+String(data.p26.num_creatives)],
  ];
  kpis.forEach(function(k,i){
    var x = 0.35 + i*2.42;
    s.addShape(pres.ShapeType.rect, { x:x, y:1.18, w:2.32, h:1.10, fill:{color:TBD_PPT_SEM.tintKpi}, line:{color:TBD_PPT_SEM.borderGray, width:0.5} });
    s.addText(k[0], { x:x+0.12,y:1.26,w:2.1,h:0.28, fontSize:8.5, bold:true, color:'888888', fontFace:'Calibri' });
    s.addText(k[1], { x:x+0.12,y:1.55,w:2.1,h:0.5, fontSize:13, bold:true, color:pal.bg, fontFace:'Calibri' });
  });
  var found = tbdDeepInsights(data).slice(0,6);
  var stripe = [TBD_PPT_SEM.green,TBD_PPT_SEM.blue,TBD_PPT_SEM.amber,TBD_PPT_SEM.red,TBD_PPT_SEM.navy,TBD_PPT_SEM.orange];
  s.addText((LANG==='en'?found.length+' Key Findings':LANG==='pt'?found.length+' Principais Achados':found.length+' Hallazgos Clave'), { x:0.35,y:2.5,w:8,h:0.3, fontSize:12, bold:true, color:pal.bg, fontFace:'Calibri' });
  var cols=2, cw=6.1, ch=1.35, gx=0.25, gy=0.10;
  found.forEach(function(f,i){
    var col=i%cols, row=Math.floor(i/cols);
    var x=0.35+col*(cw+gx), y=2.95+row*(ch+gy);
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:cw,h:ch, fill:{color:'FFFFFF'}, line:{color:TBD_PPT_SEM.borderGray, width:0.5} });
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:0.06,h:ch, fill:{color:stripe[i%stripe.length]}, line:{color:stripe[i%stripe.length]} });
    s.addText((f.icon||'')+' '+esc0(f.title), { x:x+0.2,y:y+0.08,w:cw-0.35,h:0.4, fontSize:10, bold:true, color:pal.bg, fontFace:'Calibri' });
    s.addText(esc0(f.body).slice(0,240), { x:x+0.2,y:y+0.46,w:cw-0.35,h:ch-0.55, fontSize:8.5, color:TBD_PPT_SEM.bodyGray, fontFace:'Calibri', valign:'top' });
  });
  tbdPptFooter(s, footerText);
}
/* Slide B: tabla combinada 2025+2026 (con columna Year) + panel de 5
   dimensiones a la derecha -- espejo del layout del PPTX de referencia. */
function tbdPptCreativeTableSlide(pres, pal, brand, territory, data, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, 'Creative Performance — Jan–Jul 2025 & 2026 Combined', territory+' · '+brand);
  var combined = data.y25.map(function(r){ return Object.assign({year:'2025'},r); }).concat(data.y26.map(function(r){ return Object.assign({year:'2026'},r); }));
  combined.sort(function(a,b){ return b.l1k_adj-a.l1k_adj; });
  var top = combined.slice(0,12);
  var bestSet = new Set(top.slice(0,3).map(function(r){ return r.nombre+'|'+r.year; }));
  var rows = top.map(function(r){
    var isBest = bestSet.has(r.nombre+'|'+r.year);
    return [
      { text:r.nombre, options:{ fontSize:9, valign:'middle' } },
      { text:r.year, options:{ fontSize:9, align:'center' } },
      { text:r.ad_type==='PROMO'?'PRO':'GEN', options:{ fontSize:8, align:'center', bold:true, color: r.ad_type==='PROMO'?TBD_PPT_SEM.amber:TBD_PPT_SEM.green, fill:{color: r.ad_type==='PROMO'?'FFF0D8':'E0F0E8'} } },
      { text:fmtNum(r.l1k_adj,0), options:{ fontSize:9.5, align:'right', bold:isBest, color:isBest?TBD_PPT_SEM.green:pal.bg } },
      { text:fmt$(r.cpl_adj,2), options:{ fontSize:9, align:'right' } },
      { text:fmtPct(r.cvr,1), options:{ fontSize:9, align:'right' } },
    ];
  });
  var head = ['Creative','Year','Type','L/$1K adj.★','CPL adj.★','CVR'].map(function(h){ return { text:h, options:{ fontSize:8.5, bold:true, color:'FFFFFF', fill:{color:pal.bg}, align:h==='Creative'?'left':'center' } }; });
  s.addText((LANG==='en'?'green = best performer (top 3)':LANG==='pt'?'verde = melhor desempenho (top 3)':'verde = mejor desempeño (top 3)'), { x:0.35,y:1.12,w:7.4,h:0.25, fontSize:8.5, italic:true, color:'888888', fontFace:'Calibri' });
  s.addTable([head].concat(rows), { x:0.35,y:1.42,w:7.42, colW:[3.16,0.81,0.81,0.99,0.81,0.60], fontSize:9, border:{type:'solid',color:TBD_PPT_SEM.borderGray,pt:0.5}, autoPage:false, fontFace:'Calibri' });

  var pvg = tbdDimensionRollup(combined, function(r){ return r.ad_type==='PROMO'?'Promo':'Generic'; });
  var toneRoll = tbdDimensionRollup(combined, function(r){ return r.tone_category||null; });
  var hookRoll = tbdDimensionRollup(combined, function(r){ return r.hook_audio_type_code||null; });
  var verRoll = tbdDimensionRollup(data.v26, function(r){ return r.version?('V'+r.version):'V1'; });
  var prodRoll = tbdDimensionRollup(combined, function(r){ return r.type_of_production||null; });
  var panelTitle = LANG==='en'?'Key Performance Dimensions':LANG==='pt'?'Principais Dimensões de Performance':'Dimensiones Clave de Performance';
  s.addText(panelTitle, { x:8.1,y:1.12,w:5.0,h:0.3, fontSize:11, bold:true, color:pal.bg, fontFace:'Calibri' });
  var panels = [
    { t:LANG==='en'?'Promo vs Generic':LANG==='pt'?'Promo vs Generic':'Promo vs Generic', items:pvg },
    { t:LANG==='en'?'Tone':LANG==='pt'?'Tom':'Tono', items:toneRoll },
    { t:LANG==='en'?'Best Audio Hook':LANG==='pt'?'Melhor Hook de Áudio':'Mejor Hook de Audio', items:hookRoll },
    { t:LANG==='en'?'Version Performance':LANG==='pt'?'Performance de Versão':'Performance de Versión', items:verRoll },
    { t:LANG==='en'?'Production Method (AI vs Real)':LANG==='pt'?'Método de Produção (IA vs Real)':'Método de Producción (IA vs Real)', items:prodRoll },
  ];
  panels.forEach(function(p,i){
    var y = 1.5+i*1.02;
    s.addShape(pres.ShapeType.rect, { x:8.1,y:y,w:5.0,h:0.94, fill:{color:TBD_PPT_SEM.tintDim}, line:{color:'C5D0F5', width:0.5} });
    s.addText(p.t, { x:8.25,y:y+0.06,w:4.7,h:0.26, fontSize:9.5, bold:true, color:pal.bg, fontFace:'Calibri' });
    var cmp = p.items.length>=2 ? (p.items[0].label+' '+fmtNum(p.items[0].l1k_adj,0)+' · '+p.items[p.items.length-1].label+' '+fmtNum(p.items[p.items.length-1].l1k_adj,0)) : (p.items.length===1?p.items[0].label+' '+fmtNum(p.items[0].l1k_adj,0):(LANG==='en'?'Not enough data':LANG==='pt'?'Dados insuficientes':'Datos insuficientes'));
    s.addText(cmp, { x:8.25,y:y+0.32,w:4.7,h:0.3, fontSize:10, bold:true, color:TBD_PPT_SEM.blue, fontFace:'Calibri' });
    s.addText(LANG==='en'?'Adj. L/$1k by group, combined 2025–2026.':LANG==='pt'?'L/$1k adj. por grupo, 2025–2026 combinado.':'L/$1k adj. por grupo, 2025–2026 combinado.', { x:8.25,y:y+0.60,w:4.7,h:0.3, fontSize:8, color:TBD_PPT_SEM.bodyGray, fontFace:'Calibri' });
  });
  tbdPptFooter(s, footerText);
}
function tbdPptDirectionSlide(pres, pal, brand, territory, data, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, 'Creative Direction — What Works, What to Stop, What to Build Next', territory+' · '+brand);
  var cards = tbdDirectionCards(data);
  var titles = [
    { t:LANG==='en'?'Keep & Scale':LANG==='pt'?'Manter e Escalar':'Mantener y Escalar', color:TBD_PPT_SEM.green, items:cards.keep },
    { t:LANG==='en'?'Stop or Avoid':LANG==='pt'?'Parar ou Evitar':'Parar o Evitar', color:TBD_PPT_SEM.red, items:cards.stop },
    { t:LANG==='en'?'Highest Untested Upside':LANG==='pt'?'Maior Potencial Não Testado':'Mayor Potencial Sin Probar', color:TBD_PPT_SEM.blue, items:cards.upside },
    { t:LANG==='en'?'Brief for the Creative Team':LANG==='pt'?'Brief para a Equipe Criativa':'Brief para el Equipo Creativo', color:pal.bg, items:cards.guide },
  ];
  var cw=6.3, ch=3.08, gx=0.20, gy=0.10;
  titles.forEach(function(card,i){
    var col=i%2, row=Math.floor(i/2);
    var x=0.35+col*(cw+gx), y=1.2+row*(ch+gy);
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:cw,h:0.38, fill:{color:card.color}, line:{color:card.color} });
    s.addText(card.t, { x:x+0.15,y:y,w:cw-0.3,h:0.38, fontSize:11, bold:true, color:'FFFFFF', valign:'middle', fontFace:'Calibri' });
    s.addShape(pres.ShapeType.rect, { x:x,y:y+0.38,w:cw,h:ch-0.38, fill:{color:'FFFFFF'}, line:{color:TBD_PPT_SEM.borderGray, width:0.5} });
    card.items.slice(0,5).forEach(function(txt,j){
      s.addText('› '+esc0(txt).slice(0,200), { x:x+0.18,y:y+0.44+j*0.50, w:cw-0.36,h:0.48, fontSize:9.5, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
    });
  });
  tbdPptFooter(s, footerText);
}
function tbdPptTestsSlide(pres, pal, brand, territory, list, isA, footerText){
  var s = pres.addSlide();
  var title = isA ? 'Recommended Tests A — Existing Ads · Zero Production Cost' : 'Recommended Tests B — New Production Required · Non-Promo Creatives';
  tbdPptMasthead(s, pres, pal, title, territory+' · '+brand);
  var bannerColor = isA ? TBD_PPT_SEM.blue : pal.accent;
  var bannerBg = isA ? 'E8F4FD' : (brand==='Open English Junior'?'FDECDD':'EDF1FE');
  var bannerTxt = isA
    ? (LANG==='en'?'Zero production cost — reshuffle existing creatives/rotation only.':LANG==='pt'?'Custo de produção zero — apenas reorganiza criativos/rotação existentes.':'Costo de producción cero — solo reordena creativos/rotación ya existentes.')
    : (LANG==='en'?'Requires briefing and shooting a new creative.':LANG==='pt'?'Requer brief e produção de um criativo novo.':'Requiere briefear y producir un creativo nuevo.');
  s.addShape(pres.ShapeType.rect, { x:0.35,y:1.15,w:12.6,h:0.38, fill:{color:bannerBg}, line:{color:bannerColor, width:0.75} });
  s.addText(bannerTxt, { x:0.55,y:1.15,w:12.2,h:0.38, fontSize:9.5, bold:true, color:bannerColor, valign:'middle', fontFace:'Calibri' });
  var cw=4.1, gx=0.2;
  list.slice(0,3).forEach(function(x,i){
    var cx = 0.35+i*(cw+gx);
    var color = isA ? (x.color==='var(--good)'?TBD_PPT_SEM.green:(x.color==='var(--oe)'?TBD_PPT_SEM.blue:TBD_PPT_SEM.orange)) : pal.accent;
    s.addShape(pres.ShapeType.rect, { x:cx,y:1.7,w:cw,h:0.52, fill:{color:color}, line:{color:color} });
    s.addText(x.t+' · '+(isA?(x.situation?'':'')+ (LANG==='en'?'No production needed':LANG==='pt'?'Sem necessidade de produção':'Sin producción nueva') : (LANG==='en'?'New production':LANG==='pt'?'Produção nova':'Producción nueva')), { x:cx+0.12,y:1.72,w:cw-0.24,h:0.2, fontSize:8, bold:true, color:'FFFFFF', fontFace:'Calibri' });
    s.addText(esc0(x.title), { x:cx+0.12,y:1.92,w:cw-0.24,h:0.28, fontSize:10.5, bold:true, color:'FFFFFF', fontFace:'Calibri' });
    s.addShape(pres.ShapeType.rect, { x:cx,y:2.22,w:cw,h:4.7, fill:{color:'FFFFFF'}, line:{color:color, width:0.75} });
    var blocks = isA
      ? [[LANG==='en'?'THE SITUATION':LANG==='pt'?'A SITUAÇÃO':'LA SITUACIÓN', x.situation],[LANG==='en'?'WHAT TO DO':LANG==='pt'?'O QUE FAZER':'QUÉ HACER', x.what],[LANG==='en'?'HYPOTHESIS':LANG==='pt'?'HIPÓTESE':'HIPÓTESIS', x.hypothesis],[LANG==='en'?'WHY IT MATTERS':LANG==='pt'?'POR QUE IMPORTA':'POR QUÉ IMPORTA', x.why]]
      : [[LANG==='en'?'WHAT TO PRODUCE':LANG==='pt'?'O QUE PRODUZIR':'QUÉ PRODUCIR', x.what],[LANG==='en'?'HYPOTHESIS':LANG==='pt'?'HIPÓTESE':'HIPÓTESIS', x.hypothesis],[LANG==='en'?'WHY IT MATTERS':LANG==='pt'?'POR QUE IMPORTA':'POR QUÉ IMPORTA', x.why]];
    var by = 2.32;
    blocks.forEach(function(b){
      s.addText(b[0], { x:cx+0.15,y:by,w:cw-0.3,h:0.2, fontSize:8, bold:true, color:color, fontFace:'Calibri' });
      s.addText(esc0(b[1]).slice(0,260), { x:cx+0.15,y:by+0.2,w:cw-0.3,h:1.0, fontSize:8.5, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
      by += 1.18;
    });
  });
  tbdPptFooter(s, footerText);
}
/* ---------- helpers de tabla para el PPT (una sola forma de pintar tablas
   de dimension, para que todas las slides nuevas se vean igual) ---------- */
function tbdPptL(en, pt, es){ return LANG==='en'?en:(LANG==='pt'?pt:es); }
function tbdPptDimTable(s, pres, pal, x, y, w, title, rows, colLabel){
  s.addText(title, { x:x, y:y, w:w, h:0.26, fontSize:10, bold:true, color:pal.bg, fontFace:'Calibri' });
  if(!rows || !rows.length){
    s.addText(tbdPptL('No creative carries this dimension in this period.','Nenhum criativo carrega esta dimensao neste periodo.','Ningun creativo carga esta dimension en este periodo.'),
      { x:x, y:y+0.28, w:w, h:0.3, fontSize:8.5, italic:true, color:TBD_PPT_SEM.footerGray, fontFace:'Calibri' });
    return y+0.62;
  }
  var head = [colLabel, 'n', 'L/$1K adj.★', 'CPL adj.★'].map(function(h,i){
    return { text:h, options:{ fontSize:8, bold:true, color:'FFFFFF', fill:{color:pal.bg}, align:i===0?'left':'center' } };
  });
  var best = rows[0], worst = rows[rows.length-1];
  var body = rows.slice(0,6).map(function(r,i){
    var isBest = rows.length>1 && r===best, isWorst = rows.length>1 && r===worst;
    var col = isBest ? TBD_PPT_SEM.green : (isWorst ? TBD_PPT_SEM.red : TBD_PPT_SEM.bodyGray);
    return [
      { text:esc0(r.label).slice(0,34), options:{ fontSize:8, color:TBD_PPT_SEM.bodyGray, fill:{color: i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF'} } },
      { text:String(r.n), options:{ fontSize:8, align:'center', color: r.n<3 ? TBD_PPT_SEM.amber : TBD_PPT_SEM.bodyGray, fill:{color: i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF'} } },
      { text:fmtNum(r.l1k_adj,0), options:{ fontSize:8.5, align:'right', bold:isBest||isWorst, color:col, fill:{color: i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF'} } },
      { text:r.cpl_adj!=null?fmt$(r.cpl_adj,2):'—', options:{ fontSize:8, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color: i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF'} } },
    ];
  });
  var cw = [w-2.05, 0.45, 0.90, 0.70];
  s.addTable([head].concat(body), { x:x, y:y+0.28, w:w, colW:cw, border:{type:'solid',color:TBD_PPT_SEM.borderGray,pt:0.5}, autoPage:false, fontFace:'Calibri' });
  return y + 0.28 + (body.length+1)*0.205 + 0.20;
}
/* Slide: las 7 dimensiones al detalle (hoy el deck solo mostraba mejor/peor
   de 5 dimensiones en un panel lateral -- esto es la tabla completa). */
function tbdPptDimensionsSlide(pres, pal, brand, territory, data, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Performance by Creative Dimension — Jan–Jul 2026','Performance por Dimensao Criativa — Jan–Jul 2026','Desempeno por Dimension Creativa — Ene–Jul 2026'), territory+' · '+brand);
  s.addText(tbdPptL('Green = best group, red = worst. An n in amber means fewer than 3 creatives carry that value: read it as a hint, not a verdict.',
    'Verde = melhor grupo, vermelho = pior. Um n em ambar significa menos de 3 criativos com esse valor: leia como pista, nao veredicto.',
    'Verde = mejor grupo, rojo = peor. Un n en ambar significa menos de 3 creativos con ese valor: leelo como pista, no como veredicto.'),
    { x:0.35,y:1.12,w:12.6,h:0.26, fontSize:8.5, italic:true, color:'888888', fontFace:'Calibri' });
  var items = data.y26;
  var defs = [
    [tbdPptL('Tone','Tom','Tono'), function(r){ return r.tone_category||null; }],
    [tbdPptL('Audio hook','Hook de audio','Hook de audio'), function(r){ return r.hook_audio_type_code||null; }],
    [tbdPptL('Visual hook','Hook visual','Hook visual'), function(r){ return r.hook_visual_type_code||null; }],
    [tbdPptL('Theme mechanism','Mecanismo tematico','Mecanismo tematico'), function(r){ return r.theme_mechanism_code||null; }],
    [tbdPptL('Pain point','Pain point','Pain point'), function(r){ return r.pain_point_code||null; }],
    [tbdPptL('CTA type','Tipo de CTA','Tipo de CTA'), function(r){ return r.cta_type_code||null; }],
    [tbdPptL('Production (AI vs Real)','Producao (IA vs Real)','Produccion (IA vs Real)'), function(r){ return r.type_of_production||null; }],
    [tbdPptL('Campaign','Campanha','Campana'), function(r){ return r.campaign_name||null; }],
  ];
  var colW = 4.15, gap = 0.16;
  defs.forEach(function(d, i){
    var col = i % 3, row = Math.floor(i/3);
    var x = 0.35 + col*(colW+gap);
    var y = 1.48 + row*1.95;
    tbdPptDimTable(s, pres, pal, x, y, colW, d[0], tbdDimensionRollup(items, d[1]), d[0]);
  });
  tbdPptFooter(s, footerText);
}
/* Slide: ciclo de vida -- semana de lanzamiento y desgaste, lado a lado. */
function tbdPptLifecycleSlide(pres, pal, brand, territory, data, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Creative Lifecycle — Launch Week and Wear-Out','Ciclo de Vida do Criativo — Semana de Lancamento e Desgaste','Ciclo de Vida del Creativo — Semana de Lanzamiento y Desgaste'), territory+' · '+brand);
  /* Semana de lanzamiento: tbdLaunchWeek() devuelve un agregado (mismo shape
     que tbdAgg), no un delta. El delta contra el desempenio completo del
     creativo se arma aca, igual que en el tab 'launch' de la app. */
  var lw = data.y26.map(function(r){
      var a = tbdLaunchWeek(r);
      if(!a || a.l1k_adj==null || !(r.l1k_adj>0)) return null;
      return { r:r, dias:a.n, a:a.l1k_adj, b:r.l1k_adj, pct:(r.l1k_adj-a.l1k_adj)/a.l1k_adj*100 };
    }).filter(Boolean).sort(function(x,y){ return x.pct-y.pct; });
  /* Desgaste: tbdWearout() si devuelve {h1,h2,pct}; h1/h2 son agregados. */
  var wo = data.y26.map(function(r){
      var w = tbdWearout(r);
      if(!w || w.pct==null || !w.h1 || !w.h2) return null;
      return { r:r, dias:r.n, a:w.h1.l1k_adj, b:w.h2.l1k_adj, pct:w.pct };
    }).filter(Boolean).sort(function(x,y){ return x.pct-y.pct; });

  function block(x, title, sub, list, isWear){
    s.addText(title, { x:x,y:1.15,w:6.2,h:0.3, fontSize:12, bold:true, color:pal.bg, fontFace:'Calibri' });
    s.addText(sub, { x:x,y:1.44,w:6.2,h:0.42, fontSize:8.5, italic:true, color:'888888', fontFace:'Calibri', valign:'top' });
    if(!list.length){
      s.addText(tbdPptL('No creative has enough days on air to measure this here.','Nenhum criativo tem dias suficientes no ar para medir isto aqui.','Ningun creativo tiene suficientes dias al aire para medir esto aca.'),
        { x:x,y:1.95,w:6.2,h:0.4, fontSize:9, italic:true, color:TBD_PPT_SEM.footerGray, fontFace:'Calibri' });
      return;
    }
    var head = [tbdPptL('Creative','Criativo','Creativo'), tbdPptL('Days','Dias','Dias'), isWear?tbdPptL('1st half','1a metade','1a mitad'):tbdPptL('Week 1','Semana 1','Semana 1'), isWear?tbdPptL('2nd half','2a metade','2a mitad'):tbdPptL('Full run','Corrida completa','Corrida completa'), 'Δ%']
      .map(function(h,i){ return { text:h, options:{ fontSize:8, bold:true, color:'FFFFFF', fill:{color:pal.bg}, align:i===0?'left':'center' } }; });
    var body = list.slice(0,9).map(function(o,i){
      var col = o.pct<=-20 ? TBD_PPT_SEM.red : (o.pct>=15 ? TBD_PPT_SEM.green : TBD_PPT_SEM.bodyGray);
      var z = i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF';
      return [
        { text:esc0(o.r.nombre).slice(0,32), options:{ fontSize:8, color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
        { text:String(o.dias), options:{ fontSize:8, align:'center', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
        { text:fmtNum(o.a,0), options:{ fontSize:8, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
        { text:fmtNum(o.b,0), options:{ fontSize:8, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
        { text:(o.pct>0?'+':'')+fmtNum(o.pct,0)+'%', options:{ fontSize:8.5, align:'right', bold:true, color:col, fill:{color:z} } },
      ];
    });
    s.addTable([head].concat(body), { x:x,y:1.95,w:6.2, colW:[2.85,0.55,0.90,0.90,1.00], border:{type:'solid',color:TBD_PPT_SEM.borderGray,pt:0.5}, autoPage:false, fontFace:'Calibri' });
  }
  block(0.35, tbdPptL('Launch Week','Semana de Lancamento','Semana de Lanzamiento'),
    tbdPptL('Demand-adjusted L/$1k over the first 7 days on air vs the creative full run. A large negative delta means the launch number was a novelty spike that did not hold — budget for that cooldown instead of extrapolating week 1.',
      'L/$1k ajustado nos primeiros 7 dias no ar vs a corrida completa do criativo. Um delta muito negativo significa que o numero de lancamento foi um pico de novidade que nao se sustentou — planeje esse resfriamento em vez de extrapolar a semana 1.',
      'L/$1k ajustado en los primeros 7 dias al aire vs la corrida completa del creativo. Un delta muy negativo significa que el numero de lanzamiento fue un pico de novedad que no se sostuvo — presupuesta ese enfriamiento en vez de extrapolar la semana 1.'), lw, false);
  block(6.75, tbdPptL('Wear-Out','Desgaste','Desgaste'),
    tbdPptL('First half on air vs second half, demand-adjusted so a seasonal dip is not mistaken for fatigue. Below -20% is a real wear-out signal.',
      'Primeira metade no ar vs segunda metade, ajustado por demanda para nao confundir queda sazonal com fadiga. Abaixo de -20% e sinal real de desgaste.',
      'Primera mitad al aire vs segunda mitad, ajustado por demanda para no confundir una caida estacional con fatiga. Por debajo de -20% es senal real de desgaste.'), wo, true);
  tbdPptFooter(s, footerText);
}
/* Slide: halo entre marcas -- leads REALES de la otra marca atribuidos al
   gasto de esta, prorrateados por el mismo peso de rotacion del dia. */
function tbdPptHaloSlide(pres, pal, brand, territory, data, footerText){
  var other = brand==='Open English Junior' ? 'Open English' : 'Open English Junior';
  var withHalo = data.y26.filter(function(r){ return (r.jr_l||0) > 0; }).sort(function(a,b){ return b.jr_l1k_adj-a.jr_l1k_adj; });
  if(!withHalo.length) return; // sin halo real no se agrega slide de relleno
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Cross-Brand Halo — '+other+' leads generated by '+brand+' spend','Halo Entre Marcas — leads de '+other+' gerados pelo gasto de '+brand,'Halo Entre Marcas — leads de '+other+' generados por el gasto de '+brand), territory+' · '+brand);
  var totalHalo = 0, totalOwn = 0, totalSpend = 0;
  data.y26.forEach(function(r){ totalHalo += (r.jr_l||0); totalOwn += r.l; totalSpend += r.s; });
  var sharePct = totalOwn>0 ? totalHalo/totalOwn*100 : 0;
  s.addText(tbdPptL('These are real '+other+' leads that the source system tagged as marketing_organization = '+brand+', prorated by the same creative rotation % used everywhere else in this deck. They are NOT counted in the '+brand+' numbers on the other slides — this is incremental value on top.',
    'Sao leads reais de '+other+' que o sistema de origem marcou como marketing_organization = '+brand+', prorrateados pelo mesmo % de rotacao usado no resto deste deck. NAO estao contados nos numeros de '+brand+' das outras slides — e valor incremental por cima.',
    'Son leads reales de '+other+' que el sistema de origen etiqueto como marketing_organization = '+brand+', prorrateados por el mismo % de rotacion que usa el resto de este deck. NO estan contados en los numeros de '+brand+' de las otras slides — es valor incremental por encima.'),
    { x:0.35,y:1.12,w:12.6,h:0.6, fontSize:9, italic:true, color:'888888', fontFace:'Calibri', valign:'top' });
  var kpis = [
    [tbdPptL('Halo leads (2026)','Leads de halo (2026)','Leads de halo (2026)'), fmtNum(totalHalo,0)],
    [tbdPptL('As % of own leads','Como % dos leads proprios','Como % de leads propios'), fmtNum(sharePct,1)+'%'],
    [tbdPptL('Creatives producing halo','Criativos que geram halo','Creativos que generan halo'), String(withHalo.length)+' / '+String(data.y26.length)],
    [tbdPptL('Halo L/$1k adj.','L/$1k adj. de halo','L/$1k adj. de halo'), fmtNum(totalSpend>0?(totalHalo/totalSpend*1000)/(data.p26.dem/100):0,0)],
  ];
  kpis.forEach(function(k,i){
    var x = 0.35 + i*3.18;
    s.addShape(pres.ShapeType.rect, { x:x,y:1.80,w:3.05,h:0.95, fill:{color:'FDF1E8'}, line:{color:TBD_PPT_SEM.orange, width:0.75} });
    s.addText(k[0], { x:x+0.12,y:1.86,w:2.8,h:0.3, fontSize:8, bold:true, color:TBD_PPT_SEM.orange, fontFace:'Calibri' });
    s.addText(k[1], { x:x+0.12,y:2.14,w:2.8,h:0.5, fontSize:15, bold:true, color:pal.bg, fontFace:'Calibri' });
  });
  var head = [tbdPptL('Creative','Criativo','Creativo'), tbdPptL('Halo leads','Leads de halo','Leads de halo'), tbdPptL('Halo L/$1k adj.','L/$1k adj. halo','L/$1k adj. halo'), tbdPptL('Own L/$1k adj.','L/$1k adj. proprio','L/$1k adj. propio'), tbdPptL('Halo as % of own','Halo como % do proprio','Halo como % del propio')]
    .map(function(h,i){ return { text:h, options:{ fontSize:8.5, bold:true, color:'FFFFFF', fill:{color:pal.bg}, align:i===0?'left':'center' } }; });
  var body = withHalo.slice(0,11).map(function(r,i){
    var z = i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF';
    var rel = r.l1k_adj>0 ? r.jr_l1k_adj/r.l1k_adj*100 : 0;
    return [
      { text:esc0(r.nombre).slice(0,44), options:{ fontSize:8.5, color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
      { text:fmtNum(r.jr_l,0), options:{ fontSize:8.5, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
      { text:fmtNum(r.jr_l1k_adj,0), options:{ fontSize:9, align:'right', bold:i===0, color:i===0?TBD_PPT_SEM.orange:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
      { text:fmtNum(r.l1k_adj,0), options:{ fontSize:8.5, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
      { text:fmtNum(rel,0)+'%', options:{ fontSize:8.5, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
    ];
  });
  s.addTable([head].concat(body), { x:0.35,y:2.95,w:12.6, colW:[5.20,1.70,1.90,1.90,1.90], border:{type:'solid',color:TBD_PPT_SEM.borderGray,pt:0.5}, autoPage:false, fontFace:'Calibri' });
  tbdPptFooter(s, footerText);
}
/* Slide: estacionalidad v2026 -- los 12 factores fijos, el semaforo del pais
   y el nivel de mercado (que a proposito NO entra al divisor). */
function tbdPptSeasonalitySlide(pres, pal, brand, territory, data, footerText){
  var sea = TBD_SEASONALITY[territory];
  if(!sea || !sea.factorsIndex) return;
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Seasonality Factors — model v2026','Fatores de Sazonalidade — modelo v2026','Factores de Estacionalidad — modelo v2026'), territory+' · '+tbdPptL('the divisor behind every ★ adj. number in this deck','o divisor por tras de cada numero ★ adj. deste deck','el divisor detras de cada numero ★ adj. de este deck'));
  var MM=['01','02','03','04','05','06','07','08','09','10','11','12'];
  var months = MM.map(mesLabel);
  var f = sea.factorsIndex, grey = sea.grey||[];
  var errPct = tbdSeasonErrPct(territory);
  s.addText(tbdPptL('100 = a normal month. These 12 are FIXED: the same January applies to 2025 and to 2026, so any number here stays reproducible. Rows in grey are months whose factor cannot be told apart from a normal month at 95% confidence.',
    '100 = mes normal. Estes 12 sao FIXOS: o mesmo janeiro vale para 2025 e 2026, entao qualquer numero aqui continua reproduzivel. Linhas cinzas sao meses cujo fator nao se distingue de um mes normal com 95% de confianca.',
    '100 = un mes normal. Estos 12 son FIJOS: el mismo enero aplica a 2025 y a 2026, asi que cualquier numero de aca sigue siendo reproducible. Las filas en gris son meses cuyo factor no se distingue de un mes normal con 95% de confianza.'),
    { x:0.35,y:1.12,w:12.6,h:0.55, fontSize:9, italic:true, color:'888888', fontFace:'Calibri', valign:'top' });
  var head = [tbdPptL('Month','Mes','Mes'), tbdPptL('Factor','Fator','Factor'), tbdPptL('Multiplier','Multiplicador','Multiplicador'), tbdPptL('Margin','Margem','Margen'), tbdPptL('Reliable?','Confiavel?','Confiable?')]
    .map(function(h,i){ return { text:h, options:{ fontSize:8.5, bold:true, color:'FFFFFF', fill:{color:pal.bg}, align:i===0?'left':'center' } }; });
  var body = f.map(function(v,i){
    var g = !!grey[i];
    var z = g ? 'F0F0F0' : (i%2 ? TBD_PPT_SEM.tintZebra : 'FFFFFF');
    var col = g ? TBD_PPT_SEM.footerGray : (v>=105 ? TBD_PPT_SEM.green : (v<=95 ? TBD_PPT_SEM.red : TBD_PPT_SEM.bodyGray));
    return [
      { text:months[i], options:{ fontSize:8.5, bold:true, color:col, fill:{color:z} } },
      { text:fmtNum(v,0), options:{ fontSize:9, align:'right', bold:true, color:col, fill:{color:z} } },
      { text:'x'+fmtNum(v/100,2), options:{ fontSize:8.5, align:'right', color:TBD_PPT_SEM.bodyGray, fill:{color:z} } },
      { text:errPct!=null?('±'+fmtNum(errPct,1)+'%'):'—', options:{ fontSize:8, align:'right', color:TBD_PPT_SEM.footerGray, fill:{color:z} } },
      { text:g?tbdPptL('not significant','nao significativo','no significativo'):tbdPptL('yes','sim','si'), options:{ fontSize:8, align:'center', color:g?TBD_PPT_SEM.amber:TBD_PPT_SEM.green, fill:{color:z} } },
    ];
  });
  s.addTable([head].concat(body), { x:0.35,y:1.78,w:6.1, colW:[1.30,0.95,1.25,1.05,1.55], border:{type:'solid',color:TBD_PPT_SEM.borderGray,pt:0.5}, autoPage:false, fontFace:'Calibri' });

  var gate = tbdSeasonGate(territory) || {};
  var gLbl = gate.label||'-';
  var gColor = gLbl==='VERDE' ? TBD_PPT_SEM.green : (gLbl==='AMBAR' ? TBD_PPT_SEM.amber : TBD_PPT_SEM.red);
  var gName = LANG==='en' ? (gLbl==='VERDE'?'GREEN':gLbl==='AMBAR'?'AMBER':'RED') : gLbl;
  s.addShape(pres.ShapeType.rect, { x:6.75,y:1.78,w:6.2,h:1.65, fill:{color:'FFFFFF'}, line:{color:gColor, width:1} });
  s.addShape(pres.ShapeType.rect, { x:6.75,y:1.78,w:6.2,h:0.36, fill:{color:gColor}, line:{color:gColor} });
  s.addText(gName+' · '+tbdPptL('confidence of the adjustment here','confianca do ajuste aqui','confianza del ajuste aca'), { x:6.90,y:1.78,w:5.9,h:0.36, fontSize:10, bold:true, color:'FFFFFF', valign:'middle', fontFace:'Calibri' });
  s.addText(tbdPptL('Tested on months the model had never seen, this pattern predicted '+fmtNum(gate.skill,0)+'% better than assuming every month is the same. Practical rule: do not rank two creatives apart on an adjusted difference smaller than '+(errPct!=null?fmtNum(errPct,1):'?')+'% — that is the error of the adjustment itself.',
    'Testado em meses que o modelo nunca tinha visto, este padrao acertou '+fmtNum(gate.skill,0)+'% melhor do que supor que todo mes e igual. Regra pratica: nao separe dois criativos por uma diferenca ajustada menor que '+(errPct!=null?fmtNum(errPct,1):'?')+'% — esse e o erro do proprio ajuste.',
    'Probado contra meses que el modelo nunca habia visto, este patron acerto '+fmtNum(gate.skill,0)+'% mejor que suponer que todos los meses son iguales. Regla practica: no separes a dos creativos por una diferencia ajustada menor a '+(errPct!=null?fmtNum(errPct,1):'?')+'% — ese es el error del ajuste mismo.'),
    { x:6.90,y:2.24,w:5.9,h:1.10, fontSize:9, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });

  if(sea.market_25!=null && sea.market_26!=null){
    var yoy = sea.market_yoy;
    var dir = yoy>2 ? tbdPptL('grew','cresceu','crecio') : (yoy<-2 ? tbdPptL('fell','caiu','cayo') : tbdPptL('held flat','ficou estavel','se mantuvo plano'));
    s.addShape(pres.ShapeType.rect, { x:6.75,y:3.60,w:6.2,h:1.85, fill:{color:TBD_PPT_SEM.tintDim}, line:{color:pal.bg, width:0.75} });
    s.addText(tbdPptL('Separately: the market itself','Separadamente: o proprio mercado','Aparte: el mercado en si'), { x:6.90,y:3.68,w:5.9,h:0.3, fontSize:10, bold:true, color:pal.bg, fontFace:'Calibri' });
    s.addText(tbdPptL('Once the repeating month pattern is removed, demand in '+territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% between Jan–Jul 2025 and Jan–Jul 2026 (level '+fmtNum(sea.market_25,1)+' → '+fmtNum(sea.market_26,1)+'). This is CONTEXT, not a correction: it is deliberately kept out of the divisor, because dividing by it would make a creative look better precisely because its market collapsed.',
      'Removido o padrao de mes que se repete, a demanda em '+territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% entre Jan–Jul 2025 e Jan–Jul 2026 (nivel '+fmtNum(sea.market_25,1)+' → '+fmtNum(sea.market_26,1)+'). Isto e CONTEXTO, nao correcao: fica de proposito fora do divisor, porque dividir por ele faria um criativo parecer melhor justamente porque seu mercado caiu.',
      'Una vez removido el patron de mes que se repite, la demanda en '+territory+' '+dir+' '+fmtNum(Math.abs(yoy),1)+'% entre Ene–Jul 2025 y Ene–Jul 2026 (nivel '+fmtNum(sea.market_25,1)+' → '+fmtNum(sea.market_26,1)+'). Esto es CONTEXTO, no una correccion: se deja a proposito fuera del divisor, porque dividir por el haria que un creativo se vea mejor justamente porque su mercado se derrumbo.'),
      { x:6.90,y:3.98,w:5.9,h:1.40, fontSize:9, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
  }
  s.addText(tbdPptL('Spend-weighted factor this portfolio actually ran against: '+fmtNum(data.p26.dem/100,3)+' in 2026 vs '+fmtNum(data.p25.dem/100,3)+' in 2025.',
    'Fator ponderado pelo gasto que este portfolio de fato enfrentou: '+fmtNum(data.p26.dem/100,3)+' em 2026 vs '+fmtNum(data.p25.dem/100,3)+' em 2025.',
    'Factor ponderado por gasto que este portafolio efectivamente enfrento: '+fmtNum(data.p26.dem/100,3)+' en 2026 vs '+fmtNum(data.p25.dem/100,3)+' en 2025.'),
    { x:0.35,y:5.62,w:12.6,h:0.3, fontSize:9, italic:true, color:TBD_PPT_SEM.bodyGray, fontFace:'Calibri' });
  tbdPptFooter(s, footerText);
}
/* Slide: TODOS los hallazgos con su hipotesis y su comprobacion (la slide de
   KPI solo alcanza a mostrar 6; aca van los que sobran, sin recortar). */
function tbdPptInsightsSlide(pres, pal, brand, territory, data, footerText){
  var found = tbdDeepInsights(data);
  var rest = found.slice(6);
  if(!rest.length) return; // si con 6 alcanzo, no se agrega una slide vacia
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Further Findings — finding, hypothesis, cross-check','Outros Achados — achado, hipotese, comprovacao','Hallazgos Adicionales — hallazgo, hipotesis, comprobacion'), territory+' · '+brand+' · '+tbdPptL(found.length+' findings in total, 6 already on the summary slide','' +found.length+' achados no total, 6 ja na slide de resumo', found.length+' hallazgos en total, 6 ya en la slide de resumen'));
  var cols=2, cw=6.28, gx=0.20;
  rest.slice(0,8).forEach(function(fnd,i){
    var col=i%cols, row=Math.floor(i/cols);
    var ch = 1.38;
    var x=0.35+col*(cw+gx), y=1.20+row*(ch+0.10);
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:cw,h:ch, fill:{color:'FFFFFF'}, line:{color:TBD_PPT_SEM.borderGray, width:0.5} });
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:0.06,h:ch, fill:{color:TBD_PPT_SEM.navy}, line:{color:TBD_PPT_SEM.navy} });
    s.addText((fnd.icon||'')+' '+esc0(fnd.title), { x:x+0.18,y:y+0.06,w:cw-0.32,h:0.32, fontSize:9.5, bold:true, color:pal.bg, fontFace:'Calibri' });
    s.addText(esc0(fnd.body).slice(0,210), { x:x+0.18,y:y+0.38,w:cw-0.32,h:0.52, fontSize:8, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
    if(fnd.check){
      s.addText(tbdPptL('Cross-check: ','Comprovacao: ','Comprobacion: ')+esc0(fnd.check).slice(0,150), { x:x+0.18,y:y+0.92,w:cw-0.32,h:0.42, fontSize:7.5, italic:true, color:TBD_PPT_SEM.blue, valign:'top', fontFace:'Calibri' });
    } else if(fnd.hypothesis){
      s.addText(tbdPptL('Hypothesis: ','Hipotese: ','Hipotesis: ')+esc0(fnd.hypothesis).slice(0,150), { x:x+0.18,y:y+0.92,w:cw-0.32,h:0.42, fontSize:7.5, italic:true, color:TBD_PPT_SEM.blue, valign:'top', fontFace:'Calibri' });
    }
  });
  tbdPptFooter(s, footerText);
}
/* Slide de nivel deck: como se lee el deck + la formula del ajuste. Va justo
   despues de la portada, para que nadie lea una tabla sin saber que es ★. */
function tbdPptHowToSlide(pres, pal, brand, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('How to read this deck','Como ler este deck','Como leer este deck'), brand+' · '+tbdPptL('read this before any table','leia isto antes de qualquer tabela','lee esto antes de cualquier tabla'));
  var blocks = [
    [tbdPptL('What a lead is here','O que e um lead aqui','Que es un lead aca'),
     tbdPptL('Only leads whose Organization AND MarketingOrganization are both '+brand+'. Cross-brand halo leads are NOT included in these numbers — they get their own slide. Spend is always net of SEM-Brand, and only Brand TV Channels are counted.',
       'Apenas leads cuja Organization E MarketingOrganization sao ambas '+brand+'. Leads de halo entre marcas NAO estao incluidos nestes numeros — tem slide propria. O gasto e sempre liquido de SEM-Brand, e so contam Brand TV Channels.',
       'Solo leads cuya Organization Y MarketingOrganization son ambas '+brand+'. Los leads de halo entre marcas NO estan incluidos en estos numeros — tienen su propia slide. El gasto siempre es neto de SEM-Brand, y solo cuentan Brand TV Channels.')],
    [tbdPptL('What the ★ adj. columns mean','O que significam as colunas ★ adj.','Que significan las columnas ★ adj.'),
     tbdPptL('L/$1k adj. = raw L/$1k divided by the seasonality factor of the months the creative actually aired in, weighted by the spend of each day. Two creatives that ran in different months are only comparable on the adj. column — the raw one rewards timing, not quality.',
       'L/$1k adj. = L/$1k bruto dividido pelo fator de sazonalidade dos meses em que o criativo de fato foi ao ar, ponderado pelo gasto de cada dia. Dois criativos que rodaram em meses diferentes so sao comparaveis na coluna adj. — a bruta premia o timing, nao a qualidade.',
       'L/$1k adj. = L/$1k crudo dividido por el factor de estacionalidad de los meses en que el creativo efectivamente salio al aire, ponderado por el gasto de cada dia. Dos creativos que corrieron en meses distintos solo son comparables en la columna adj. — la cruda premia el timing, no la calidad.')],
    [tbdPptL('What is deliberately NOT corrected','O que NAO e corrigido de proposito','Que NO se corrige a proposito'),
     tbdPptL('The market going up or down between years. That is a business fact, not a measurement bias. If we divided by it too, a creative that ran while its market collapsed would look better precisely because it collapsed. It is reported as separate context on each Seasonality slide.',
       'O mercado subir ou cair entre anos. Isso e um fato de negocio, nao um vies de medicao. Se dividissemos por ele tambem, um criativo que rodou num mercado em queda pareceria melhor justamente por isso. E reportado como contexto separado em cada slide de Sazonalidade.',
       'Que el mercado suba o baje entre anios. Eso es un hecho del negocio, no un sesgo de medicion. Si tambien dividieramos por el, un creativo que corrio mientras su mercado se derrumbaba se veria mejor justamente por eso. Se reporta como contexto aparte en cada slide de Estacionalidad.')],
    [tbdPptL('How much to trust a small difference','Quanto confiar numa diferenca pequena','Cuanto confiar en una diferencia chica'),
     tbdPptL('Every country carries an error margin on its adjustment, printed on its Seasonality slide. Do not rank two creatives apart on a difference smaller than that margin. An n shown in amber means fewer than 3 creatives back that number: a hint, not a verdict.',
       'Cada pais carrega uma margem de erro no seu ajuste, impressa na sua slide de Sazonalidade. Nao separe dois criativos por uma diferenca menor que essa margem. Um n em ambar significa menos de 3 criativos por tras: uma pista, nao um veredicto.',
       'Cada pais carga un margen de error en su ajuste, impreso en su slide de Estacionalidad. No separes a dos creativos por una diferencia menor a ese margen. Un n en ambar significa menos de 3 creativos detras: una pista, no un veredicto.')],
  ];
  var cw=6.28, ch=2.55, gx=0.20, gy=0.14;
  blocks.forEach(function(b,i){
    var col=i%2, row=Math.floor(i/2);
    var x=0.35+col*(cw+gx), y=1.25+row*(ch+gy);
    s.addShape(pres.ShapeType.rect, { x:x,y:y,w:cw,h:0.40, fill:{color:pal.bg}, line:{color:pal.bg} });
    s.addText(b[0], { x:x+0.15,y:y,w:cw-0.3,h:0.40, fontSize:11, bold:true, color:'FFFFFF', valign:'middle', fontFace:'Calibri' });
    s.addShape(pres.ShapeType.rect, { x:x,y:y+0.40,w:cw,h:ch-0.40, fill:{color:'FFFFFF'}, line:{color:TBD_PPT_SEM.borderGray, width:0.5} });
    s.addText(b[1], { x:x+0.18,y:y+0.50,w:cw-0.36,h:ch-0.58, fontSize:9.5, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
  });
  tbdPptFooter(s, footerText);
}
/* Slide de nivel deck: metodologia completa, al final. */
function tbdPptMethodologySlide(pres, pal, brand, footerText){
  var s = pres.addSlide();
  tbdPptMasthead(s, pres, pal, tbdPptL('Methodology','Metodologia','Metodologia'), brand+' · '+tbdPptL('how every number in this deck was built','como cada numero deste deck foi construido','como se construyo cada numero de este deck'));
  var items = TBD_METHODOLOGY_ITEMS.map(function(it){
    var body = it.dynamic ? it.dynamic() : tbdT(it.text);
    return [tbdT(it.label), String(body).replace(/<[^>]+>/g, '')];
  });
  var cols=3, cw=4.15, gx=0.16;
  var perCol = Math.ceil(items.length/cols);
  items.forEach(function(it,i){
    var col=Math.floor(i/perCol), row=i%perCol;
    var x=0.35+col*(cw+gx);
    var y=1.20+row*(5.85/perCol);
    var h=(5.85/perCol)-0.10;
    s.addText(it[0], { x:x,y:y,w:cw,h:0.24, fontSize:9, bold:true, color:pal.bg, fontFace:'Calibri' });
    s.addText(it[1].slice(0,430), { x:x,y:y+0.24,w:cw,h:h-0.24, fontSize:7, color:TBD_PPT_SEM.bodyGray, valign:'top', fontFace:'Calibri' });
  });
  tbdPptFooter(s, footerText);
}
function tbdPptCoverSlide(pres, brand, territories){
  var pal = TBD_PPT_PALETTE[brand] || TBD_PPT_PALETTE['Open English'];
  var s = pres.addSlide();
  s.background = { color:pal.bg };
  s.addText('TBD Dolo', { x:0,y:2.1,w:13.3,h:1.0, fontSize:40, bold:true, color:'FFFFFF', align:'center', fontFace:'Calibri' });
  s.addText(brand+' · TV Creatives Performance Analysis', { x:0,y:3.05,w:13.3,h:0.5, fontSize:16, color:pal.boxLabel, align:'center', fontFace:'Calibri' });
  s.addText('Jan–Jul 2025 vs Jan–Jul 2026 · Brand TV Channels · Demand-adjusted KPIs (★ adj.)', { x:0,y:3.6,w:13.3,h:0.4, fontSize:12, italic:true, color:pal.boxLabel, align:'center', fontFace:'Calibri' });
  s.addText(territories.join(' · '), { x:1,y:4.6,w:11.3,h:1.6, fontSize:10, color:'FFFFFF', align:'center', valign:'top', fontFace:'Calibri' });
  s.addText('TBD Dolo — TV Ads Performance', { x:0.35,y:7.15,w:12.6,h:0.3, fontSize:8, color:pal.boxLabel, fontFace:'Calibri' });
}
/* Construye y descarga un solo .pptx en el idioma actualmente puesto en LANG
   (el caller es responsable de fijar/restaurar LANG antes/despues). */
function tbdBuildOnePpt(brand, byTerritory, territories, langSuffix){
  var pal = TBD_PPT_PALETTE[brand] || TBD_PPT_PALETTE['Open English'];
  var pres = new PptxGenJS();
  pres.defineLayout({ name:'WIDE', width:13.3, height:7.5 });
  pres.layout = 'WIDE';
  var footerText = 'TBD Dolo · '+brand+' · Jan–Jul 2025 vs 2026';
  tbdPptCoverSlide(pres, brand, territories);
  tbdPptHowToSlide(pres, pal, brand, footerText);
  /* Orden por territorio: primero QUE paso (KPI, creativos, dimensiones),
     luego POR QUE (ciclo de vida, halo, estacionalidad, hallazgos), y al
     final QUE HACER (direccion, tests). Las slides de halo, hallazgos
     adicionales y estacionalidad se omiten solas cuando ese territorio no
     tiene material real -- nunca se agrega una slide de relleno. */
  territories.forEach(function(t){
    var data = byTerritory[t];
    var tests = tbdComputeTests(data);
    tbdPptDividerSlide(pres, pal, t);
    tbdPptKpiSlide(pres, pal, brand, t, data, footerText);
    tbdPptCreativeTableSlide(pres, pal, brand, t, data, footerText);
    tbdPptDimensionsSlide(pres, pal, brand, t, data, footerText);
    tbdPptLifecycleSlide(pres, pal, brand, t, data, footerText);
    tbdPptHaloSlide(pres, pal, brand, t, data, footerText);
    tbdPptSeasonalitySlide(pres, pal, brand, t, data, footerText);
    tbdPptInsightsSlide(pres, pal, brand, t, data, footerText);
    tbdPptDirectionSlide(pres, pal, brand, t, data, footerText);
    tbdPptTestsSlide(pres, pal, brand, t, tests.testsA, true, footerText);
    tbdPptTestsSlide(pres, pal, brand, t, tests.testsB, false, footerText);
  });
  tbdPptMethodologySlide(pres, pal, brand, footerText);
  var brandSuffix = brand==='Open English Junior' ? 'OEJunior' : 'OE';
  return pres.writeFile({ fileName: 'TBD_Dolo_'+brandSuffix+'_'+langSuffix+'_'+territories.length+'territories_2025_vs_2026.pptx' });
}
/* Genera 3 .pptx separados (ES, EN, PT) para la marca elegida -- uno por
   idioma, no un solo archivo mezclado. Se generan en secuencia (no en
   paralelo) para no disparar 3 descargas simultaneas de golpe. */
function tbdDownloadPPT(){
  tbdShowPptBrandModal(function(brand){
    tbdEnsurePptxLib(function(){
      var byTerritory = {};
      TBD_TERRITORIES.forEach(function(t){ byTerritory[t] = tbdDataForOrgTerritory(brand, t); });
      var territories = TBD_TERRITORIES.filter(function(t){ var d=byTerritory[t]; return d.p25.l1k_adj!=null || d.p26.l1k_adj!=null; });
      if(!territories.length){ showToast(LANG==='en'?'No territory has enough data for this brand to build a PPT.':LANG==='pt'?'Nenhum território tem dados suficientes para esta marca para montar o PPT.':'Ningún territorio tiene suficientes datos para esta marca para armar el PPT.'); return; }
      var savedLang = LANG;
      var order = ['es','en','pt'];
      var chain = Promise.resolve();
      order.forEach(function(l){
        chain = chain.then(function(){ LANG = l; return tbdBuildOnePpt(brand, byTerritory, territories, l.toUpperCase()); });
      });
      chain.then(function(){ LANG = savedLang; })
        .catch(function(e){ LANG = savedLang; showToast('Error generando PPT: '+e.message); });
    });
  });
}

/* ============================================================
   Modal infografico del creativo (clic en el Ad Name) -- 3 pasos en orden
   estricto: (1) desglose de versiones (Video Name -> dias), (2) detalle de
   rotacion cronologico (con quien roto y a que %, para auditar el total de
   dias que muestra la tabla), (3) perfil cualitativo. Reusa el modal global
   (#modal-backdrop/#modal-card) que ya existe en dashboard.html para el
   dashboard principal -- nunca se duplica esa estructura, solo se le agrega
   la clase .tbd-wide (apaisado) mientras esta abierto este modal puntual.
   ============================================================ */
function tbdGroupContinuousRotation(rawDays){
  var groups = [];
  var current = null, lastTime = null, lastSig = null;
  rawDays.forEach(function(d){
    var t = Date.parse(d.fecha+'T00:00:00Z');
    var sig = d.video_name+'|'+d.peso_propio+'|'+(d.companions||[]).map(function(c){ return c.nombre+':'+c.peso; }).sort().join(',');
    if(current && lastTime!=null && (t-lastTime)===86400000 && sig===lastSig){ current.dates.push(d.fecha); }
    else { current = { dates:[d.fecha], video_name:d.video_name, peso_propio:d.peso_propio, companions:d.companions||[] }; groups.push(current); }
    lastTime = t; lastSig = sig;
  });
  return groups;
}
function tbdInfoCard(label, value, descObj){
  var desc = descObj ? tbdT(descObj) : null;
  return '<div class="tbd-info-card"><div class="tbd-info-label">'+esc(label)+'</div><div class="tbd-info-value">'+esc(value||'—')+'</div>'+(desc?'<div class="tbd-info-desc">'+esc(desc)+'</div>':'')+'</div>';
}
function tbdCreativeModalHTML(row){
  var L = { versions:{en:'Version breakdown',es:'Desglose de versiones',pt:'Detalhamento de versões'},
    rotation:{en:'Rotation detail (chronological)',es:'Detalle de rotación (cronológico)',pt:'Detalhe de rotação (cronológico)'},
    profile:{en:'Creative profile',es:'Perfil del creativo',pt:'Perfil do criativo'},
    totalDays:{en:'Total unique active days: ',es:'Total de días activos únicos: ',pt:'Total de dias ativos únicos: '},
    withTxt:{en:'with: ',es:'con: ',pt:'com: '},
    days:{en:'days',es:'días',pt:'dias'},
    campaign:{en:'Campaign',es:'Campaña',pt:'Campanha'}, theme:{en:'Theme',es:'Tema',pt:'Tema'}, mechanism:{en:'Mechanism',es:'Mecanismo',pt:'Mecanismo'},
    audioHook:{en:'Audio Hook',es:'Hook de Audio',pt:'Hook de Áudio'}, visualHook:{en:'Visual Hook',es:'Hook Visual',pt:'Hook Visual'} };
  var html = '';
  // Paso 1
  var maxDias = Math.max.apply(null, row.versions.map(function(v){return v.num_dias;}).concat([1]));
  html += '<div class="tbd-modal-step"><div class="tbd-modal-step-label">1 · '+esc(tbdT(L.versions))+'</div>'+
    row.versions.map(function(v){
      return '<div class="tbd-version-row"><div style="min-width:180px;font-weight:700;font-size:12px;">'+esc(v.video_name)+(v.link_video?(' <a href="'+escAttr(v.link_video)+'" target="_blank" rel="noopener" style="color:var(--tbd-accent);">▶</a>'):'')+'</div>'+
        '<div class="tbd-version-bar"><div class="tbd-version-bar-fill" style="width:'+(v.num_dias/maxDias*100)+'%;"></div></div>'+
        '<div style="font-size:12px;font-weight:700;min-width:70px;text-align:right;">'+v.num_dias+' '+esc(tbdT(L.days))+'</div></div>';
    }).join('')+
    '<div style="font-size:11px;color:var(--ink-faint);margin-top:4px;">'+esc(tbdT(L.totalDays))+'<b>'+row.n+'</b></div></div>';
  // Paso 2
  var groups = tbdGroupContinuousRotation(row._rawDays);
  html += '<div class="tbd-modal-step"><div class="tbd-modal-step-label">2 · '+esc(tbdT(L.rotation))+'</div>'+
    '<div style="max-height:230px;overflow-y:auto;">'+groups.map(function(g){
      var d0=g.dates[0], d1=g.dates[g.dates.length-1];
      var dateLabel = d0===d1 ? d0 : (d0+' → '+d1);
      var comp = g.companions.map(function(c){ return c.nombre+' ('+fmtPct(c.peso,0)+')'; }).join(', ') || '—';
      return '<div class="tbd-rot-row"><div class="tbd-rot-date">'+esc(dateLabel)+'</div><div class="tbd-rot-companions"><b style="color:var(--ink);">'+esc(g.video_name)+'</b> · '+esc(tbdT(L.withTxt))+esc(comp)+'</div><div style="text-align:right;font-weight:800;">'+fmtPct(g.peso_propio,0)+'</div></div>';
    }).join('')+'</div></div>';
  // Paso 3
  html += '<div class="tbd-modal-step"><div class="tbd-modal-step-label">3 · '+esc(tbdT(L.profile))+'</div><div class="tbd-info-grid">'+
    tbdInfoCard(tbdT(L.campaign), row.campaign_name)+
    tbdInfoCard(tbdT(L.theme), row.theme, row.theme_explanation)+
    tbdInfoCard(tbdT(L.mechanism), row.theme_mechanism_code)+
    tbdInfoCard('Pain Point', row.pain_point)+
    tbdInfoCard(tbdT(L.audioHook), row.hook_audio_type_code, row.hook_audio)+
    tbdInfoCard(tbdT(L.visualHook), row.hook_visual_type_code, row.hook_visual)+
    '</div></div>';
  return html;
}
function tbdOpenCreativeModal(adName, year){
  if(!TBD_LAST_DATA) return;
  var grouped = year==='2025' ? TBD_LAST_DATA.y25 : TBD_LAST_DATA.y26;
  var ungrouped = year==='2025' ? TBD_LAST_DATA.v25 : TBD_LAST_DATA.v26;
  var row = grouped.filter(function(r){ return r.nombre===adName; })[0] || (ungrouped||[]).filter(function(r){ return r.nombre===adName; })[0];
  if(!row) return;
  document.getElementById('modal-card').classList.add('tbd-wide');
  var versionsLabel = LANG==='en'?'versions':LANG==='pt'?'versões':'versiones';
  document.getElementById('modal-eyebrow').textContent = (row.ad_type||'')+(row.is_grouped?(' · '+row.versions.length+' '+versionsLabel):'');
  document.getElementById('modal-title').innerHTML = esc(row.nombre);
  document.getElementById('modal-body').innerHTML = tbdCreativeModalHTML(row);
  document.getElementById('modal-backdrop').classList.add('open');
}
function tbdWireModalCleanup(){
  var strip = function(){ document.getElementById('modal-card').classList.remove('tbd-wide'); };
  document.getElementById('modal-close').addEventListener('click', strip);
  document.getElementById('modal-backdrop').addEventListener('click', function(e){ if(e.target.id==='modal-backdrop') strip(); });
}

